-- Baseline: the Embel database as production (Supabase project fricsfwqibyhemknqgyf)
-- stands after migration 20261110180000_retire_old_worker_objects, in one migration.
--
-- Every earlier migration and every hand-applied packet (now under supabase/archive/)
-- is folded into this file. A new database gets the whole schema from here; production
-- already has it and only records this version as applied (docs/baseline-release.md).
--
-- Contents, in order: the roles the schema references (created without passwords when
-- missing; a deployment sets passwords for the login roles), the public and fluid_private
-- schemas with every table, function, trigger, policy, index and grant, the storage
-- bucket row and the app's policies and trigger on storage.objects, the trigger on
-- auth.users, the default privileges, and the configuration rows the app needs
-- (generation kinds, engine settings, plans, catalogs). No user data.
--
-- Generated from pg_dump 17.11 of a database built by the retired pipeline, then
-- compared with production object by object (supabase/tests/baseline-parity.sql).

SET check_function_bodies = false;
SET client_min_messages = warning;
SET row_security = off;
SELECT pg_catalog.set_config('search_path', '', false);

--
-- Roles. Attributes as in production; no passwords (a login role without a password
-- cannot connect until a deployment sets one).
--

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'fluid_identity_writer_definer_v1') THEN
    CREATE ROLE fluid_identity_writer_definer_v1 NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'embel_engine') THEN
    CREATE ROLE embel_engine LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS CONNECTION LIMIT 40;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'embel_shared_http_home_prod_v1') THEN
    CREATE ROLE embel_shared_http_home_prod_v1 LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'embel_shared_http_identity_prod_v1') THEN
    CREATE ROLE embel_shared_http_identity_prod_v1 LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_roles WHERE rolname = 'embel_shared_http_logo_prod_v1') THEN
    CREATE ROLE embel_shared_http_logo_prod_v1 LOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE NOREPLICATION NOBYPASSRLS;
  END IF;
END $$;

-- Two Identity functions are owned by fluid_identity_writer_definer_v1. Changing an owner
-- needs SET on that role and CREATE on the schema; both are given here and taken back at
-- the end, as the original installer did.
GRANT fluid_identity_writer_definer_v1 TO postgres WITH INHERIT FALSE, SET TRUE;

-- A Supabase database gives every table, sequence and function the postgres role creates
-- in public to anon, authenticated and service_role by default. The grants below are the
-- exact ones each object has in production, so those defaults are switched off while the
-- objects are created and restored (as production has them) at the end of this file.
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE ALL ON TABLES FROM anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE ALL ON SEQUENCES FROM anon, authenticated, service_role;
ALTER DEFAULT PRIVILEGES FOR ROLE postgres IN SCHEMA public REVOKE ALL ON FUNCTIONS FROM anon, authenticated, service_role;

--
-- Name: fluid_private; Type: SCHEMA; Schema: -; Owner: postgres
--

CREATE SCHEMA fluid_private;


ALTER SCHEMA fluid_private OWNER TO postgres;

GRANT CREATE ON SCHEMA fluid_private TO fluid_identity_writer_definer_v1;

--
-- Name: advance_account_profile_revision(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.advance_account_profile_revision() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if new.owner_id is distinct from old.owner_id or new.revision is distinct from old.revision
    or new.created_at is distinct from old.created_at then
    raise exception using errcode = '22023', message = 'invalid_profile_update';
  end if;
  new.revision := old.revision + 1;
  new.updated_at := clock_timestamp();
  return new;
end;
$$;


ALTER FUNCTION fluid_private.advance_account_profile_revision() OWNER TO postgres;

