--
-- Name: api_text_guided_policy(text, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.api_text_guided_policy(p_operation text, p jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select coalesce(p_operation in ('strategy.reformulate','strategy.competitors','strategy.audience','strategy.positioning','strategy.personality','strategy.slogan')
  and (p=jsonb_build_object('version',2,'pricingVersion','2026-10-14','handlerVersion','strategy-openai-guided-v1',
   'model','gpt-6.1-sol','maxInputTokens',case when p_operation='strategy.competitors' then 3150000 else 32768 end,
   'maxOutputTokens',case when p_operation='strategy.competitors' then 8192 else 4096 end,
   'maxWebSearchCalls',case when p_operation='strategy.competitors' then 2 else 0 end,
   'inputMicrousdPerMillionTokens',2000000,'cachedInputMicrousdPerMillionTokens',100000,
   'cacheWriteMicrousdPerMillionTokens',2500000,'outputMicrousdPerMillionTokens',10000000,
   'webSearchMicrousdPerCall',10000,'maximumCostMicrousd',case when p_operation='strategy.competitors' then 15892880 else 122880 end) or p=jsonb_build_object(
   'version',2,'pricingVersion','2026-10-18','handlerVersion','strategy-openai-guided-v1','model','gpt-6-luna',
   'maxInputTokens',case when p_operation='strategy.competitors' then 3150000 else 32768 end,
   'maxOutputTokens',case when p_operation='strategy.competitors' then 8192 else 4096 end,
   'maxWebSearchCalls',case when p_operation='strategy.competitors' then 2 else 0 end,
   'inputMicrousdPerMillionTokens',100000,'cachedInputMicrousdPerMillionTokens',10000,
   'cacheWriteMicrousdPerMillionTokens',125000,'outputMicrousdPerMillionTokens',500000,
   'webSearchMicrousdPerCall',10000,'maximumCostMicrousd',case when p_operation='strategy.competitors' then 813644 else 6144 end)),false);
$$;


ALTER FUNCTION fluid_private.api_text_guided_policy(p_operation text, p jsonb) OWNER TO postgres;

--
-- Name: api_text_restricted_role(name, oid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.api_text_restricted_role(p_name name, p_oid oid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select exists(select 1 from pg_catalog.pg_roles r where r.rolname=p_name and r.oid=p_oid
 and r.rolcanlogin and not r.rolinherit and not r.rolsuper and not r.rolbypassrls
 and not r.rolcreatedb and not r.rolcreaterole and not r.rolreplication
 and not exists(select 1 from pg_catalog.pg_auth_members m where m.member=r.oid)
 and not exists(select 1 from pg_catalog.pg_shdepend d where d.refclassid='pg_catalog.pg_authid'::regclass and d.refobjid=r.oid and d.deptype='o'));
$$;


ALTER FUNCTION fluid_private.api_text_restricted_role(p_name name, p_oid oid) OWNER TO postgres;

