--
-- Name: asset_library_query(jsonb, boolean); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.asset_library_query(p_query jsonb, p_detail boolean) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare v_cursor jsonb:=p_query->'cursor';v_limit integer;
begin
 if p_query is null or jsonb_typeof(p_query)<>'object' or p_query-(case when p_detail then array['format','cursor','limit'] else array['tab','projectId','format','cursor','limit'] end)<>'{}' then raise exception 'invalid_asset_query' using errcode='22023';end if;
 if p_query ? 'limit' then
  if jsonb_typeof(p_query->'limit')<>'number' or (p_query->>'limit')!~'^[0-9]+$' or (p_query->>'limit')::numeric not between 1 and 100 then raise exception 'invalid_asset_query' using errcode='22023';end if;
 end if;
 if p_query ? 'tab' and(jsonb_typeof(p_query->'tab')<>'string' or p_query->>'tab' not in('my_selection','all_generations')) then raise exception 'invalid_asset_query' using errcode='22023';end if;
 if p_query ? 'format' and(jsonb_typeof(p_query->'format')<>'string' or p_query->>'format' not in('svg','png','webp','jpeg','pdf','zip','json','other')) then raise exception 'invalid_asset_query' using errcode='22023';end if;
 if p_query ? 'projectId' then
  if jsonb_typeof(p_query->'projectId')<>'string' then raise exception 'invalid_asset_query' using errcode='22023';end if;perform(p_query->>'projectId')::uuid;
  p_query:=jsonb_set(p_query,'{projectId}',to_jsonb((p_query->>'projectId')::uuid));
 end if;
 if p_query ? 'cursor' then
  if jsonb_typeof(v_cursor)<>'object' or v_cursor-(case when p_detail then array['createdAt','versionId','assetId','projectId','format'] else array['createdAt','assetId','tab','projectId','format'] end)<>'{}'
   or not(v_cursor ?& (case when p_detail then array['createdAt','versionId','assetId','projectId','format'] else array['createdAt','assetId','tab','projectId','format'] end))
   or jsonb_typeof(v_cursor->'createdAt')<>'string' or jsonb_typeof(v_cursor->'assetId')<>'string'
   or(v_cursor->'format' is distinct from coalesce(p_query->'format','null'::jsonb)) then raise exception 'invalid_asset_cursor' using errcode='22023';end if;
  perform(v_cursor->>'createdAt')::timestamptz;perform(v_cursor->>'assetId')::uuid;
  v_cursor:=jsonb_set(v_cursor,'{assetId}',to_jsonb((v_cursor->>'assetId')::uuid));
  if jsonb_typeof(v_cursor->'projectId')='string' then v_cursor:=jsonb_set(v_cursor,'{projectId}',to_jsonb((v_cursor->>'projectId')::uuid));end if;
  if p_detail then
   if jsonb_typeof(v_cursor->'versionId')<>'string' or jsonb_typeof(v_cursor->'projectId')<>'string' then raise exception 'invalid_asset_cursor' using errcode='22023';end if;
   perform(v_cursor->>'versionId')::uuid;perform(v_cursor->>'projectId')::uuid;
   v_cursor:=jsonb_set(v_cursor,'{versionId}',to_jsonb((v_cursor->>'versionId')::uuid));
  elsif v_cursor->'tab' is distinct from coalesce(p_query->'tab','"my_selection"'::jsonb) or v_cursor->'projectId' is distinct from coalesce(p_query->'projectId','null'::jsonb) then raise exception 'invalid_asset_cursor' using errcode='22023';
  end if;
  p_query:=jsonb_set(p_query,'{cursor}',v_cursor);
 end if;
 v_limit:=coalesce((p_query->>'limit')::integer,40);
 return(case when p_detail then '{}'::jsonb else jsonb_build_object('tab',coalesce(p_query->>'tab','my_selection')) end)||p_query||jsonb_build_object('limit',v_limit);
end $_$;


ALTER FUNCTION fluid_private.asset_library_query(p_query jsonb, p_detail boolean) OWNER TO postgres;

--
-- Name: asset_library_record(public.assets); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.asset_library_record(p_asset public.assets) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select jsonb_build_object('id',p_asset.id,'ownerId',p_asset.owner_id,'projectId',p_asset.project_id,'kind',p_asset.kind,'purpose',p_asset.purpose,'createdAt',p_asset.created_at,
 'versionCount',(select count(*) from public.asset_versions v where v.asset_id=p_asset.id and v.project_id=p_asset.project_id and v.owner_id=p_asset.owner_id),
 'retentionRevision',p_asset.retention_revision,'liked',p_asset.liked,'saved',p_asset.saved,'usage',jsonb_build_object('active',exists(select 1 from public.asset_usages u join public.identity_sessions ih on ih.current_selection_id=u.selection_id and ih.project_id=u.project_id and ih.owner_id=u.owner_id where u.asset_id=p_asset.id and u.project_id=p_asset.project_id and u.owner_id=p_asset.owner_id),'legacy',p_asset.legacy_used),
 'selectionRevision',h.selection_revision,'currentSelection',fluid_private.asset_library_selection(s))
 from public.asset_heads h left join public.asset_selections s on s.id=h.current_selection_id and s.version_id=h.current_version_id and s.asset_id=h.asset_id and s.project_id=h.project_id and s.owner_id=h.owner_id
 where h.asset_id=p_asset.id and h.project_id=p_asset.project_id and h.owner_id=p_asset.owner_id;
$$;


ALTER FUNCTION fluid_private.asset_library_record(p_asset public.assets) OWNER TO postgres;

--
-- Name: asset_library_selected_version(public.assets, integer); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.asset_library_selected_version(p_asset public.assets, p_project_revision integer) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select fluid_private.asset_library_version(v,p_project_revision) from public.asset_heads h join public.asset_versions v on v.id=h.current_version_id and v.asset_id=h.asset_id and v.project_id=h.project_id and v.owner_id=h.owner_id
 where h.asset_id=p_asset.id and h.project_id=p_asset.project_id and h.owner_id=p_asset.owner_id;
$$;


ALTER FUNCTION fluid_private.asset_library_selected_version(p_asset public.assets, p_project_revision integer) OWNER TO postgres;

--
-- Name: asset_selections; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.asset_selections (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_id uuid DEFAULT auth.uid() NOT NULL,
    project_id uuid NOT NULL,
    asset_id uuid NOT NULL,
    version_id uuid NOT NULL,
    reason text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT asset_selections_reason_check CHECK ((reason = ANY (ARRAY['selected'::text, 'restored'::text])))
);

ALTER TABLE ONLY public.asset_selections FORCE ROW LEVEL SECURITY;


ALTER TABLE public.asset_selections OWNER TO postgres;

--
-- Name: asset_library_selection(public.asset_selections); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.asset_library_selection(p_selection public.asset_selections) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select case when p_selection.id is null then null else jsonb_build_object('id',p_selection.id,'ownerId',p_selection.owner_id,'projectId',p_selection.project_id,'assetId',p_selection.asset_id,'versionId',p_selection.version_id,'reason',p_selection.reason,'createdAt',p_selection.created_at,
 'receipt',coalesce((select jsonb_build_object('status','recorded','projectRevision',r.project_revision,'acceptedStaleBasis',r.accepted_stale_basis,'previousSelectionId',r.previous_selection_id) from public.asset_selection_receipts r where r.selection_id=p_selection.id and r.version_id=p_selection.version_id and r.asset_id=p_selection.asset_id and r.project_id=p_selection.project_id and r.owner_id=p_selection.owner_id),' {"status":"legacy_unverified"}'::jsonb)) end;
$$;


ALTER FUNCTION fluid_private.asset_library_selection(p_selection public.asset_selections) OWNER TO postgres;

--
-- Name: asset_versions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.asset_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_id uuid NOT NULL,
    project_id uuid NOT NULL,
    asset_id uuid NOT NULL,
    version integer NOT NULL,
    input_revision integer NOT NULL,
    input_hash text NOT NULL,
    content jsonb DEFAULT '{}'::jsonb NOT NULL,
    content_hash text NOT NULL,
    mime_type text NOT NULL,
    storage_path text,
    provenance jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT asset_versions_check CHECK (((storage_path IS NULL) OR (storage_path = (((((((owner_id)::text || '/'::text) || (project_id)::text) || '/'::text) || (asset_id)::text) || '/'::text) || (id)::text)))),
    CONSTRAINT asset_versions_content_check CHECK ((octet_length((content)::text) <= 1048576)),
    CONSTRAINT asset_versions_content_hash_check CHECK ((content_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT asset_versions_input_hash_check CHECK ((input_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT asset_versions_mime_type_check CHECK (((length(mime_type) >= 1) AND (length(mime_type) <= 150))),
    CONSTRAINT asset_versions_provenance_check CHECK (((jsonb_typeof(provenance) = 'object'::text) AND (octet_length((provenance)::text) <= 32768))),
    CONSTRAINT asset_versions_version_check CHECK ((version > 0))
);

ALTER TABLE ONLY public.asset_versions FORCE ROW LEVEL SECURITY;


ALTER TABLE public.asset_versions OWNER TO postgres;

--
-- Name: asset_library_version(public.asset_versions, integer); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.asset_library_version(p_version public.asset_versions, p_project_revision integer) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select case when p_version.id is null then null else jsonb_build_object('versionId',p_version.id,'ownerId',p_version.owner_id,'projectId',p_version.project_id,'assetId',p_version.asset_id,
 'versionNumber',p_version.version,'inputRevision',p_version.input_revision,'inputHash',p_version.input_hash,'contentHash',p_version.content_hash,'createdAt',p_version.created_at,'mimeType',p_version.mime_type,'format',fluid_private.asset_library_format(p_version.mime_type),
 'provenance','{"status":"legacy_unverified"}'::jsonb,'vectorStatus','unverified','licenseStatus','unverified','fileState',case when p_version.storage_path is null then 'metadata_only' else 'unverified' end,'fileVerification',null,
 'freshness',jsonb_build_object('basis','revision_only','status',case when p_version.input_revision=p_project_revision then 'unknown' else 'stale' end,'inputRevision',p_version.input_revision,'currentProjectRevision',p_project_revision,
 'reasons',case when p_version.input_revision=p_project_revision then '["material_basis_unavailable"]'::jsonb else '["project_revision_changed","material_basis_unavailable"]'::jsonb end)) end;
$$;


ALTER FUNCTION fluid_private.asset_library_version(p_version public.asset_versions, p_project_revision integer) OWNER TO postgres;

--
-- Name: asset_library_versions(public.assets, integer, text, integer, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.asset_library_versions(p_asset public.assets, p_project_revision integer, p_format text, p_limit integer, p_cursor jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare v_items jsonb:='[]';v_total bigint;v_row public.asset_versions;v_count integer:=0;v_last public.asset_versions;v_next jsonb;
begin
 if p_cursor is not null then
  if (p_cursor->>'assetId')::uuid<>p_asset.id or(p_cursor->>'projectId')::uuid<>p_asset.project_id or p_cursor->'format' is distinct from coalesce(to_jsonb(p_format),'null'::jsonb) then raise exception 'invalid_asset_cursor' using errcode='22023';end if;
  if not exists(select 1 from public.asset_versions where id=(p_cursor->>'versionId')::uuid and asset_id=p_asset.id and project_id=p_asset.project_id and owner_id=p_asset.owner_id and created_at=(p_cursor->>'createdAt')::timestamptz and(p_format is null or fluid_private.asset_library_format(mime_type)=p_format)) then raise exception 'not_found' using errcode='P0002';end if;
 end if;
 select count(*) into v_total from public.asset_versions where asset_id=p_asset.id and project_id=p_asset.project_id and owner_id=p_asset.owner_id and(p_format is null or fluid_private.asset_library_format(mime_type)=p_format);
 for v_row in select v.* from public.asset_versions v where v.asset_id=p_asset.id and v.project_id=p_asset.project_id and v.owner_id=p_asset.owner_id and(p_format is null or fluid_private.asset_library_format(v.mime_type)=p_format)
  and(p_cursor is null or(v.created_at,v.id)<((p_cursor->>'createdAt')::timestamptz,(p_cursor->>'versionId')::uuid)) order by v.created_at desc,v.id desc limit p_limit+1 loop
  v_count:=v_count+1;if v_count>p_limit then
   v_next:=jsonb_build_object('createdAt',v_last.created_at,'versionId',v_last.id,'assetId',p_asset.id,'projectId',p_asset.project_id,'format',p_format);exit;
  end if;
  v_items:=v_items||jsonb_build_array(fluid_private.asset_library_version(v_row,p_project_revision));v_last:=v_row;
 end loop;
 return jsonb_build_object('ownerId',p_asset.owner_id,'projectId',p_asset.project_id,'assetId',p_asset.id,'format',p_format,'items',v_items,'totalCount',v_total,'nextCursor',v_next);
end $$;


ALTER FUNCTION fluid_private.asset_library_versions(p_asset public.assets, p_project_revision integer, p_format text, p_limit integer, p_cursor jsonb) OWNER TO postgres;

--
-- Name: capture_identity_reference_snapshot(uuid, bigint); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.capture_identity_reference_snapshot(p_project_id uuid, p_expected_reference_revision bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid();v_revision bigint;v_count integer;v_selected jsonb;v_result jsonb;
begin
 perform 1 from public.projects p where p.id=p_project_id and p.owner_id=v_owner for update;
 if not found then raise exception 'reference_project_not_found' using errcode='P0002';end if;
 select h.reference_revision,h.selected_reference_count into v_revision,v_count from public.identity_reference_heads h where h.project_id=p_project_id and h.owner_id=v_owner for update;
 v_revision:=coalesce(v_revision,0);v_count:=coalesce(v_count,0);
 if p_expected_reference_revision is null or p_expected_reference_revision<>v_revision then raise exception 'reference_snapshot_conflict' using errcode='PT409';end if;
 select coalesce(jsonb_agg(fluid_private.identity_reference_entry(r.reference_id,p_project_id,v_owner) order by r.reference_id),'[]'::jsonb) into v_selected
 from public.identity_reference_reactions r where r.project_id=p_project_id and r.owner_id=v_owner and(r.ensemble or cardinality(r.elements)>0);
 if jsonb_array_length(v_selected)<>v_count or v_count>100 or exists(select 1 from public.identity_reference_reactions r where r.project_id=p_project_id and r.owner_id=v_owner and r.revision>v_revision) then raise exception 'invalid_reference_snapshot_state' using errcode='55000';end if;
 select s.snapshot into v_result from public.identity_reference_snapshots s where s.project_id=p_project_id and s.owner_id=v_owner and s.reference_revision=v_revision;
 if found then return v_result;end if;
 v_result:=jsonb_build_object('version',1,'ownerId',v_owner,'projectId',p_project_id,'referenceRevision',v_revision,'selectedReferenceCount',v_count,'capturedAt',clock_timestamp(),'selected',v_selected);
 insert into public.identity_reference_snapshots(project_id,owner_id,reference_revision,snapshot) values(p_project_id,v_owner,v_revision,v_result);
 return v_result;
end $$;


ALTER FUNCTION fluid_private.capture_identity_reference_snapshot(p_project_id uuid, p_expected_reference_revision bigint) OWNER TO postgres;

--
-- Name: check_naming_context(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.check_naming_context() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_previous jsonb; v_selected text; v_supplied text;
begin
 v_selected:=nullif(btrim(new.context->>'selectedName'),''); v_supplied:=nullif(btrim(new.context#>>'{intake,suppliedName}'),'');
 if new.context ? 'namingSource' and (jsonb_typeof(new.context->'namingSource')<>'object'
  or new.context#>>'{namingSource,origin}' not in('manual','workshop')
  or (new.context->'namingSource')-array['id','value','createdAt','origin','history']<>'{}') then raise exception 'invalid_user_source' using errcode='22023'; end if;
 if new.revision>1 then
  select context into v_previous from public.project_revisions where project_id=new.project_id and owner_id=new.owner_id and revision=new.revision-1;
  if ((v_selected,v_supplied) is distinct from(nullif(btrim(v_previous->>'selectedName'),''),nullif(btrim(v_previous#>>'{intake,suppliedName}'),'')) or exists(select 1 from public.naming_sessions where project_id=new.project_id and owner_id=new.owner_id and current_selection_id is not null)) and v_selected is distinct from v_supplied then raise exception 'inconsistent_selected_name' using errcode='22023'; end if;
  if v_previous ? 'namingSource' and new.context->'namingSource' is distinct from v_previous->'namingSource' then raise exception 'immutable_naming_source' using errcode='22023'; end if;
 end if;
 update public.naming_sessions s set current_selection_id=null,revision=revision+1,updated_at=clock_timestamp()
  where s.project_id=new.project_id and s.owner_id=new.owner_id and s.current_selection_id is not null and not exists(
   select 1 from public.name_selections sel join public.name_candidates c on c.id=sel.candidate_id and c.owner_id=sel.owner_id and c.project_id=sel.project_id
    where sel.id=s.current_selection_id and sel.owner_id=s.owner_id and sel.project_id=s.project_id and c.value=v_selected);
 return new;
end $$;


ALTER FUNCTION fluid_private.check_naming_context() OWNER TO postgres;

--
-- Name: commit_identity_transaction(uuid, jsonb, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: fluid_identity_writer_definer_v1
--

CREATE FUNCTION fluid_private.commit_identity_transaction(p_project uuid, p_request jsonb, p_proposal jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
 v_owner uuid:=fluid_private.identity_web_owner(); v_role oid:=pg_catalog.to_regrole(session_user)::oid;
 v_relation oid; v_prepared record; v_dto jsonb; v_frozen jsonb; v_ids uuid[]; v_jobs uuid[]; v_assets uuid[];
 v_input jsonb; v_basis jsonb; v_reference_basis jsonb; v_response jsonb; v_expected jsonb; v_system jsonb; v_selection jsonb; v_change jsonb;
 v_components jsonb; v_board jsonb; v_files jsonb; v_stale_components jsonb; v_freshness jsonb; v_changed jsonb;
 v_project public.projects; v_head public.identity_reference_heads; v_session public.identity_sessions; v_target public.identity_system_versions;
 v_selected public.identity_selections; v_saved_change public.identity_component_changes; v_saved_system public.identity_system_versions;
 v_previous public.identity_selections; v_now timestamptz; v_system_id uuid; v_selection_id uuid; v_change_id uuid; v_component text;
 v_project_revision bigint; v_reference_revision bigint; v_preferences_revision bigint; v_identity_revision bigint;
 v_stale boolean; v_refinement boolean; v_reason text; v_count bigint; v_expected_count bigint; v_saved_snapshot jsonb;
begin
 if pg_catalog.current_setting('request.jwt.claim.sub',true) is distinct from v_owner::text then raise exception 'identity_claim_mismatch' using errcode='42501'; end if;
 select c.oid into v_relation from pg_catalog.pg_class c where c.relnamespace=pg_catalog.pg_my_temp_schema() and c.relname='identity_transaction_preparation';
 if v_relation is null then raise exception 'identity_preparation_required' using errcode='55000'; end if;
 if not exists(select 1 from pg_catalog.pg_class c where c.oid=v_relation and c.relowner=pg_catalog.to_regrole(current_user)::oid
  and c.relnamespace=pg_catalog.pg_my_temp_schema() and c.relkind='r' and c.relpersistence='t'
  and not exists(select 1 from pg_catalog.aclexplode(coalesce(c.relacl,pg_catalog.acldefault('r',c.relowner))) acl where acl.grantee<>c.relowner))
  or (select pg_catalog.array_agg(attname::text order by attnum) from pg_catalog.pg_attribute where attrelid=v_relation and attnum>0 and not attisdropped)
   is distinct from array['singleton','backend_pid','transaction_id','session_user_name','session_user_oid','owner_id','project_id','refinement','request','payload','consumed']
  or (select pg_catalog.array_agg(pg_catalog.format_type(atttypid,atttypmod) order by attnum) from pg_catalog.pg_attribute where attrelid=v_relation and attnum>0 and not attisdropped)
   is distinct from array['boolean','integer','xid8','name','oid','uuid','uuid','boolean','jsonb','jsonb','boolean']
  or exists(select 1 from pg_catalog.pg_attribute where attrelid=v_relation and attnum>0 and (attisdropped or not attnotnull or attacl is not null))
  or (select count(*) from pg_catalog.pg_constraint where conrelid=v_relation and contype in ('p','c'))<>2
 then raise exception 'untrusted_identity_preparation_relation' using errcode='42501'; end if;
 if not exists(select 1 from pg_catalog.pg_locks l where l.locktype='advisory' and l.database=(select oid from pg_catalog.pg_database where datname=pg_catalog.current_database())
  and l.pid=pg_catalog.pg_backend_pid() and l.classid=1229214808::oid and l.objid=pg_catalog.pg_backend_pid()::oid and l.objsubid=2 and l.granted)
 then raise exception 'identity_guard_required' using errcode='55000'; end if;
 if (select count(*) from pg_temp.identity_transaction_preparation)<>1 then raise exception 'invalid_identity_preparation' using errcode='55000'; end if;
 select * into strict v_prepared from pg_temp.identity_transaction_preparation where singleton;
 if v_prepared.consumed or v_prepared.backend_pid<>pg_catalog.pg_backend_pid() or v_prepared.transaction_id<>pg_catalog.pg_current_xact_id()
  or v_prepared.session_user_name<>session_user or v_prepared.session_user_oid<>v_role or v_prepared.owner_id<>v_owner or v_prepared.project_id<>p_project
  or v_prepared.request is distinct from p_request or v_prepared.payload#>>'{dto,kind}'<>'new'
 then raise exception 'stale_identity_preparation' using errcode='55000'; end if;
 v_dto:=v_prepared.payload->'dto'; v_refinement:=v_prepared.refinement;
 select pg_catalog.array_agg(value::uuid order by value) into v_ids from pg_catalog.jsonb_array_elements_text(v_prepared.payload->'ids');
 select coalesce(pg_catalog.array_agg(value::uuid order by value),'{}') into v_jobs from pg_catalog.jsonb_array_elements_text(v_prepared.payload->'jobs');
 select coalesce(pg_catalog.array_agg(value::uuid order by value),'{}') into v_assets from pg_catalog.jsonb_array_elements_text(v_prepared.payload->'assets');
 -- No lock acquisition here: exact graph reread is bound to preparation and the already-held classes.
 select pg_catalog.jsonb_build_object(
  'projects',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.projects frozen_row where owner_id=v_owner and id=p_project),
  'project_revisions',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.project_revisions frozen_row where owner_id=v_owner and project_id=p_project),
  'identity_reference_heads',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.identity_reference_heads frozen_row where owner_id=v_owner and project_id=p_project),
  'identity_sessions',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.identity_sessions frozen_row where owner_id=v_owner and project_id=p_project),
  'identity_preferences',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.identity_preferences frozen_row where owner_id=v_owner and project_id=p_project),
  'identity_references',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.identity_references frozen_row where owner_id=v_owner and project_id=p_project),
  'identity_reference_reactions',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.identity_reference_reactions frozen_row where owner_id=v_owner and project_id=p_project),
  'identity_reference_snapshots',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.identity_reference_snapshots frozen_row where owner_id=v_owner and project_id=p_project),
  'identity_system_versions',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.identity_system_versions frozen_row where owner_id=v_owner and id=any(v_ids) and project_id=p_project),
  'identity_input_snapshots',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.identity_input_snapshots frozen_row where owner_id=v_owner and id in(select input_id from public.identity_system_versions where id=any(v_ids) and owner_id=v_owner and project_id=p_project) and project_id=p_project),
  'identity_system_files',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.identity_system_files frozen_row where owner_id=v_owner and system_id=any(v_ids) and project_id=p_project),
  'identity_generated_roots',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.identity_generated_roots frozen_row where owner_id=v_owner and batch_id in(select batch_id from public.identity_generated_roots where system_id=any(v_ids) and owner_id=v_owner and project_id=p_project) and project_id=p_project),
  'identity_batches',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.identity_batches frozen_row where owner_id=v_owner and id in(select batch_id from public.identity_generated_roots where system_id=any(v_ids) and owner_id=v_owner and project_id=p_project) and project_id=p_project),
  'jobs',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.jobs frozen_row where owner_id=v_owner and id=any(v_jobs) and project_id=p_project),
  'job_steps',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.job_steps frozen_row where owner_id=v_owner and job_id=any(v_jobs) and project_id=p_project),
  'identity_component_changes',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.identity_component_changes frozen_row where owner_id=v_owner and result_system_id=any(v_ids) and project_id=p_project),
  'identity_selections',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.identity_selections frozen_row where owner_id=v_owner and project_id=p_project),
  'asset_usages',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.asset_usages frozen_row where owner_id=v_owner and project_id=p_project),
  'assets',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.assets frozen_row where owner_id=v_owner and id=any(v_assets) and project_id=p_project),
  'asset_versions',(select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(frozen_row) order by pg_catalog.to_jsonb(frozen_row)::text),'[]') from public.asset_versions frozen_row where owner_id=v_owner and asset_id=any(v_assets) and project_id=p_project)
 ) into v_frozen;
 if v_frozen is distinct from v_prepared.payload->'frozen' then raise exception 'identity_graph_changed' using errcode='55000'; end if;
 select * into strict v_project from public.projects where id=p_project and owner_id=v_owner;
 select * into v_head from public.identity_reference_heads where project_id=p_project and owner_id=v_owner;
 select * into v_session from public.identity_sessions where project_id=p_project and owner_id=v_owner;
 select * into strict v_target from public.identity_system_versions where id=(v_dto->>'targetSystemId')::uuid and owner_id=v_owner and project_id=p_project;
 v_project_revision:=(p_request->>'expectedProjectRevision')::bigint; v_reference_revision:=(p_request->>'expectedReferenceRevision')::bigint;
 v_preferences_revision:=(p_request->>'expectedPreferencesRevision')::bigint; v_identity_revision:=(p_request->>'expectedIdentityRevision')::bigint;
 if v_project_revision<>v_project.current_revision or v_reference_revision<>coalesce(v_head.reference_revision,0)
  or v_preferences_revision<>coalesce(v_session.current_preferences_revision,0) or v_identity_revision<>coalesce(v_session.identity_revision,0) or v_identity_revision>=9007199254740991
 then raise exception 'identity_revision_conflict' using errcode='PT409'; end if;
 v_input:=p_proposal->'currentInput'; v_basis:=v_input->'basis'; v_response:=p_proposal->'response';
 if p_proposal-array['version','kind','currentInput','response'] is distinct from '{}'::jsonb or p_proposal->'version' is distinct from '1'::jsonb
  or p_proposal->>'kind' is distinct from (case when v_refinement then 'refinement' else 'selection' end)
  or pg_catalog.octet_length(p_proposal::text)>16777216
  or v_input-array['version','ownerId','projectId','scope','projectRevision','context','referenceSnapshot','preferencesRevision','preferences','capturedAt','basis','logoBrief'] is distinct from '{}'::jsonb
  or v_input->'version' is distinct from (case when v_dto?'logoBrief' then '2'::jsonb else '1'::jsonb end) or v_input->'logoBrief' is distinct from v_dto->'logoBrief' or v_input->>'ownerId' is distinct from v_owner::text or v_input->>'projectId' is distinct from p_project::text
  or v_input->>'scope' is distinct from v_project.scope::text or v_input->'projectRevision' is distinct from pg_catalog.to_jsonb(v_project_revision)
  or v_input->'referenceSnapshot' is distinct from v_dto->'referenceSnapshot' or v_input->'preferencesRevision' is distinct from pg_catalog.to_jsonb(v_preferences_revision)
  or v_input->'capturedAt' is distinct from v_dto->'now' or pg_catalog.jsonb_typeof(v_input->'context') is distinct from 'object'
  or pg_catalog.jsonb_typeof(v_input->'preferences') is distinct from 'object' or pg_catalog.jsonb_typeof(v_basis) is distinct from 'object'
  or v_basis->'version' is distinct from v_input->'version' or v_basis->'logoBrief' is distinct from v_input->'logoBrief' or v_basis->>'ownerId' is distinct from v_owner::text or v_basis->>'projectId' is distinct from p_project::text
  or v_basis->'preferences' is distinct from v_input->'preferences' or (v_preferences_revision>0 and v_input->'preferences' is distinct from v_dto#>'{preferences,preferences}')
 then raise exception 'invalid_identity_proposal_input' using errcode='55000'; end if;
 -- Shared TypeScript owns normalized context/material-basis and complete Naming/WHATWG semantics.
 -- SQL binds that projection to the exact owner, four heads, stored references and preferences.
 select pg_catalog.jsonb_build_object('version',1,'ownerId',v_owner,'projectId',p_project,'references',coalesce(pg_catalog.jsonb_agg(pg_catalog.jsonb_build_object(
  'referenceId',value#>'{reference,id}','media',value#>'{reference,media}','ensemble',value#>'{reaction,ensemble}','elements',value#>'{reaction,elements}') order by value#>>'{reference,id}'),'[]')) into v_reference_basis
  from pg_catalog.jsonb_array_elements(v_dto#>'{referenceSnapshot,selected}');
 if v_basis->'referenceBasis' is distinct from v_reference_basis then raise exception 'invalid_identity_reference_basis' using errcode='55000'; end if;
 v_system:=fluid_private.identity_system_json(v_target);
 select * into v_previous from public.identity_selections where id=v_session.current_selection_id and owner_id=v_owner and project_id=p_project;
 if v_project_revision<coalesce((v_target.source->>'editedAtProjectRevision')::bigint,(v_system#>>'{input,projectRevision}')::bigint)
  or v_reference_revision<coalesce((v_target.source->>'editedAtReferenceRevision')::bigint,(v_system#>>'{input,referenceSnapshot,referenceRevision}')::bigint)
  or v_preferences_revision<coalesce((v_target.source->>'editedAtPreferencesRevision')::bigint,(v_system#>>'{input,preferencesRevision}')::bigint)
  or (v_previous.id is not null and (v_previous.identity_revision<>v_identity_revision or v_previous.project_revision>v_project_revision or v_previous.reference_revision>v_reference_revision or coalesce(v_previous.preferences_revision,0)>v_preferences_revision))
  or (v_previous.id is null and v_identity_revision<>0)
 then raise exception 'identity_creation_revision_conflict' using errcode='PT409'; end if;
 v_stale:=v_system#>'{input,basis}'<>v_basis;
 if v_stale and p_request->'acceptEarlierBasis'<>'true'::jsonb then raise exception 'identity_earlier_basis_required' using errcode='PT409'; end if;
 v_now:=(v_dto->>'now')::timestamptz; v_selection_id:=(v_dto->>'selectionId')::uuid; v_change_id:=(v_dto->>'changeId')::uuid;
 v_system_id:=case when v_refinement then (v_dto->>'systemVersionId')::uuid else v_target.id end;
 v_reason:=case when v_refinement then 'refined' else v_dto->>'reason' end;
 v_selection:=pg_catalog.jsonb_build_object('id',v_selection_id,'ownerId',v_owner,'projectId',p_project,'systemVersionId',v_system_id,
  'identityRevision',v_identity_revision+1,'projectRevision',v_project_revision,'referenceRevision',v_reference_revision,'preferencesRevision',v_preferences_revision,
  'currentBasis',v_basis,'acceptedEarlierBasis',v_stale,'previousSelectionId',v_previous.id,'reason',v_reason,'createdAt',v_now);
 if v_refinement then
  v_component:=p_request->>'component';
  if v_target.components->v_component is not distinct from p_request->'input' then raise exception 'identity_edit_must_change' using errcode='22023'; end if;
  v_components:=pg_catalog.jsonb_set(v_target.components,array[v_component],p_request->'input');
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(component) order by n),'[]') into v_stale_components
   from pg_catalog.unnest(array['logo','colors','typography','graphics','imagery','composition']) with ordinality x(component,n) where component=v_component or v_target.board->'staleComponents' ? component;
  v_board:=pg_catalog.jsonb_set(v_target.board,'{staleComponents}',v_stale_components);
  select coalesce(pg_catalog.jsonb_agg(value order by n),'[]') into v_files from pg_catalog.jsonb_array_elements(v_target.production_files) with ordinality x(value,n) where value->>'component'<>v_component;
  v_change:=pg_catalog.jsonb_build_object('id',v_change_id,'ownerId',v_owner,'projectId',p_project,'baseSystemVersionId',v_target.id,'resultSystemVersionId',v_system_id,
   'projectRevision',v_project_revision,'referenceRevision',v_reference_revision,'preferencesRevision',v_preferences_revision,'currentBasis',v_basis,'acceptedEarlierBasis',v_stale,
   'component',v_component,'before',v_target.components->v_component,'after',p_request->'input','provenance',pg_catalog.jsonb_build_object('kind','user_edit','actorId',v_owner),'createdAt',v_now);
  v_system:=v_system||pg_catalog.jsonb_build_object('id',v_system_id,'createdAt',v_dto->'now','source',pg_catalog.jsonb_build_object('kind','manual_edit','baseSystemVersionId',v_target.id,'changeId',v_change_id,'component',v_component,
   'editedAtProjectRevision',v_project_revision,'editedAtReferenceRevision',v_reference_revision,'editedAtPreferencesRevision',v_preferences_revision),'components',v_components,'board',v_board,'productionFiles',v_files);
  v_expected:=pg_catalog.jsonb_build_object('system',v_system,'change',v_change,'selection',v_selection);
 else
  select coalesce(pg_catalog.jsonb_agg(pg_catalog.to_jsonb(label) order by n),'[]') into v_changed from
   (values ('strategy','strategy',1),('name','name',2),('references','referenceBasis',3),('preferences','preferences',4),('logoBrief','logoBrief',5)) x(label,key,n)
   where v_system#>array['input','basis',key] is distinct from v_basis->key;
  v_freshness:=pg_catalog.jsonb_build_object('status',case when pg_catalog.jsonb_array_length(v_changed)=0 then 'current' else 'stale' end,'changed',v_changed);
  v_expected:=pg_catalog.jsonb_build_object('session',pg_catalog.jsonb_build_object('ownerId',v_owner,'projectId',p_project,'identityRevision',v_identity_revision+1,
   'currentSelectionId',v_selection_id,'currentPreferencesRevision',v_preferences_revision,'createdAt',coalesce(v_session.created_at,v_now),'updatedAt',v_now),
   'currentSelection',pg_catalog.jsonb_build_object('selection',v_selection,'system',v_system,'freshness',v_freshness));
 end if;
 if v_response is distinct from v_expected then raise exception 'invalid_identity_transition_projection' using errcode='55000'; end if;

 if v_session.project_id is null then
  insert into public.identity_sessions(project_id,owner_id,created_at,updated_at) values(p_project,v_owner,v_now,v_now);
  get diagnostics v_count=row_count;
  if v_count<>1 then raise exception 'identity_session_write_count' using errcode='55000'; end if;
 end if;
 select snapshot into v_saved_snapshot from public.identity_reference_snapshots where project_id=p_project and owner_id=v_owner and reference_revision=v_reference_revision;
 if found then
  if v_saved_snapshot is distinct from v_dto->'referenceSnapshot' then raise exception 'identity_snapshot_changed' using errcode='55000'; end if;
 else
  insert into public.identity_reference_snapshots(project_id,owner_id,reference_revision,snapshot) values(p_project,v_owner,v_reference_revision,v_dto->'referenceSnapshot');
  get diagnostics v_count=row_count;
  if v_count<>1 then raise exception 'identity_snapshot_write_count' using errcode='55000'; end if;
 end if;
 if v_refinement then
  insert into public.identity_system_versions(id,project_id,owner_id,input_id,root_system_id,base_system_id,change_id,source,components,board,production_files,created_at,created_at_text)
   values(v_system_id,p_project,v_owner,v_target.input_id,v_target.root_system_id,v_target.id,v_change_id,v_system->'source',v_components,v_board,v_files,v_now,v_dto->>'now');
  get diagnostics v_count=row_count;
  if v_count<>1 then raise exception 'identity_system_write_count' using errcode='55000'; end if;
  insert into public.identity_system_files(system_id,slot,project_id,owner_id,component,role,asset_id,version_id)
   select v_system_id,(n-1)::integer,p_project,v_owner,value->>'component',value->>'role',(value#>>'{asset,assetId}')::uuid,(value#>>'{asset,versionId}')::uuid
   from pg_catalog.jsonb_array_elements(pg_catalog.jsonb_build_array(pg_catalog.jsonb_build_object('component',null,'role','board','asset',v_board->'asset'))||v_files) with ordinality x(value,n);
  get diagnostics v_count=row_count;
  if v_count<>pg_catalog.jsonb_array_length(v_files)+1 then raise exception 'identity_file_write_count' using errcode='55000'; end if;
 end if;
 insert into public.identity_selections(id,project_id,owner_id,system_id,identity_revision,project_revision,reference_revision,preferences_revision,current_basis,accepted_earlier_basis,previous_selection_id,reason,created_at)
  values(v_selection_id,p_project,v_owner,v_system_id,v_identity_revision+1,v_project_revision,v_reference_revision,nullif(v_preferences_revision,0),v_basis,v_stale,v_previous.id,v_reason,v_now) returning * into v_selected;
 get diagnostics v_count=row_count;
 if v_count<>1 or fluid_private.identity_selection_json(v_selected) is distinct from v_selection then raise exception 'identity_selection_receipt' using errcode='55000'; end if;
 select count(*) into v_expected_count from public.identity_system_files where system_id=v_system_id and owner_id=v_owner and project_id=p_project;
 insert into public.asset_usages(selection_id,system_id,slot,project_id,owner_id,asset_id,version_id)
  select v_selection_id,system_id,slot,project_id,owner_id,asset_id,version_id from public.identity_system_files where system_id=v_system_id and owner_id=v_owner and project_id=p_project;
 get diagnostics v_count=row_count;
 if v_count<>v_expected_count then raise exception 'identity_usage_write_count' using errcode='55000'; end if;
 if v_refinement then
  insert into public.identity_component_changes(id,project_id,owner_id,base_system_id,result_system_id,selection_id,component,before_value,after_value,project_revision,reference_revision,preferences_revision,current_basis,accepted_earlier_basis,idempotency_key,intent,created_at)
   values(v_change_id,p_project,v_owner,v_target.id,v_system_id,v_selection_id,v_component,v_target.components->v_component,p_request->'input',v_project_revision,v_reference_revision,nullif(v_preferences_revision,0),v_basis,v_stale,p_request->>'idempotencyKey',p_request,v_now) returning * into v_saved_change;
  get diagnostics v_count=row_count;
  if v_count<>1 or fluid_private.identity_change_json(v_saved_change) is distinct from v_change then raise exception 'identity_change_receipt' using errcode='55000'; end if;
 end if;
 update public.identity_sessions set identity_revision=v_identity_revision+1,current_selection_id=v_selection_id,updated_at=v_now
  where project_id=p_project and owner_id=v_owner and identity_revision=v_identity_revision and coalesce(current_preferences_revision,0)=v_preferences_revision and current_selection_id is not distinct from v_previous.id returning * into v_session;
 get diagnostics v_count=row_count;
 if v_count<>1 then raise exception 'identity_head_cas' using errcode='PT409'; end if;
 if exists(select 1 from public.asset_usages where selection_id in(v_previous.id,v_selection_id) and owner_id=v_owner and project_id=p_project and not(asset_id=any(v_assets))) then raise exception 'unprepared_identity_asset' using errcode='55000'; end if;
 select count(distinct asset_id) into v_expected_count from public.asset_usages where selection_id in(v_previous.id,v_selection_id) and owner_id=v_owner and project_id=p_project;
 update public.assets a set used=(a.legacy_used or exists(select 1 from public.asset_usages u join public.identity_sessions h on h.current_selection_id=u.selection_id and h.project_id=u.project_id and h.owner_id=u.owner_id
   where u.asset_id=a.id and u.owner_id=a.owner_id and u.project_id=a.project_id))
  where a.id=any(v_assets) and a.owner_id=v_owner and a.project_id=p_project and a.id in(select asset_id from public.asset_usages where selection_id in(v_previous.id,v_selection_id) and owner_id=v_owner and project_id=p_project);
 get diagnostics v_count=row_count;
 if v_count<>v_expected_count then raise exception 'identity_asset_write_count' using errcode='55000'; end if;
 select * into strict v_saved_system from public.identity_system_versions where id=v_system_id and owner_id=v_owner and project_id=p_project;
 v_response:=case when v_refinement then pg_catalog.jsonb_build_object('system',fluid_private.identity_system_json(v_saved_system),'change',fluid_private.identity_change_json(v_saved_change),'selection',fluid_private.identity_selection_json(v_selected))
  else pg_catalog.jsonb_build_object('session',fluid_private.identity_session_json(v_session),'currentSelection',pg_catalog.jsonb_build_object('selection',fluid_private.identity_selection_json(v_selected),'system',fluid_private.identity_system_json(v_saved_system),'freshness',v_freshness)) end;
 if v_response is distinct from v_expected then raise exception 'identity_persisted_receipt_mismatch' using errcode='55000'; end if;
 update pg_temp.identity_transaction_preparation set consumed=true where singleton and not consumed;
 get diagnostics v_count=row_count;
 if v_count<>1 then raise exception 'identity_preparation_consumed' using errcode='55000'; end if;
 return v_response;
end $$;


ALTER FUNCTION fluid_private.commit_identity_transaction(p_project uuid, p_request jsonb, p_proposal jsonb) OWNER TO fluid_identity_writer_definer_v1;

--
-- Name: commit_logo_deliverable_command(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.commit_logo_deliverable_command(p_owner uuid, p_project uuid, p_command jsonb, p_evidence jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare b jsonb:=p_command->'body';method text:=p_command->>'method';source jsonb;candidate jsonb;item jsonb;items jsonb:='[]';document public.logo_asset_publications;preview public.logo_asset_publications;stored public.logo_variant_sets;expected_reviews jsonb;review jsonb;revision jsonb;review_id uuid:=gen_random_uuid();prior jsonb;format text;
begin
 source:=fluid_private.logo_approved_deliverable_sources(p_owner,p_project);
 if b->'approvedLogoId' is distinct from source#>'{logoApproval,id}' or b->'directionApprovalId' is distinct from source#>'{directionApproval,id}' then raise exception 'export_approval_changed' using errcode='PT409';end if;
 select r.record->'payload' into prior from public.logo_stage_heads h join public.logo_stage_revisions r on r.id=h.revision_id where h.owner_id=p_owner and h.project_id=p_project and h.stage='deliverables';
 if method='prepareLogoVariants' then
  if (fluid_private.standalone_keys(b,array['requestKey','expected','approvedLogoId','directionApprovalId']) and fluid_private.standalone_keys(p_evidence,array['source','variantSet']) and p_evidence->'source'=source) is not true then raise exception 'variant_source_changed' using errcode='PT409';end if;
  candidate:=p_evidence->'variantSet';
  if (fluid_private.standalone_keys(candidate,array['id','ownerId','projectId','approvedLogoId','directionApprovalId','items','createdAt']) and fluid_private.logo_uuid(candidate->'id') and candidate->>'ownerId'=p_owner::text and candidate->>'projectId'=p_project::text and candidate->'approvedLogoId'=b->'approvedLogoId' and candidate->'directionApprovalId'=b->'directionApprovalId' and fluid_private.standalone_timestamp(candidate->'createdAt') and jsonb_typeof(candidate->'items')='array' and jsonb_array_length(candidate->'items')=12) is not true then raise exception 'invalid_variant_set' using errcode='22023';end if;
  if (select count(*)<>count(distinct value->>'id') or count(*)<>count(distinct (value->>'role',value->>'colorway')) from jsonb_array_elements(candidate->'items')) then raise exception 'duplicate_variant' using errcode='22023';end if;
  for item in select value from jsonb_array_elements(candidate->'items') loop
   if (fluid_private.standalone_keys(item,array['id','role','colorway','documentAsset','renderHash','preview','clearSpace','minimumDigitalSize','applicability','reviewStatus']) and fluid_private.logo_uuid(item->'id') and item->>'role' in('primary','horizontal','stacked','symbol_only') and item->>'colorway' in('black','white','color') and item->>'reviewStatus'='review_required' and jsonb_typeof(item->'clearSpace')='number' and(item->>'clearSpace')::numeric between 0 and 1000000 and(item->'minimumDigitalSize'='null' or(jsonb_typeof(item->'minimumDigitalSize')='number' and(item->>'minimumDigitalSize')::numeric>0 and(item->>'minimumDigitalSize')::numeric<=16384))) is not true then raise exception 'invalid_variant_item' using errcode='22023';end if;
   if item#>>'{applicability,status}'='not_applicable' then
    if (fluid_private.standalone_keys(item->'applicability',array['status','reason']) and item#>>'{applicability,reason}' in('no_symbol','inseparable_artwork') and item->>'role'<>'primary' and item->'documentAsset'='null' and item->'renderHash'='null' and item->'preview'='null') is not true then raise exception 'invalid_variant_omission' using errcode='22023';end if;
   elsif item->'applicability'='{"status":"applicable"}' then
    if (item->>'renderHash' ~ '^[0-9a-f]{64}$' and fluid_private.logo_uuid(item#>'{documentAsset,versionId}') and fluid_private.logo_uuid(item#>'{preview,id}')) is not true then raise exception 'variant_proof_required' using errcode='55000';end if;
    select * into document from public.logo_asset_publications a where a.owner_id=p_owner and a.project_id=p_project and a.version_id=(item#>>'{documentAsset,versionId}')::uuid and a.source_kind='variant' and a.source_receipt_id=(b->>'approvedLogoId')::uuid and a.job_id is null for update;
    select * into preview from public.logo_asset_publications a where a.owner_id=p_owner and a.project_id=p_project and a.id=(item#>>'{preview,id}')::uuid and a.source_kind='variant' and a.source_receipt_id=(b->>'approvedLogoId')::uuid and a.job_id is null for update;
    if document.id is null or preview.id is null or document.state='reserved' or preview.state='reserved' or document.mime_type<>'application/json' or preview.mime_type<>'image/png' or document.request#>'{publication,inputRevisions}' is distinct from source->'inputRevisions' or preview.request#>'{publication,inputRevisions}' is distinct from source->'inputRevisions' or fluid_private.logo_asset_reservation(document)->'reference' is distinct from item->'documentAsset' or fluid_private.logo_asset_receipt(preview) is distinct from item->'preview' then raise exception 'variant_bytes_missing_or_changed' using errcode='55000';end if;
    perform fluid_private.logo_commit_asset(document);
    item:=jsonb_set(item,'{preview}',fluid_private.logo_commit_asset(preview));
   else raise exception 'invalid_variant_applicability' using errcode='22023';end if;
   items:=items||jsonb_build_array(item);
  end loop;
  -- All four roles and three colorways are explicit, even when non-applicable.
  candidate:=jsonb_set(candidate,'{items}',items);
  insert into public.logo_variant_sets(id,owner_id,project_id,approved_logo_id,direction_approval_id,record,source) values((candidate->>'id')::uuid,p_owner,p_project,(b->>'approvedLogoId')::uuid,(b->>'directionApprovalId')::uuid,candidate,source);
  revision:=fluid_private.logo_append_stage(p_owner,p_project,'deliverables',jsonb_build_object('variantSetId',candidate->'id','exportManifestIds',coalesce(prior->'exportManifestIds','[]')),source->'inputRevisions');
  return jsonb_build_object('revision',revision,'variantSet',candidate);
 elsif method='reviewLogoVariants' then
  if (fluid_private.standalone_keys(b,array['requestKey','expected','approvedLogoId','directionApprovalId','variantSetId','acceptedVariantIds']) and fluid_private.logo_uuid(b->'variantSetId') and fluid_private.standalone_keys(p_evidence,array['variantSet','acceptedVariants']) and jsonb_typeof(b->'acceptedVariantIds')='array') is not true then raise exception 'invalid_variant_review' using errcode='22023';end if;
  select * into stored from public.logo_variant_sets where id=(b->>'variantSetId')::uuid and owner_id=p_owner and project_id=p_project;
  if stored.id is null then raise exception 'variant_set_not_found' using errcode='P0002';end if;
  if stored.record is distinct from p_evidence->'variantSet' or stored.source-'heads' is distinct from source-'heads' or prior->'variantSetId' is distinct from b->'variantSetId' then raise exception 'variant_source_changed' using errcode='PT409';end if;
  select jsonb_agg(jsonb_build_object('variantId',value->'id','renderHash',value->'renderHash') order by ordinality) into expected_reviews from jsonb_array_elements(stored.record->'items') with ordinality where value#>>'{applicability,status}'='applicable';
  if expected_reviews is null or p_evidence->'acceptedVariants' is distinct from expected_reviews or jsonb_array_length(b->'acceptedVariantIds')<>jsonb_array_length(expected_reviews) or(select count(*)<>count(distinct value) from jsonb_array_elements(b->'acceptedVariantIds')) or exists(select 1 from jsonb_array_elements(expected_reviews) r where not (b->'acceptedVariantIds' @> jsonb_build_array(r->'variantId'))) then raise exception 'every_variant_requires_review' using errcode='22023';end if;
  review:=jsonb_build_object('id',review_id,'ownerId',p_owner,'projectId',p_project,'variantSetId',stored.id,'approvedLogoId',stored.approved_logo_id,'directionApprovalId',stored.direction_approval_id,'acceptedVariants',expected_reviews,'reviewedAt',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
  insert into public.logo_variant_reviews(id,owner_id,project_id,variant_set_id,record) values(review_id,p_owner,p_project,stored.id,review);
  revision:=fluid_private.logo_append_stage(p_owner,p_project,'deliverables',prior,source->'inputRevisions');
  return jsonb_build_object('revision',revision);
 else raise exception 'deliverable_method_unavailable' using errcode='55000';end if;
end $_$;


ALTER FUNCTION fluid_private.commit_logo_deliverable_command(p_owner uuid, p_project uuid, p_command jsonb, p_evidence jsonb) OWNER TO postgres;

--
-- Name: commit_logo_direction_command(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.commit_logo_direction_command(p_owner uuid, p_project uuid, p_command jsonb, p_evidence jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $_$
declare b jsonb:=p_command->'body';method text:=p_command->>'method';source jsonb;consistency jsonb;overview jsonb;selection jsonb;approval jsonb;stage jsonb;new_id uuid:=gen_random_uuid();available_ids jsonb;inputs jsonb;w jsonb;actual jsonb;
begin
 -- The fixed trusted wrapper has already verified the direct-login owner,
 -- original request body, all expected heads and project-first lock order.
 if method not in('selectIdentityDirectionComponents','approveIdentityDirection') then raise exception 'direction_method_unavailable' using errcode='55000';end if;
 if not fluid_private.standalone_keys(p_evidence,array['sources','consistency']) or octet_length(p_evidence::text)>1048576 then raise exception 'invalid_direction_evidence' using errcode='22023';end if;
 source:=p_evidence->'sources';consistency:=p_evidence->'consistency';
 if not fluid_private.standalone_keys(source,array['approvedLogo','palette','typography','graphics','fonts','fontChecks','sourceDirectionIds']) then raise exception 'invalid_direction_sources' using errcode='22023';end if;
 w:=fluid_private.logo_workspace_json(p_owner,p_project);
 if source->'approvedLogo' is distinct from w->'approvedLogo' then raise exception 'direction_approval_changed' using errcode='PT409';end if;
 select record into stage from public.logo_stage_revisions where id=(w#>>'{stages,directions,id}')::uuid and owner_id=p_owner and project_id=p_project;
 available_ids:=coalesce(stage#>'{payload,directionIds}',source->'sourceDirectionIds');
 overview:=fluid_private.logo_direction_selection_sources(p_owner,p_project,jsonb_build_object('paletteVersionId',source#>'{palette,id}','typographyVersionId',source#>'{typography,id}','graphicsVersionId',source#>'{graphics,id}'));
 if overview->'stale'='true' then raise exception 'direction_source_stale' using errcode='PT409';end if;
 if source->'palette' is distinct from overview#>'{palettes,0}' or source->'typography' is distinct from overview#>'{typography,0}' or source->'graphics' is distinct from overview#>'{graphics,0}' or source->'fonts' is distinct from overview->'fonts' or source->'fontChecks' is distinct from overview->'fontChecks' then raise exception 'direction_source_changed' using errcode='PT409';end if;
 if jsonb_typeof(source->'sourceDirectionIds') is distinct from 'array' or jsonb_array_length(source->'sourceDirectionIds') not between 1 and 3 or (select count(*)<>count(distinct value) from jsonb_array_elements(source->'sourceDirectionIds')) or exists(select 1 from jsonb_array_elements(source->'sourceDirectionIds') i where not exists(select 1 from jsonb_array_elements(overview->'directions') d where d->'id'=i)) then raise exception 'direction_source_changed' using errcode='PT409';end if;
 if not fluid_private.standalone_keys(consistency,array['hash','status','checks','warnings','blockingReasons']) or consistency->>'hash' !~ '^[a-f0-9]{64}$' or consistency->>'status' not in('pass','warning') or jsonb_typeof(consistency->'checks') is distinct from 'array' or jsonb_array_length(consistency->'checks')>100 or jsonb_typeof(consistency->'warnings') is distinct from 'array' or jsonb_array_length(consistency->'warnings')>100 or consistency->'blockingReasons'<>'[]' or exists(select 1 from jsonb_array_elements(consistency->'checks') c where c->>'status'='blocked') or (consistency->>'status'='pass' and(jsonb_array_length(consistency->'warnings')>0 or exists(select 1 from jsonb_array_elements(consistency->'checks') c where c->>'status'='warning'))) then raise exception 'direction_consistency_blocked' using errcode='55000';end if;
 inputs:=source#>'{palette,inputRevisions}';
 if method='selectIdentityDirectionComponents' then
  if b->'approvedLogoId' is distinct from source#>'{approvedLogo,id}' or b->'paletteVersionId' is distinct from source#>'{palette,id}' or b->'typographyVersionId' is distinct from source#>'{typography,id}' or b->'graphicsVersionId' is distinct from source#>'{graphics,id}' then raise exception 'direction_selection_changed' using errcode='PT409';end if;
  selection:=jsonb_build_object('id',new_id,'ownerId',p_owner,'projectId',p_project,'approvedLogoId',source#>'{approvedLogo,id}','inputRevisions',inputs,'paletteVersionId',b->'paletteVersionId','typographyVersionId',b->'typographyVersionId','graphicsVersionId',b->'graphicsVersionId','sourceDirectionIds',source->'sourceDirectionIds','consistency',consistency);
  insert into public.logo_direction_records(id,owner_id,project_id,kind,approved_logo_id,record) values(new_id,p_owner,p_project,'selection',(source#>>'{approvedLogo,id}')::uuid,selection);
  return fluid_private.logo_append_stage(p_owner,p_project,'directions',jsonb_build_object('directionIds',available_ids,'selectionId',new_id,'approvalId',null),inputs);
 end if;
 selection:=overview->'selection';
 if selection is null or selection='null' or selection->'id' is distinct from b->'directionSelectionId' or selection->'consistency' is distinct from consistency or b->'consistencyHash' is distinct from consistency->'hash' or selection->'paletteVersionId' is distinct from source#>'{palette,id}' or selection->'typographyVersionId' is distinct from source#>'{typography,id}' or selection->'graphicsVersionId' is distinct from source#>'{graphics,id}' then raise exception 'direction_review_changed' using errcode='PT409';end if;
 approval:=jsonb_build_object('id',new_id,'ownerId',p_owner,'projectId',p_project,'directionSelectionId',selection->'id','approvedLogoId',source#>'{approvedLogo,id}','consistencyHash',consistency->'hash','approvedAt',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
 insert into public.logo_direction_records(id,owner_id,project_id,kind,approved_logo_id,record) values(new_id,p_owner,p_project,'approval',(source#>>'{approvedLogo,id}')::uuid,approval);
 return fluid_private.logo_append_stage(p_owner,p_project,'directions',jsonb_build_object('directionIds',available_ids,'selectionId',selection->'id','approvalId',new_id),inputs);
end $_$;


ALTER FUNCTION fluid_private.commit_logo_direction_command(p_owner uuid, p_project uuid, p_command jsonb, p_evidence jsonb) OWNER TO postgres;

--
-- Name: commit_logo_input(uuid, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.commit_logo_input(p_project uuid, p_request jsonb, p_receipt jsonb, p_evidence jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=fluid_private.logo_asset_web_owner(); prior public.logo_input_requests; request_state jsonb; workspace jsonb; a public.logo_asset_publications;
 k text:=p_request->>'kind'; declaration text; catalog jsonb; rights jsonb; result jsonb; license_text text; license_hash text; source_url text; family text;
begin
 if fluid_private.logo_input_request_valid(p_request) is distinct from true then raise exception 'invalid_logo_input' using errcode='22023';end if;
 perform 1 from public.projects where id=p_project and owner_id=owner for update;
 if not found then raise exception 'logo_project_not_found' using errcode='P0002';end if;
 select * into prior from public.logo_input_requests where owner_id=owner and project_id=p_project and request_key=(p_request#>>'{input,requestKey}')::uuid;
 if not found then raise exception 'logo_input_request_not_found' using errcode='P0002';end if;
 if prior.request is distinct from p_request then raise exception 'immutable_logo_input_request' using errcode='PT409';end if;
 request_state:=fluid_private.logo_input_state(owner,p_project,prior.request_key);if request_state->>'status' in('succeeded','rejected') then return request_state;end if;
 perform 1 from public.identity_reference_heads where owner_id=owner and project_id=p_project for update;
 perform 1 from public.identity_sessions where owner_id=owner and project_id=p_project for update;
 workspace:=fluid_private.logo_workspace_json(owner,p_project);
 if workspace->'heads' is distinct from p_request#>'{input,expected}' then
  insert into public.logo_input_rejections(owner_id,project_id,request_key,reason) values(owner,p_project,prior.request_key,'inputs_changed');
  return fluid_private.logo_input_state(owner,p_project,prior.request_key);
 end if;
 select * into a from public.logo_asset_publications where id=(p_receipt->>'id')::uuid and owner_id=owner and project_id=p_project and request_key=prior.request_key and state='committed' and job_id is null and request->>'kind'='upload';
 if not found or fluid_private.logo_asset_receipt(a) is distinct from p_receipt or a.rights_evidence_id is null or a.content_hash is distinct from p_request#>>'{file,contentHash}' or a.mime_type is distinct from p_request#>>'{file,mimeType}' or to_jsonb(a.byte_length) is distinct from p_request#>'{file,byteLength}'
  or a.purpose is distinct from(case when k='reference_upload' then 'reference_media' else 'brand_asset' end)
  or a.request#>>'{intent,usage}' is distinct from(case when k='reference_upload' then 'logo_reference' else 'font' end) then raise exception 'logo_input_publication_not_found' using errcode='P0002';end if;
 if k='reference_upload' then
  if p_evidence is distinct from 'null'::jsonb then raise exception 'invalid_logo_reference_evidence' using errcode='22023';end if;
  declaration:=p_request#>>'{input,rightsDeclaration}';
 else
  if not fluid_private.standalone_keys(p_evidence,array['family','licenseText','licenseSourceUrl']) or not fluid_private.standalone_text(p_evidence->'family',200,1) or jsonb_typeof(p_evidence->'licenseText') is distinct from 'string' or octet_length(p_evidence->>'licenseText')>262144 or fluid_private.idea_trim(p_evidence->>'licenseText')='' then raise exception 'invalid_logo_font_evidence' using errcode='22023';end if;
  family:=p_evidence->>'family';license_text:=p_evidence->>'licenseText';license_hash:=encode(sha256(convert_to(license_text,'UTF8')),'hex');source_url:=p_evidence->>'licenseSourceUrl';
  if k='font_catalog' then
   select record into catalog from fluid_private.logo_input_font_catalog where id=p_request#>>'{input,catalogFontId}';
   if catalog is null or catalog->>'contentHash' is distinct from a.content_hash or catalog->>'mimeType' is distinct from a.mime_type or catalog->>'family' is distinct from family or catalog#>>'{rights,licenseTextHash}' is distinct from license_hash or catalog#>>'{rights,sourceUrl}' is distinct from source_url then raise exception 'logo_catalog_source_unavailable' using errcode='P0002';end if;
   declaration:='Reviewed free-commercial catalog '||(catalog->>'id')||'; exact license SHA-256 '||license_hash||'.';
   rights:=(catalog->'rights')||jsonb_build_object('id',a.rights_evidence_id);
  else
   if p_evidence->'licenseText' is distinct from p_request#>'{input,licenseText}' or p_evidence->'licenseSourceUrl' is distinct from p_request#>'{input,licenseSourceUrl}' then raise exception 'logo_license_changed' using errcode='PT409';end if;
   declaration:=p_request#>>'{input,rightsDeclaration}';
   rights:=jsonb_build_object('id',a.rights_evidence_id,'fontContentHash',a.content_hash,'sourceKind','user_declaration','sourceUrl',source_url,'licenseTextHash',license_hash,'commercialUse','unknown','permissions',jsonb_build_object('render','unknown','outline','unknown','embed','unknown','modify','unknown','redistribute','unknown'),'reviewedAt',null);
  end if;
  if (select count(*) from public.logo_font_records where owner_id=owner and project_id=p_project)>=100 then raise exception 'logo_font_limit' using errcode='22023';end if;
 end if;
 if a.request#>>'{intent,rightsDeclaration}' is distinct from declaration then raise exception 'logo_declaration_changed' using errcode='PT409';end if;
 insert into public.logo_input_rights(id,owner_id,project_id,publication_id,source_kind,content_hash,rights_declaration,license_text,license_text_hash,source_url,catalog_id)
 values(a.rights_evidence_id,owner,p_project,a.id,case when k='font_catalog' then 'reviewed_license' else 'user_declaration' end,a.content_hash,declaration,license_text,license_hash,source_url,case when k='font_catalog' then catalog->>'id' else null end);
 if k='reference_upload' then
  insert into public.logo_reference_sources(reference_id,project_id,owner_id,asset_id,version_id,content_hash,source_kind,rights_evidence_id) values(a.source_receipt_id,p_project,owner,a.asset_id,a.version_id,a.content_hash,'upload',a.rights_evidence_id);
  result:=jsonb_build_object('referenceId',a.source_receipt_id,'asset',p_receipt->'reference','sourceKind','upload','aspects',p_request#>'{input,aspects}','rightsEvidenceId',a.rights_evidence_id,'workspace',workspace);
 else
  result:=jsonb_build_object('id',a.version_id,'asset',p_receipt->'reference','family',family,'source',case when k='font_catalog' then 'free_catalog' else 'user_upload' end,'rights',rights);
  insert into public.logo_font_records(record_id,version_id,owner_id,project_id,record) values(a.version_id,a.version_id,owner,p_project,result);
 end if;
 insert into public.logo_input_receipts(owner_id,project_id,request_key,result,reference_id,font_record_id) values(owner,p_project,prior.request_key,result,case when k='reference_upload' then a.source_receipt_id else null end,case when k<>'reference_upload' then a.version_id else null end);
 return fluid_private.logo_input_state(owner,p_project,prior.request_key);
end $$;


ALTER FUNCTION fluid_private.commit_logo_input(p_project uuid, p_request jsonb, p_receipt jsonb, p_evidence jsonb) OWNER TO postgres;

--
-- Name: commit_logo_vector_edit(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.commit_logo_vector_edit(p_owner uuid, p_project uuid, p_command jsonb, p_evidence jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare base jsonb;current_id uuid;d public.logo_asset_publications;s public.logo_asset_publications;b jsonb:=p_command->'body';v jsonb;payload jsonb;revision jsonb;ids jsonb;cancelled public.logo_vector_edit_cancellations;
begin
 if fluid_private.logo_asset_web_owner() is distinct from p_owner then raise exception 'logo_principal_mismatch' using errcode='42501';end if;
 -- Reacquire the owned project lock even if invoked directly by an existing
 -- internal caller. Cancel may have won while the producer was staging bytes.
 perform 1 from public.projects where id=p_project and owner_id=p_owner for update;
 if not found then raise exception 'logo_project_not_found' using errcode='P0002';end if;
 select * into cancelled from public.logo_vector_edit_cancellations where owner_id=p_owner and project_id=p_project and request_key=(b->>'requestKey')::uuid;
 if found then
  if cancelled.command is distinct from p_command then raise exception 'logo_request_conflict' using errcode='PT409';end if;
  raise exception 'logo_edit_cancelled' using errcode='PT409';
 end if;
 if p_command->>'method' is distinct from 'saveLogoEdit' or not coalesce(fluid_private.standalone_keys(b,array['requestKey','expected','baseVectorRevisionId','edit']),false)
  or not coalesce(fluid_private.logo_uuid(b->'baseVectorRevisionId'),false)
  or not coalesce(fluid_private.standalone_keys(p_evidence,array['baseVectorRevisionId','documentPublicationId','svgPublicationId','documentHash','proof','locks']),false)
  or p_evidence->'baseVectorRevisionId' is distinct from b->'baseVectorRevisionId'
  or not coalesce(fluid_private.logo_uuid(p_evidence->'documentPublicationId'),false) or not coalesce(fluid_private.logo_uuid(p_evidence->'svgPublicationId'),false)
  or not fluid_private.logo_vector_proof_valid(p_evidence->'proof') or p_evidence->'documentHash' is distinct from p_evidence#>'{proof,documentHash}'
  or not fluid_private.logo_vector_locks_valid(p_evidence->'locks') then raise exception 'invalid_logo_edit_evidence' using errcode='22023';end if;
 if fluid_private.logo_workspace_json(p_owner,p_project)->'heads' is distinct from b->'expected' then raise exception 'logo_head_conflict' using errcode='PT409';end if;
 select record into base from public.logo_vector_revisions where id=(b->>'baseVectorRevisionId')::uuid and owner_id=p_owner and project_id=p_project;
 if base is null then raise exception 'logo_vector_not_found' using errcode='P0002';end if;
 current_id:=fluid_private.logo_current_vector_id(p_owner,p_project);
 if current_id is distinct from (base->>'id')::uuid then raise exception 'logo_edit_base_conflict' using errcode='PT409';end if;
 if b#>>'{edit,kind}'='locks' then
  if not coalesce(fluid_private.standalone_keys(b->'edit',array['kind','componentIds']),false) or jsonb_typeof(b#>'{edit,componentIds}') is distinct from 'array'
   or p_evidence->'documentHash' is distinct from base->'documentHash' or p_evidence->'proof' is distinct from base->'proof' then raise exception 'logo_unlock_requires_unchanged_artwork' using errcode='22023';end if;
  select coalesce(jsonb_agg(value->'componentId' order by value->>'componentId'),'[]') into ids from jsonb_array_elements(p_evidence->'locks');
  if ids is distinct from (select coalesce(jsonb_agg(value order by value),'[]') from jsonb_array_elements(b#>'{edit,componentIds}')) then raise exception 'logo_lock_ids_mismatch' using errcode='22023';end if;
 elsif b#>>'{edit,kind}' not in('text','font','spacing','size','rotation','color','arrangement','group_components','replace_outlined_lettering') or p_evidence->'locks' is distinct from base->'locks' then raise exception 'logo_locks_mismatch' using errcode='22023';end if;
 select * into d from public.logo_asset_publications where id=(p_evidence->>'documentPublicationId')::uuid for update;
 select * into s from public.logo_asset_publications where id=(p_evidence->>'svgPublicationId')::uuid for update;
 if not fluid_private.logo_vector_member_valid(d,p_owner,p_project,(base->>'id')::uuid,base->'inputRevisions','application/json',p_evidence->>'documentHash')
  or not fluid_private.logo_vector_member_valid(s,p_owner,p_project,(base->>'id')::uuid,base->'inputRevisions','image/svg+xml',p_evidence#>>'{proof,svgContentHash}')
  or d.id=s.id or d.asset_id=s.asset_id or d.version_id=s.version_id or d.job_id is not null or s.job_id is not null then raise exception 'invalid_logo_vector_members' using errcode='55000';end if;
 perform fluid_private.logo_commit_asset(d);perform fluid_private.logo_commit_asset(s);
 v:=jsonb_build_object('id',gen_random_uuid(),'ownerId',p_owner,'projectId',p_project,'parentRevisionId',base->'id','source',base->'source','sourcePreview',base->'sourcePreview',
  'documentAsset',fluid_private.logo_asset_reservation(d)->'reference','svgAsset',fluid_private.logo_asset_reservation(s)->'reference','documentHash',p_evidence->'documentHash',
  'proof',p_evidence->'proof','locks',p_evidence->'locks','inputRevisions',base->'inputRevisions','reviewStatus','review_required','createdAt',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
 insert into public.logo_vector_revisions(id,owner_id,project_id,record) values((v->>'id')::uuid,p_owner,p_project,v);
 select r.record->'payload' into payload from public.logo_stage_heads h join public.logo_stage_revisions r on r.id=h.revision_id and r.owner_id=h.owner_id and r.project_id=h.project_id where h.owner_id=p_owner and h.project_id=p_project and h.stage='refinements';
 payload:=jsonb_build_object('rasterRevisionIds',coalesce(payload->'rasterRevisionIds','[]'::jsonb),'vectorRevisionId',v->'id','approvalId',null,'sourceRequestKey',b->'requestKey');
 revision:=fluid_private.logo_append_stage(p_owner,p_project,'refinements',payload,base->'inputRevisions');
 return revision;
end $$;


ALTER FUNCTION fluid_private.commit_logo_vector_edit(p_owner uuid, p_project uuid, p_command jsonb, p_evidence jsonb) OWNER TO postgres;

--
-- Name: create_project_with_request(uuid, text, text, jsonb, text); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.create_project_with_request(p_request_key uuid, p_scope text, p_title text, p_context jsonb, p_input_hash text) RETURNS TABLE(id uuid, owner_id uuid, scope text, title text, current_revision integer, created_at timestamp with time zone, context jsonb)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_owner uuid := auth.uid();
  v_payload_hash text;
  v_receipt fluid_private.project_create_requests;
  v_project public.projects;
begin
  if v_owner is null then raise exception 'not_found' using errcode='P0002'; end if;
  if p_request_key is null then raise exception 'invalid_request_key' using errcode='22023'; end if;

  -- Compute the receipt digest from the captured payload, independently of the
  -- caller-provided context hash. jsonb gives equivalent key order one identity.
  v_payload_hash := encode(sha256(convert_to(jsonb_build_object(
    'scope',p_scope,'title',p_title,'context',p_context,'input_hash',p_input_hash
  )::text,'UTF8')),'hex');
  perform pg_advisory_xact_lock(hashtextextended(v_owner::text||':project:create:'||p_request_key::text,0));
  select r.* into v_receipt from fluid_private.project_create_requests r
    where r.owner_id=v_owner and r.request_key=p_request_key;
  if found then
    if v_receipt.payload_hash is distinct from v_payload_hash then
      raise exception 'request_conflict' using errcode='PT409';
    end if;
  else
    -- The creation and receipt commit or roll back together. Failed validation
    -- leaves neither a project nor a consumed request key.
    v_project := public.create_project(p_scope,p_title,p_context,p_input_hash);
    insert into fluid_private.project_create_requests(owner_id,request_key,project_id,payload_hash)
      values(v_owner,p_request_key,v_project.id,v_payload_hash) returning * into v_receipt;
  end if;

  -- One join observes the current revision and context together. Recovery must
  -- never relabel the first context as a newer revision or overwrite later work.
  return query select p.id,p.owner_id,p.scope,p.title,p.current_revision,p.created_at,r.context
    from public.projects p join public.project_revisions r
      on (r.project_id,r.owner_id,r.revision)=(p.id,p.owner_id,p.current_revision)
    where p.id=v_receipt.project_id and p.owner_id=v_owner;
  if not found then raise exception 'not_found' using errcode='P0002'; end if;
end $$;


