--
-- Name: engine_identity_save_board(uuid, integer, jsonb, text, bigint); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.engine_identity_save_board(p_run_id uuid, p_ordinal integer, p_board jsonb, p_response_id text, p_cost bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare r public.generation_runs; v_key text; existing jsonb; cost bigint := greatest(coalesce(p_cost, 0), 0); spent bigint;
  j public.jobs; b public.identity_batches; v_step text; sid uuid; succeeded boolean; code text;
  img jsonb := p_board->'image'; v_components jsonb := p_board#>'{specification,components}'; v_design jsonb := p_board#>'{specification,applicationDesign}';
  publication public.logo_asset_publications; created text; sv public.identity_system_versions; snapshot jsonb; v_result jsonb;
begin
  if p_ordinal is null or p_ordinal not between 1 and 3 or jsonb_typeof(p_board) is distinct from 'object'
     or p_board->>'state' not in ('succeeded', 'failed') or (p_response_id is not null and length(p_response_id) not between 1 and 200) then
    raise exception 'invalid_input' using errcode = '22023';
  end if;
  v_key := 'board.' || p_ordinal;
  select * into r from public.generation_runs where id = p_run_id for update;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  select o.output into existing from public.generation_outputs o where o.run_id = r.id and o.output_key = v_key;
  if existing is not null then return existing; end if;
  if r.kind <> 'identity.directions' then raise exception 'invalid_input' using errcode = '22023'; end if;
  succeeded := p_board->>'state' = 'succeeded';
  code := case when succeeded then null else p_board->>'code' end;
  if not succeeded and (code is null or code !~ '^[a-z][a-z_]{0,63}$') then raise exception 'invalid_input' using errcode = '22023'; end if;
  if succeeded and (jsonb_typeof(img) is distinct from 'object' or img->>'mimeType' is distinct from 'image/png'
     or not fluid_private.logo_uuid(img->'assetId') or not fluid_private.logo_uuid(img->'versionId')
     or coalesce(img->>'contentHash', '') !~ '^[0-9a-f]{64}$' or jsonb_typeof(img->'byteLength') is distinct from 'number'
     or (img->>'byteLength')::numeric not between 1 and 52428800
     or jsonb_typeof(v_components) is distinct from 'object' or jsonb_typeof(v_design) is distinct from 'object') then
    raise exception 'invalid_input' using errcode = '22023';
  end if;
  if r.status <> 'running' then
    -- The round already ended: this board is not delivered, but its usage is kept.
    if r.status in ('cancelled', 'failed') and r.finished_at > now() - interval '1 hour' then
      v_result := jsonb_build_object('state', 'discarded', 'code', coalesce(code, 'run_stopped'));
      insert into public.generation_outputs (run_id, owner_id, output_key, output, provider_response_id, cost_microusd)
        values (r.id, r.owner_id, v_key, v_result, p_response_id, cost) on conflict (run_id, output_key) do nothing;
      return v_result;
    end if;
    raise exception 'run_not_running' using errcode = '55000';
  end if;
  select * into j from public.jobs where id = (r.input->>'jobId')::uuid and owner_id = r.owner_id and project_id = r.project_id
     and operation = 'identity.image' and idempotency_key = 'engine:' || r.id::text for update;
  select * into b from public.identity_batches where id = (r.input->>'batchId')::uuid and job_id = j.id and owner_id = r.owner_id and project_id = r.project_id;
  if j.id is null or b.id is null then raise exception 'invalid_run_input' using errcode = '22023'; end if;
  v_step := 'identity-system-v1:' || p_ordinal;
  sid := (j.input#>>array['systemIds', (p_ordinal - 1)::text])::uuid;
  select coalesce(sum(o.cost_microusd), 0) + cost into spent from public.generation_outputs o
   where o.run_id = r.id and o.output_key like 'spec.' || p_ordinal || '.%';
  if succeeded then
    if v_components is distinct from fluid_private.identity_components(v_components)
       or fluid_private.identity_application_design_valid(v_design, v_components) is not true
       or fluid_private.identity_board_typography_valid(v_components) is not true then
      raise exception 'invalid_input' using errcode = '22023';
    end if;
    -- Each direction of a round is distinct, as on the shared worker.
    if exists (select 1 from public.identity_generated_roots root join public.identity_system_versions other on other.id = root.system_id
                where root.batch_id = b.id and other.components = v_components) then
      succeeded := false; code := 'duplicate_identity_direction';
    elsif exists (select 1 from public.identity_generated_roots root where root.batch_id = b.id and root.board->>'contentHash' = img->>'contentHash') then
      succeeded := false; code := 'duplicate_identity_board';
    elsif not exists (select 1 from storage.objects so where so.bucket_id = 'fluid-assets'
        and so.name = r.owner_id::text || '/' || r.project_id::text || '/' || (img->>'assetId') || '/' || (img->>'versionId')) then
      raise exception 'image_not_stored' using errcode = '55000';
    end if;
  end if;
  if succeeded then
    insert into public.logo_asset_publications (owner_id, project_id, request_key, request, asset_id, version_id, content_hash, mime_type, byte_length,
        purpose, source_receipt_id, rights_evidence_id, source_kind, state, verification, job_id, lease_token, input_revision, input_hash)
      values (r.owner_id, r.project_id, sid, jsonb_build_object('kind', 'engine', 'runId', r.id, 'outputKey', v_key),
        (img->>'assetId')::uuid, (img->>'versionId')::uuid, img->>'contentHash', 'image/png', (img->>'byteLength')::bigint,
        'brand_asset', sid, null, 'identity_system', 'staged',
        jsonb_build_object('status', 'verified', 'checkedAt', to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
          'contentHash', img->'contentHash', 'mimeType', 'image/png', 'byteLength', img->'byteLength'),
        null, null, j.input_revision, j.input_hash)
      returning * into publication;
    perform fluid_private.logo_commit_asset(publication);
    created := to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"');
    insert into public.identity_system_versions (id, owner_id, project_id, input_id, source, components, board, production_files, created_at, created_at_text, root_system_id)
      values (sid, r.owner_id, r.project_id, b.input_id, jsonb_build_object('kind', 'generated', 'batchId', b.id, 'jobId', j.id, 'stepKey', v_step), v_components,
        jsonb_build_object('asset', jsonb_build_object('ownerId', r.owner_id, 'projectId', r.project_id, 'assetId', publication.asset_id,
          'versionId', publication.version_id, 'contentHash', publication.content_hash, 'purpose', 'brand_asset', 'mimeType', 'image/png'),
          'depictsSystemVersionId', sid, 'staleComponents', '[]'::jsonb),
        '[]'::jsonb, created::timestamptz, created, sid)
      returning * into sv;
    insert into fluid_private.identity_system_applications (system_id, owner_id, project_id, design) values (sid, r.owner_id, r.project_id, v_design);
    insert into public.identity_system_files (system_id, slot, project_id, owner_id, component, role, asset_id, version_id)
      values (sid, 0, r.project_id, r.owner_id, null, 'board', publication.asset_id, publication.version_id);
    select i.input into strict snapshot from public.identity_input_snapshots i where i.id = b.input_id and i.owner_id = r.owner_id and i.project_id = r.project_id;
    insert into public.job_steps (job_id, owner_id, project_id, step_key, request_key, state, reserved_cost_microusd, actual_cost_microusd, provider_request_id, output, completed_at)
      values (j.id, r.owner_id, r.project_id, v_step, 'engine:' || r.id::text || ':' || v_key, 'succeeded', 0, spent, p_response_id,
        jsonb_build_object('identity', jsonb_build_object('version', 1, 'operation', 'identity.image', 'ownerId', r.owner_id, 'projectId', r.project_id,
          'batchId', b.id, 'jobId', j.id, 'stepKey', v_step, 'targetCount', 3, 'input', snapshot, 'systems', jsonb_build_array(fluid_private.identity_system_json(sv)))),
        clock_timestamp());
    insert into public.identity_generated_roots (system_id, project_id, owner_id, batch_id, job_id, step_key, output_index, board)
      values (sid, r.project_id, r.owner_id, b.id, j.id, v_step, 0, sv.board->'asset');
    -- The same check every reader applies; anything inconsistent rolls the board back.
    perform fluid_private.identity_root_evidence(sv);
    v_result := jsonb_build_object('state', 'succeeded', 'systemId', sid);
  else
    insert into public.job_steps (job_id, owner_id, project_id, step_key, request_key, state, reserved_cost_microusd, actual_cost_microusd, provider_request_id, output, completed_at)
      values (j.id, r.owner_id, r.project_id, v_step, 'engine:' || r.id::text || ':' || v_key, 'failed', 0, spent, p_response_id,
        jsonb_build_object('error', code), clock_timestamp());
    v_result := jsonb_build_object('state', 'failed', 'code', code);
  end if;
  update public.jobs set actual_cost_microusd = actual_cost_microusd + spent,
      progress = least(99, (select count(*)::integer * 33 from public.job_steps s where s.job_id = j.id))
   where id = j.id;
  insert into public.generation_outputs (run_id, owner_id, output_key, output, provider_response_id, cost_microusd)
    values (r.id, r.owner_id, v_key, v_result, p_response_id, cost);
  return v_result;
end $_$;


ALTER FUNCTION fluid_private.engine_identity_save_board(p_run_id uuid, p_ordinal integer, p_board jsonb, p_response_id text, p_cost bigint) OWNER TO postgres;

--
-- Name: engine_logo_begin(uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.engine_logo_begin(p_run_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.generation_runs; i jsonb; brief public.logo_stage_revisions; b public.logo_concept_batches;
  plan jsonb; prior bigint; item jsonb; slots jsonb := '[]'::jsonb; s public.logo_concept_slots; v_batch uuid;
begin
  select * into r from public.generation_runs where id = p_run_id for update;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if r.status <> 'running' then raise exception 'run_not_running' using errcode = '55000'; end if;
  i := r.input;
  if r.kind <> 'logo.concepts' or i->'version' is distinct from '1'::jsonb or not fluid_private.logo_uuid(i->'batchId')
     or not fluid_private.logo_uuid(i#>'{brief,id}') or jsonb_typeof(i#>'{brief,revision}') is distinct from 'number' then
    raise exception 'invalid_run_input' using errcode = '22023';
  end if;
  v_batch := (i->>'batchId')::uuid;
  select * into brief from public.logo_stage_revisions
   where id = (i#>>'{brief,id}')::uuid and owner_id = r.owner_id and project_id = r.project_id and stage = 'brief_references'
     and revision = (i#>>'{brief,revision}')::bigint;
  if not found then raise exception 'invalid_run_input' using errcode = '22023'; end if;
  select * into b from public.logo_concept_batches where id = v_batch;
  if i->>'operation' in ('concepts', 'more_concepts') then
    if not found then
      select count(*) * 6 into prior from public.logo_concept_batches where owner_id = r.owner_id and project_id = r.project_id;
      plan := fluid_private.logo_plan(brief.record#>'{payload,logoTypes}', prior);
      insert into public.logo_concept_batches (id, owner_id, project_id, request_key, brief_revision_id, reference_snapshot_id, plan, input_revisions)
        values (v_batch, r.owner_id, r.project_id, r.id, brief.id, brief.reference_snapshot_id, plan,
          jsonb_build_array(jsonb_build_object('stage', 'brief_references', 'id', brief.id, 'revision', brief.revision)))
        returning * into b;
      for item in select value from jsonb_array_elements(plan->'slots') loop
        insert into public.logo_concept_slots (id, batch_id, owner_id, project_id, ordinal, logo_type, direction_id)
          values (gen_random_uuid(), v_batch, r.owner_id, r.project_id, (item->>'ordinal')::integer, item->>'type', item->>'directionId');
      end loop;
    elsif b.owner_id <> r.owner_id or b.project_id <> r.project_id or b.request_key <> r.id then
      raise exception 'invalid_run_input' using errcode = '22023';
    end if;
    for s in select sl.* from public.logo_concept_slots sl where sl.batch_id = b.id order by sl.ordinal loop
      slots := slots || jsonb_build_array(jsonb_build_object('ordinal', s.ordinal, 'slotId', s.id, 'type', s.logo_type, 'directionId', s.direction_id));
    end loop;
  elsif i->>'operation' = 'retry_failed' then
    if not found or b.owner_id <> r.owner_id or b.project_id <> r.project_id or b.brief_revision_id <> brief.id
       or jsonb_typeof(i->'slotIds') is distinct from 'array' or jsonb_array_length(i->'slotIds') not between 1 and 6 then
      raise exception 'invalid_run_input' using errcode = '22023';
    end if;
    for s in select sl.* from public.logo_concept_slots sl where sl.batch_id = b.id order by sl.ordinal loop
      if i->'slotIds' ? s.id::text then
        -- Only a slot whose latest attempt definitely failed is drawn again.
        if (select j.state from public.logo_concept_attempts a join public.jobs j on j.id = a.job_id
             where a.slot_id = s.id order by a.attempt_number desc limit 1) is distinct from 'failed'
           and not exists (select 1 from public.generation_outputs o where o.run_id = r.id and o.output_key = 'image.' || s.ordinal) then
          raise exception 'logo_retry_requires_confirmed_failure' using errcode = '22023';
        end if;
        slots := slots || jsonb_build_array(jsonb_build_object('ordinal', s.ordinal, 'slotId', s.id, 'type', s.logo_type, 'directionId', s.direction_id));
      end if;
    end loop;
    if jsonb_array_length(slots) <> jsonb_array_length(i->'slotIds') then raise exception 'invalid_run_input' using errcode = '22023'; end if;
  else
    raise exception 'invalid_run_input' using errcode = '22023';
  end if;
  insert into public.generation_outputs (run_id, owner_id, output_key, output)
    values (r.id, r.owner_id, 'batch', jsonb_build_object('batchId', b.id)) on conflict (run_id, output_key) do nothing;
  return jsonb_build_object('batchId', b.id, 'plan', b.plan, 'slots', slots);
end $$;


ALTER FUNCTION fluid_private.engine_logo_begin(p_run_id uuid) OWNER TO postgres;

--
-- Name: engine_logo_save_image(uuid, text, jsonb, text, bigint); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.engine_logo_save_image(p_run_id uuid, p_key text, p_image jsonb, p_response_id text, p_cost bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare r public.generation_runs; i jsonb; existing jsonb; cost bigint := greatest(coalesce(p_cost, 0), 0);
  succeeded boolean; code text; img jsonb := p_image->'image'; provider jsonb := p_image->'provider';
  v_revision integer; job_id uuid := gen_random_uuid(); job_input jsonb; job_hash text; target_id uuid := gen_random_uuid();
  s public.logo_concept_slots; previous public.logo_concept_attempts; resolved jsonb; inputs jsonb; receipt_id uuid;
  publication public.logo_asset_publications; receipt jsonb; payload jsonb; v_output jsonb;
begin
  if p_key is null or p_key !~ '^image\.([0-5]|refine)$' or jsonb_typeof(p_image) is distinct from 'object'
     or p_image->>'state' not in ('succeeded', 'failed') or (p_response_id is not null and length(p_response_id) not between 1 and 200) then
    raise exception 'invalid_input' using errcode = '22023';
  end if;
  select * into r from public.generation_runs where id = p_run_id for update;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  select o.output into existing from public.generation_outputs o where o.run_id = r.id and o.output_key = p_key;
  if existing is not null then return existing; end if;
  if r.kind not in ('logo.concepts', 'logo.refine') or (r.kind = 'logo.refine') <> (p_key = 'image.refine') then
    raise exception 'invalid_input' using errcode = '22023';
  end if;
  succeeded := p_image->>'state' = 'succeeded';
  code := case when succeeded then null else p_image->>'code' end;
  if not succeeded and (code is null or code !~ '^[a-z][a-z_]{0,63}$') then raise exception 'invalid_input' using errcode = '22023'; end if;
  if succeeded and (provider is null or jsonb_typeof(img) is distinct from 'object' or img->>'mimeType' <> 'image/png'
     or not fluid_private.logo_uuid(img->'assetId') or not fluid_private.logo_uuid(img->'versionId')
     or coalesce(img->>'contentHash', '') !~ '^[0-9a-f]{64}$' or coalesce(img->>'normalizedPixelHash', '') !~ '^[0-9a-f]{64}$'
     or jsonb_typeof(img->'byteLength') is distinct from 'number' or (img->>'byteLength')::numeric not between 1 and 52428800) then
    raise exception 'invalid_input' using errcode = '22023';
  end if;
  if provider is not null and jsonb_typeof(provider) is distinct from 'object' then raise exception 'invalid_input' using errcode = '22023'; end if;
  if r.status <> 'running' then
    -- The run already ended; this image is not delivered, but its usage is kept.
    if r.status in ('cancelled', 'failed') and r.finished_at > now() - interval '1 hour' then
      v_output := jsonb_build_object('state', 'discarded', 'code', coalesce(code, 'run_stopped'));
      insert into public.generation_outputs (run_id, owner_id, output_key, output, provider_response_id, cost_microusd)
        values (r.id, r.owner_id, p_key, v_output, p_response_id, cost) on conflict (run_id, output_key) do nothing;
      return v_output;
    end if;
    raise exception 'run_not_running' using errcode = '55000';
  end if;
  i := r.input;
  v_revision := (i->>'revision')::integer;
  if r.kind = 'logo.concepts' then
    select sl.* into s from public.logo_concept_slots sl
     where sl.batch_id = (i->>'batchId')::uuid and sl.owner_id = r.owner_id and sl.project_id = r.project_id and sl.ordinal = substring(p_key from 7)::integer;
    if not found or (i->>'operation' = 'retry_failed' and not (i->'slotIds' ? s.id::text)) then raise exception 'invalid_input' using errcode = '22023'; end if;
    select a.* into previous from public.logo_concept_attempts a where a.slot_id = s.id order by a.attempt_number desc limit 1;
    -- The same picture twice in one round is not a second concept.
    if succeeded and exists (select 1 from public.logo_concept_slots sl
         join public.logo_concept_attempts a on a.slot_id = sl.id
         join public.logo_raster_results rr on rr.job_id = a.job_id
         join public.logo_provider_responses pr on pr.id = rr.provider_response_receipt_id
        where sl.batch_id = s.batch_id and pr.observation->>'normalizedPixelHash' = img->>'normalizedPixelHash') then
      succeeded := false; code := 'duplicate_preview';
    end if;
    job_input := jsonb_build_object('version', 1, 'engine', jsonb_build_object('runId', r.id, 'outputKey', p_key),
      'operation', 'identity.logo_concept', 'ownerId', r.owner_id, 'projectId', r.project_id, 'requestKey', r.id,
      'batchId', s.batch_id, 'slotId', s.id, 'attemptId', target_id);
  else
    resolved := fluid_private.resolve_logo_raster_source(r.owner_id, r.project_id, i->'source');
    select jsonb_agg(value order by value->>'stage', value->>'id') into inputs from (select distinct value from jsonb_array_elements(
      jsonb_build_array(jsonb_build_object('stage', 'brief_references', 'id', i#>'{brief,id}', 'revision', i#>'{brief,revision}')) || (resolved->'inputRevisions'))) refs;
    job_input := jsonb_build_object('version', 1, 'engine', jsonb_build_object('runId', r.id, 'outputKey', p_key),
      'operation', 'identity.logo_refine', 'ownerId', r.owner_id, 'projectId', r.project_id, 'requestKey', r.id,
      'rasterRevisionId', target_id, 'source', i->'source');
  end if;
  if succeeded and not exists (select 1 from storage.objects o where o.bucket_id = 'fluid-assets'
       and o.name = r.owner_id::text || '/' || r.project_id::text || '/' || (img->>'assetId') || '/' || (img->>'versionId')) then
    raise exception 'image_not_stored' using errcode = '55000';
  end if;
  job_hash := encode(sha256(convert_to(job_input::text, 'UTF8')), 'hex');
  -- A finished record only: no lease, so no worker ever claims it.
  insert into public.jobs (id, owner_id, project_id, operation, input_revision, input_hash, input, idempotency_key, state, progress,
      worker_id, attempts, max_attempts, reserved_cost_microusd, actual_cost_microusd, error_code, finished_at)
    values (job_id, r.owner_id, r.project_id, job_input->>'operation', v_revision, job_hash, job_input, 'engine:' || r.id::text || ':' || p_key,
      case when succeeded then 'succeeded' else 'failed' end, 100, 'embel-engine', 1, 1, 0, cost, code, clock_timestamp());
  if provider is not null then
    insert into public.logo_provider_responses (owner_id, project_id, job_id, lease_token, observation)
      values (r.owner_id, r.project_id, job_id, gen_random_uuid(), jsonb_strip_nulls(jsonb_build_object('provider', 'openai',
        'model', provider->'model', 'providerRequestId', provider->'providerRequestId', 'responseHash', provider->'responseHash',
        'observedAt', provider->'observedAt', 'billing', jsonb_build_object('status', 'recorded', 'confirmedMicrousd', cost),
        'artifactHash', img->'contentHash', 'normalizedPixelHash', img->'normalizedPixelHash')))
      returning id into receipt_id;
  end if;
  if r.kind = 'logo.concepts' then
    insert into public.logo_concept_attempts (id, owner_id, project_id, slot_id, job_id, request_key, previous_attempt_id, attempt_number, input_hash)
      values (target_id, r.owner_id, r.project_id, s.id, job_id, r.id, previous.id, coalesce(previous.attempt_number, 0) + 1, job_hash);
  else
    insert into public.logo_raster_refinements (id, owner_id, project_id, request_key, job_id, source, logo_type, input_revisions)
      values (target_id, r.owner_id, r.project_id, r.id, job_id, i->'source', resolved->>'logoType', inputs);
  end if;
  if succeeded then
    insert into public.logo_asset_publications (owner_id, project_id, request_key, request, asset_id, version_id, content_hash, mime_type, byte_length,
        purpose, source_receipt_id, rights_evidence_id, source_kind, state, verification, job_id, lease_token, input_revision, input_hash)
      values (r.owner_id, r.project_id, target_id, jsonb_build_object('kind', 'engine', 'runId', r.id, 'outputKey', p_key),
        (img->>'assetId')::uuid, (img->>'versionId')::uuid, img->>'contentHash', 'image/png', (img->>'byteLength')::bigint,
        'brand_asset', target_id, null, 'concept', 'staged',
        jsonb_build_object('status', 'verified', 'checkedAt', to_char(clock_timestamp() at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
          'contentHash', img->'contentHash', 'mimeType', 'image/png', 'byteLength', img->'byteLength'),
        null, null, v_revision, job_hash)
      returning * into publication;
    receipt := fluid_private.logo_commit_asset(publication);
    insert into public.logo_raster_results (job_id, owner_id, project_id, preview, provider_response_receipt_id)
      values (job_id, r.owner_id, r.project_id, receipt, receipt_id);
    -- Like the shared worker: a refinement moves the refinements head only
    -- while the workspace is still where the person asked from.
    if r.kind = 'logo.refine' and fluid_private.logo_workspace_json(r.owner_id, r.project_id)->'heads' = i->'expected' then
      select rr.record->'payload' into payload from public.logo_stage_heads h join public.logo_stage_revisions rr on rr.id = h.revision_id
       where h.project_id = r.project_id and h.owner_id = r.owner_id and h.stage = 'refinements';
      payload := jsonb_build_object('rasterRevisionIds', coalesce(payload->'rasterRevisionIds', '[]'::jsonb) || jsonb_build_array(target_id),
        'vectorRevisionId', null, 'approvalId', null, 'sourceRequestKey', r.id);
      perform fluid_private.logo_append_stage(r.owner_id, r.project_id, 'refinements', payload, inputs);
    end if;
  end if;
  v_output := jsonb_build_object('state', case when succeeded then 'succeeded' else 'failed' end, 'jobId', job_id)
    || case when code is null then '{}'::jsonb else jsonb_build_object('code', code) end
    || case when r.kind = 'logo.concepts' then jsonb_build_object('batchId', s.batch_id, 'slotId', s.id, 'ordinal', s.ordinal, 'attemptId', target_id)
            else jsonb_build_object('rasterRevisionId', target_id) end;
  insert into public.generation_outputs (run_id, owner_id, output_key, output, provider_response_id, cost_microusd)
    values (r.id, r.owner_id, p_key, v_output, p_response_id, cost);
  return v_output;
end $_$;


ALTER FUNCTION fluid_private.engine_logo_save_image(p_run_id uuid, p_key text, p_image jsonb, p_response_id text, p_cost bigint) OWNER TO postgres;

--
-- Name: engine_save_names(uuid, text, jsonb, text, bigint); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.engine_save_names(p_run_id uuid, p_key text, p_output jsonb, p_response_id text, p_cost bigint) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare r public.generation_runs; total integer; inserted jsonb := '[]'::jsonb; item jsonb; v_id uuid; v_identity text; v_revision integer; v_basis jsonb;
begin
  -- The row lock serializes saves of one run, so the 100-name cap and duplicate checks hold.
  select * into r from public.generation_runs where id = p_run_id for update;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if r.kind <> 'naming.generate' or p_key is null or p_key !~ '^round\.[1-3]\.[1-9]$'
     or jsonb_typeof(p_output) is distinct from 'object' or jsonb_typeof(p_output->'names') is distinct from 'array'
     or jsonb_array_length(p_output->'names') > 100 or length(coalesce(p_output->>'model', '')) not between 1 and 150
     or p_response_id is null or p_response_id !~ '^resp_[A-Za-z0-9_-]{1,194}$' or pg_column_size(p_output) > 262144 then
    raise exception 'invalid_input' using errcode = '22023';
  end if;
  if r.status <> 'running' then raise exception 'run_not_running' using errcode = '55000'; end if;
  select count(*) into total from public.name_candidates c
   where c.project_id = r.project_id and c.owner_id = r.owner_id and c.batch_id is null and c.origin->>'runId' = r.id::text;
  insert into public.generation_outputs (run_id, owner_id, output_key, output, provider_response_id, cost_microusd)
    values (r.id, r.owner_id, p_key, p_output, p_response_id, greatest(coalesce(p_cost, 0), 0))
    on conflict (run_id, output_key) do nothing;
  if not found then
    return jsonb_build_object('saved', false, 'savedCount', least(total, 100), 'inserted', coalesce((select jsonb_agg(c.identity_key order by c.created_at, c.id)
      from public.name_candidates c where c.project_id = r.project_id and c.owner_id = r.owner_id and c.batch_id is null
       and c.origin->>'runId' = r.id::text and c.origin->>'outputKey' = p_key), '[]'::jsonb));
  end if;
  v_revision := case when jsonb_typeof(r.input->'revision') = 'number' then (r.input->>'revision')::integer end;
  v_basis := r.input #> '{brief,strategyBasis}';
  if v_revision is null or jsonb_typeof(v_basis) is distinct from 'object' then raise exception 'invalid_run_input' using errcode = '22023'; end if;
  for item in select value from jsonb_array_elements(p_output->'names') loop
    if jsonb_typeof(item) is distinct from 'object'
       or (select array_agg(k order by k) from jsonb_object_keys(item) k) is distinct from array['identityKey', 'primaryApproach', 'rationale', 'value']
       or jsonb_typeof(item->'value') is distinct from 'string' or length(item->>'value') not between 1 and 160 or btrim(item->>'value') = ''
       or jsonb_typeof(item->'rationale') is distinct from 'string' or length(item->>'rationale') not between 1 and 600
       or jsonb_typeof(item->'identityKey') is distinct from 'string' or length(item->>'identityKey') not between 1 and 320
       or coalesce(item->>'primaryApproach', '') not in ('real_words', 'compounds', 'blends', 'invented', 'modified', 'phrases', 'initials',
         'other_languages', 'classical_roots', 'people_places', 'stories_culture') then
      raise exception 'invalid_input' using errcode = '22023';
    end if;
    exit when total >= 100;
    v_identity := item->>'identityKey';
    continue when exists (select 1 from public.name_candidates where project_id = r.project_id and identity_key = v_identity);
    v_id := gen_random_uuid();
    -- clock_timestamp keeps the feed in the order the AI proposed the names.
    insert into public.name_candidates (id, owner_id, project_id, value, identity_key, context_revision, strategy_basis, origin, rationale, caution, created_at)
    values (v_id, r.owner_id, r.project_id, item->>'value', v_identity, v_revision, v_basis,
      jsonb_build_object('kind', 'brainstorm', 'version', 2, 'profile', 'brainstorm_v1', 'ownerId', r.owner_id, 'projectId', r.project_id,
        'candidateId', v_id, 'contextRevision', v_revision, 'value', item->>'value', 'runId', r.id, 'outputKey', p_key,
        'responseId', p_response_id, 'model', p_output->>'model', 'primaryApproach', item->>'primaryApproach', 'generatedAt', clock_timestamp()),
      item->>'rationale', 'Unchecked brainstorm. Research and screening are needed before use.', clock_timestamp());
    inserted := inserted || to_jsonb(v_identity);
    total := total + 1;
  end loop;
  return jsonb_build_object('saved', true, 'inserted', inserted, 'savedCount', total);
end $_$;


ALTER FUNCTION fluid_private.engine_save_names(p_run_id uuid, p_key text, p_output jsonb, p_response_id text, p_cost bigint) OWNER TO postgres;

--
-- Name: engine_save_output(uuid, text, jsonb, text, bigint); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.engine_save_output(p_run_id uuid, p_key text, p_output jsonb, p_response_id text, p_cost bigint) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.generation_runs;
begin
  select * into r from public.generation_runs where id = p_run_id;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if r.status <> 'running' then raise exception 'run_not_running' using errcode = '55000'; end if;
  insert into public.generation_outputs (run_id, owner_id, output_key, output, provider_response_id, cost_microusd)
    values (r.id, r.owner_id, p_key, p_output, p_response_id, greatest(coalesce(p_cost, 0), 0))
    on conflict (run_id, output_key) do nothing;
  return found;
end $$;


ALTER FUNCTION fluid_private.engine_save_output(p_run_id uuid, p_key text, p_output jsonb, p_response_id text, p_cost bigint) OWNER TO postgres;

--
-- Name: credit_accounts; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.credit_accounts (
    owner_id uuid NOT NULL,
    plan_id text DEFAULT 'free'::text NOT NULL,
    period_start timestamp with time zone NOT NULL,
    period_end timestamp with time zone NOT NULL,
    granted_period_start timestamp with time zone,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT credit_accounts_check CHECK ((period_end > period_start))
);

ALTER TABLE ONLY public.credit_accounts FORCE ROW LEVEL SECURITY;


ALTER TABLE public.credit_accounts OWNER TO postgres;

--
-- Name: ensure_credit_period(uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.ensure_credit_period(p_owner uuid) RETURNS public.credit_accounts
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a public.credit_accounts; monthly integer; balance integer;
begin
  insert into public.credit_accounts (owner_id, period_start, period_end)
    values (p_owner, date_trunc('month', now()), date_trunc('month', now()) + interval '1 month')
    on conflict (owner_id) do nothing;
  select * into strict a from public.credit_accounts where owner_id = p_owner for update;
  if a.period_end <= now() then
    update public.credit_accounts
       set period_start = date_trunc('month', now()), period_end = date_trunc('month', now()) + interval '1 month', updated_at = now()
     where owner_id = p_owner returning * into a;
  end if;
  if a.granted_period_start is distinct from a.period_start then
    select monthly_credits into strict monthly from fluid_private.plans where id = a.plan_id;
    balance := fluid_private.credit_balance(p_owner);
    if monthly - balance <> 0 then
      insert into public.credit_entries (owner_id, delta, kind, note) values (p_owner, monthly - balance, 'grant', 'Monthly allowance');
    end if;
    update public.credit_accounts set granted_period_start = a.period_start, updated_at = now()
     where owner_id = p_owner returning * into a;
  end if;
  return a;
end $$;


ALTER FUNCTION fluid_private.ensure_credit_period(p_owner uuid) OWNER TO postgres;

--
-- Name: naming_sessions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.naming_sessions (
    project_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    preferences_version integer,
    batch_sequence integer DEFAULT 0 NOT NULL,
    current_selection_id uuid,
    revision integer DEFAULT 1 NOT NULL,
    view_revision integer DEFAULT 1 NOT NULL,
    view_state jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT naming_sessions_batch_sequence_check CHECK ((batch_sequence >= 0)),
    CONSTRAINT naming_sessions_preferences_version_check CHECK ((preferences_version > 0)),
    CONSTRAINT naming_sessions_revision_check CHECK ((revision > 0)),
    CONSTRAINT naming_sessions_view_revision_check CHECK ((view_revision > 0))
);

ALTER TABLE ONLY public.naming_sessions FORCE ROW LEVEL SECURITY;


ALTER TABLE public.naming_sessions OWNER TO postgres;

--
-- Name: ensure_naming_session(uuid, uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.ensure_naming_session(p_project_id uuid, p_owner uuid) RETURNS public.naming_sessions
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_session public.naming_sessions;
begin
 if p_owner is null then raise exception 'unauthenticated' using errcode='42501'; end if;
 perform 1 from public.projects where id=p_project_id and owner_id=p_owner for update;
 if not found then raise exception 'not_found' using errcode='P0002'; end if;
 insert into public.naming_sessions(project_id,owner_id,view_state) values(p_project_id,p_owner,
  '{"pane":"results","conversationOpen":true,"filter":"all","query":"","visibleBatchId":null,"scrollCandidateId":null,"workshopCandidateId":null}') on conflict(project_id) do nothing;
 select * into strict v_session from public.naming_sessions where project_id=p_project_id and owner_id=p_owner for update;
 return v_session;
end $$;


ALTER FUNCTION fluid_private.ensure_naming_session(p_project_id uuid, p_owner uuid) OWNER TO postgres;

--
-- Name: expire_overdue_generation_runs(uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.expire_overdue_generation_runs(p_owner uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare overdue record;
begin
  for overdue in
    select r.id, case when r.status = 'queued' then 'start_failed' else 'run_timed_out' end as code
      from public.generation_runs r join fluid_private.generation_kinds k on k.kind = r.kind
     where r.owner_id = p_owner
       and ((r.status = 'queued' and r.workflow_run_id is null and r.created_at < now() - interval '10 minutes')
         or (r.status = 'running' and r.started_at < now() - make_interval(mins => k.max_running_minutes)))
  loop
    perform fluid_private.finish_generation_run(overdue.id, 'failed', overdue.code);
  end loop;
end $$;


ALTER FUNCTION fluid_private.expire_overdue_generation_runs(p_owner uuid) OWNER TO postgres;

--
-- Name: finish_generation_run(uuid, text, text); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.finish_generation_run(p_run_id uuid, p_status text, p_error text) RETURNS public.generation_runs
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r public.generation_runs; images boolean; delivered integer := 0; kept integer; v_status text := p_status; v_error text := p_error;
begin
  if p_status not in ('succeeded', 'failed', 'cancelled') then raise exception 'invalid_status' using errcode = '22023'; end if;
  select * into r from public.generation_runs where id = p_run_id for update;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if r.status not in ('queued', 'running') then return r; end if;
  images := r.kind in ('logo.concepts', 'logo.refine', 'identity.directions');
  if images then
    select count(*) into delivered from public.generation_outputs o
     where o.run_id = r.id and o.output_key ~ case when r.kind = 'identity.directions' then '^board\.' else '^image\.' end
       and o.output->>'state' = 'succeeded';
    if v_status = 'succeeded' and delivered = 0 then
      v_status := 'failed';
      v_error := coalesce(v_error, case when r.kind = 'identity.directions' then 'no_boards_delivered' else 'no_images_delivered' end);
    end if;
  end if;
  update public.generation_runs
     set status = v_status, error_code = case when v_status = 'succeeded' then null else v_error end, finished_at = now()
   where id = r.id returning * into r;
  kept := case when images then least(delivered, r.credits) when v_status = 'succeeded' then r.credits else 0 end;
  if r.credits - kept > 0 then
    insert into public.credit_entries (owner_id, delta, kind, run_id, note)
      values (r.owner_id, r.credits - kept, 'refund', r.id, case when kept > 0 then 'Images that were not delivered' else 'Generation did not finish' end)
      on conflict (run_id) where kind = 'refund' do nothing;
  end if;
  if r.kind = 'identity.directions' then perform fluid_private.engine_identity_close_job(r); end if;
  return r;
end $$;


ALTER FUNCTION fluid_private.finish_generation_run(p_run_id uuid, p_status text, p_error text) OWNER TO postgres;

