--
-- Name: guard_project_content_lifecycle(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.guard_project_content_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_link record; p public.projects;
begin
  for v_link in select NEW.project_id as project_id,NEW.owner_id as owner_id where TG_OP<>'DELETE'
    union select OLD.project_id,OLD.owner_id where TG_OP<>'INSERT'
  loop
    if v_link.project_id is null then continue; end if;
    select * into p from public.projects where id=v_link.project_id and owner_id=v_link.owner_id;
    if not found then raise exception 'project_not_found' using errcode='P0002'; end if;
    if p.deleted_at is not null or (p.deletion_requested_at is not null and
      (not fluid_private.project_deletion_worker(p.owner_id) or fluid_private.project_deletion_state(p.id,p.owner_id)='deleted')) then
      raise exception 'project_deleted' using errcode='PT409';
    end if;
  end loop;
  if TG_OP='DELETE' then return OLD; end if;
  return NEW;
end $$;


ALTER FUNCTION fluid_private.guard_project_content_lifecycle() OWNER TO postgres;

--
-- Name: guard_project_job_admission(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.guard_project_job_admission() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p public.projects;
begin
  if TG_OP='INSERT' or (NEW.project_id,NEW.owner_id) is distinct from (OLD.project_id,OLD.owner_id)
    or (NEW.state in ('queued','running','partial','cancel_requested','needs_reconciliation') and OLD.state in ('succeeded','failed','cancelled')) then
    select * into p from public.projects where id=NEW.project_id and owner_id=NEW.owner_id for share;
    if not found then raise exception 'project_not_found' using errcode='P0002'; end if;
    if p.deleted_at is not null or p.deletion_requested_at is not null then raise exception 'project_deleted' using errcode='PT409'; end if;
  elsif NEW.state in ('queued','running') and NEW.state is distinct from OLD.state then
    -- No new job->project lock on claim/retry. The stop transaction atomically
    -- locks/cancels every pre-existing job; INSERT uses the strong fence above.
    if exists(select 1 from public.projects where id=NEW.project_id and owner_id=NEW.owner_id
      and (deleted_at is not null or deletion_requested_at is not null)) then
      raise exception 'project_deleted' using errcode='PT409';
    end if;
  end if;
  return NEW;
end $$;


ALTER FUNCTION fluid_private.guard_project_job_admission() OWNER TO postgres;

--
-- Name: guard_project_lifecycle_change(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.guard_project_lifecycle_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if (NEW.deleted_at,NEW.deletion_requested_at) is distinct from (OLD.deleted_at,OLD.deletion_requested_at) then
    if current_setting('transaction_isolation') not in ('read committed','read uncommitted') then
      raise exception 'lifecycle_requires_read_committed' using errcode='40001';
    end if;
    if NEW.lifecycle_version<>OLD.lifecycle_version+1
      or (NEW.deleted_at is not null and NEW.deletion_requested_at is not null)
      or (NEW.deleted_at is not null and OLD.deleted_at is not null)
      or (NEW.deletion_requested_at is not null and OLD.deletion_requested_at is not null)
      or (to_jsonb(NEW)-array['deleted_at','deletion_requested_at','lifecycle_version']) is distinct from
        (to_jsonb(OLD)-array['deleted_at','deletion_requested_at','lifecycle_version']) then
      raise exception 'invalid_lifecycle_transition' using errcode='22023';
    end if;
    -- Preserve the original direct-delete contract for older clients. Only the
    -- new explicit stop intent is allowed to cancel work through the new RPC.
    if NEW.deleted_at is not null and (exists(select 1 from public.jobs where project_id=OLD.id and owner_id=OLD.owner_id
      and state in ('queued','running','partial','cancel_requested','needs_reconciliation'))
      or exists(select 1 from public.usage_reservations where project_id=OLD.id and owner_id=OLD.owner_id and state='active')) then
      raise exception 'project_busy' using errcode='PT409';
    end if;
  elsif NEW.lifecycle_version<>OLD.lifecycle_version then
    raise exception 'invalid_lifecycle_transition' using errcode='22023';
  elsif NEW is distinct from OLD and (OLD.deleted_at is not null or (OLD.deletion_requested_at is not null and
    (not fluid_private.project_deletion_worker(OLD.owner_id) or fluid_private.project_deletion_state(OLD.id,OLD.owner_id)='deleted'))) then
    raise exception 'project_deleted' using errcode='PT409';
  end if;
  return NEW;
end $$;


ALTER FUNCTION fluid_private.guard_project_lifecycle_change() OWNER TO postgres;

--
-- Name: guard_project_storage_lifecycle(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.guard_project_storage_lifecycle() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid(); v_link record; v_object record;
begin
  -- An unauthenticated authenticated-role request cannot gain information before
  -- the unchanged Storage RLS check denies it.
  if current_setting('role',true) in ('authenticated','anon') and v_owner is null then return NEW; end if;
  for v_object in select NEW.bucket_id as bucket_id,NEW.name as name
    union select OLD.bucket_id,OLD.name where TG_OP='UPDATE'
  loop
    if v_object.bucket_id is distinct from 'fluid-assets' then continue; end if;
    if split_part(v_object.name,'/',2)='home' then
      -- This row lock also serializes an upload with linking a staged Home file.
      -- Unlinked Home files remain usable; their later linkage is content-guarded.
      for v_link in select h.project_id,h.owner_id from public.home_attachments h
        where v_object.name=h.owner_id::text||'/home/'||h.id::text||'/'||h.blob_version_id::text
          and (v_owner is null or h.owner_id=v_owner) for share
      loop
        if v_link.project_id is not null then
          perform fluid_private.require_active_project(v_link.project_id,v_link.owner_id);
        end if;
      end loop;
    else
      for v_link in select v.project_id,v.owner_id from public.asset_versions v
        where v.storage_path=v_object.name and (v_owner is null or v.owner_id=v_owner)
        union select p.project_id,p.owner_id from public.logo_asset_publications p
        where v_object.name=p.owner_id::text||'/'||p.project_id::text||'/'||p.asset_id::text||'/'||p.version_id::text
          and (v_owner is null or p.owner_id=v_owner)
      loop
        perform fluid_private.require_active_project(v_link.project_id,v_link.owner_id);
      end loop;
    end if;
  end loop;
  return NEW;
end $$;


ALTER FUNCTION fluid_private.guard_project_storage_lifecycle() OWNER TO postgres;

--
-- Name: guided_interview_context(jsonb, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.guided_interview_context(p_value jsonb, p_events jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare t jsonb; a jsonb; x jsonb; ids text[]:='{}'; stages text[]:='{}'; option_ids text[];
 previous_revision integer:=0; revision integer; id text;
begin
 perform fluid_private.identity_conversation(coalesce(p_events,'[]'));
 if jsonb_typeof(p_value) is distinct from 'object' or p_value-array['version','stage','turns','answers']<>'{}'
  or not(p_value ?& array['version','stage','turns','answers']) or p_value->'version'<>'1'
  or coalesce(p_value->>'stage','') not in ('competitors','audience','positioning','personality','slogan','complete')
  or jsonb_typeof(p_value->'turns') is distinct from 'array' or jsonb_array_length(p_value->'turns')>48
  or jsonb_typeof(p_value->'answers') is distinct from 'array' or jsonb_array_length(p_value->'answers')>5
  or octet_length(fluid_private.standalone_compact(p_value))>32768 then
  raise exception 'invalid_guided_interview' using errcode='22023'; end if;
 for t in select value from jsonb_array_elements(p_value->'turns') loop
  if jsonb_typeof(t) is distinct from 'object' or t-array['id','userMessageId','stage','purpose','inputRevision']<>'{}'
   or not(t ?& array['id','userMessageId','stage','purpose','inputRevision'])
   or coalesce(t->>'stage','') not in ('competitors','audience','positioning','personality','slogan') or coalesce(t->>'purpose','') not in ('research','message','propose') then
   raise exception 'invalid_guided_interview' using errcode='22023'; end if;
  id:=fluid_private.identity_text(t->'id',1,128,false);
  revision:=fluid_private.identity_counter(t->'inputRevision');
  if revision<=previous_revision or id=any(ids) then raise exception 'invalid_guided_interview' using errcode='22023'; end if;
  previous_revision:=revision; ids:=array_append(ids,id);
  if t->'userMessageId'='null' then
   if t->>'purpose'<>'propose' then raise exception 'invalid_guided_interview' using errcode='22023'; end if;
  else
   perform fluid_private.identity_text(t->'userMessageId',1,128,false);
   if (t->>'purpose'='research' and t->>'stage'<>'competitors') or not exists(
    select 1 from jsonb_array_elements(coalesce(p_events,'[]')) e where e->>'kind'='user_message' and e->>'id'=t->>'userMessageId') then
    raise exception 'invalid_guided_interview' using errcode='22023'; end if;
  end if;
 end loop;
 for a in select value from jsonb_array_elements(p_value->'answers') loop
  if jsonb_typeof(a) is distinct from 'object' or a-array['stage','turnId','optionIds','customText','confirmedAt']<>'{}'
   or not(a ?& array['stage','turnId','optionIds','customText','confirmedAt'])
   or coalesce(a->>'stage','') not in ('competitors','audience','positioning','personality','slogan') or a->>'stage'=any(stages)
   or jsonb_typeof(a->'optionIds') is distinct from 'array' or jsonb_array_length(a->'optionIds')>20 then
   raise exception 'invalid_guided_interview' using errcode='22023'; end if;
  stages:=array_append(stages,a->>'stage');
  perform fluid_private.identity_text(a->'turnId',1,128,false);
  if not exists(select 1 from jsonb_array_elements(p_value->'turns') turn where turn->>'id'=a->>'turnId' and turn->>'stage'=a->>'stage') then
   raise exception 'invalid_guided_interview' using errcode='22023'; end if;
  option_ids:='{}';
  for x in select value from jsonb_array_elements(a->'optionIds') loop
   id:=fluid_private.identity_text(x,1,128,false);
   if id=any(option_ids) then raise exception 'invalid_guided_interview' using errcode='22023'; end if;
   option_ids:=array_append(option_ids,id);
  end loop;
  if a->'customText'<>'null' then perform fluid_private.identity_text(a->'customText',1,12000); end if;
  perform fluid_private.identity_time_key(fluid_private.identity_text(a->'confirmedAt',1,64,false));
 end loop;
 return p_value;
end $$;


ALTER FUNCTION fluid_private.guided_interview_context(p_value jsonb, p_events jsonb) OWNER TO postgres;

--
-- Name: home_attachment_immutable(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.home_attachment_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if tg_op='DELETE' then raise exception 'immutable_home_attachment' using errcode='55000'; end if;
 if (to_jsonb(new)-array['verified','project_id','project_revision']) is distinct from (to_jsonb(old)-array['verified','project_id','project_revision']) or (old.verified and not new.verified) or (old.project_id is not null and (new.project_id is distinct from old.project_id or new.project_revision is distinct from old.project_revision)) then raise exception 'immutable_home_attachment' using errcode='55000'; end if;
 return new;
end $$;


ALTER FUNCTION fluid_private.home_attachment_immutable() OWNER TO postgres;

--
-- Name: home_attachment_owner(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.home_attachment_owner() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r pg_catalog.pg_roles; result uuid;
begin
 result:=fluid_private.shared_http_context_owner('home'); if result is not null then return result; end if;
 select * into r from pg_catalog.pg_roles where rolname=session_user;
 if r.oid is null or not r.rolcanlogin or r.rolinherit or r.rolsuper or r.rolbypassrls or r.rolcreatedb or r.rolcreaterole or r.rolreplication or exists(select 1 from pg_catalog.pg_auth_members where member=r.oid) then raise exception 'home_principal_invalid' using errcode='42501'; end if;
 select owner_id into result from fluid_private.home_attachment_principals where role_name=session_user and role_oid=r.oid;
 if result is null then raise exception 'home_principal_unbound' using errcode='42501'; end if; return result;
end $$;


ALTER FUNCTION fluid_private.home_attachment_owner() OWNER TO postgres;

--
-- Name: home_attachments; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.home_attachments (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_id uuid NOT NULL,
    request_key uuid NOT NULL,
    input jsonb NOT NULL,
    blob_version_id uuid DEFAULT gen_random_uuid() NOT NULL,
    source_receipt_id uuid DEFAULT gen_random_uuid() NOT NULL,
    name text NOT NULL,
    mime_type text NOT NULL,
    content_hash text NOT NULL,
    byte_length bigint NOT NULL,
    verified boolean DEFAULT false NOT NULL,
    project_id uuid,
    project_revision integer,
    CONSTRAINT home_attachments_byte_length_check CHECK (((byte_length >= 1) AND (byte_length <= 10485760))),
    CONSTRAINT home_attachments_check CHECK (((project_id IS NULL) = (project_revision IS NULL))),
    CONSTRAINT home_attachments_check1 CHECK (((project_id IS NULL) OR (verified AND (project_revision = 1)))),
    CONSTRAINT home_attachments_content_hash_check CHECK ((content_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT home_attachments_input_check CHECK ((octet_length((input)::text) <= 32768)),
    CONSTRAINT home_attachments_mime_type_check CHECK ((mime_type = ANY (ARRAY['text/plain'::text, 'application/pdf'::text, 'image/png'::text, 'image/jpeg'::text]))),
    CONSTRAINT home_attachments_name_check CHECK (((length(name) >= 1) AND (length(name) <= 255)))
);

ALTER TABLE ONLY public.home_attachments FORCE ROW LEVEL SECURITY;


ALTER TABLE public.home_attachments OWNER TO postgres;

