CREATE TABLE public.identity_system_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    project_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    input_id uuid NOT NULL,
    source jsonb NOT NULL,
    components jsonb NOT NULL,
    board jsonb NOT NULL,
    production_files jsonb NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    created_at_text text NOT NULL,
    created_at_order numeric GENERATED ALWAYS AS (fluid_private.identity_time_key(created_at_text)) STORED,
    root_system_id uuid NOT NULL,
    base_system_id uuid,
    change_id uuid,
    CONSTRAINT identity_system_versions_board_check CHECK ((jsonb_typeof(board) = 'object'::text)),
    CONSTRAINT identity_system_versions_check CHECK (((created_at_text)::timestamp with time zone = created_at)),
    CONSTRAINT identity_system_versions_check1 CHECK (((((source ->> 'kind'::text) = 'generated'::text) AND (root_system_id = id) AND (base_system_id IS NULL) AND (change_id IS NULL)) OR (((source ->> 'kind'::text) = 'manual_edit'::text) AND (root_system_id <> id) AND (base_system_id IS NOT NULL) AND (base_system_id <> id) AND (change_id IS NOT NULL)))),
    CONSTRAINT identity_system_versions_components_check CHECK ((jsonb_typeof(components) = 'object'::text)),
    CONSTRAINT identity_system_versions_created_at_check CHECK (isfinite(created_at)),
    CONSTRAINT identity_system_versions_production_files_check CHECK (((jsonb_typeof(production_files) = 'array'::text) AND (jsonb_array_length(production_files) <= 48))),
    CONSTRAINT identity_system_versions_source_check CHECK (((jsonb_typeof(source) = 'object'::text) AND ((source ->> 'kind'::text) = ANY (ARRAY['generated'::text, 'manual_edit'::text]))))
);

