-- Name: invalidate_logo_subscription_readiness(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.invalidate_logo_subscription_readiness() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if tg_op='DELETE' or to_jsonb(old) is distinct from to_jsonb(new) then
  delete from fluid_private.logo_worker_readiness r using fluid_private.logo_runtime_policies p
   where p.owner_id=old.owner_id and p.subscription_policy->>'registrationId'=old.registration_id and r.owner_id=p.owner_id and r.operation=p.operation;
 end if;
 if tg_op='DELETE' then return old;end if;return new;
end $$;


ALTER FUNCTION fluid_private.invalidate_logo_subscription_readiness() OWNER TO postgres;

