-- Name: invalidate_strategy_readiness(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.invalidate_strategy_readiness() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if (new.policy,new.enabled) is distinct from (old.policy,old.enabled) then new.worker_ready_until := null; end if;
  return new;
end $$;


