--
-- Name: logo_append_brief(uuid, uuid, jsonb, uuid, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_append_brief(p_owner uuid, p_project uuid, p_brief jsonb, p_snapshot uuid, p_inputs jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare prior public.logo_stage_revisions; project_revision bigint; new_id uuid:=gen_random_uuid(); result jsonb; payload jsonb; item jsonb;
begin
 if not fluid_private.logo_brief_valid(p_brief-'sourceProjectRevision') or jsonb_typeof(p_inputs) is distinct from 'array' or jsonb_array_length(p_inputs)>100 then raise exception 'invalid_logo_brief' using errcode='22023'; end if;
 select current_revision into project_revision from public.projects where id=p_project and owner_id=p_owner;
 if not found then raise exception 'logo_project_not_found' using errcode='P0002'; end if;
 perform fluid_private.logo_snapshot_json(p_owner,p_project,p_snapshot);
 for item in select value from jsonb_array_elements(p_inputs) loop
  if not fluid_private.standalone_keys(item,array['stage','id','revision']) or not exists(select 1 from public.logo_stage_revisions r where r.id=(item->>'id')::uuid and r.owner_id=p_owner and r.project_id=p_project and r.stage=item->>'stage' and r.revision=(item->>'revision')::bigint) then
   raise exception 'invalid_logo_input_source' using errcode='55000'; end if;
 end loop;
 if (select count(*)<>count(distinct value->>'id') from jsonb_array_elements(p_inputs)) then raise exception 'duplicate_logo_input' using errcode='55000'; end if;
 select r.* into prior from public.logo_stage_heads h join public.logo_stage_revisions r on r.id=h.revision_id where h.project_id=p_project and h.owner_id=p_owner and h.stage='brief_references';
 -- Only the fixed restore branch supplies this field, copied from its actual
 -- immutable source row; browser brief schemas reject it. Retain earlier basis.
 if p_brief ? 'sourceProjectRevision' then
  if jsonb_typeof(p_brief->'sourceProjectRevision') is distinct from 'number' or not exists(select 1 from public.project_revisions r where r.project_id=p_project and r.owner_id=p_owner and to_jsonb(r.revision)=p_brief->'sourceProjectRevision') then
   raise exception 'invalid_logo_project_source' using errcode='55000'; end if;
  project_revision:=(p_brief->>'sourceProjectRevision')::bigint;
 end if;
 payload:=(p_brief-'sourceProjectRevision')||jsonb_build_object('referenceSnapshotId',p_snapshot,'sourceProjectRevision',project_revision);
 result:=jsonb_build_object('version',2,'id',new_id,'ownerId',p_owner,'projectId',p_project,'stage','brief_references','revision',coalesce(prior.revision,0)+1,'parentRevisionId',prior.id,
  'inputRevisions',p_inputs,'inputHash',encode(sha256(convert_to(jsonb_build_object('payload',payload,'inputs',p_inputs)::text,'UTF8')),'hex'),'payload',payload,
  'createdAt',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 insert into public.logo_workspaces(project_id,owner_id) values(p_project,p_owner) on conflict(project_id) do nothing;
 insert into public.logo_stage_revisions(id,project_id,owner_id,stage,revision,parent_revision_id,reference_snapshot_id,record)
  values(new_id,p_project,p_owner,'brief_references',coalesce(prior.revision,0)+1,prior.id,p_snapshot,result);
 insert into public.logo_stage_heads(project_id,owner_id,stage,revision_id) values(p_project,p_owner,'brief_references',new_id)
  on conflict(project_id,stage) do update set revision_id=excluded.revision_id;
 update public.logo_workspaces set revision=revision+1 where project_id=p_project and owner_id=p_owner;
 return result;
end $$;


ALTER FUNCTION fluid_private.logo_append_brief(p_owner uuid, p_project uuid, p_brief jsonb, p_snapshot uuid, p_inputs jsonb) OWNER TO postgres;

--
-- Name: logo_append_stage(uuid, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_append_stage(p_owner uuid, p_project uuid, p_stage text, p_payload jsonb, p_inputs jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare prior public.logo_stage_revisions;new_id uuid:=gen_random_uuid();result jsonb;item jsonb;next_workspace_revision bigint;
begin
 if not fluid_private.logo_stage_payload_valid(p_stage,p_payload) or jsonb_typeof(p_inputs) is distinct from 'array' or jsonb_array_length(p_inputs)>100 then raise exception 'invalid_logo_stage_payload' using errcode='22023';end if;
 perform 1 from public.projects where id=p_project and owner_id=p_owner for update;
 if not found then raise exception 'logo_project_not_found' using errcode='P0002';end if;
 select coalesce(max(w.revision),0)+1 into next_workspace_revision from public.logo_workspaces w where w.owner_id=p_owner and w.project_id=p_project;
 for item in select value from jsonb_array_elements(p_inputs) loop
  if not fluid_private.standalone_keys(item,array['stage','id','revision']) or not exists(select 1 from public.logo_stage_revisions r where r.owner_id=p_owner and r.project_id=p_project and r.id::text=item->>'id' and r.stage=item->>'stage' and to_jsonb(r.revision)=item->'revision') then raise exception 'invalid_logo_input_source' using errcode='55000';end if;
 end loop;
 if(select count(*)<>count(distinct value->>'id') from jsonb_array_elements(p_inputs)) then raise exception 'duplicate_logo_input' using errcode='55000';end if;
 select r.* into prior from public.logo_stage_heads h join public.logo_stage_revisions r on r.id=h.revision_id and r.owner_id=h.owner_id and r.project_id=h.project_id where h.owner_id=p_owner and h.project_id=p_project and h.stage=p_stage;
 result:=jsonb_build_object('version',2,'id',new_id,'ownerId',p_owner,'projectId',p_project,'stage',p_stage,'revision',coalesce(prior.revision,0)+1,'parentRevisionId',prior.id,'inputRevisions',p_inputs,'inputHash',encode(sha256(convert_to(jsonb_build_object('payload',p_payload,'inputs',p_inputs)::text,'UTF8')),'hex'),'payload',p_payload,'createdAt',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
 insert into public.logo_stage_revisions(id,project_id,owner_id,stage,revision,parent_revision_id,record,workspace_revision) values(new_id,p_project,p_owner,p_stage,coalesce(prior.revision,0)+1,prior.id,result,next_workspace_revision);
 insert into public.logo_workspaces(project_id,owner_id,revision) values(p_project,p_owner,1) on conflict(project_id) do update set revision=public.logo_workspaces.revision+1;
 insert into public.logo_stage_heads(project_id,owner_id,stage,revision_id) values(p_project,p_owner,p_stage,new_id) on conflict(project_id,stage) do update set revision_id=excluded.revision_id;
 return result;
end $$;


ALTER FUNCTION fluid_private.logo_append_stage(p_owner uuid, p_project uuid, p_stage text, p_payload jsonb, p_inputs jsonb) OWNER TO postgres;

--
-- Name: logo_apply(uuid, uuid, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_apply(p_owner uuid, p_project uuid, p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare b jsonb:=p_command->'body';method text:=p_command->>'method';existing public.logo_workspace_requests;workspace jsonb;target public.logo_stage_revisions;prior public.logo_stage_revisions;payload jsonb;inputs jsonb;revision jsonb;result jsonb;source jsonb;resolved jsonb;batches jsonb;vector jsonb;current_vector jsonb;approval_id uuid;approval jsonb;item jsonb;
begin
 -- Integration delta: serialize the cross-operation key guard with admission.
 if fluid_private.logo_uuid(b->'requestKey') then
  perform 1 from public.projects where id=p_project and owner_id=p_owner for update;
  if not found then raise exception 'logo_project_not_found' using errcode='P0002';end if;
  if to_regclass('public.logo_operation_rejections') is not null then
   if not exists(select 1 from public.logo_workspace_requests req where req.owner_id=p_owner and req.project_id=p_project and req.request_key=(b->>'requestKey')::uuid and req.method<>'startLogoProject') and exists(select 1 from public.logo_operation_rejections req where req.owner_id=p_owner and req.project_id=p_project and req.request_key=(b->>'requestKey')::uuid) then raise exception 'logo_request_conflict' using errcode='PT409';end if;
  end if;
 end if;
 if fluid_private.logo_uuid(b->'requestKey') and to_regclass('public.logo_operation_requests') is not null then
  if not exists(select 1 from public.logo_workspace_requests req where req.owner_id=p_owner and req.project_id=p_project and req.request_key=(b->>'requestKey')::uuid and req.method<>'startLogoProject') and exists(select 1 from public.logo_operation_requests req where req.owner_id=p_owner and req.project_id=p_project and req.request_key=(b->>'requestKey')::uuid) then raise exception 'logo_request_conflict' using errcode='PT409';end if;
 end if;
 if method in('saveLogoBrief','saveLogoReferences') or(method='restoreLogoStage' and b->>'stage'='brief_references') then return fluid_private.logo_apply_brief(p_owner,p_project,p_command);end if;
 if not fluid_private.logo_command_valid(p_command) then raise exception 'invalid_logo_command' using errcode='22023';end if;
 perform 1 from public.projects where id=p_project and owner_id=p_owner for update;
 if not found then raise exception 'logo_project_not_found' using errcode='P0002';end if;
 select * into existing from public.logo_workspace_requests req where req.owner_id=p_owner and req.project_id=p_project and req.request_key=(b->>'requestKey')::uuid and req.method<>'startLogoProject';
 if found then if existing.input is distinct from p_command then raise exception 'logo_request_conflict' using errcode='PT409';end if;return existing.receipt;end if;
 perform 1 from public.identity_reference_heads where owner_id=p_owner and project_id=p_project for update;
 perform 1 from public.identity_sessions where owner_id=p_owner and project_id=p_project for update;
 workspace:=fluid_private.logo_workspace_json(p_owner,p_project);
 if workspace->'heads' is distinct from b->'expected' then raise exception 'logo_head_conflict' using errcode='PT409';end if;
 if method in('selectLogoConcept','selectLogoRaster') then
  source:=case when method='selectLogoConcept' then jsonb_build_object('kind','concept','batchId',b->'batchId','slotId',b->'slotId','attemptId',b->'attemptId') else b->'source' end;
  resolved:=fluid_private.resolve_logo_raster_source(p_owner,p_project,source);
  if resolved->'source' is distinct from source or resolved#>>'{preview,publicationState}'<>'committed' then raise exception 'logo_raster_unavailable' using errcode='55000';end if;
  select r.* into prior from public.logo_stage_heads h join public.logo_stage_revisions r on r.id=h.revision_id where h.owner_id=p_owner and h.project_id=p_project and h.stage='concepts';
  batches:=coalesce(prior.record#>'{payload,batchIds}','[]'::jsonb);
  if source->>'kind'='concept' and not(batches ? (source->>'batchId')) then batches:=batches||jsonb_build_array(source->'batchId');end if;
  revision:=fluid_private.logo_append_stage(p_owner,p_project,'concepts',jsonb_build_object('batchIds',batches,'selected',source),resolved->'inputRevisions');
 elsif method='restoreLogoStage' then
  if b->>'stage' in('vector','refinements') and fluid_private.logo_asset_web_owner()<>p_owner then raise exception 'logo_principal_mismatch' using errcode='42501';end if;
  select * into target from public.logo_stage_revisions where id=(b->>'revisionId')::uuid and owner_id=p_owner and project_id=p_project and stage=b->>'stage';
  if not found then raise exception 'logo_revision_not_found' using errcode='P0002';end if;
  inputs:=target.record->'inputRevisions';payload:=target.record->'payload';
  if exists(select 1 from jsonb_array_elements(inputs) i left join public.logo_stage_heads h on h.owner_id=p_owner and h.project_id=p_project and h.stage=i->>'stage' where h.revision_id::text is distinct from i->>'id') and b->'acceptEarlierBasis'<>'true'::jsonb then raise exception 'logo_earlier_basis_requires_acknowledgement' using errcode='PT409';end if;
  if target.stage in('vector','refinements','directions') then payload:=jsonb_set(payload,'{approvalId}','null');end if;
  if target.stage='directions' then payload:=jsonb_set(payload,'{selectionId}','null');end if;
  if target.stage in('vector','refinements') and payload->'vectorRevisionId'<>'null'::jsonb then
   select record into vector from public.logo_vector_revisions where id=(payload->>'vectorRevisionId')::uuid and owner_id=p_owner and project_id=p_project;
   if vector is null then raise exception 'logo_vector_not_found' using errcode='P0002';end if;
   select v.record into current_vector from public.logo_vector_revisions v where v.owner_id=p_owner and v.project_id=p_project and v.id=fluid_private.logo_current_vector_id(p_owner,p_project);
   for item in select value from jsonb_array_elements(coalesce(current_vector->'locks','[]')) loop
    if not exists(select 1 from jsonb_array_elements(vector->'locks') target_lock where target_lock=item) then raise exception 'logo_restore_lock_conflict' using errcode='PT409';end if;
   end loop;
  end if;
  revision:=fluid_private.logo_append_stage(p_owner,p_project,target.stage,payload,inputs);
 elsif method='acceptLogoVector' then
  if fluid_private.logo_asset_web_owner()<>p_owner then raise exception 'logo_principal_mismatch' using errcode='42501';end if;
  select record into vector from public.logo_vector_revisions where id=(b->>'vectorRevisionId')::uuid and owner_id=p_owner and project_id=p_project;
  if vector is null then raise exception 'logo_vector_not_found' using errcode='P0002';end if;
  inputs:=vector->'inputRevisions';
  if exists(select 1 from jsonb_array_elements(inputs) i left join public.logo_stage_heads h on h.owner_id=p_owner and h.project_id=p_project and h.stage=i->>'stage' where h.revision_id::text is distinct from i->>'id') and b->'acceptEarlierBasis'<>'true'::jsonb then raise exception 'logo_earlier_basis_requires_acknowledgement' using errcode='PT409';end if;
  approval_id:=gen_random_uuid();revision:=fluid_private.logo_append_stage(p_owner,p_project,'vector',jsonb_build_object('vectorRevisionId',b->'vectorRevisionId','approvalId',approval_id),inputs);
  approval:=jsonb_build_object('id',approval_id,'ownerId',p_owner,'projectId',p_project,'vectorRevisionId',b->'vectorRevisionId','stageRevisionId',revision->'id','approvedAt',revision->'createdAt');
  insert into public.logo_approvals(id,owner_id,project_id,vector_revision_id,stage_revision_id,record) values(approval_id,p_owner,p_project,(b->>'vectorRevisionId')::uuid,(revision->>'id')::uuid,approval);
 else raise exception 'logo_producer_unavailable' using errcode='55000';end if;
 result:=jsonb_build_object('ownerId',p_owner,'projectId',p_project,'requestKey',b->'requestKey','revision',revision,'workspace',fluid_private.logo_workspace_json(p_owner,p_project));
 insert into public.logo_workspace_requests(project_id,owner_id,request_key,method,input,receipt) values(p_project,p_owner,(b->>'requestKey')::uuid,method,p_command,result);return result;
end $$;


ALTER FUNCTION fluid_private.logo_apply(p_owner uuid, p_project uuid, p_command jsonb) OWNER TO postgres;

--
-- Name: logo_apply_brief(uuid, uuid, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_apply_brief(p_owner uuid, p_project uuid, p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare b jsonb:=p_command->'body'; project public.projects; old public.logo_stage_revisions; target public.logo_stage_revisions; existing public.logo_workspace_requests;
 workspace jsonb; brief jsonb; snapshot_id uuid; snapshot_revision bigint; snapshot jsonb; selections jsonb; selection jsonb; item jsonb; refs jsonb:='[]'; inputs jsonb:='[]'; revision jsonb; result jsonb;
begin
 if not fluid_private.logo_command_valid(p_command) then raise exception 'invalid_logo_command' using errcode='22023'; end if;
 select * into project from public.projects where id=p_project and owner_id=p_owner for update;
 if not found then raise exception 'logo_project_not_found' using errcode='P0002'; end if;
 select * into existing from public.logo_workspace_requests where project_id=p_project and owner_id=p_owner and request_key=(b->>'requestKey')::uuid and method<>'startLogoProject';
 if found then
  if existing.input is distinct from p_command then raise exception 'logo_request_conflict' using errcode='PT409'; end if;
  return existing.receipt;
 end if;
 -- Existing source writers use the same project-first lock. Read their real heads.
 perform 1 from public.identity_reference_heads where project_id=p_project and owner_id=p_owner for update;
 perform 1 from public.identity_sessions where project_id=p_project and owner_id=p_owner for update;
 workspace:=fluid_private.logo_workspace_json(p_owner,p_project);
 if workspace->'heads' is distinct from b->'expected' then raise exception 'logo_head_conflict' using errcode='PT409'; end if;
 select r.* into old from public.logo_stage_heads h join public.logo_stage_revisions r on r.id=h.revision_id where h.project_id=p_project and h.owner_id=p_owner and h.stage='brief_references';
 if p_command->>'method'='restoreLogoStage' then
  if b->>'stage'<>'brief_references' then raise exception 'logo_producer_unavailable' using errcode='55000'; end if;
  select * into target from public.logo_stage_revisions where id=(b->>'revisionId')::uuid and owner_id=p_owner and project_id=p_project and stage='brief_references';
  if not found then raise exception 'logo_revision_not_found' using errcode='P0002'; end if;
  if ((target.record#>>'{payload,sourceProjectRevision}')::bigint<>project.current_revision
    or exists(select 1 from jsonb_array_elements(target.record->'inputRevisions') i left join public.logo_stage_heads h on h.project_id=p_project and h.owner_id=p_owner and h.stage=i->>'stage' where h.revision_id is distinct from (i->>'id')::uuid))
   and b->'acceptEarlierBasis'<>'true'::jsonb then raise exception 'logo_earlier_basis_requires_acknowledgement' using errcode='PT409'; end if;
  brief:=(target.record->'payload')-'referenceSnapshotId'; snapshot_id:=target.reference_snapshot_id;
  -- Brief has no generated inputs. Preserve its original dependency set on restore.
  inputs:=target.record->'inputRevisions';
 elsif p_command->>'method'='saveLogoBrief' then
  brief:=b->'brief'; snapshot_id:=old.reference_snapshot_id;
 else
  if old.id is null then raise exception 'logo_brief_required' using errcode='PT409'; end if;
  brief:=(old.record->'payload')-array['referenceSnapshotId','sourceProjectRevision']; selections:=b->'selections';
  for selection in select value from jsonb_array_elements(selections) loop
   select jsonb_build_object('referenceId',s.reference_id,'asset',jsonb_build_object('ownerId',s.owner_id,'projectId',s.project_id,'assetId',s.asset_id,'versionId',s.version_id,'contentHash',v.content_hash),
    'sourceKind',s.source_kind,'aspects',selection->'aspects','rightsEvidenceId',s.rights_evidence_id) into item
   from public.logo_reference_sources s join public.asset_versions v on v.id=s.version_id and v.asset_id=s.asset_id and v.project_id=s.project_id and v.owner_id=s.owner_id
   join public.assets a on a.id=s.asset_id and a.project_id=s.project_id and a.owner_id=s.owner_id
   where s.reference_id=(selection->>'referenceId')::uuid and s.project_id=p_project and s.owner_id=p_owner and s.content_hash=v.content_hash and a.purpose='reference_media';
   if item is null then raise exception 'logo_reference_source_unavailable' using errcode='P0002'; end if;
   refs:=refs||jsonb_build_array(item);
  end loop;
  snapshot_id:=null;
 end if;
 if snapshot_id is null then
  snapshot_id:=gen_random_uuid();
  select coalesce(max(rs.revision),0)+1 into snapshot_revision from public.logo_reference_snapshots rs where rs.project_id=p_project and rs.owner_id=p_owner;
  snapshot:=jsonb_build_object('version',2,'id',snapshot_id,'ownerId',p_owner,'projectId',p_project,'revision',snapshot_revision,'references',refs);
  insert into public.logo_reference_snapshots(id,project_id,owner_id,revision,snapshot) values(snapshot_id,p_project,p_owner,snapshot_revision,snapshot);
 end if;
 revision:=fluid_private.logo_append_brief(p_owner,p_project,brief,snapshot_id,inputs);
 result:=jsonb_build_object('ownerId',p_owner,'projectId',p_project,'requestKey',b->'requestKey','revision',revision,'workspace',fluid_private.logo_workspace_json(p_owner,p_project));
 insert into public.logo_workspace_requests(project_id,owner_id,request_key,method,input,receipt) values(p_project,p_owner,(b->>'requestKey')::uuid,p_command->>'method',p_command,result);
 return result;
end $$;


ALTER FUNCTION fluid_private.logo_apply_brief(p_owner uuid, p_project uuid, p_command jsonb) OWNER TO postgres;

--
-- Name: logo_approved_deliverable_sources(uuid, uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_approved_deliverable_sources(p_owner uuid, p_project uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare w jsonb;logo jsonb;direction_stage jsonb;selection jsonb;approval jsonb;palette jsonb;typography jsonb;graphics jsonb;fonts jsonb;inputs jsonb;brand text;
begin
 w:=fluid_private.logo_workspace_json(p_owner,p_project);
 if w->'approvedLogo' is null or w->'approvedLogo'='null' then raise exception 'logo_approval_required' using errcode='PT409';end if;
 if exists(select 1 from jsonb_array_elements(w->'staleStages') s where s->>'stage' in('vector','directions')) then raise exception 'identity_approval_stale' using errcode='PT409';end if;
 select record into logo from public.logo_vector_revisions where id=(w#>>'{approvedLogo,vectorRevisionId}')::uuid and owner_id=p_owner and project_id=p_project;
 select record into direction_stage from public.logo_stage_revisions where id=(w#>>'{stages,directions,id}')::uuid and owner_id=p_owner and project_id=p_project;
 select record into selection from public.logo_direction_records where id=(direction_stage#>>'{payload,selectionId}')::uuid and owner_id=p_owner and project_id=p_project and kind='selection';
 select record into approval from public.logo_direction_records where id=(direction_stage#>>'{payload,approvalId}')::uuid and owner_id=p_owner and project_id=p_project and kind='approval';
 if logo is null or selection is null or approval is null or selection->'approvedLogoId' is distinct from w#>'{approvedLogo,id}' or approval->'approvedLogoId' is distinct from w#>'{approvedLogo,id}' or approval->'directionSelectionId' is distinct from selection->'id' or approval->'consistencyHash' is distinct from selection#>'{consistency,hash}' then raise exception 'identity_approval_required' using errcode='PT409';end if;
 select record into palette from public.logo_direction_records where id=(selection->>'paletteVersionId')::uuid and owner_id=p_owner and project_id=p_project and kind='palette';
 select record into typography from public.logo_direction_records where id=(selection->>'typographyVersionId')::uuid and owner_id=p_owner and project_id=p_project and kind='typography';
 select record into graphics from public.logo_direction_records where id=(selection->>'graphicsVersionId')::uuid and owner_id=p_owner and project_id=p_project and kind='graphics';
 if palette is null or typography is null or graphics is null or exists(select 1 from jsonb_array_elements(jsonb_build_array(palette,typography,graphics)) r where r->'approvedLogoId' is distinct from w#>'{approvedLogo,id}') then raise exception 'identity_components_missing' using errcode='P0002';end if;
 select coalesce(jsonb_agg(record order by record_id),'[]') into fonts from public.logo_font_records f where owner_id=p_owner and project_id=p_project and exists(select 1 from jsonb_array_elements(typography->'styles') s where s->>'fontVersionId'=f.record_id::text);
 if exists(select 1 from jsonb_array_elements(typography->'styles') s where not exists(select 1 from jsonb_array_elements(fonts) f where f->'id'=s->'fontVersionId')) or jsonb_array_length(fonts)>100 then raise exception 'identity_font_sources_missing' using errcode='P0002';end if;
 select record#>>'{payload,name}' into brand from public.logo_stage_revisions where id=(w#>>'{stages,brief_references,id}')::uuid and owner_id=p_owner and project_id=p_project;
 if brand is null or char_length(brand) not between 1 and 200 then raise exception 'brand_name_required' using errcode='55000';end if;
 select jsonb_agg(jsonb_build_object('stage',r.stage,'id',r.id,'revision',r.revision) order by r.stage) into inputs from public.logo_stage_revisions r where r.owner_id=p_owner and r.project_id=p_project and r.id in((w#>>'{stages,brief_references,id}')::uuid,(w#>>'{approvedLogo,stageRevisionId}')::uuid,(direction_stage->>'id')::uuid);
 if jsonb_array_length(inputs)<>3 then raise exception 'export_basis_missing' using errcode='55000';end if;
 return jsonb_build_object('ownerId',p_owner,'projectId',p_project,'brandName',brand,'heads',w->'heads','logo',logo,'logoApproval',w->'approvedLogo','directionSelection',selection,'directionApproval',approval,'palette',palette,'typography',typography,'graphics',graphics,'fonts',fonts,'inputRevisions',inputs);
end $$;


ALTER FUNCTION fluid_private.logo_approved_deliverable_sources(p_owner uuid, p_project uuid) OWNER TO postgres;

--
-- Name: shared_logo_text_policy_valid(jsonb, text); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.shared_logo_text_policy_valid(p jsonb, p_kind text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$declare k text; n numeric; keys text[]; begin
 keys:=array['version','billingMode','spendControl','handlerVersion','adapterVersion','model','pricingVersion','serviceTier','maxInputTokens','maxOutputTokens','maxInputBytes','maxOutputBytes','maxStreamBytes','deadlineMs','maxTools','inputMicrousdPerMillionTokens','cachedInputMicrousdPerMillionTokens','cacheWriteMicrousdPerMillionTokens','outputMicrousdPerMillionTokens'];
 if p_kind='proposal' then keys:=array_append(keys,'schemaVersion'); elsif p_kind<>'directions' then return false; end if;
 if not fluid_private.standalone_keys(p,keys) or p->>'billingMode' is distinct from 'openai_api' or p->>'spendControl' is distinct from 'uncapped'
  or p->>'model' is distinct from 'gpt-6.1-sol' or p->>'pricingVersion' is distinct from '2026-10-03' or p->>'serviceTier' is distinct from 'default'
  or p->'maxTools' is distinct from '0'::jsonb or p->'inputMicrousdPerMillionTokens' is distinct from '2000000'::jsonb
  or p->'cachedInputMicrousdPerMillionTokens' is distinct from '100000'::jsonb or p->'cacheWriteMicrousdPerMillionTokens' is distinct from '2500000'::jsonb
  or p->'outputMicrousdPerMillionTokens' is distinct from '10000000'::jsonb then return false; end if;
 if p_kind='directions' then
  if p->'version' is distinct from '1'::jsonb or p->>'handlerVersion' is distinct from 'logo-directions-api-v1' or p->>'adapterVersion' is distinct from 'logo-directions-openai-v1' then return false; end if;
 else
  if p->'version' is distinct from '2'::jsonb or p->>'handlerVersion' is distinct from 'logo-vector-propose-v1' or p->>'adapterVersion' is distinct from 'logo-vector-propose-api-uncapped-v2'
   or p->>'schemaVersion' is distinct from 'logo-vector-proposal-v1' then return false; end if;
 end if;
 foreach k in array array['maxInputTokens','maxOutputTokens','maxInputBytes','maxOutputBytes','maxStreamBytes','deadlineMs'] loop
  if jsonb_typeof(p->k) is distinct from 'number' then return false; end if; n:=(p->>k)::numeric;
  if trunc(n)<>n or n<(case when k in('maxInputBytes','maxOutputBytes','maxStreamBytes') then 1024 when k='deadlineMs' then 1000 else 1 end)
   or n>(case k when 'maxInputTokens' then 32768 when 'maxOutputTokens' then 4096 when 'maxInputBytes' then 131072 when 'maxOutputBytes' then 32768 when 'maxStreamBytes' then 2097152 when 'deadlineMs' then 240000 end) then return false; end if;
 end loop; return true;
exception when others then return false;
end $$;


ALTER FUNCTION fluid_private.shared_logo_text_policy_valid(p jsonb, p_kind text) OWNER TO postgres;

--
-- Name: valid_logo_directions_subscription_policy(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.valid_logo_directions_subscription_policy(p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare lim jsonb;k text;n numeric;lo integer;hi integer;
begin
 if fluid_private.standalone_keys(p,array['version','billingMode','handlerVersion','adapterVersion','registrationId','model','apiCharge','limits']) is distinct from true
  or p->'version' is distinct from '1'::jsonb or p->>'billingMode' is distinct from 'chatgpt_subscription'
  or p->>'handlerVersion' is distinct from 'logo-directions-v1' or p->>'adapterVersion' is distinct from 'logo-directions-chatgpt-v1'
  or p->>'apiCharge' is distinct from 'verified_zero'
  or jsonb_typeof(p->'registrationId') is distinct from 'string' or length(p->>'registrationId') not between 1 and 200 or p->>'registrationId' !~ '^[A-Za-z0-9_-]+$'
  or jsonb_typeof(p->'model') is distinct from 'string' or length(p->>'model') not between 1 and 150 or p->>'model' !~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$' then return false;end if;
 lim:=p->'limits';
 if fluid_private.standalone_keys(lim,array['maxInputBytes','maxOutputBytes','maxStreamBytes','deadlineMs','maxObservedWebSearchCalls','maxRequestsPerHour','maxQueuedJobs']) is distinct from true then return false;end if;
 foreach k in array array['maxInputBytes','maxOutputBytes','maxStreamBytes','deadlineMs','maxObservedWebSearchCalls','maxRequestsPerHour','maxQueuedJobs'] loop
  if jsonb_typeof(lim->k) is distinct from 'number' then return false;end if;n:=(lim->>k)::numeric;
  lo:=case k when 'maxInputBytes' then 1024 when 'maxOutputBytes' then 1024 when 'maxStreamBytes' then 1024 when 'deadlineMs' then 1000 when 'maxObservedWebSearchCalls' then 0 else 1 end;
  hi:=case k when 'maxInputBytes' then 131072 when 'maxOutputBytes' then 262144 when 'maxStreamBytes' then 2097152 when 'deadlineMs' then 240000 when 'maxObservedWebSearchCalls' then 0 when 'maxRequestsPerHour' then 100 else 10 end;
  if n<>trunc(n) or n not between lo and hi then return false;end if;
 end loop;return true;
end $_$;


ALTER FUNCTION fluid_private.valid_logo_directions_subscription_policy(p jsonb) OWNER TO postgres;

--
-- Name: jobs; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.jobs (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_id uuid NOT NULL,
    project_id uuid NOT NULL,
    operation text NOT NULL,
    input_revision integer NOT NULL,
    input_hash text NOT NULL,
    input jsonb NOT NULL,
    plan_manifest jsonb,
    plan_fingerprint text,
    plan_registered_at timestamp with time zone,
    idempotency_key text NOT NULL,
    state text DEFAULT 'queued'::text NOT NULL,
    progress integer DEFAULT 0 NOT NULL,
    lease_token uuid,
    lease_expires_at timestamp with time zone,
    worker_id text,
    attempts integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 3 NOT NULL,
    reserved_cost_microusd bigint NOT NULL,
    actual_cost_microusd bigint DEFAULT 0 NOT NULL,
    cancel_requested_at timestamp with time zone,
    error_code text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    finished_at timestamp with time zone,
    billing_mode text DEFAULT 'openai_api'::text NOT NULL,
    policy_identity text,
    project_deletion_requested_at timestamp with time zone,
    CONSTRAINT jobs_actual_cost_microusd_check CHECK ((actual_cost_microusd >= 0)),
    CONSTRAINT jobs_billing_mode_check CHECK ((billing_mode = ANY (ARRAY['openai_api'::text, 'chatgpt_subscription'::text]))),
    CONSTRAINT jobs_check CHECK (((attempts >= 0) AND (attempts <= max_attempts))),
    CONSTRAINT jobs_check1 CHECK ((((plan_manifest IS NULL) = (plan_fingerprint IS NULL)) AND ((plan_manifest IS NULL) = (plan_registered_at IS NULL)))),
    CONSTRAINT jobs_check2 CHECK (((lease_token IS NULL) = (lease_expires_at IS NULL))),
    CONSTRAINT jobs_check3 CHECK (((state = ANY (ARRAY['running'::text, 'cancel_requested'::text])) = (lease_token IS NOT NULL))),
    CONSTRAINT jobs_error_code_check CHECK (((error_code IS NULL) OR (error_code ~ '^[a-z][a-z0-9_]{0,79}$'::text))),
    CONSTRAINT jobs_idempotency_key_check CHECK (((length(idempotency_key) >= 1) AND (length(idempotency_key) <= 200))),
    CONSTRAINT jobs_input_check CHECK (((jsonb_typeof(input) = 'object'::text) AND (octet_length((input)::text) <= 131072))),
    CONSTRAINT jobs_input_hash_check CHECK ((input_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT jobs_max_attempts_check CHECK (((max_attempts >= 1) AND (max_attempts <= 10))),
    CONSTRAINT jobs_operation_check CHECK (((length(operation) >= 1) AND (length(operation) <= 100))),
    CONSTRAINT jobs_plan_fingerprint_check CHECK (((plan_fingerprint IS NULL) OR (plan_fingerprint ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT jobs_progress_check CHECK (((progress >= 0) AND (progress <= 100))),
    CONSTRAINT jobs_project_deletion_requested_at_check CHECK (((project_deletion_requested_at IS NULL) OR isfinite(project_deletion_requested_at))),
    CONSTRAINT jobs_reserved_cost_microusd_check CHECK (((reserved_cost_microusd >= 0) AND (reserved_cost_microusd <= '9007199254740991'::bigint))),
    CONSTRAINT jobs_state_check CHECK ((state = ANY (ARRAY['queued'::text, 'running'::text, 'partial'::text, 'cancel_requested'::text, 'cancelled'::text, 'succeeded'::text, 'failed'::text, 'needs_reconciliation'::text]))),
    CONSTRAINT logo_subscription_job_scope CHECK (((operation <> ALL (ARRAY['identity.logo_concept'::text, 'identity.logo_refine'::text, 'identity.logo_vectorize'::text, 'identity.logo_directions'::text, 'identity.logo_export'::text])) OR ((((billing_mode = 'openai_api'::text) AND (NOT (input ? 'billingMode'::text)) AND (NOT (input ? 'policy'::text))) OR ((operation = 'identity.logo_directions'::text) AND (billing_mode = 'chatgpt_subscription'::text) AND fluid_private.valid_logo_directions_subscription_policy((input -> 'policy'::text)) AND ((input ->> 'policyIdentity'::text) = policy_identity) AND ((input ->> 'handlerVersion'::text) = 'logo-directions-v1'::text))) IS TRUE) OR ((operation = 'identity.logo_directions'::text) AND (billing_mode = 'openai_api'::text) AND ((input -> 'version'::text) = '3'::jsonb) AND ((input ->> 'spendControl'::text) = 'uncapped'::text) AND fluid_private.shared_logo_text_policy_valid((input -> 'apiPolicy'::text), 'directions'::text)) OR COALESCE(((operation = ANY (ARRAY['identity.logo_concept'::text, 'identity.logo_refine'::text])) AND (billing_mode = 'openai_api'::text) AND (policy_identity IS NULL) AND ((input -> 'version'::text) = '3'::jsonb) AND ((input ->> 'billingMode'::text) = 'openai_api'::text) AND ((input ->> 'spendControl'::text) = 'uncapped'::text) AND (reserved_cost_microusd = 0) AND (max_attempts = 1)), false))),
    CONSTRAINT subscription_job_input CHECK (((billing_mode <> 'chatgpt_subscription'::text) OR ((NOT ((input ->> 'billingMode'::text) IS DISTINCT FROM 'chatgpt_subscription'::text)) AND (reserved_cost_microusd = 0) AND (actual_cost_microusd = 0) AND (max_attempts = 1)))),
    CONSTRAINT subscription_policy_identity CHECK ((((billing_mode = 'openai_api'::text) AND (policy_identity IS NULL)) OR ((billing_mode = 'chatgpt_subscription'::text) AND (policy_identity IS NOT NULL) AND (policy_identity ~ '^[0-9a-f]{64}$'::text) AND (NOT (policy_identity IS DISTINCT FROM encode(sha256(convert_to(((input -> 'policy'::text))::text, 'UTF8'::name)), 'hex'::text))))))
);

ALTER TABLE ONLY public.jobs FORCE ROW LEVEL SECURITY;


ALTER TABLE public.jobs OWNER TO postgres;

--
-- Name: logo_asset_job(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_asset_job(p_owner uuid, p_project uuid, p_job uuid, p_lease uuid) RETURNS public.jobs
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare j public.jobs;
begin
 select * into j from public.jobs where id=p_job and owner_id=p_owner and project_id=p_project for update;
 if not found or j.lease_token is distinct from p_lease or j.lease_expires_at<=clock_timestamp() or j.state not in('running','cancel_requested') or j.operation not in('identity.logo_concept','identity.logo_refine','identity.logo_vectorize','identity.logo_directions','identity.logo_export') then raise exception 'logo_lease_invalid' using errcode='55000';end if;return j;
end $$;


ALTER FUNCTION fluid_private.logo_asset_job(p_owner uuid, p_project uuid, p_job uuid, p_lease uuid) OWNER TO postgres;

--
-- Name: logo_asset_publications; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.logo_asset_publications (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_id uuid NOT NULL,
    project_id uuid NOT NULL,
    request_key uuid NOT NULL,
    request jsonb NOT NULL,
    asset_id uuid DEFAULT gen_random_uuid() NOT NULL,
    version_id uuid DEFAULT gen_random_uuid() NOT NULL,
    content_hash text NOT NULL,
    mime_type text NOT NULL,
    byte_length bigint NOT NULL,
    purpose text NOT NULL,
    source_receipt_id uuid NOT NULL,
    rights_evidence_id uuid,
    source_kind text NOT NULL,
    state text DEFAULT 'reserved'::text NOT NULL,
    verification jsonb,
    job_id uuid,
    lease_token uuid,
    input_revision integer NOT NULL,
    input_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT logo_asset_publications_byte_length_check CHECK (((byte_length >= 1) AND (byte_length <= 52428800))),
    CONSTRAINT logo_asset_publications_check CHECK (((job_id IS NULL) = (lease_token IS NULL))),
    CONSTRAINT logo_asset_publications_check1 CHECK (((state = 'reserved'::text) = (verification IS NULL))),
    CONSTRAINT logo_asset_publications_content_hash_check CHECK ((content_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT logo_asset_publications_purpose_check CHECK ((purpose = ANY (ARRAY['brand_asset'::text, 'reference_media'::text, 'input_attachment'::text]))),
    CONSTRAINT logo_asset_publications_request_check CHECK ((octet_length((request)::text) <= 32768)),
    CONSTRAINT logo_asset_publications_state_check CHECK ((state = ANY (ARRAY['reserved'::text, 'staged'::text, 'committed'::text])))
);

ALTER TABLE ONLY public.logo_asset_publications FORCE ROW LEVEL SECURITY;


ALTER TABLE public.logo_asset_publications OWNER TO postgres;

--
-- Name: logo_asset_receipt(public.logo_asset_publications); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_asset_receipt(r public.logo_asset_publications) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
begin
 if r.verification is null or r.state='reserved' then raise exception 'logo_asset_not_verified' using errcode='55000';end if;
 return (fluid_private.logo_asset_reservation(r)-array['requestKey','storagePath','mimeType','byteLength'])||jsonb_build_object('verification',r.verification);
end $$;


ALTER FUNCTION fluid_private.logo_asset_receipt(r public.logo_asset_publications) OWNER TO postgres;

--
-- Name: logo_asset_reservation(public.logo_asset_publications); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_asset_reservation(r public.logo_asset_publications) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select jsonb_build_object('id',r.id,'requestKey',r.request_key,'reference',jsonb_build_object('ownerId',r.owner_id,'projectId',r.project_id,'assetId',r.asset_id,'versionId',r.version_id,'contentHash',r.content_hash),
 'storagePath',r.owner_id::text||'/'||r.project_id::text||'/'||r.asset_id::text||'/'||r.version_id::text,'mimeType',r.mime_type,'byteLength',r.byte_length,'purpose',r.purpose,'sourceReceiptId',r.source_receipt_id,'rightsEvidenceId',r.rights_evidence_id,'publicationState',case when r.state='committed' then 'committed' else 'staged' end)
$$;


ALTER FUNCTION fluid_private.logo_asset_reservation(r public.logo_asset_publications) OWNER TO postgres;

--
-- Name: logo_asset_web_owner(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_asset_web_owner() RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r pg_catalog.pg_roles; result uuid;
begin
 result:=fluid_private.shared_logo_http_context_owner('logo'); if result is not null then return result; end if;
 select * into r from pg_catalog.pg_roles where rolname=session_user;
 if r.oid is null or not r.rolcanlogin or r.rolsuper or r.rolinherit or r.rolcreatedb or r.rolcreaterole or r.rolreplication or r.rolbypassrls or exists(select 1 from pg_catalog.pg_auth_members where member=r.oid) then raise exception 'logo_web_principal_invalid' using errcode='42501';end if;
 select owner_id into result from fluid_private.logo_asset_web_principals where role_name=session_user and role_oid=r.oid;
 if result is null then raise exception 'logo_web_principal_unbound' using errcode='42501';end if;return result;
end $$;


ALTER FUNCTION fluid_private.logo_asset_web_owner() OWNER TO postgres;

--
-- Name: logo_base_command_valid(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_base_command_valid(v jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare b jsonb; e jsonb; item jsonb; aspect jsonb; k text; n numeric;
begin
 if not fluid_private.standalone_keys(v,array['method','body']) or octet_length(v::text)>32768 then return false; end if;
 b:=v->'body'; e:=b->'expected';
 if not fluid_private.logo_uuid(b->'requestKey') or not fluid_private.standalone_keys(e,array['projectRevision','referenceRevision','preferencesRevision','workspaceRevision','stageRevisions'])
  or not fluid_private.standalone_keys(e->'stageRevisions',array['brief_references','concepts','vector','refinements','directions','deliverables']) then return false; end if;
 for k,item in select key,value from jsonb_each(e-'stageRevisions') union all select key,value from jsonb_each(e->'stageRevisions') loop
  if jsonb_typeof(item) is distinct from 'number' then return false; end if;
  n:=(item#>>'{}')::numeric;
  if n<>trunc(n) or n<(case when k='projectRevision' then 1 else 0 end) or n>9007199254740991 then return false; end if;
 end loop;
 case v->>'method'
 when 'saveLogoBrief' then
  return fluid_private.standalone_keys(b,array['requestKey','expected','brief']) and fluid_private.logo_brief_valid(b->'brief');
 when 'saveLogoReferences' then
  if not fluid_private.standalone_keys(b,array['requestKey','expected','selections']) or jsonb_typeof(b->'selections') is distinct from 'array' then return false; end if;
  if jsonb_array_length(b->'selections')>100 or (select count(*)<>count(distinct value->>'referenceId') from jsonb_array_elements(b->'selections')) then return false; end if;
  for item in select value from jsonb_array_elements(b->'selections') loop
   if not fluid_private.standalone_keys(item,array['referenceId','aspects']) or not fluid_private.logo_uuid(item->'referenceId') or jsonb_typeof(item->'aspects') is distinct from 'array' then return false; end if;
   if jsonb_array_length(item->'aspects') not between 1 and 4 or (select count(*)<>count(distinct value) from jsonb_array_elements(item->'aspects')) then return false; end if;
   for aspect in select value from jsonb_array_elements(item->'aspects') loop
    if jsonb_typeof(aspect) is distinct from 'string' or (aspect#>>'{}') not in ('lettering','shape','composition','overall_feel') then return false; end if;
   end loop;
  end loop;
  return true;
 when 'restoreLogoStage' then
  return fluid_private.standalone_keys(b,array['requestKey','expected','stage','revisionId','acceptEarlierBasis'])
   and b->>'stage' in ('brief_references','concepts','vector','refinements','directions','deliverables')
   and fluid_private.logo_uuid(b->'revisionId') and jsonb_typeof(b->'acceptEarlierBasis')='boolean';
 else return false;
 end case;
exception when others then return false;
end $$;


ALTER FUNCTION fluid_private.logo_base_command_valid(v jsonb) OWNER TO postgres;

--
-- Name: logo_brief_same_except_types(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_brief_same_except_types(p_owner uuid, p_project uuid, p_left uuid, p_right uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select coalesce((select (a.record->'payload')-'logoTypes'=(b.record->'payload')-'logoTypes' and a.record->'inputRevisions'=b.record->'inputRevisions'
  from public.logo_stage_revisions a,public.logo_stage_revisions b
  where a.id=p_left and b.id=p_right and a.owner_id=p_owner and b.owner_id=p_owner and a.project_id=p_project and b.project_id=p_project
   and a.stage='brief_references' and b.stage='brief_references'),false)
$$;


ALTER FUNCTION fluid_private.logo_brief_same_except_types(p_owner uuid, p_project uuid, p_left uuid, p_right uuid) OWNER TO postgres;

--
-- Name: logo_brief_valid(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_brief_valid(v jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare k text; item jsonb;
begin
 if not fluid_private.standalone_keys(v,array['name','activity','audience','personality','logoTypes']) or octet_length(v::text)>32768 then return false; end if;
 foreach k in array array['name','activity','audience','personality'] loop
  -- Installed Zod 4.6.5 string min/max count Unicode code points. Do not trim saved spelling.
  if jsonb_typeof(v->k) is distinct from 'string' or length(v->>k)>(case when k='name' then 200 else 4000 end) then return false; end if;
 end loop;
 if fluid_private.idea_trim(v->>'name')='' or jsonb_typeof(v->'logoTypes') is distinct from 'array' then return false; end if;
 if jsonb_array_length(v->'logoTypes') not between 1 and 7 or (select count(*)<>count(distinct value) from jsonb_array_elements(v->'logoTypes')) then return false; end if;
 for item in select value from jsonb_array_elements(v->'logoTypes') loop
  if jsonb_typeof(item) is distinct from 'string' or (item#>>'{}') not in ('wordmark','lettermark_monogram','pictorial','abstract','combination','emblem','mascot') then return false; end if;
 end loop;
 return true;
exception when others then return false;
end $$;


ALTER FUNCTION fluid_private.logo_brief_valid(v jsonb) OWNER TO postgres;

--
-- Name: logo_command_valid(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_command_valid(v jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare b jsonb:=v->'body';method text:=v->>'method';source jsonb;check_command jsonb;
begin
 if method in('saveLogoBrief','saveLogoReferences','restoreLogoStage') then return fluid_private.logo_base_command_valid(v);end if;
 -- Reuse exact existing key/head/number validation without widening that codec.
 check_command:=jsonb_build_object('method','restoreLogoStage','body',jsonb_build_object('requestKey',b->'requestKey','expected',b->'expected','stage','concepts','revisionId','00000000-0000-4000-8000-000000000001','acceptEarlierBasis',false));
 if not fluid_private.standalone_keys(v,array['method','body']) or octet_length(v::text)>32768 or not fluid_private.logo_base_command_valid(check_command) then return false;end if;
 case method
 when 'selectLogoConcept' then return fluid_private.standalone_keys(b,array['requestKey','expected','batchId','slotId','attemptId']) and fluid_private.logo_uuid(b->'batchId') and fluid_private.logo_uuid(b->'slotId') and fluid_private.logo_uuid(b->'attemptId');
 when 'selectLogoRaster' then
  source:=b->'source';
  if not fluid_private.standalone_keys(b,array['requestKey','expected','source']) then return false;end if;
  return case when source->>'kind'='concept' then fluid_private.standalone_keys(source,array['kind','batchId','slotId','attemptId']) and fluid_private.logo_uuid(source->'batchId') and fluid_private.logo_uuid(source->'slotId') and fluid_private.logo_uuid(source->'attemptId')
   when source->>'kind'='refinement' then fluid_private.standalone_keys(source,array['kind','rasterRevisionId']) and fluid_private.logo_uuid(source->'rasterRevisionId') else false end;
 when 'acceptLogoVector' then return fluid_private.standalone_keys(b,array['requestKey','expected','vectorRevisionId','acceptEarlierBasis']) and fluid_private.logo_uuid(b->'vectorRevisionId') and jsonb_typeof(b->'acceptEarlierBasis')='boolean';
 else return false;
 end case;
exception when others then return false;
end $$;


ALTER FUNCTION fluid_private.logo_command_valid(v jsonb) OWNER TO postgres;

--
-- Name: logo_commit_asset(public.logo_asset_publications); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_commit_asset(r public.logo_asset_publications) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if r.state='reserved' or r.verification is null then raise exception 'logo_asset_not_verified' using errcode='55000';end if;
 if r.state<>'committed' then
  insert into public.assets(id,owner_id,project_id,kind,purpose) values(r.asset_id,r.owner_id,r.project_id,'logo_'||r.source_kind,r.purpose);
  insert into public.asset_versions(id,owner_id,project_id,asset_id,version,input_revision,input_hash,content_hash,mime_type,storage_path,provenance)
   values(r.version_id,r.owner_id,r.project_id,r.asset_id,1,r.input_revision,r.input_hash,r.content_hash,r.mime_type,r.owner_id::text||'/'||r.project_id::text||'/'||r.asset_id::text||'/'||r.version_id::text,jsonb_build_object('version',2,'publicationId',r.id,'sourceReceiptId',r.source_receipt_id));
  update public.logo_asset_publications set state='committed' where id=r.id returning * into r;
 end if;
 return fluid_private.logo_asset_receipt(r);
end $$;


ALTER FUNCTION fluid_private.logo_commit_asset(r public.logo_asset_publications) OWNER TO postgres;

--
-- Name: logo_current_vector_id(uuid, uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_current_vector_id(p_owner uuid, p_project uuid) RETURNS uuid
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare result uuid;
begin
 -- Only appended stage revisions are activations. Raw/stale worker candidates
 -- remain separate source records and cannot become current. Later raster-only
 -- revisions must not erase the prior non-null vector activation in this history.
 if exists(select 1 from public.logo_stage_revisions r
  where r.owner_id=p_owner and r.project_id=p_project and r.stage in('refinements','vector') and r.record#>>'{payload,vectorRevisionId}' is not null and r.workspace_revision is null) then
  raise exception 'logo_activation_order_unavailable' using errcode='55000';
 end if;
 select (r.record#>>'{payload,vectorRevisionId}')::uuid into result from public.logo_stage_revisions r
 where r.owner_id=p_owner and r.project_id=p_project and r.stage in('refinements','vector') and r.record#>>'{payload,vectorRevisionId}' is not null
 order by r.workspace_revision desc limit 1;
 if result is not null and not exists(select 1 from public.logo_vector_revisions v where v.id=result and v.owner_id=p_owner and v.project_id=p_project) then raise exception 'logo_current_vector_unavailable' using errcode='55000';end if;
 return result;
end $$;


ALTER FUNCTION fluid_private.logo_current_vector_id(p_owner uuid, p_project uuid) OWNER TO postgres;

--
-- Name: logo_direction_overview(uuid, uuid, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_direction_overview(p_owner uuid, p_project uuid, p_query jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare w jsonb;stage jsonb;selected jsonb;approval jsonb;dirs jsonb;palettes jsonb;types jsonb;graphics jsonb;fonts jsonb;checks jsonb;ids uuid[];current_ids uuid[];last public.logo_direction_records;cursor_row public.logo_direction_records;current_after uuid;current_offset integer:=0;remaining_current boolean:=false;more boolean;pin_current boolean:=false;lim integer:=least(coalesce((p_query->>'limit')::integer,3),3);
begin
 w:=fluid_private.logo_workspace_json(p_owner,p_project);
 if lim<1 then raise exception 'invalid_direction_page' using errcode='22023';end if;
 if p_query->>'cursor' like 'current:%' then
  if cardinality(string_to_array(p_query->>'cursor',':'))<>3 or not fluid_private.logo_uuid(to_jsonb(split_part(p_query->>'cursor',':',2))) or not fluid_private.logo_uuid(to_jsonb(split_part(p_query->>'cursor',':',3))) then raise exception 'invalid_direction_page' using errcode='22023';end if;
  -- A current-set continuation is bound to its immutable stage, so a changed
  -- head requires a fresh first page instead of silently switching collections.
  if split_part(p_query->>'cursor',':',2) is distinct from w#>>'{stages,directions,id}' then raise exception 'direction_page_head_changed' using errcode='PT409';end if;
  current_after:=split_part(p_query->>'cursor',':',3)::uuid;
 elsif p_query->>'cursor' is not null and p_query->>'cursor'<>'history' then
  if not fluid_private.logo_uuid(p_query->'cursor') then raise exception 'invalid_direction_page' using errcode='22023';end if;
  select * into cursor_row from public.logo_direction_records where id=(p_query->>'cursor')::uuid and owner_id=p_owner and project_id=p_project and kind='direction';if not found then raise exception 'direction_cursor_not_found' using errcode='P0002';end if;
 end if;
 select record into stage from public.logo_stage_revisions where id=(w#>>'{stages,directions,id}')::uuid and owner_id=p_owner and project_id=p_project;
 select coalesce(array_agg((value#>>'{}')::uuid),'{}') into current_ids from jsonb_array_elements(coalesce(stage#>'{payload,directionIds}','[]'));
 if current_after is not null then
  current_offset:=array_position(current_ids,current_after);if current_offset is null then raise exception 'direction_cursor_not_found' using errcode='P0002';end if;
 end if;
 if (p_query->>'cursor' is null or current_after is not null) and cardinality(current_ids)>0 then
  pin_current:=true;
  -- The first page is the current available set, independent of selected-source
  -- provenance and of newer retained groups that never advanced this head.
  select array_agg(id order by ordinal) into ids from(select r.id,d.ordinality ordinal from jsonb_array_elements(stage#>'{payload,directionIds}') with ordinality d(value,ordinality) join public.logo_direction_records r on r.id::text=d.value#>>'{}' and r.owner_id=p_owner and r.project_id=p_project and r.kind='direction' where d.ordinality>current_offset order by d.ordinality limit lim) current_set;
 else
  select array_agg(id) into ids from(select id from public.logo_direction_records where owner_id=p_owner and project_id=p_project and kind='direction' and not(id=any(current_ids)) and (cursor_row.id is null or(created_at,id)<(cursor_row.created_at,cursor_row.id)) order by created_at desc,id desc limit lim) page;
 end if;
 select coalesce(jsonb_agg(record order by array_position(ids,id)),'[]') into dirs from public.logo_direction_records where id=any(ids);
 select * into last from public.logo_direction_records where id=any(ids) order by created_at,id limit 1;
 remaining_current:=pin_current and exists(select 1 from unnest(current_ids) with ordinality d(id,ordinal) join public.logo_direction_records r on r.id=d.id and r.owner_id=p_owner and r.project_id=p_project and r.kind='direction' where d.ordinal>coalesce(array_position(current_ids,ids[cardinality(ids)]),current_offset));
 more:=exists(select 1 from public.logo_direction_records where owner_id=p_owner and project_id=p_project and kind='direction' and not(id=any(current_ids)) and (pin_current or (last.id is not null and(created_at,id)<(last.created_at,last.id))));
 select record into stage from public.logo_stage_revisions where id=(w#>>'{stages,directions,id}')::uuid and owner_id=p_owner and project_id=p_project;
 select record into selected from public.logo_direction_records where id=(stage#>>'{payload,selectionId}')::uuid and kind='selection' and owner_id=p_owner and project_id=p_project;
 select record into approval from public.logo_direction_records where id=(stage#>>'{payload,approvalId}')::uuid and kind='approval' and owner_id=p_owner and project_id=p_project;
 select coalesce(jsonb_agg(record order by id),'[]') into palettes from public.logo_direction_records where owner_id=p_owner and project_id=p_project and kind='palette' and(id::text=selected->>'paletteVersionId' or exists(select 1 from jsonb_array_elements(dirs) d where d->>'paletteVersionId'=id::text));
 select coalesce(jsonb_agg(record order by id),'[]') into types from public.logo_direction_records where owner_id=p_owner and project_id=p_project and kind='typography' and(id::text=selected->>'typographyVersionId' or exists(select 1 from jsonb_array_elements(dirs) d where d->>'typographyVersionId'=id::text));
 select coalesce(jsonb_agg(record order by id),'[]') into graphics from public.logo_direction_records where owner_id=p_owner and project_id=p_project and kind='graphics' and(id::text=selected->>'graphicsVersionId' or exists(select 1 from jsonb_array_elements(dirs) d where d->>'graphicsVersionId'=id::text));
 select coalesce(jsonb_agg(record order by record_id),'[]') into fonts from public.logo_font_records f where owner_id=p_owner and project_id=p_project and exists(select 1 from jsonb_array_elements(types) t,jsonb_array_elements(t->'styles') s where s->>'fontVersionId'=f.record_id::text);
 select coalesce(jsonb_agg(record),'[]') into checks from(select c.record from public.logo_direction_font_checks c where owner_id=p_owner and project_id=p_project and exists(select 1 from jsonb_array_elements(types) t where t->>'id'=c.typography_id::text) order by(c.typography_id::text=selected->>'typographyVersionId') desc nulls last,c.typography_id,c.style_key limit 100) bounded_checks;
 return jsonb_build_object('ownerId',p_owner,'projectId',p_project,'currentApprovedLogo',w->'approvedLogo','directions',dirs,'palettes',palettes,'typography',types,'graphics',graphics,'fonts',fonts,'fontChecks',checks,'selection',selected,'approval',approval,'stale',exists(select 1 from jsonb_array_elements(w->'staleStages') s where s->>'stage'='directions') or (selected is not null and selected->'approvedLogoId' is distinct from w#>'{approvedLogo,id}'),'nextCursor',case when remaining_current then 'current:'||(stage->>'id')||':'||ids[cardinality(ids)]::text when more then case when pin_current then 'history' else last.id::text end else null end);
exception when invalid_text_representation or numeric_value_out_of_range then raise exception 'invalid_direction_page' using errcode='22023';
end $$;


ALTER FUNCTION fluid_private.logo_direction_overview(p_owner uuid, p_project uuid, p_query jsonb) OWNER TO postgres;

