--
-- Name: logo_input_request_valid(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_input_request_valid(v jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare b jsonb:=v->'input'; f jsonb:=v->'file'; k text:=v->>'kind'; n numeric; source_url text; source_host text; source_port text;
begin
 if not fluid_private.standalone_keys(v,array['kind','input','file']) or octet_length(v::text)>327680 or jsonb_typeof(v->'kind') is distinct from 'string' or k not in('reference_upload','font_upload','font_catalog') then return false;end if;
 if not fluid_private.logo_command_valid(jsonb_build_object('method','saveLogoReferences','body',jsonb_build_object('requestKey',b->'requestKey','expected',b->'expected','selections','[]'::jsonb))) then return false;end if;
 if not fluid_private.standalone_keys(f,array['contentHash','mimeType','byteLength']) or jsonb_typeof(f->'contentHash') is distinct from 'string' or f->>'contentHash' !~ '^[0-9a-f]{64}$' or jsonb_typeof(f->'byteLength') is distinct from 'number' or jsonb_typeof(f->'mimeType') is distinct from 'string' then return false;end if;
 n:=(f->>'byteLength')::numeric;if n<>trunc(n) or n<1 or n>(case when k='reference_upload' then 33554432 else 10485760 end) then return false;end if;
 if k='reference_upload' then
  return fluid_private.standalone_keys(b,array['requestKey','expected','aspects','rightsDeclaration'])
   and f->>'mimeType' in('image/png','image/jpeg','image/webp')
   and fluid_private.standalone_text(b->'rightsDeclaration',2000,1) and fluid_private.idea_trim(b->>'rightsDeclaration')<>''
   and fluid_private.logo_command_valid(jsonb_build_object('method','saveLogoReferences','body',jsonb_build_object('requestKey',b->'requestKey','expected',b->'expected','selections',jsonb_build_array(jsonb_build_object('referenceId',b->'requestKey','aspects',b->'aspects')))));
 end if;
 if jsonb_typeof(f->'mimeType') is distinct from 'string' or f->>'mimeType' not in('font/ttf','font/otf') or n<12 then return false;end if;
 if k='font_catalog' then return fluid_private.standalone_keys(b,array['requestKey','expected','catalogFontId']) and jsonb_typeof(b->'catalogFontId')='string' and length(b->>'catalogFontId') between 1 and 100 and b->>'catalogFontId'~'^[a-z][a-z0-9-]*$';end if;
 if b->'licenseSourceUrl' is distinct from 'null'::jsonb then
  if jsonb_typeof(b->'licenseSourceUrl') is distinct from 'string' then return false;end if;
  source_url:=b->>'licenseSourceUrl';
  if length(source_url)>2048 or source_url !~ '^https://([A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?(\.[A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?)*)(:[0-9]{1,5})?(/[A-Za-z0-9._~!$&''()*+,;=:@%/-]*)?$' then return false;end if;
  source_host:=substring(source_url from '^https://([^/:]+)');source_port:=substring(source_url from '^https://[^/:]+:([0-9]{1,5})');
  if length(source_host)>253 or source_host !~ '[A-Za-z]$' or(source_port is not null and source_port::integer not between 1 and 65535) then return false;end if;
 end if;
 return fluid_private.standalone_keys(b,array['requestKey','expected','licenseSourceUrl','licenseText','rightsDeclaration'])
  and fluid_private.standalone_text(b->'rightsDeclaration',2000,1) and fluid_private.idea_trim(b->>'rightsDeclaration')<>''
  and jsonb_typeof(b->'licenseText')='string' and octet_length(b->>'licenseText')<=262144 and fluid_private.idea_trim(b->>'licenseText')<>'';

exception when others then return false;
end $_$;


ALTER FUNCTION fluid_private.logo_input_request_valid(v jsonb) OWNER TO postgres;

--
-- Name: logo_input_state(uuid, uuid, uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_input_state(p_owner uuid, p_project uuid, p_key uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare r public.logo_input_requests; result jsonb; rejection_reason text;
begin
 select * into r from public.logo_input_requests where owner_id=p_owner and project_id=p_project and request_key=p_key;
 if not found then return jsonb_build_object('status','not_found');end if;
 select reason into rejection_reason from public.logo_input_rejections where owner_id=p_owner and project_id=p_project and request_key=p_key;
 if rejection_reason is not null then return jsonb_build_object('status','rejected','reason',rejection_reason,'ownerId',p_owner,'projectId',p_project,'requestKey',p_key,'request',r.request);end if;
 select x.result into result from public.logo_input_receipts x where x.owner_id=p_owner and x.project_id=p_project and x.request_key=p_key;
 return jsonb_build_object('status',case when result is null then 'pending' else 'succeeded' end,'ownerId',p_owner,'projectId',p_project,'requestKey',p_key,'request',r.request)
  ||case when result is null then '{}'::jsonb else jsonb_build_object('result',result) end;
end $$;


ALTER FUNCTION fluid_private.logo_input_state(p_owner uuid, p_project uuid, p_key uuid) OWNER TO postgres;

--
-- Name: logo_job_can_read_asset(public.jobs, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_job_can_read_asset(p_job public.jobs, p_reference jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare q public.logo_cost_quotes;item jsonb;
begin
 if p_reference->>'ownerId' is distinct from p_job.owner_id::text or p_reference->>'projectId' is distinct from p_job.project_id::text then return false;end if;
 if p_job.operation='identity.logo_export' then return fluid_private.logo_export_can_read_asset(p_job,p_reference);end if;
 select * into q from public.logo_cost_quotes where id=(p_job.input->>'quoteId')::uuid and owner_id=p_job.owner_id and project_id=p_job.project_id;
 if not found then return false;end if;
 if p_job.operation='identity.logo_directions' then
  if p_reference in (q.source_inputs#>'{direction,logoRevision,documentAsset}',q.source_inputs#>'{direction,logoRevision,svgAsset}',q.source_inputs#>'{direction,logoRevision,sourcePreview}') then return true;end if;
  if exists(select 1 from jsonb_array_elements(q.source_inputs#>'{direction,permittedFonts}') f where f->'asset'=p_reference) then return true;end if;
 end if;
 for item in select value from jsonb_array_elements(q.source_inputs#>'{referenceSnapshot,references}') loop
  if item->'asset'=p_reference and exists(select 1 from public.logo_reference_sources s where s.owner_id=p_job.owner_id and s.project_id=p_job.project_id and s.reference_id=(item->>'referenceId')::uuid and s.asset_id=(p_reference->>'assetId')::uuid and s.version_id=(p_reference->>'versionId')::uuid and s.content_hash=p_reference->>'contentHash' and s.rights_evidence_id=(item->>'rightsEvidenceId')::uuid and s.source_kind=item->>'sourceKind') then return true;end if;
 end loop;
 if q.source_inputs#>'{raster,preview,reference}'=p_reference then return exists(select 1 from public.logo_raster_results r where r.owner_id=p_job.owner_id and r.project_id=p_job.project_id and r.preview#>'{reference}'=p_reference);end if;
 return exists(select 1 from public.logo_raster_results r where r.job_id=p_job.id and r.owner_id=p_job.owner_id and r.project_id=p_job.project_id and r.preview->'reference'=p_reference);
end $$;


ALTER FUNCTION fluid_private.logo_job_can_read_asset(p_job public.jobs, p_reference jsonb) OWNER TO postgres;

--
-- Name: logo_job_input_revisions(public.jobs); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_job_input_revisions(p_job public.jobs) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
 if p_job.operation='identity.logo_export' then return fluid_private.logo_export_input_revisions(p_job);end if;
 select q.input_revisions into result from public.logo_cost_quotes q where q.id=(p_job.input->>'quoteId')::uuid and q.owner_id=p_job.owner_id and q.project_id=p_job.project_id and q.record->>'inputHash'=p_job.input_hash;
 if result is null then raise exception 'logo_job_sources_missing' using errcode='55000'; end if;return result;end $$;


ALTER FUNCTION fluid_private.logo_job_input_revisions(p_job public.jobs) OWNER TO postgres;

--
-- Name: logo_job_observation(public.jobs); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_job_observation(p_job public.jobs) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare r public.logo_raster_results;b jsonb;status text;reason text;provider_id uuid;
begin
 select * into r from public.logo_raster_results where job_id=p_job.id and owner_id=p_job.owner_id and project_id=p_job.project_id;
 select observation->'billing',id into b,provider_id from public.logo_provider_responses where job_id=p_job.id and owner_id=p_job.owner_id and project_id=p_job.project_id;
 if b is null then
  if p_job.operation in ('identity.logo_vectorize','identity.logo_export') or not exists(select 1 from public.job_steps where job_id=p_job.id) or (p_job.state in ('cancelled','failed') and not exists(select 1 from public.job_steps where job_id=p_job.id and (state in ('ambiguous','in_flight') or output->>'error' is distinct from 'not_dispatched'))) then b:=jsonb_build_object('status','recorded','confirmedMicrousd',0);
  else b:=jsonb_build_object('status','unknown','confirmedMicrousd',null);end if;
 end if;
 status:=case when p_job.state='cancel_requested' then 'running' when p_job.state='partial' then 'failed' else p_job.state end;
 reason:=p_job.error_code;
 if r.preview is not null and b->>'status'='unknown' then status:='needs_reconciliation';reason:='billing_unknown';end if;
 if status='needs_reconciliation' and reason is null then reason:='provider_outcome_unknown';end if;
 return jsonb_build_object('preview',r.preview,'providerResponseReceiptId',provider_id,'state',status,'billing',b,'reason',reason);
end $$;


ALTER FUNCTION fluid_private.logo_job_observation(p_job public.jobs) OWNER TO postgres;

--
-- Name: logo_job_record(uuid, uuid, text, uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_job_record(p_owner uuid, p_project uuid, p_kind text, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare batch public.logo_concept_batches;slot public.logo_concept_slots;attempt public.logo_concept_attempts;j public.jobs;raster public.logo_raster_refinements;slots jsonb:='[]';attempts jsonb;observation jsonb;
begin
 if p_kind='concept_batch' then
  select * into batch from public.logo_concept_batches where id=p_id and owner_id=p_owner and project_id=p_project;if not found then raise exception 'logo_batch_not_found' using errcode='P0002';end if;
  for slot in select * from public.logo_concept_slots where batch_id=batch.id and owner_id=p_owner and project_id=p_project order by ordinal loop
   attempts:='[]';for attempt in select * from public.logo_concept_attempts where slot_id=slot.id and owner_id=p_owner and project_id=p_project order by attempt_number loop
    select * into j from public.jobs where id=attempt.job_id and owner_id=p_owner and project_id=p_project;observation:=fluid_private.logo_job_observation(j);
    attempts:=attempts||jsonb_build_array(jsonb_build_object('id',attempt.id,'jobId',j.id,'slotId',slot.id,'requestKey',attempt.request_key,'previousAttemptId',attempt.previous_attempt_id,'attemptNumber',attempt.attempt_number,'inputHash',attempt.input_hash,'reservedCostMicrousd',j.reserved_cost_microusd)||observation);
   end loop;
   slots:=slots||jsonb_build_array(jsonb_build_object('id',slot.id,'ordinal',slot.ordinal,'type',slot.logo_type,'directionId',slot.direction_id,'attempts',attempts,'acceptedPreview',null));
  end loop;
  return jsonb_build_object('version',2,'id',batch.id,'ownerId',p_owner,'projectId',p_project,'requestKey',batch.request_key,'briefRevisionId',batch.brief_revision_id,'referenceSnapshotId',batch.reference_snapshot_id,'targetCount',6,'plan',batch.plan,'slots',slots,'createdAt',to_char(batch.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'));
 elsif p_kind='raster_refinement' then
  select * into raster from public.logo_raster_refinements where id=p_id and owner_id=p_owner and project_id=p_project;if not found then raise exception 'logo_raster_not_found' using errcode='P0002';end if;
  select * into j from public.jobs where id=raster.job_id and owner_id=p_owner and project_id=p_project;
  return jsonb_build_object('version',2,'id',raster.id,'ownerId',p_owner,'projectId',p_project,'requestKey',raster.request_key,'jobId',j.id,'source',raster.source,'logoType',raster.logo_type,'inputRevisions',raster.input_revisions,'createdAt',to_char(raster.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'))||fluid_private.logo_job_observation(j);
 else raise exception 'invalid_logo_read_kind' using errcode='22023';end if;
end $$;


ALTER FUNCTION fluid_private.logo_job_record(p_owner uuid, p_project uuid, p_kind text, p_id uuid) OWNER TO postgres;

--
-- Name: logo_job_records(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_job_records(p_owner uuid, p_project uuid, p_kind text, p_query jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare n integer;cursor_id uuid;cursor_time timestamptz;row public.logo_raster_refinements;batch public.logo_concept_batches;items jsonb:='[]';next_cursor text;seen integer:=0;
begin
 if p_kind not in ('raster_refinement','concept_batch') or jsonb_typeof(p_query) is distinct from 'object' or p_query-array['cursor','limit']<>'{}' then raise exception 'invalid_logo_query' using errcode='22023';end if;
 if p_query ? 'limit' and (jsonb_typeof(p_query->'limit')<>'number' or (p_query->>'limit')::numeric<>trunc((p_query->>'limit')::numeric) or (p_query->>'limit')::numeric not between 1 and 50) then raise exception 'invalid_logo_limit' using errcode='22023';end if;n:=coalesce((p_query->>'limit')::integer,20);
 if p_kind='concept_batch' then
  if p_query ? 'cursor' then
   if not fluid_private.logo_uuid(p_query->'cursor') then raise exception 'invalid_logo_cursor' using errcode='22023';end if;
   cursor_id:=(p_query->>'cursor')::uuid;select created_at into cursor_time from public.logo_concept_batches where id=cursor_id and owner_id=p_owner and project_id=p_project;
   if not found then raise exception 'invalid_logo_cursor' using errcode='22023';end if;
  end if;
  for batch in select * from public.logo_concept_batches where owner_id=p_owner and project_id=p_project and (cursor_id is null or (created_at,id)<(cursor_time,cursor_id)) order by created_at desc,id desc limit n+1 loop
   seen:=seen+1;if seen>n then return jsonb_build_object('ownerId',p_owner,'projectId',p_project,'items',items,'nextCursor',next_cursor);end if;
   items:=items||jsonb_build_array(jsonb_build_object('id',batch.id,'requestKey',batch.request_key,'createdAt',to_char(batch.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));next_cursor:=batch.id::text;
  end loop;return jsonb_build_object('ownerId',p_owner,'projectId',p_project,'items',items,'nextCursor',null);
 end if;
 if p_query ? 'cursor' then if not fluid_private.logo_uuid(p_query->'cursor') then raise exception 'invalid_logo_cursor' using errcode='22023';end if;cursor_id:=(p_query->>'cursor')::uuid;select created_at into cursor_time from public.logo_raster_refinements where id=cursor_id and owner_id=p_owner and project_id=p_project;if not found then raise exception 'invalid_logo_cursor' using errcode='22023';end if;end if;
 for row in select * from public.logo_raster_refinements where owner_id=p_owner and project_id=p_project and (cursor_id is null or (created_at,id)<(cursor_time,cursor_id)) order by created_at desc,id desc limit n+1 loop
  seen:=seen+1;if seen>n then return jsonb_build_object('ownerId',p_owner,'projectId',p_project,'items',items,'nextCursor',next_cursor);end if;
  items:=items||jsonb_build_array(fluid_private.logo_job_record(p_owner,p_project,'raster_refinement',row.id));next_cursor:=row.id::text;
 end loop;return jsonb_build_object('ownerId',p_owner,'projectId',p_project,'items',items,'nextCursor',null);
end $$;


ALTER FUNCTION fluid_private.logo_job_records(p_owner uuid, p_project uuid, p_kind text, p_query jsonb) OWNER TO postgres;

--
-- Name: logo_plan(jsonb, bigint); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_plan(p_types jsonb, p_prior bigint) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare types jsonb;slots jsonb:='[]';covered jsonb;uncovered jsonb;i integer;t jsonb;dirs text[]:=array['open_geometry','compact_structure','organic_motion','angular_energy','negative_space','expressive_detail'];
begin
 select jsonb_agg(value order by ordinality) into types from jsonb_array_elements('["wordmark","lettermark_monogram","pictorial","abstract","combination","emblem","mascot"]'::jsonb) with ordinality where p_types @> jsonb_build_array(value);
 if types is null then raise exception 'logo_types_required' using errcode='22023';end if;
 for i in 0..5 loop t:=types->(((p_prior+i)%jsonb_array_length(types))::integer);slots:=slots||jsonb_build_array(jsonb_build_object('ordinal',i,'type',t,'directionId',dirs[i+1]));end loop;
 select coalesce(jsonb_agg(t.value order by t.ordinality),'[]') into covered from jsonb_array_elements(types) with ordinality t where exists(select 1 from jsonb_array_elements(slots) s where s->'type'=t.value);
 select coalesce(jsonb_agg(t.value order by t.ordinality),'[]') into uncovered from jsonb_array_elements(types) with ordinality t where not exists(select 1 from jsonb_array_elements(slots) s where s->'type'=t.value);
 return jsonb_build_object('version',1,'targetCount',6,'requestedTypes',types,'slots',slots,'coveredTypes',covered,'uncoveredTypes',uncovered);
end $$;


ALTER FUNCTION fluid_private.logo_plan(p_types jsonb, p_prior bigint) OWNER TO postgres;

--
-- Name: logo_snapshot_json(uuid, uuid, uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_snapshot_json(p_owner uuid, p_project uuid, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare result jsonb; item jsonb; actual jsonb;
begin
 select snapshot into result from public.logo_reference_snapshots where id=p_id and project_id=p_project and owner_id=p_owner;
 if not found then raise exception 'logo_snapshot_not_found' using errcode='P0002'; end if;
 for item in select value from jsonb_array_elements(result->'references') loop
  select jsonb_build_object('referenceId',s.reference_id,'asset',jsonb_build_object('ownerId',s.owner_id,'projectId',s.project_id,'assetId',s.asset_id,'versionId',s.version_id,'contentHash',v.content_hash),
   'sourceKind',s.source_kind,'rightsEvidenceId',s.rights_evidence_id,'aspects',item->'aspects') into actual
  from public.logo_reference_sources s join public.asset_versions v on v.id=s.version_id and v.asset_id=s.asset_id and v.owner_id=s.owner_id and v.project_id=s.project_id
  join public.assets a on a.id=s.asset_id and a.owner_id=s.owner_id and a.project_id=s.project_id
  where s.reference_id=(item->>'referenceId')::uuid and s.owner_id=p_owner and s.project_id=p_project and s.content_hash=v.content_hash and a.purpose='reference_media';
  if actual is distinct from item then raise exception 'logo_reference_source_unavailable' using errcode='55000'; end if;
 end loop;
 return result;
end $$;


ALTER FUNCTION fluid_private.logo_snapshot_json(p_owner uuid, p_project uuid, p_id uuid) OWNER TO postgres;

--
-- Name: logo_stage_payload_valid(text, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_stage_payload_valid(p_stage text, p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare key text;item jsonb;items jsonb;
begin
 case p_stage
 when 'concepts' then
  if not fluid_private.standalone_keys(p,array['batchIds','selected']) or jsonb_typeof(p->'batchIds') is distinct from 'array' then return false;end if;
  items:=p->'batchIds';
  if p->'selected'<>'null'::jsonb then
   if p#>>'{selected,kind}'='concept' then
    if not fluid_private.standalone_keys(p->'selected',array['kind','batchId','slotId','attemptId']) or not fluid_private.logo_uuid(p#>'{selected,batchId}') or not fluid_private.logo_uuid(p#>'{selected,slotId}') or not fluid_private.logo_uuid(p#>'{selected,attemptId}') or not(items ? (p#>>'{selected,batchId}')) then return false;end if;
   elsif p#>>'{selected,kind}'='refinement' then
    if not fluid_private.standalone_keys(p->'selected',array['kind','rasterRevisionId']) or not fluid_private.logo_uuid(p#>'{selected,rasterRevisionId}') then return false;end if;
   else return false;end if;
  end if;
 when 'vector' then
  return fluid_private.standalone_keys(p,array['vectorRevisionId','approvalId']) and fluid_private.logo_uuid(p->'vectorRevisionId') and(p->'approvalId'='null'::jsonb or fluid_private.logo_uuid(p->'approvalId'));
 when 'refinements' then
  if not fluid_private.standalone_keys(p,array['rasterRevisionIds','vectorRevisionId','approvalId','sourceRequestKey']) or jsonb_typeof(p->'rasterRevisionIds') is distinct from 'array' then return false;end if;
  foreach key in array array['vectorRevisionId','approvalId','sourceRequestKey'] loop if p->key<>'null'::jsonb and not fluid_private.logo_uuid(p->key) then return false;end if;end loop;
  if p->'approvalId'<>'null'::jsonb and p->'vectorRevisionId'='null'::jsonb then return false;end if;items:=p->'rasterRevisionIds';
 when 'directions' then
  if not fluid_private.standalone_keys(p,array['directionIds','selectionId','approvalId']) or jsonb_typeof(p->'directionIds') is distinct from 'array' or jsonb_array_length(p->'directionIds')<>3 then return false;end if;
  foreach key in array array['selectionId','approvalId'] loop if p->key<>'null'::jsonb and not fluid_private.logo_uuid(p->key) then return false;end if;end loop;
  if p->'approvalId'<>'null'::jsonb and p->'selectionId'='null'::jsonb then return false;end if;items:=p->'directionIds';
 when 'deliverables' then
  if not fluid_private.standalone_keys(p,array['variantSetId','exportManifestIds']) or jsonb_typeof(p->'exportManifestIds') is distinct from 'array' or(p->'variantSetId'<>'null'::jsonb and not fluid_private.logo_uuid(p->'variantSetId')) then return false;end if;items:=p->'exportManifestIds';
 else return false;
 end case;
 if jsonb_array_length(items)>1000 or(select count(*)<>count(distinct value) from jsonb_array_elements(items)) then return false;end if;
 for item in select value from jsonb_array_elements(items) loop if not fluid_private.logo_uuid(item) then return false;end if;end loop;return true;
exception when others then return false;
end $$;


ALTER FUNCTION fluid_private.logo_stage_payload_valid(p_stage text, p jsonb) OWNER TO postgres;

--
-- Name: logo_uuid(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_uuid(v jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
 select coalesce(jsonb_typeof(v)='string' and (v#>>'{}') ~ '^([0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}|00000000-0000-0000-0000-000000000000|ffffffff-ffff-ffff-ffff-ffffffffffff)$',false)
$_$;


ALTER FUNCTION fluid_private.logo_uuid(v jsonb) OWNER TO postgres;

--
-- Name: logo_vector_locks_valid(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_vector_locks_valid(p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare item jsonb;key text;
begin
 if jsonb_typeof(p) is distinct from 'array' or jsonb_array_length(p)>64 then return false;end if;
 for item in select value from jsonb_array_elements(p) loop
  if not coalesce(fluid_private.standalone_keys(item,array['componentId','geometryHash','appearanceHash','transformHash','textHash','zOrderHash','effectiveHash']),false)
   or jsonb_typeof(item->'componentId') is distinct from 'string' or item->>'componentId'!~'^[A-Za-z0-9][A-Za-z0-9._:-]{0,199}$' then return false;end if;
  foreach key in array array['geometryHash','appearanceHash','transformHash','textHash','zOrderHash','effectiveHash'] loop
   if jsonb_typeof(item->key) is distinct from 'string' or item->>key!~'^[0-9a-f]{64}$' then return false;end if;
  end loop;
 end loop;
 return (select count(*)=count(distinct value->>'componentId') from jsonb_array_elements(p));
exception when others then return false;
end $_$;


ALTER FUNCTION fluid_private.logo_vector_locks_valid(p jsonb) OWNER TO postgres;

--
-- Name: logo_vector_member_valid(public.logo_asset_publications, uuid, uuid, uuid, jsonb, text, text); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_vector_member_valid(r public.logo_asset_publications, p_owner uuid, p_project uuid, p_source uuid, p_inputs jsonb, p_mime text, p_hash text) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select coalesce(r.id is not null and r.owner_id=p_owner and r.project_id=p_project and r.source_kind='vector' and r.source_receipt_id=p_source
  and r.request#>'{publication,inputRevisions}'=p_inputs and r.state in('staged','committed') and r.purpose='brand_asset'
  and r.mime_type=p_mime and r.content_hash=p_hash and r.byte_length between 1 and 8388608
  and r.verification->>'status'='verified' and r.verification->>'contentHash'=r.content_hash and r.verification->>'mimeType'=r.mime_type
  and r.verification->'byteLength'=to_jsonb(r.byte_length),false)
$$;


ALTER FUNCTION fluid_private.logo_vector_member_valid(r public.logo_asset_publications, p_owner uuid, p_project uuid, p_source uuid, p_inputs jsonb, p_mime text, p_hash text) OWNER TO postgres;

--
-- Name: logo_vector_proof_valid(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_vector_proof_valid(p jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare n numeric;
begin
 if not coalesce(fluid_private.standalone_keys(p,array['version','svgContentHash','documentHash','validator','viewBox','pathCount','componentCount','externalFontDependencies']),false)
  or p->'version' is distinct from '1'::jsonb or p->'validator' is distinct from '{"id":"fluid.logo-vector","version":"1"}'::jsonb
  or p->'externalFontDependencies' is distinct from '[]'::jsonb
  or jsonb_typeof(p->'documentHash') is distinct from 'string' or p->>'documentHash'!~'^[0-9a-f]{64}$'
  or jsonb_typeof(p->'svgContentHash') is distinct from 'string' or p->>'svgContentHash'!~'^[0-9a-f]{64}$'
  or jsonb_typeof(p->'viewBox') is distinct from 'array' or jsonb_array_length(p->'viewBox')<>4
  or jsonb_typeof(p->'pathCount') is distinct from 'number' or jsonb_typeof(p->'componentCount') is distinct from 'number' then return false;end if;
 n:=(p->>'pathCount')::numeric;if n<>trunc(n) or n not between 1 and 20000 then return false;end if;
 n:=(p->>'componentCount')::numeric;if n<>trunc(n) or n not between 1 and 64 or n>(p->>'pathCount')::numeric then return false;end if;
 for i in 0..3 loop
  if jsonb_typeof(p#>array['viewBox',i::text]) is distinct from 'number' then return false;end if;
  n:=(p#>>array['viewBox',i::text])::numeric;
  if abs(n)>1000000 or (i>=2 and (n<=0 or n>16384)) then return false;end if;
 end loop;
 return true;
exception when others then return false;
end $_$;


ALTER FUNCTION fluid_private.logo_vector_proof_valid(p jsonb) OWNER TO postgres;

--
-- Name: logo_worker_owner(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

