    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select case when exists(select 1 from fluid_private.shared_worker_slots where role_name=session_user)
 then fluid_private.shared_worker_context_owner('logo') else fluid_private.shared_logo_legacy_owner() end;
$$;


ALTER FUNCTION fluid_private.logo_worker_owner() OWNER TO postgres;

--
-- Name: logo_workspace_base_json(uuid, uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_workspace_base_json(p_owner uuid, p_project uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare project public.projects; w bigint; rr bigint; pr bigint; s text; row public.logo_stage_revisions; stages jsonb:='{}'; revisions jsonb:='{}'; stale jsonb:='[]'; reasons jsonb;
begin
 select * into project from public.projects where id=p_project and owner_id=p_owner;
 if not found then raise exception 'logo_project_not_found' using errcode='P0002'; end if;
 select revision into w from public.logo_workspaces where project_id=p_project and owner_id=p_owner;
 select reference_revision into rr from public.identity_reference_heads where project_id=p_project and owner_id=p_owner;
 select current_preferences_revision into pr from public.identity_sessions where project_id=p_project and owner_id=p_owner;
 foreach s in array array['brief_references','concepts','vector','refinements','directions','deliverables'] loop
  select r.* into row from public.logo_stage_heads h join public.logo_stage_revisions r on r.id=h.revision_id and r.owner_id=h.owner_id and r.project_id=h.project_id and r.stage=h.stage
   where h.project_id=p_project and h.owner_id=p_owner and h.stage=s;
  stages:=stages||jsonb_build_object(s,case when row.id is null then null else jsonb_build_object('stage',s,'id',row.id,'revision',row.revision) end);
  revisions:=revisions||jsonb_build_object(s,coalesce(row.revision,0));
  if row.id is not null then
   reasons:='[]';
   if s='brief_references' and not exists(
    select 1 from public.project_revisions source_revision
    join public.project_revisions current_revision
      on current_revision.project_id=source_revision.project_id and current_revision.owner_id=source_revision.owner_id
    where source_revision.project_id=p_project and source_revision.owner_id=p_owner
      and source_revision.revision=(row.record#>>'{payload,sourceProjectRevision}')::bigint
      and current_revision.revision=project.current_revision
      and jsonb_typeof(source_revision.context)='object' and jsonb_typeof(current_revision.context)='object'
      and source_revision.context=current_revision.context
   ) then reasons:=reasons||'"project_revision_changed"'::jsonb; end if;
   if exists(select 1 from jsonb_array_elements(row.record->'inputRevisions') i left join public.logo_stage_heads h on h.owner_id=p_owner and h.project_id=p_project and h.stage=i->>'stage'
    left join public.logo_stage_revisions r on r.id=h.revision_id and r.owner_id=p_owner and r.project_id=p_project
    where (r.id is null or r.id::text<>i->>'id' or r.revision<>(i->>'revision')::bigint)
    and not (i->>'stage'='brief_references' and fluid_private.logo_brief_same_except_types(p_owner,p_project,(i->>'id')::uuid,r.id))) then reasons:=reasons||'"input_revision_changed"'::jsonb; end if;
   if jsonb_array_length(reasons)>0 then stale:=stale||jsonb_build_array(jsonb_build_object('stage',s,'reasons',reasons)); end if;
  end if;
 end loop;
 return jsonb_build_object('version',2,'ownerId',p_owner,'projectId',p_project,'heads',jsonb_build_object('projectRevision',project.current_revision,'referenceRevision',coalesce(rr,0),'preferencesRevision',coalesce(pr,0),'workspaceRevision',coalesce(w,0),'stageRevisions',revisions),
  'stages',stages,'approvedLogo',null,'staleStages',stale,'capabilities',jsonb_build_object('save',jsonb_build_object('status','available'),'upload',jsonb_build_object('status','unavailable','reason','logo_upload_unavailable'),
   'generate',jsonb_build_object('status','unavailable','reason','logo_pipeline_unavailable'),'convert',jsonb_build_object('status','unavailable','reason','logo_pipeline_unavailable'),'export',jsonb_build_object('status','unavailable','reason','logo_pipeline_unavailable')));
end $$;


ALTER FUNCTION fluid_private.logo_workspace_base_json(p_owner uuid, p_project uuid) OWNER TO postgres;

--
-- Name: logo_workspace_json(uuid, uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_workspace_json(p_owner uuid, p_project uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare workspace jsonb; stage jsonb; key text; stages jsonb;
begin
 workspace:=fluid_private.logo_workspace_json_before_visual_direction(p_owner,p_project);
 select record into stage from public.logo_stage_revisions where id=(workspace#>>'{stages,directions,id}')::uuid and owner_id=p_owner and project_id=p_project;
 if stage is not null and not fluid_private.logo_direction_visual_basis_current(p_owner,p_project,stage#>'{payload,directionIds}') then
  stages:=workspace->'staleStages';
  foreach key in array array['directions','deliverables'] loop
   if workspace#>>array['stages',key,'id'] is not null and not exists(select 1 from jsonb_array_elements(stages) s where s->>'stage'=key) then
    stages:=stages||jsonb_build_array(jsonb_build_object('stage',key,'reasons',jsonb_build_array('Reviewed visual direction or saved inspiration changed.')));
   end if;
  end loop;
  workspace:=jsonb_set(workspace,'{staleStages}',stages);
 end if;
 return workspace;
end $$;


ALTER FUNCTION fluid_private.logo_workspace_json(p_owner uuid, p_project uuid) OWNER TO postgres;

--
-- Name: logo_workspace_json_before_visual_direction(uuid, uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.logo_workspace_json_before_visual_direction(p_owner uuid, p_project uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare result jsonb;approval jsonb;
begin
 result:=fluid_private.logo_workspace_base_json(p_owner,p_project);
 select a.record into approval from public.logo_stage_heads h join public.logo_stage_revisions r on r.id=h.revision_id and r.owner_id=h.owner_id and r.project_id=h.project_id join public.logo_approvals a on a.id::text=r.record#>>'{payload,approvalId}' and a.owner_id=h.owner_id and a.project_id=h.project_id where h.owner_id=p_owner and h.project_id=p_project and h.stage='vector';
 return result||jsonb_build_object('approvedLogo',approval);
end $$;


ALTER FUNCTION fluid_private.logo_workspace_json_before_visual_direction(p_owner uuid, p_project uuid) OWNER TO postgres;

--
-- Name: lookup_home_attachment(uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.lookup_home_attachment(p_request_key uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=fluid_private.home_attachment_owner(); row public.home_attachments;
begin select * into row from public.home_attachments where owner_id=owner and request_key=p_request_key;
 if not found then return null; end if; return fluid_private.home_attachment_reservation(row); end $$;


ALTER FUNCTION fluid_private.lookup_home_attachment(p_request_key uuid) OWNER TO postgres;

