    idempotency_key text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    engine_version integer DEFAULT 1 NOT NULL,
    CONSTRAINT naming_batches_engine_version_check CHECK ((engine_version = ANY (ARRAY[1, 2, 3]))),
    CONSTRAINT naming_batches_idempotency_key_check CHECK ((idempotency_key ~ '^[A-Za-z0-9._:-]{16,128}$'::text)),
    CONSTRAINT naming_batches_policy_identity_check CHECK ((policy_identity ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT naming_batches_sequence_check CHECK ((sequence > 0)),
    CONSTRAINT naming_batches_target_count_check CHECK ((target_count = ANY (ARRAY[100, 50, 250])))
);

