--
-- Name: name_candidates; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.name_candidates (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    owner_id uuid NOT NULL,
    project_id uuid NOT NULL,
    value text NOT NULL,
    identity_key text NOT NULL,
    context_revision integer NOT NULL,
    strategy_basis jsonb NOT NULL,
    origin jsonb NOT NULL,
    rationale text DEFAULT ''::text NOT NULL,
    caution text,
    batch_id uuid,
    transform_id uuid,
    source_project_id uuid,
    source_candidate_id uuid,
    source_context jsonb,
    idempotency_key text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT name_candidates_caution_check CHECK ((length(caution) <= 2000)),
    CONSTRAINT name_candidates_check CHECK (((source_project_id IS NULL) = (source_candidate_id IS NULL))),
    CONSTRAINT name_candidates_check1 CHECK (((((origin ->> 'kind'::text) = 'generated'::text) AND (batch_id IS NOT NULL) AND (transform_id IS NULL) AND (source_candidate_id IS NULL)) OR (((origin ->> 'kind'::text) = 'local_import'::text) AND (batch_id IS NULL) AND (transform_id IS NULL) AND (source_candidate_id IS NULL)) OR (((origin ->> 'kind'::text) = 'transform'::text) AND (batch_id IS NULL) AND (transform_id IS NOT NULL) AND (source_candidate_id IS NULL) AND ((origin ->> 'authorship'::text) = 'user_supplied'::text)) OR (((origin ->> 'kind'::text) = 'account_copy'::text) AND (batch_id IS NULL) AND (transform_id IS NULL) AND (source_candidate_id IS NOT NULL)) OR (((origin ->> 'kind'::text) = 'brainstorm'::text) AND ((origin ->> 'profile'::text) = 'brainstorm_v1'::text) AND ((origin -> 'version'::text) = '1'::jsonb) AND (batch_id IS NOT NULL) AND (transform_id IS NULL) AND (source_candidate_id IS NULL)) OR (((origin ->> 'kind'::text) = 'brainstorm'::text) AND ((origin ->> 'profile'::text) = 'brainstorm_v1'::text) AND ((origin -> 'version'::text) = '2'::jsonb) AND (batch_id IS NULL) AND (transform_id IS NULL) AND (source_candidate_id IS NULL) AND (origin ? 'runId'::text)))),
    CONSTRAINT name_candidates_idempotency_key_check CHECK ((idempotency_key ~ '^[A-Za-z0-9._:-]{16,128}$'::text)),
    CONSTRAINT name_candidates_identity_key_check CHECK (((length(identity_key) >= 0) AND (length(identity_key) <= 320))),
    CONSTRAINT name_candidates_rationale_check CHECK ((length(rationale) <= 2000)),
    CONSTRAINT name_candidates_value_check CHECK (((length(value) >= 1) AND (length(value) <= 160)))
);

ALTER TABLE ONLY public.name_candidates FORCE ROW LEVEL SECURITY;


ALTER TABLE public.name_candidates OWNER TO postgres;

