--
-- Name: naming_generation_policy(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.naming_generation_policy() RETURNS TABLE(slot_id uuid, deployment_id text, policy jsonb, policy_identity text)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select s.slot_id,s.deployment_id,p.policy,p.policy_identity from fluid_private.shared_worker_slots s
  join fluid_private.shared_worker_policies p on p.slot_id=s.slot_id and p.operation='naming.generate'
  join fluid_private.shared_naming_slot_configuration cfg on cfg.slot_id=s.slot_id
 where s.lane='naming' and s.enabled and s.expires_at>clock_timestamp() and cfg.ready_until>clock_timestamp()
  and fluid_private.naming_generation_policy_valid(p.policy)
  and p.policy_identity=encode(sha256(convert_to(p.policy::text,'UTF8')),'hex')
 order by s.slot_id limit 1;
$$;


ALTER FUNCTION fluid_private.naming_generation_policy() OWNER TO postgres;

--
-- Name: naming_generation_policy_valid(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.naming_generation_policy_valid(p jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select coalesce(jsonb_typeof(p)='object' and p->'version'='2'::jsonb and p->>'operation'='naming.generate'
  and length(btrim(coalesce(p->>'model',''))) between 1 and 150 and p->>'model'=btrim(p->>'model')
  and p->>'reasoningEffort' in('low','medium') and (select count(*) from jsonb_object_keys(p))=4,false);
$$;


ALTER FUNCTION fluid_private.naming_generation_policy_valid(p jsonb) OWNER TO postgres;

--
-- Name: naming_job_dto(public.naming_batches); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.naming_job_dto(p_batch public.naming_batches) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select fluid_private.strategy_job_summary(j)||jsonb_build_object('batchId',p_batch.id,'sequence',p_batch.sequence,'targetCount',p_batch.target_count,
 'results',coalesce((select jsonb_agg(jsonb_build_object('stepKey',step_key,'output',output) order by created_at) from public.job_steps where job_id=j.id and owner_id=j.owner_id and project_id=j.project_id and state='succeeded'),'[]'))
 ||case when p.partial_text is not null then jsonb_build_object('partialText',p.partial_text) else '{}'::jsonb end
 from public.jobs j left join public.subscription_job_partials p on p.job_id=j.id and p.owner_id=j.owner_id and p.project_id=j.project_id
 where j.id=p_batch.job_id and j.owner_id=p_batch.owner_id and j.project_id=p_batch.project_id;
$$;


ALTER FUNCTION fluid_private.naming_job_dto(p_batch public.naming_batches) OWNER TO postgres;

--
-- Name: valid_naming_preferences(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.valid_naming_preferences(p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
 declare k text; v jsonb; begin
 if p_value->'version'='1' then return fluid_private.naming_preferences_v1_valid(p_value); end if;
 if p_value->'version' is distinct from '2'::jsonb or p_value-array['version','creativeLocale','notes','minimumGraphemes','maximumGraphemes','approaches','directness','sourceLanguages','heritageNotes','culturalNotes','requiredText','excludedText']<>'{}'
 or not(p_value ?& array['approaches','directness','sourceLanguages','heritageNotes','culturalNotes','requiredText','excludedText']) then return false; end if;
 if not fluid_private.naming_preferences_v1_valid((p_value-array['approaches','directness','sourceLanguages','heritageNotes','culturalNotes','requiredText','excludedText'])||'{"version":1}') then return false; end if;
 if p_value->'directness'<>'null' and p_value->>'directness' not in('direct','suggestive','open_ended','all') then return false; end if;
 foreach k in array array['heritageNotes','culturalNotes'] loop if jsonb_typeof(p_value->k)<>'string' or length(p_value->>k)>2000 then return false; end if; end loop;
 foreach k in array array['approaches','sourceLanguages','requiredText','excludedText'] loop
 if jsonb_typeof(p_value->k)<>'array' or jsonb_array_length(p_value->k)>(case k when 'approaches' then 11 when 'sourceLanguages' then 12 else 20 end) then return false; end if;
 if exists(select 1 from jsonb_array_elements(p_value->k) x group by x having count(*)>1) then return false; end if;
 for v in select value from jsonb_array_elements(p_value->k) loop
 if jsonb_typeof(v)<>'string' or length(v#>>'{}') not between 1 and (case k when 'sourceLanguages' then 80 else 160 end) then return false; end if;
 if k='approaches' and v#>>'{}' not in('real_words','compounds','blends','invented','modified','phrases','initials','other_languages','classical_roots','people_places','stories_culture') then return false; end if;
 end loop; end loop;
 return true; end $$;


ALTER FUNCTION fluid_private.valid_naming_preferences(p_value jsonb) OWNER TO postgres;

