--
-- Name: naming_readiness(text, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.naming_readiness(p_scope text, p_context jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare v_missing jsonb:='[]';
begin
 if p_scope='visual_identity_only' then return '{"ready":false,"missing":["scope"]}'; end if;
 if length(btrim(coalesce(p_context->>'description','')))=0 then v_missing:=v_missing||'"description"'::jsonb; end if;
 if p_context#>'{intake,guidedInterview}' is null and coalesce(p_context->'reformulationConfirmed','false')<>'true' then v_missing:=v_missing||'"reformulation"'::jsonb; end if;
 if coalesce(p_context->'competitorReviewComplete','false')<>'true' then v_missing:=v_missing||'"competitors"'::jsonb; end if;
 if not exists(select 1 from jsonb_array_elements(coalesce(p_context->'audienceSegments','[]')) x where x->'selected'='true')
  or coalesce(p_context#>'{intake,audienceReviewedAt}','null')='null' then v_missing:=v_missing||'"audience"'::jsonb; end if;
 if coalesce(p_context->'personality','null')='null' or coalesce(p_context#>'{intake,personalityReviewedAt}','null')='null' then v_missing:=v_missing||'"personality"'::jsonb; end if;
 if p_context#>'{intake,guidedInterview}' is null and (length(btrim(coalesce(p_context->>'positioning','')))=0 or coalesce(p_context#>'{intake,positioningReviewedAt}','null')='null') then v_missing:=v_missing||'"positioning"'::jsonb; end if;
 if p_context#>'{intake,guidedInterview}' is not null then
  perform fluid_private.guided_interview_context(p_context#>'{intake,guidedInterview}',p_context#>'{intake,conversation}');
 end if;
 return jsonb_build_object('ready',case when p_scope='naming_only' then not(v_missing ? 'description') else jsonb_array_length(v_missing)=0 end,'missing',v_missing);
end $$;


ALTER FUNCTION fluid_private.naming_readiness(p_scope text, p_context jsonb) OWNER TO postgres;

--
-- Name: naming_run_json(public.naming_batches, public.jobs); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.naming_run_json(b public.naming_batches, j public.jobs) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select jsonb_build_object('runId',b.id,'jobId',j.id,'kind',j.input->>'kind',
  'state',case when j.state='running' and j.cancel_requested_at is not null then 'cancel_requested'
   when j.state in('partial','needs_reconciliation') then 'failed' else j.state end,
  'target',100,
  'savedCount',least(100,(select count(*) from public.name_candidates c where c.batch_id=b.id))::integer,
  'errorCode',j.error_code,
  'usage',(select case when count(r.usage)=0 then null else jsonb_build_object(
    'inputTokens',sum((r.usage->>'inputTokens')::bigint),'outputTokens',sum((r.usage->>'outputTokens')::bigint),
    'totalTokens',sum((r.usage->>'totalTokens')::bigint)) end
   from fluid_private.naming_rounds r where r.batch_id=b.id),
  'createdAt',j.created_at,'finishedAt',j.finished_at);
$$;


ALTER FUNCTION fluid_private.naming_run_json(b public.naming_batches, j public.jobs) OWNER TO postgres;

