ALTER FUNCTION fluid_private.project_deletion_worker(p_owner_id uuid) OWNER TO postgres;

--
-- Name: project_screening_basis(uuid, uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.project_screening_basis(p_project_id uuid, p_owner uuid) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select jsonb_build_object('ownerId',p.owner_id,'projectId',p.id,'selectionId',s.id,'candidateId',c.id,
  'projectRevision',p.current_revision,'contextHash',r.input_hash,'name',c.value)
 from public.projects p join public.naming_sessions n on n.project_id=p.id and n.owner_id=p.owner_id
 join public.name_selections s on s.id=n.current_selection_id and s.owner_id=n.owner_id and s.project_id=n.project_id
 join public.name_candidates c on c.id=s.candidate_id and c.owner_id=s.owner_id and c.project_id=s.project_id
 join public.project_revisions r on r.project_id=p.id and r.owner_id=p.owner_id and r.revision=p.current_revision
 where p.id=p_project_id and p.owner_id=p_owner and r.context->>'selectedName'=c.value;
$$;


ALTER FUNCTION fluid_private.project_screening_basis(p_project_id uuid, p_owner uuid) OWNER TO postgres;

--
-- Name: project_screening_records; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.project_screening_records (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    request_id uuid NOT NULL,
    owner_id uuid NOT NULL,
    project_id uuid NOT NULL,
    selection_id uuid NOT NULL,
    candidate_id uuid NOT NULL,
    project_revision integer NOT NULL,
    context_hash text NOT NULL,
    selected_name text NOT NULL,
    criteria jsonb NOT NULL,
    notes text NOT NULL,
    source_urls jsonb NOT NULL,
    observed_at timestamp with time zone NOT NULL,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    request_payload jsonb NOT NULL,
    CONSTRAINT project_screening_records_check CHECK ((observed_at <= recorded_at)),
    CONSTRAINT project_screening_records_context_hash_check CHECK ((context_hash ~ '^[a-f0-9]{64}$'::text)),
    CONSTRAINT project_screening_records_notes_check CHECK (((length(notes) >= 1) AND (length(notes) <= 3000))),
    CONSTRAINT project_screening_records_request_payload_check CHECK ((octet_length((request_payload)::text) <= 32768)),
    CONSTRAINT project_screening_records_selected_name_check CHECK (((length(selected_name) >= 1) AND (length(selected_name) <= 160)))
);

ALTER TABLE ONLY public.project_screening_records FORCE ROW LEVEL SECURITY;


