--
-- Name: protect_api_text_dispatch(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.protect_api_text_dispatch() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if tg_op='DELETE' then raise exception 'immutable_dispatch' using errcode='55000'; end if;
 if (new.job_id,new.owner_id,new.project_id,new.policy_identity,new.deployment_id,new.dispatch_identity,new.created_at)
    is distinct from (old.job_id,old.owner_id,old.project_id,old.policy_identity,old.deployment_id,old.dispatch_identity,old.created_at)
    or new.publication_generation not in (old.publication_generation,old.publication_generation+1)
    or (new.publication_generation=old.publication_generation and new.generation_started_at is distinct from old.generation_started_at)
    or (new.publication_generation=old.publication_generation and old.published_at is not null and
       (new.published_at,new.published_message_id) is distinct from (old.published_at,old.published_message_id))
    or (new.publication_generation=old.publication_generation+1 and
       (new.generation_started_at<=old.generation_started_at or new.published_at is not null or new.published_message_id is not null)) then
   raise exception 'immutable_dispatch' using errcode='55000';
 end if;
 return new;
end $$;


ALTER FUNCTION fluid_private.protect_api_text_dispatch() OWNER TO postgres;

--
-- Name: protect_job_plan(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.protect_job_plan() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
  if old.plan_manifest is not null and (new.plan_manifest, new.plan_fingerprint, new.plan_registered_at)
      is distinct from (old.plan_manifest, old.plan_fingerprint, old.plan_registered_at) then
    raise exception 'immutable_job_plan' using errcode = '55000';
  end if;
  return new;
end $$;


ALTER FUNCTION fluid_private.protect_job_plan() OWNER TO postgres;

--
-- Name: read_logo_asset_publication(uuid, jsonb, uuid, uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.read_logo_asset_publication(p_project uuid, p_reference jsonb, p_job uuid, p_lease uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid;r public.logo_asset_publications;j public.jobs;allowed boolean;
begin
 if p_job is null then owner:=fluid_private.logo_asset_web_owner();else owner:=fluid_private.logo_worker_owner();end if;
 if p_job is not null then j:=fluid_private.logo_asset_job(owner,p_project,p_job,p_lease);end if;
 select * into r from public.logo_asset_publications where owner_id=owner and project_id=p_project and version_id=(p_reference->>'versionId')::uuid;
 if not found or (fluid_private.logo_asset_reservation(r)->'reference') is distinct from p_reference then raise exception 'logo_asset_not_found' using errcode='P0002';end if;
 if p_job is null and r.state<>'committed' then raise exception 'logo_asset_not_committed' using errcode='P0002';end if;
 if p_job is not null then
  allowed:=(r.job_id=j.id and r.lease_token=j.lease_token) or fluid_private.logo_job_can_read_asset(j,p_reference);
  if not coalesce(allowed,false) then raise exception 'logo_unlisted_source' using errcode='42501';end if;
 end if;
 return fluid_private.logo_asset_reservation(r);
end $$;


ALTER FUNCTION fluid_private.read_logo_asset_publication(p_project uuid, p_reference jsonb, p_job uuid, p_lease uuid) OWNER TO postgres;

--
-- Name: read_logo_trusted_request(uuid, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.read_logo_trusted_request(p_project uuid, p_command jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=fluid_private.logo_asset_web_owner();existing public.logo_workspace_requests;cancelled public.logo_vector_edit_cancellations;
begin
 if not exists(select 1 from public.projects where id=p_project and owner_id=owner) then raise exception 'logo_project_not_found' using errcode='P0002';end if;
 if not fluid_private.logo_uuid(p_command#>'{body,requestKey}') then raise exception 'invalid_logo_request' using errcode='22023';end if;
 select * into existing from public.logo_workspace_requests where owner_id=owner and project_id=p_project and request_key=(p_command#>>'{body,requestKey}')::uuid and method<>'startLogoProject';
 if found then
  if existing.input is distinct from p_command then raise exception 'logo_request_conflict' using errcode='PT409';end if;return existing.receipt;
 end if;
 select * into cancelled from public.logo_vector_edit_cancellations where owner_id=owner and project_id=p_project and request_key=(p_command#>>'{body,requestKey}')::uuid;
 if found then
  if cancelled.command is distinct from p_command then raise exception 'logo_request_conflict' using errcode='PT409';end if;
  raise exception 'logo_edit_cancelled' using errcode='PT409';
 end if;
 return null;
end $$;


ALTER FUNCTION fluid_private.read_logo_trusted_request(p_project uuid, p_command jsonb) OWNER TO postgres;

--
-- Name: record_logo_publication_failure_adjudication(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.record_logo_publication_failure_adjudication() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
declare
 pinned_job_sha256 constant text := 'c7b1ac00aee020e6db578db75f87838baf8c55a6e7130575db1e627d002b585d';
 pinned_step_sha256 constant text := '1fa597253d291b6525698070eb5330d453bd7e5872a8646461e7a0a7ab07f0ac';
 pinned_provider_sha256 constant text := '2672367f36d38be037824734a817f46623f2234d5f67a34dcf40bedb6ef02698';
 pinned_publication_sha256 constant text := '8fa6350214758eb59bdebe19386f618d88fb5a3675833ae84a89d2989946d814';
 pinned_reservation_sha256 constant text := 'c438f1c8d703a12728c9eeea4a173228ae20560f21866e67024df9d91972abd4';
 j public.jobs; s public.job_steps; p public.logo_provider_responses; a public.logo_asset_publications;
 r public.usage_reservations; m fluid_private.logo_local_jobs; g fluid_private.logo_generative_storage_grants;
 o storage.objects; ledger public.usage_accounts; after_ledger public.usage_accounts; project public.projects;
 released bigint;
begin
 if tg_op='TRUNCATE' and not exists(select 1 from fluid_private.logo_publication_failure_adjudications) then return null; end if;
 if tg_op<>'INSERT' then raise exception 'immutable_logo_publication_adjudication' using errcode='55000'; end if;
 if current_user is distinct from pg_get_userbyid((select relowner from pg_class where oid=tg_relid)) then
  raise exception 'operator_required' using errcode='42501'; end if;
 -- Project -> job is the publication lock order. The initial lookup acquires
 -- no authority; every owner, input, lease and receipt is checked below.
 select pr.* into strict project from public.projects pr join public.jobs jj on jj.project_id=pr.id and jj.owner_id=pr.owner_id
  where jj.id=new.job_id for update of pr;
 select * into strict j from public.jobs where id=new.job_id for update;
 select * into strict s from public.job_steps where job_id=j.id for update;
 select * into strict p from public.logo_provider_responses where job_id=j.id for update;
 select * into strict a from public.logo_asset_publications where job_id=j.id for update;
 select * into strict r from public.usage_reservations where job_id=j.id for update;
 select * into strict m from fluid_private.logo_local_jobs where job_id=j.id for share;
 select * into strict g from fluid_private.logo_generative_storage_grants
  where job_id=j.id and lease_token=a.lease_token and reservation_id=a.id and mode='write' for share;
 select * into strict o from storage.objects where bucket_id='fluid-assets'
  and name=a.owner_id::text||'/'||a.project_id::text||'/'||a.asset_id::text||'/'||a.version_id::text for share;
 select * into strict ledger from public.usage_accounts where owner_id=j.owner_id for update;
 if encode(sha256(convert_to(to_jsonb(j)::text,'UTF8')),'hex') is distinct from pinned_job_sha256
  or encode(sha256(convert_to(to_jsonb(s)::text,'UTF8')),'hex') is distinct from pinned_step_sha256
  or encode(sha256(convert_to(to_jsonb(p)::text,'UTF8')),'hex') is distinct from pinned_provider_sha256
  or encode(sha256(convert_to(to_jsonb(a)::text,'UTF8')),'hex') is distinct from pinned_publication_sha256
  or encode(sha256(convert_to(to_jsonb(r)::text,'UTF8')),'hex') is distinct from pinned_reservation_sha256
  or j.operation is distinct from 'identity.logo_concept' or j.state is distinct from 'needs_reconciliation'
  or j.error_code is distinct from 'publication_unknown' or j.billing_mode is distinct from 'openai_api'
  or j.lease_token is not null or j.lease_expires_at is not null or j.finished_at is not null
  or j.cancel_requested_at is not null or j.project_deletion_requested_at is not null
  or project.deleted_at is not null or project.deletion_requested_at is not null
  or (s.owner_id,s.project_id,s.state,s.output) is distinct from (j.owner_id,j.project_id,'ambiguous','{"error":"publication_unknown"}'::jsonb)
  or s.completed_at is null or s.provider_request_id is null
  or j.plan_manifest is distinct from jsonb_build_array(jsonb_build_object('key',s.step_key,'maximumCostMicrousd',j.reserved_cost_microusd))
  or (p.owner_id,p.project_id,p.lease_token) is distinct from (j.owner_id,j.project_id,a.lease_token)
  or p.observation->>'providerRequestId' is distinct from s.provider_request_id
  or p.observation#>>'{billing,status}' is distinct from 'recorded'
  or (p.observation#>>'{billing,confirmedMicrousd}')::bigint is distinct from j.actual_cost_microusd
  or j.actual_cost_microusd<=0 or j.actual_cost_microusd>j.reserved_cost_microusd
  or s.actual_cost_microusd is distinct from j.actual_cost_microusd
  or (r.owner_id,r.project_id,r.state,r.reserved_microusd,r.actual_microusd,r.captured_microusd)
   is distinct from (j.owner_id,j.project_id,'active',j.reserved_cost_microusd,j.actual_cost_microusd,j.actual_cost_microusd)
  or (a.owner_id,a.project_id,a.state,a.input_revision,a.input_hash)
   is distinct from (j.owner_id,j.project_id,'reserved',j.input_revision,j.input_hash)
  or a.verification is not null or a.lease_token is null or a.mime_type is distinct from 'image/png'
  or a.content_hash is distinct from p.observation->>'artifactHash'
  or a.request_key::text is distinct from j.input->>'attemptId'
  or a.request#>>'{publication,source,sourceId}' is distinct from j.input->>'attemptId'
  or a.request#>>'{publication,source,kind}' is distinct from 'concept'
  or exists(select 1 from public.assets where id=a.asset_id)
  or exists(select 1 from public.asset_versions where id=a.version_id)
  or exists(select 1 from public.logo_raster_results where job_id=j.id)
  or (m.owner_id,m.project_id,m.worker_id,m.policy_identity)
   is distinct from (j.owner_id,j.project_id,j.worker_id,j.input->>'policyIdentity')
  or not exists(select 1 from fluid_private.logo_worker_principals wp join pg_roles role on role.oid=wp.role_oid and role.rolname=wp.role_name
   where wp.owner_id=m.owner_id and wp.role_name=m.role_name and wp.role_oid=m.role_oid
   and role.rolcanlogin and not role.rolinherit and not role.rolsuper and not role.rolbypassrls
   and not role.rolcreatedb and not role.rolcreaterole and not role.rolreplication
   and not exists(select 1 from pg_auth_members where member=role.oid))
  or g.member is distinct from 'output'
  or g.binding is distinct from jsonb_build_object('ownerId',j.owner_id,'workerId',m.worker_id,'sessionId',g.session_id,
   'authUserId',g.auth_user_id,'workerRoleOid',m.role_oid::bigint,'workerRoleName',m.role_name)
  or not exists(select 1 from fluid_private.logo_storage_principals sp where sp.auth_user_id=g.auth_user_id
   and sp.owner_id=j.owner_id and sp.role_name=m.role_name and sp.role_oid=m.role_oid and sp.worker_id=m.worker_id)
  or o.owner_id is distinct from g.auth_user_id::text
  or (to_jsonb(o)#>>'{metadata,size}')::bigint is distinct from a.byte_length
  or (to_jsonb(o)#>>'{metadata,contentLength}')::bigint is distinct from a.byte_length
  or to_jsonb(o)#>>'{metadata,mimetype}' is distinct from a.mime_type then
  raise exception 'logo_publication_adjudication_evidence_mismatch' using errcode='55000';
 end if;
 new.job_before:=to_jsonb(j); new.step_before:=to_jsonb(s); new.provider_before:=to_jsonb(p);
 new.publication_before:=to_jsonb(a); new.reservation_before:=to_jsonb(r); new.local_marker:=to_jsonb(m); new.storage_grant:=to_jsonb(g);
 -- Access timestamps are not object identity. Object version and upload metadata
 -- remain bound without requiring an expired Auth session to exist forever.
 new.storage_object:=to_jsonb(o)-array['last_accessed_at'];
 new.account_before:=to_jsonb(ledger); new.operator_role:=current_user; new.operator_session:=session_user;
 new.recorded_at:=clock_timestamp();
 perform fluid_private.settle_reservation(j.id);
 select to_jsonb(rr) into strict new.reservation_after from public.usage_reservations rr where job_id=j.id;
 select * into strict after_ledger from public.usage_accounts where owner_id=j.owner_id;
 new.account_after:=to_jsonb(after_ledger); released:=greatest(r.reserved_microusd-r.actual_microusd,0);
 if new.reservation_after is distinct from (new.reservation_before||'{"state":"settled"}'::jsonb)
  or new.account_after is distinct from (new.account_before||jsonb_build_object('reserved_microusd',ledger.reserved_microusd-released)) then
  raise exception 'logo_publication_adjudication_accounting_changed' using errcode='55000'; end if;
 update public.jobs set state='failed',error_code='publication_not_committed',finished_at=new.recorded_at where id=j.id;
 return new;
end $$;


ALTER FUNCTION fluid_private.record_logo_publication_failure_adjudication() OWNER TO postgres;

--
-- Name: reference_attribution(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.reference_attribution(p_value jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare v_key text;
begin
 if jsonb_typeof(p_value) is distinct from 'object' then return false;end if;
 if p_value-array['label','creator','sourceUrl','rightsNote']<>'{}' or not(p_value ?& array['label','creator','sourceUrl','rightsNote']) then return false;end if;
 if jsonb_typeof(p_value->'label')<>'string' or length(p_value->>'label') not between 1 and 240 then return false;end if;
 foreach v_key in array array['creator','rightsNote','sourceUrl'] loop
  if jsonb_typeof(p_value->v_key) not in('string','null') then return false;end if;
  if jsonb_typeof(p_value->v_key)='string' and length(p_value->>v_key) not between 1 and (case v_key when 'creator' then 240 when 'rightsNote' then 2000 else 2048 end) then return false;end if;
 end loop;
 foreach v_key in array array['label','creator','sourceUrl','rightsNote'] loop
  if jsonb_typeof(p_value->v_key)='string' and (p_value->>v_key)<>fluid_private.reference_trim(p_value->>v_key) then return false;end if;
 end loop;
 if jsonb_typeof(p_value->'sourceUrl')='string' and not fluid_private.reference_attribution_url(p_value->>'sourceUrl') then return false;end if;
 return true;
end $$;


ALTER FUNCTION fluid_private.reference_attribution(p_value jsonb) OWNER TO postgres;

--
-- Name: reference_attribution_url(text); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.reference_attribution_url(p_value text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare v_parts text[];v_authority text[];v_host text;v_labels text[];v_label text;
begin
 if p_value is null or length(p_value)>2048 or p_value collate "C" !~ '^[!-~]+$' or position(chr(92) in p_value)>0
  or position('%' in regexp_replace(p_value,'%[0-9A-Fa-f]{2}','','g'))>0 then return false;end if;
 v_parts:=regexp_match(p_value,'^(https?)://([^/?#]+)([/?#].*)?$','i');
 if v_parts is null then return false;end if;
 v_authority:=regexp_match(v_parts[2],'^([^:]+)(:([1-9][0-9]{0,4}))?$');
 if v_authority is null or (v_authority[3] is not null and v_authority[3]::integer>65535) then return false;end if;
 v_host:=v_authority[1];v_labels:=string_to_array(v_host,'.');
 if length(v_host)>253 then return false;end if;
 if v_host ~ '^[0-9.]+$' then
  if cardinality(v_labels)<>4 then return false;end if;
  foreach v_label in array v_labels loop
   if v_label !~ '^(0|[1-9][0-9]{0,2})$' then return false;end if;
   if v_label::integer>255 then return false;end if;
  end loop;
 else
  if v_labels[cardinality(v_labels)] collate "C" !~ '^[A-Za-z]' then return false;end if;
  foreach v_label in array v_labels loop
   if length(v_label)>63 or left(translate(v_label,'ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'),4)='xn--' or v_label collate "C" !~ '^[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?$' then return false;end if;
  end loop;
 end if;
 return true;
end $_$;


ALTER FUNCTION fluid_private.reference_attribution_url(p_value text) OWNER TO postgres;

--
-- Name: reference_elements(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.reference_elements(p_value jsonb) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare v_result text[]; v_order constant text[]:=array['logo','typography','colors','graphics','images','composition'];
begin
 if jsonb_typeof(p_value) is distinct from 'array' then raise exception 'invalid_reference_elements' using errcode='22023';end if;
 if jsonb_array_length(p_value)>6 or exists(select 1 from jsonb_array_elements(p_value) x where jsonb_typeof(x)<>'string' or not((x#>>'{}')=any(v_order))) then raise exception 'invalid_reference_elements' using errcode='22023';end if;
 select coalesce(array_agg(x order by array_position(v_order,x)),array[]::text[]) into v_result from jsonb_array_elements_text(p_value) x;
 if cardinality(v_result)<>(select count(distinct x) from unnest(v_result) x) then raise exception 'duplicate_reference_elements' using errcode='22023';end if;
 return v_result;
end $$;


ALTER FUNCTION fluid_private.reference_elements(p_value jsonb) OWNER TO postgres;

--
-- Name: reference_tags(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.reference_tags(p_value jsonb) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare v_result text[];
begin
 if jsonb_typeof(p_value) is distinct from 'array' then raise exception 'invalid_reference_tags' using errcode='22023';end if;
 if jsonb_array_length(p_value)>50 or exists(select 1 from jsonb_array_elements(p_value) x where jsonb_typeof(x)<>'string') then raise exception 'invalid_reference_tags' using errcode='22023';end if;
 select coalesce(array_agg(t order by t collate "C"),array[]::text[]) into v_result from
  (select fluid_private.reference_trim(x) t from jsonb_array_elements_text(p_value) x) s;
 if exists(select 1 from unnest(v_result) t where length(t) not between 1 and 80) or cardinality(v_result)<>(select count(distinct t) from unnest(v_result) t) then raise exception 'invalid_reference_tags' using errcode='22023';end if;
 return v_result;
end $$;


ALTER FUNCTION fluid_private.reference_tags(p_value jsonb) OWNER TO postgres;

--
-- Name: reference_trim(text); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.reference_trim(p_value text) RETURNS text
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $$
 select btrim(p_value,U&'\0009\000A\000B\000C\000D\0020\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000\FEFF');
$$;


ALTER FUNCTION fluid_private.reference_trim(p_value text) OWNER TO postgres;

--
-- Name: refresh_shared_account(uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.refresh_shared_account(p_owner uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 insert into fluid_private.shared_accounts(owner_id,enabled) values(p_owner,exists(select 1 from auth.users where id=p_owner))
 on conflict(owner_id) do update set eligibility_epoch=fluid_private.shared_accounts.eligibility_epoch+1,
 enabled=exists(select 1 from auth.users where id=p_owner),updated_at=clock_timestamp();
end $$;


ALTER FUNCTION fluid_private.refresh_shared_account(p_owner uuid) OWNER TO postgres;

--
-- Name: require_active_project(uuid, uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.require_active_project(p_project_id uuid, p_owner_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p public.projects;
begin
  select * into p from public.projects where id=p_project_id and owner_id=p_owner_id for share;
  if not found then raise exception 'project_not_found' using errcode='P0002'; end if;
  if p.deleted_at is not null or (p.deletion_requested_at is not null and
    (not fluid_private.project_deletion_worker(p.owner_id) or fluid_private.project_deletion_state(p.id,p.owner_id)='deleted')) then
    raise exception 'project_deleted' using errcode='PT409';
  end if;
end $$;


ALTER FUNCTION fluid_private.require_active_project(p_project_id uuid, p_owner_id uuid) OWNER TO postgres;

--
-- Name: resolve_home_attachments(uuid[]); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.resolve_home_attachments(p_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=fluid_private.home_attachment_owner(); v_attachment_id uuid; row public.home_attachments; result jsonb:='[]';
begin
 if p_ids is null or cardinality(p_ids)>5 or array_position(p_ids,null) is not null or cardinality(p_ids)<>(select count(distinct v) from unnest(p_ids) v) then raise exception 'invalid_home_ids' using errcode='22023'; end if;
 foreach v_attachment_id in array p_ids loop select * into row from public.home_attachments where home_attachments.id=v_attachment_id and owner_id=owner; if not found then raise exception 'home_attachment_not_found' using errcode='P0002'; end if; result:=result||jsonb_build_array(fluid_private.home_attachment_reservation(row)); end loop; return result;
end $$;


ALTER FUNCTION fluid_private.resolve_home_attachments(p_ids uuid[]) OWNER TO postgres;

--
-- Name: resolve_logo_raster_source(uuid, uuid, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.resolve_logo_raster_source(p_owner uuid, p_project uuid, p_source jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare result jsonb;jid uuid;inputs jsonb;typ text;
begin
 if p_source->>'kind'='concept' and fluid_private.standalone_keys(p_source,array['kind','batchId','slotId','attemptId']) and fluid_private.logo_uuid(p_source->'batchId') and fluid_private.logo_uuid(p_source->'slotId') and fluid_private.logo_uuid(p_source->'attemptId') then
  select a.job_id,b.input_revisions,s.logo_type into jid,inputs,typ from public.logo_concept_attempts a join public.logo_concept_slots s on s.id=a.slot_id and s.owner_id=a.owner_id and s.project_id=a.project_id join public.logo_concept_batches b on b.id=s.batch_id and b.owner_id=s.owner_id and b.project_id=s.project_id where a.id=(p_source->>'attemptId')::uuid and s.id=(p_source->>'slotId')::uuid and b.id=(p_source->>'batchId')::uuid and a.owner_id=p_owner and a.project_id=p_project;
 elsif p_source->>'kind'='refinement' and fluid_private.standalone_keys(p_source,array['kind','rasterRevisionId']) and fluid_private.logo_uuid(p_source->'rasterRevisionId') then
  select job_id,input_revisions,logo_type into jid,inputs,typ from public.logo_raster_refinements where id=(p_source->>'rasterRevisionId')::uuid and owner_id=p_owner and project_id=p_project;
 else raise exception 'invalid_logo_source' using errcode='22023';end if;
 select preview into result from public.logo_raster_results where job_id=jid and owner_id=p_owner and project_id=p_project;
 if result is null or result->>'publicationState'<>'committed' then raise exception 'logo_source_not_found' using errcode='P0002';end if;
 return jsonb_build_object('source',p_source,'preview',result,'inputRevisions',inputs,'logoType',typ);
end $$;


ALTER FUNCTION fluid_private.resolve_logo_raster_source(p_owner uuid, p_project uuid, p_source jsonb) OWNER TO postgres;

--
-- Name: settle_reservation(uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.settle_reservation(p_job_id uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare v_reservation public.usage_reservations;
begin
  if exists(select 1 from public.jobs where id=p_job_id and billing_mode='chatgpt_subscription') then return; end if;
  select * into strict v_reservation from public.usage_reservations where job_id = p_job_id for update;
  if v_reservation.state = 'settled' then return; end if;
  update public.usage_accounts set reserved_microusd = reserved_microusd - greatest(v_reservation.reserved_microusd - v_reservation.actual_microusd, 0)
    where owner_id = v_reservation.owner_id;
  update public.usage_reservations set state = 'settled' where job_id = p_job_id;
end $$;


ALTER FUNCTION fluid_private.settle_reservation(p_job_id uuid) OWNER TO postgres;

