--
-- Name: shared_account_customer_active(uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.shared_account_customer_active(p_owner uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from fluid_private.shared_accounts a join auth.users u on u.id=a.owner_id
  where a.owner_id=p_owner and a.enabled and u.email_confirmed_at is not null
  and u.is_anonymous=false and u.deleted_at is null
  and (u.banned_until is null or u.banned_until<=clock_timestamp())
  and not exists(select 1 from fluid_private.shared_service_actors s where s.auth_user_id=u.id));
$$;


ALTER FUNCTION fluid_private.shared_account_customer_active(p_owner uuid) OWNER TO postgres;

--
-- Name: shared_http_context_closed(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.shared_http_context_closed() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if exists(select 1 from fluid_private.shared_http_contexts where backend_pid=new.backend_pid and transaction_id=new.transaction_id)
 then raise exception 'shared_http_context_cleanup_required' using errcode='55000'; end if;
 return null;
end $$;


ALTER FUNCTION fluid_private.shared_http_context_closed() OWNER TO postgres;

--
-- Name: shared_http_context_owner(text); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.shared_http_context_owner(p_lane text) RETURNS uuid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c fluid_private.shared_http_contexts; role_id oid;
begin
 if not exists(select 1 from fluid_private.shared_http_principals where role_name=session_user) then return null; end if;
 role_id:=fluid_private.shared_http_role(p_lane);
 select * into c from fluid_private.shared_http_contexts where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id()
  and role_name=session_user and role_oid=role_id and lane=p_lane;
 if c.owner_id is null or c.eligibility_epoch is distinct from (select eligibility_epoch from fluid_private.shared_accounts where owner_id=c.owner_id)
  or not fluid_private.shared_http_live(c.owner_id,c.session_id,c.expires_at)
 then raise exception 'shared_http_context_required' using errcode='42501'; end if;
 return c.owner_id;
end $$;


ALTER FUNCTION fluid_private.shared_http_context_owner(p_lane text) OWNER TO postgres;

--
-- Name: shared_http_customer_storage_live(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.shared_http_customer_storage_live() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); claims jsonb:=auth.jwt(); sid uuid;
begin
 if owner is null then return false; end if;
 if not exists(select 1 from fluid_private.shared_accounts where owner_id=owner)
  or exists(select 1 from fluid_private.shared_service_actors where auth_user_id=owner) then return true; end if;
 if claims->>'sub' is distinct from owner::text or claims->>'role' is distinct from 'authenticated'
  or claims->>'aud' is distinct from 'authenticated' or claims->'is_anonymous' is distinct from 'false'::jsonb
  or not coalesce(fluid_private.logo_uuid(claims->'session_id'),false)
  or jsonb_typeof(claims->'exp') is distinct from 'number'
  or (claims->>'exp')::numeric<=extract(epoch from clock_timestamp())
  or claims ? 'nbf' and (jsonb_typeof(claims->'nbf') is distinct from 'number'
   or (claims->>'nbf')::numeric>extract(epoch from clock_timestamp()))
  or not exists(select 1 from fluid_private.shared_http_target where singleton and claims->>'iss'=origin||'/auth/v1') then return false; end if;
 sid:=(claims->>'session_id')::uuid;
 -- Hold actual Auth rows through this Storage transaction. A concurrent ban or
 -- session deletion must serialize with the final request authority check.
 perform 1 from auth.users where id=owner for share;
 perform 1 from auth.sessions where id=sid and user_id=owner for share;
 perform 1 from fluid_private.shared_accounts where owner_id=owner for share;
 return fluid_private.shared_account_customer_active(owner)
  and exists(select 1 from auth.sessions where id=sid and user_id=owner and (not_after is null or not_after>clock_timestamp()));
exception when invalid_text_representation or numeric_value_out_of_range then return false;
end $$;


ALTER FUNCTION fluid_private.shared_http_customer_storage_live() OWNER TO postgres;

--
-- Name: shared_http_live(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.shared_http_live(p_owner uuid, p_session uuid, p_expires timestamp with time zone) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select p_expires>clock_timestamp() and fluid_private.shared_account_customer_active(p_owner)
  and exists(select 1 from auth.sessions where id=p_session and user_id=p_owner and (not_after is null or not_after>clock_timestamp()));
$$;


ALTER FUNCTION fluid_private.shared_http_live(p_owner uuid, p_session uuid, p_expires timestamp with time zone) OWNER TO postgres;

--
-- Name: shared_http_redeem(text, text, text, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.shared_http_redeem(p_token text, p_lane text, p_action text, p_arguments jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare r fluid_private.shared_http_requests; snapshot fluid_private.shared_http_requests; role_id oid;
begin
 role_id:=fluid_private.shared_http_role(p_lane);
 if session_user<>(select role_name from fluid_private.shared_http_principals where lane=p_lane)
  or to_regrole(session_user)::oid<>role_id or current_setting('role')<>'none' or p_token!~'^[a-f0-9]{64}$'
  or exists(select 1 from fluid_private.shared_http_contexts where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id())
 then raise exception 'shared_http_redemption_denied' using errcode='42501'; end if;
 -- Read immutable identity first. Auth/session deletion cascades token rows, so
 -- acquiring a token lock before its parent Auth locks would invert that order.
 select * into r from fluid_private.shared_http_requests where token_hash=sha256(convert_to(p_token,'UTF8'));
 if r.token_hash is null or r.consumed or r.lane<>p_lane or r.role_oid<>role_id or r.action<>p_action
  or r.arguments_hash<>sha256(convert_to(p_arguments::text,'UTF8'))
  or r.eligibility_epoch is distinct from (select eligibility_epoch from fluid_private.shared_accounts where owner_id=r.owner_id)
  or not fluid_private.shared_http_live(r.owner_id,r.session_id,r.expires_at)
 then raise exception 'shared_http_request_invalid' using errcode='42501'; end if;
 snapshot:=r;
 -- Hold real Auth/session rows until transaction outcome; no post-ban write race.
 perform 1 from auth.users where id=r.owner_id for share;
 perform 1 from auth.sessions where id=r.session_id and user_id=r.owner_id for share;
 perform 1 from fluid_private.shared_accounts where owner_id=r.owner_id for share;
 select * into r from fluid_private.shared_http_requests where token_hash=sha256(convert_to(p_token,'UTF8')) for update;
 if r.token_hash is null or r is distinct from snapshot or r.consumed or r.lane<>p_lane or r.role_oid<>role_id or r.action<>p_action
  or r.arguments_hash<>sha256(convert_to(p_arguments::text,'UTF8'))
  or not fluid_private.shared_http_live(r.owner_id,r.session_id,r.expires_at)
  or r.eligibility_epoch is distinct from (select eligibility_epoch from fluid_private.shared_accounts where owner_id=r.owner_id)
 then raise exception 'shared_http_account_unavailable' using errcode='42501'; end if;
 update fluid_private.shared_http_requests set consumed=true where token_hash=r.token_hash;
 insert into fluid_private.shared_http_contexts values(pg_backend_pid(),pg_current_xact_id(),session_user,role_id,r.token_hash,r.owner_id,r.session_id,p_lane,p_action,p_arguments,r.eligibility_epoch,r.expires_at);
 return r.owner_id;
end $_$;


ALTER FUNCTION fluid_private.shared_http_redeem(p_token text, p_lane text, p_action text, p_arguments jsonb) OWNER TO postgres;

--
-- Name: shared_http_role(text); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.shared_http_role(p_lane text) RETURNS oid
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r pg_catalog.pg_roles; p fluid_private.shared_http_principals; allowed oid[];
begin
 select * into p from fluid_private.shared_http_principals where lane=p_lane and enabled;
 select * into r from pg_catalog.pg_roles where oid=p.role_oid and rolname=p.role_name;
 allowed:=array[to_regprocedure('public.subscription_worker_owner()')::oid,to_regprocedure('public.subscription_worker_can_read_step(uuid,uuid)')::oid,
  to_regprocedure('public.api_text_worker_owner()')::oid,to_regprocedure('public.api_text_worker_can_read_step(uuid,uuid)')::oid,
  to_regprocedure('public.shared_account_http_principal()')::oid];
 if p_lane='home' then allowed:=allowed||to_regprocedure('public.execute_shared_home_request(text,text,jsonb,jsonb)')::oid;
 elsif p_lane='identity' then allowed:=allowed||array[to_regprocedure('public.prepare_shared_identity_request(text,uuid,jsonb,boolean)')::oid,
  to_regprocedure('public.commit_shared_identity_request(uuid,jsonb,jsonb)')::oid,to_regprocedure('public.finish_shared_identity_request()')::oid]; end if;
 allowed:=array_remove(allowed,null);
 if r.oid is null or not r.rolcanlogin or r.rolinherit or r.rolsuper or r.rolcreatedb or r.rolcreaterole or r.rolbypassrls or r.rolreplication
  or exists(select 1 from pg_catalog.pg_auth_members where member=r.oid
   or roleid=r.oid and not(member=to_regrole('postgres')::oid and admin_option and not inherit_option and not set_option))
  or exists(select 1 from pg_catalog.pg_class where relowner=r.oid)
  or exists(select 1 from pg_catalog.pg_namespace where nspowner=r.oid)
  or exists(select 1 from pg_catalog.pg_proc where proowner=r.oid)
  or has_database_privilege(r.oid,current_database(),'CREATE')
  or has_schema_privilege(r.oid,'public','CREATE') or has_schema_privilege(r.oid,'fluid_private','CREATE') or has_schema_privilege(r.oid,'fluid_private','USAGE')
  or exists(select 1 from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace
   where n.nspname in('public','fluid_private','auth','storage') and c.relkind in('r','p','v','m','f')
   and (has_any_column_privilege(r.oid,c.oid,'SELECT,INSERT,UPDATE,REFERENCES') or has_table_privilege(r.oid,c.oid,'DELETE,TRUNCATE,TRIGGER')))
  or exists(select 1 from pg_catalog.pg_class c join pg_catalog.pg_namespace n on n.oid=c.relnamespace
   where case when n.nspname in('public','fluid_private','auth','storage') and c.relkind='S'
    then has_sequence_privilege(r.oid,c.oid,'SELECT,USAGE,UPDATE') else false end)
  or exists(select 1 from pg_catalog.pg_proc fn join pg_catalog.pg_namespace ns on ns.oid=fn.pronamespace
   where ns.nspname='public' and fn.prosecdef and has_function_privilege(r.oid,fn.oid,'EXECUTE') and not(fn.oid=any(allowed)))
 then raise exception 'shared_http_principal_unqualified' using errcode='42501'; end if;
 return r.oid;
end $$;


ALTER FUNCTION fluid_private.shared_http_role(p_lane text) OWNER TO postgres;

--
-- Name: shared_identity_batch_state(uuid, uuid, uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.shared_identity_batch_state(p_owner uuid, p_project uuid, p_batch uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare b public.identity_batches;j public.jobs;i public.identity_input_snapshots;intent jsonb;systems jsonb;n integer;terminal boolean;usage_status text;known bigint;missing boolean;
begin
 select * into b from public.identity_batches where id=p_batch and owner_id=p_owner and project_id=p_project;
 if not found then return null; end if;
 select * into strict j from public.jobs where id=b.job_id and owner_id=p_owner and project_id=p_project and operation='identity.image';
 select * into strict i from public.identity_input_snapshots where id=b.input_id and owner_id=p_owner and project_id=p_project;
 select r.intent into strict intent from fluid_private.shared_identity_requests r where r.batch_id=b.id and r.owner_id=p_owner and r.project_id=p_project;
 select coalesce(jsonb_agg(fluid_private.shared_identity_verified_system(s) order by root.step_key,root.output_index),'[]') into systems
 from public.identity_generated_roots root join public.identity_system_versions s on s.id=root.system_id and s.owner_id=root.owner_id and s.project_id=root.project_id
 where root.batch_id=b.id and root.owner_id=p_owner and root.project_id=p_project;
 n:=jsonb_array_length(systems);terminal:=j.state in('succeeded','failed','cancelled','partial');
 select coalesce(sum(case when r.observation#>>'{billing,status}'='recorded' then (r.observation#>>'{billing,confirmedMicrousd}')::bigint else 0 end),0),
 count(*) filter(where r.id is null or r.observation#>>'{billing,status}'<>'recorded')>0 into known,missing
 from fluid_private.shared_identity_calls c left join fluid_private.shared_identity_receipts r on r.call_id=c.id where c.job_id=j.id;
 usage_status:=case when missing then 'unknown' when j.state in('queued','running','cancel_requested') then 'pending' else 'recorded' end;
 return jsonb_build_object('ownerId',p_owner,'projectId',p_project,'batchId',b.id,'jobId',j.id,'status',j.state,'terminal',j.lease_token is null and j.state in('succeeded','failed','cancelled','partial'),'intent',intent,'input',i.input,'systems',systems,
 'fulfillment',jsonb_build_object('targetCount',3,'acceptedCount',n,'status',case when n=3 then 'complete' when n>0 then 'partial' when terminal or j.state='needs_reconciliation' then 'none' else 'pending' end))||case when j.input->'version'='3' then jsonb_build_object('sourceLogo',j.input->'sourceLogo','sourceLogoCurrent',coalesce(((j.input->'sourceLogo')-'selectionRevision')=(fluid_private.shared_identity_selected_logo(p_owner,p_project)-'selectionRevision'),false),'usage',jsonb_build_object('status',usage_status,'knownCostMicrousd',known)) else '{}'::jsonb end;
end $$;


ALTER FUNCTION fluid_private.shared_identity_batch_state(p_owner uuid, p_project uuid, p_batch uuid) OWNER TO postgres;

--
-- Name: shared_identity_customer(uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.shared_identity_customer(p_project uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o uuid:=auth.uid();c jsonb:=auth.jwt();sid uuid;
begin
 if session_user<>'authenticator' or current_setting('role')<>'authenticated' or o is null or c->>'sub' is distinct from o::text
 or c->>'role' is distinct from 'authenticated' or c->>'aud' is distinct from 'authenticated' or c->>'is_anonymous' is distinct from 'false'
 or jsonb_typeof(c->'exp') is distinct from 'number' or to_timestamp((c->>'exp')::double precision)<=clock_timestamp()
 or not exists(select 1 from fluid_private.shared_http_target where c->>'iss'=origin||'/auth/v1')
 then raise exception 'shared_identity_verified_account_required' using errcode='42501'; end if;
 sid:=(c->>'session_id')::uuid;
 perform 1 from auth.users where id=o for share;
 perform 1 from auth.sessions where id=sid and user_id=o for share;
 perform 1 from fluid_private.shared_accounts where owner_id=o for share;
 if not fluid_private.shared_account_customer_active(o) or not exists(select 1 from auth.sessions where id=sid and user_id=o and (not_after is null or not_after>clock_timestamp()))
 then raise exception 'shared_identity_account_unavailable' using errcode='42501'; end if;
 if not exists(select 1 from public.projects where id=p_project and owner_id=o and deleted_at is null and deletion_requested_at is null)
 then raise exception 'shared_identity_project_missing' using errcode='P0002'; end if;
 return o;
end $$;


ALTER FUNCTION fluid_private.shared_identity_customer(p_project uuid) OWNER TO postgres;

--
-- Name: shared_identity_intent_valid(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.shared_identity_intent_valid(p_intent jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$begin
 if fluid_private.standalone_keys(p_intent,array['version','spendControl','expectedProjectRevision','expectedReferenceRevision','expectedPreferencesRevision','expectedIdentityRevision','idempotencyKey','acceptedPolicyIdentity']||(case when p_intent->'version'='3' then array['sourceLogo','expectedLogoRevision'] else array[]::text[] end)) is distinct from true
 or p_intent->>'version' not in('2','3') or p_intent->>'spendControl' is distinct from 'uncapped'
 or coalesce(p_intent->>'idempotencyKey','')!~'^[A-Za-z0-9._:-]{16,128}$' or coalesce(p_intent->>'acceptedPolicyIdentity','')!~'^[a-f0-9]{64}$' then return false;end if;
 perform fluid_private.identity_counter(p_intent->'expectedProjectRevision',true);perform fluid_private.identity_counter(p_intent->'expectedReferenceRevision');
 if p_intent->'version'='3' then perform fluid_private.identity_counter(p_intent->'expectedLogoRevision',true);if jsonb_typeof(p_intent->'sourceLogo') is distinct from 'object' then return false;end if;end if;
 perform fluid_private.identity_counter(p_intent->'expectedPreferencesRevision');perform fluid_private.identity_counter(p_intent->'expectedIdentityRevision');return true;
exception when invalid_parameter_value or invalid_text_representation or numeric_value_out_of_range then return false;
end $_$;


ALTER FUNCTION fluid_private.shared_identity_intent_valid(p_intent jsonb) OWNER TO postgres;

--
-- Name: shared_identity_job(public.jobs); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.shared_identity_job(j public.jobs) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select case when j.operation is distinct from 'identity.image' or not exists(select 1 from fluid_private.shared_identity_admissions admitted where admitted.job_id=j.id) then false else exists(select 1 from fluid_private.shared_job_admissions a
 join fluid_private.shared_identity_admissions admitted on admitted.job_id=a.job_id
 and (admitted.owner_id,admitted.project_id,admitted.input_hash,admitted.policy_identity,admitted.policy,admitted.deployment_id)
 =(a.owner_id,a.project_id,a.input_hash,a.policy_identity,a.policy,a.deployment_id)
 join fluid_private.shared_worker_slots anchor on anchor.slot_id=admitted.slot_id and (anchor.role_name,anchor.role_oid)=(admitted.role_name,admitted.role_oid)
 join public.identity_batches b on b.job_id=j.id and b.owner_id=j.owner_id and b.project_id=j.project_id
 join public.identity_input_snapshots i on i.id=b.input_id and i.owner_id=b.owner_id and i.project_id=b.project_id
 where a.job_id=j.id and (a.owner_id,a.project_id,a.operation,a.input_hash,a.lane)=(j.owner_id,j.project_id,'identity.image'::text,j.input_hash,'logo'::text)
 and fluid_private.shared_identity_policy_valid(a.policy) and a.policy_identity=j.input->>'policyIdentity' and a.policy->'textPolicy'=j.input->'textPolicy'
 and j.input->>'operation'='identity.image' and j.input->>'version' in('2','3')
 and (j.input->'version'='2' or (j.input#>'{input,version}'='2' and j.input#>'{input,logoBrief}'=j.input#>'{sourceLogo,brief}' and fluid_private.shared_identity_logo_source_valid(j.owner_id,j.project_id,j.input->'sourceLogo'))) and j.input->>'spendControl'='uncapped' and j.input->>'handlerVersion'='identity-image-v1'
 and j.input->>'ownerId'=j.owner_id::text and j.input->>'projectId'=j.project_id::text and j.input->>'batchId'=b.id::text and j.input->'input'=i.input
 and jsonb_array_length(j.input->'systemIds')=3 and (select count(distinct value) from jsonb_array_elements(j.input->'systemIds'))=3
 and j.input_hash=encode(sha256(convert_to(j.input::text,'UTF8')),'hex')) end;
$$;


ALTER FUNCTION fluid_private.shared_identity_job(j public.jobs) OWNER TO postgres;

--
-- Name: shared_identity_logo_source_valid(uuid, uuid, jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.shared_identity_logo_source_valid(o uuid, p uuid, s jsonb) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare selection jsonb;brief jsonb;raster jsonb;publication public.logo_asset_publications;begin
 if fluid_private.standalone_keys(s,array['version','source','selectionRevision','logoType','brief','preview']) is distinct from true
 or s->'version' is distinct from '1'::jsonb then return false;end if;
 select record into selection from public.logo_stage_revisions where owner_id=o and project_id=p and stage='concepts' and revision=fluid_private.identity_counter(s->'selectionRevision',true);
 if selection#>'{payload,selected}' is distinct from s->'source' then return false;end if;
 raster:=fluid_private.resolve_logo_raster_source(o,p,s->'source');
 select record into brief from public.logo_stage_revisions where owner_id=o and project_id=p and stage='brief_references' and id=(s#>>'{brief,id}')::uuid;
 if brief is null or brief is distinct from s->'brief' or s->'preview' is distinct from raster->'preview' or s->'logoType' is distinct from raster->'logoType'
 or not exists(select 1 from jsonb_array_elements(raster->'inputRevisions') ref where ref->>'stage'='brief_references' and ref->>'id'=brief->>'id' and ref->'revision'=brief->'revision') then return false;end if;
 select * into publication from public.logo_asset_publications where id=(s#>>'{preview,id}')::uuid and owner_id=o and project_id=p;
 return publication.id is not null and publication.state='committed' and publication.purpose='brand_asset' and publication.mime_type in('image/png','image/jpeg','image/webp')
 and fluid_private.logo_asset_receipt(publication)=s->'preview'
 and exists(select 1 from public.asset_versions v where (v.id,v.asset_id,v.owner_id,v.project_id,v.content_hash,v.mime_type)=(publication.version_id,publication.asset_id,o,p,publication.content_hash,publication.mime_type)
 and v.storage_path=o::text||'/'||p::text||'/'||publication.asset_id::text||'/'||publication.version_id::text and v.provenance->>'publicationId'=publication.id::text);
exception when invalid_parameter_value or invalid_text_representation or numeric_value_out_of_range or no_data_found then return false;
end $$;


ALTER FUNCTION fluid_private.shared_identity_logo_source_valid(o uuid, p uuid, s jsonb) OWNER TO postgres;

--
-- Name: shared_identity_policy_valid(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.shared_identity_policy_valid(p jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO ''
    AS $_$
 select coalesce(fluid_private.standalone_keys(p,array['operation','policyIdentity','handlerVersion','provider','model','engine','maxCostMicrousd','spendControl','textPolicy'])
 and p->>'operation'='identity.image' and p->>'policyIdentity'~'^[a-f0-9]{64}$' and p->>'handlerVersion'='identity-image-v1'
 and p->>'provider'='openai' and p->>'model'='gpt-image-2.5-sunburst-2026-09-08' and p->'engine'='null' and p->'maxCostMicrousd'='0' and p->>'spendControl'='uncapped'
 and fluid_private.standalone_keys(p->'textPolicy',array['version','model','serviceTier','pricingVersion','maxInputTokens','maxOutputTokens','maxInputBytes','maxOutputBytes','deadlineMs','maxTools'])
 and p#>'{textPolicy,version}'='1' and p#>>'{textPolicy,model}'='gpt-6.1-sol' and p#>>'{textPolicy,serviceTier}'='default' and p#>>'{textPolicy,pricingVersion}'='2026-10-03'
 and p#>'{textPolicy,maxTools}'='0' and fluid_private.identity_counter(p#>'{textPolicy,maxInputTokens}',true)<=32768
 and fluid_private.identity_counter(p#>'{textPolicy,maxOutputTokens}',true)<=8192
 and fluid_private.identity_counter(p#>'{textPolicy,maxInputBytes}') between 1024 and 131072
 and fluid_private.identity_counter(p#>'{textPolicy,maxOutputBytes}') between 1024 and 65536
 and fluid_private.identity_counter(p#>'{textPolicy,deadlineMs}') between 1000 and 240000,false);
$_$;


ALTER FUNCTION fluid_private.shared_identity_policy_valid(p jsonb) OWNER TO postgres;

--
-- Name: shared_identity_selected_logo(uuid, uuid); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.shared_identity_selected_logo(o uuid, p uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare workspace jsonb;selection jsonb;raster jsonb;brief jsonb;result jsonb;begin
 workspace:=fluid_private.logo_workspace_json(o,p);
 select record into selection from public.logo_stage_revisions where id=(workspace#>>'{stages,concepts,id}')::uuid and owner_id=o and project_id=p;
 if selection#>'{payload,selected}' is null or selection#>'{payload,selected}'='null'::jsonb then return null;end if;
 if exists(select 1 from jsonb_array_elements(workspace->'staleStages') stale where stale->>'stage' in('brief_references','concepts')
 or selection#>>'{payload,selected,kind}'='refinement' and stale->>'stage'='refinements') then return null;end if;
 raster:=fluid_private.resolve_logo_raster_source(o,p,selection#>'{payload,selected}');
 select r.record into brief from jsonb_array_elements(raster->'inputRevisions') ref
  join public.logo_stage_revisions r on r.id=(ref->>'id')::uuid and r.owner_id=o and r.project_id=p and r.stage='brief_references' and to_jsonb(r.revision)=ref->'revision'
  where ref->>'stage'='brief_references' and fluid_private.logo_brief_same_except_types(o,p,r.id,(workspace#>>'{stages,brief_references,id}')::uuid)
  order by r.id::text=workspace#>>'{stages,brief_references,id}' desc,r.revision desc limit 1;
 result:=jsonb_build_object('version',1,'source',raster->'source','selectionRevision',selection->'revision','logoType',raster->'logoType','brief',brief,'preview',raster->'preview');
 if fluid_private.shared_identity_logo_source_valid(o,p,result) is not true then return null;end if;
 return result;
end $$;


ALTER FUNCTION fluid_private.shared_identity_selected_logo(o uuid, p uuid) OWNER TO postgres;

