-- Name: shared_logo_http_live(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.shared_logo_http_live(p_owner uuid, p_session uuid, p_expires timestamp with time zone) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select p_expires>clock_timestamp() and fluid_private.shared_account_customer_active(p_owner)
  and exists(select 1 from auth.sessions where id=p_session and user_id=p_owner and (not_after is null or not_after>clock_timestamp()));
$$;


