--
-- Name: valid_strategy_subscription_policy(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.valid_strategy_subscription_policy(p_policy jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
declare v_limits jsonb; v_key text; v_value numeric; v_min integer; v_max integer;
begin
  if p_policy is null or jsonb_typeof(p_policy) <> 'object'
    or p_policy - array['version','billingMode','handlerVersion','registrationId','model','limits'] <> '{}'::jsonb
    or p_policy->'version' is distinct from '1'::jsonb
    or p_policy->>'billingMode' is distinct from 'chatgpt_subscription'
    or p_policy->>'handlerVersion' is distinct from 'strategy-chatgpt-v1'
    or jsonb_typeof(p_policy->'registrationId') is distinct from 'string'
    or length(p_policy->>'registrationId') not between 1 and 300
    or jsonb_typeof(p_policy->'model') is distinct from 'string'
    or length(p_policy->>'model') not between 1 and 150 then return false; end if;
  v_limits := p_policy->'limits';
  if jsonb_typeof(v_limits) is distinct from 'object'
    or v_limits - array['maxInputBytes','maxOutputBytes','deadlineMs','maxObservedWebSearchCalls','maxRequestsPerHour','maxQueuedJobs'] <> '{}'::jsonb then return false; end if;
  foreach v_key in array array['maxInputBytes','maxOutputBytes','deadlineMs','maxObservedWebSearchCalls','maxRequestsPerHour','maxQueuedJobs'] loop
    if jsonb_typeof(v_limits->v_key) is distinct from 'number' then return false; end if;
    v_value := (v_limits->>v_key)::numeric;
    v_min := case v_key when 'maxInputBytes' then 1024 when 'maxOutputBytes' then 1024 when 'deadlineMs' then 1000 when 'maxObservedWebSearchCalls' then 0 else 1 end;
    v_max := case v_key when 'maxInputBytes' then 1048576 when 'maxOutputBytes' then 1048576 when 'deadlineMs' then 300000 when 'maxObservedWebSearchCalls' then 10 when 'maxRequestsPerHour' then 100 else 10 end;
    if trunc(v_value) <> v_value or v_value not between v_min and v_max then return false; end if;
  end loop;
  return true;
end $$;


ALTER FUNCTION fluid_private.valid_strategy_subscription_policy(p_policy jsonb) OWNER TO postgres;

--
-- Name: valid_subscription_policy(jsonb); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.valid_subscription_policy(p_policy jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $$
begin
 if p_policy->>'handlerVersion'='strategy-chatgpt-v1' then return fluid_private.valid_strategy_subscription_policy(p_policy); end if;
 if p_policy->>'handlerVersion'='naming-chatgpt-v1' then
  return fluid_private.valid_strategy_subscription_policy(jsonb_set(p_policy,'{handlerVersion}','"strategy-chatgpt-v1"'))
   and p_policy#>'{limits,maxObservedWebSearchCalls}'='0'::jsonb;
 end if;
 return false;
end $$;


ALTER FUNCTION fluid_private.valid_subscription_policy(p_policy jsonb) OWNER TO postgres;

--
-- Name: validate_identity_reference_media(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.validate_identity_reference_media() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_field text;
begin
 -- Normalize whitespace only on actual string fields; preserve nulls, unknown
 -- keys and invalid types so the strict constraint can reject them unchanged.
 foreach v_field in array array['label','creator','sourceUrl','rightsNote'] loop
  if jsonb_typeof(new.attribution->v_field)='string' then
   new.attribution:=jsonb_set(new.attribution,array[v_field],to_jsonb(fluid_private.reference_trim(new.attribution->>v_field)),false);
  end if;
 end loop;
 -- Future trusted constructors must take this same project lock before selection/capture.
 perform 1 from public.projects p where p.id=new.project_id and p.owner_id=new.owner_id for update;
 if not exists(select 1 from public.assets a join public.asset_versions v on v.asset_id=a.id and v.project_id=a.project_id and v.owner_id=a.owner_id
  where a.id=new.asset_id and a.project_id=new.project_id and a.owner_id=new.owner_id and a.purpose='reference_media'
   and v.id=new.media_version_id and v.mime_type in('image/png','image/jpeg','image/webp')
   and v.storage_path=new.owner_id::text||'/'||new.project_id::text||'/'||new.asset_id::text||'/'||new.media_version_id::text)
 then raise exception 'invalid_reference_media' using errcode='23514';end if;
 -- Purpose is insertion-time immutable in the Assets migration, and versions are immutable.
 -- This binding does not establish that Storage bytes exist or match their metadata hash.
 return new;
end $$;


ALTER FUNCTION fluid_private.validate_identity_reference_media() OWNER TO postgres;

--
-- Name: validate_identity_reference_reaction(); Type: FUNCTION; Schema: fluid_private; Owner: postgres
--

CREATE FUNCTION fluid_private.validate_identity_reference_reaction() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_relevant text[];
begin
 select r.relevant_elements into v_relevant from public.identity_references r where r.id=new.reference_id and r.project_id=new.project_id and r.owner_id=new.owner_id;
 if found and not(new.elements<@v_relevant) then raise exception 'irrelevant_reference_element' using errcode='22023';end if;
 return new;
end $$;


ALTER FUNCTION fluid_private.validate_identity_reference_reaction() OWNER TO postgres;

