--
-- Name: project_revisions; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.project_revisions (
    project_id uuid NOT NULL,
    owner_id uuid DEFAULT auth.uid() NOT NULL,
    revision integer NOT NULL,
    context jsonb NOT NULL,
    input_hash text NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT project_revisions_context_check CHECK (((jsonb_typeof(context) = 'object'::text) AND (octet_length((context)::text) <= 131072))),
    CONSTRAINT project_revisions_input_hash_check CHECK ((input_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT project_revisions_revision_check CHECK ((revision > 0))
);

ALTER TABLE ONLY public.project_revisions FORCE ROW LEVEL SECURITY;


ALTER TABLE public.project_revisions OWNER TO postgres;

--
-- Name: append_project_revision(uuid, integer, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.append_project_revision(p_project_id uuid, p_expected_revision integer, p_context jsonb, p_input_hash text, p_title text DEFAULT NULL::text) RETURNS public.project_revisions
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_owner uuid := auth.uid();
  v_project public.projects;
  v_revision public.project_revisions;
begin
  select p.* into v_project from public.projects p
    where p.id = p_project_id and p.owner_id = v_owner for update;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if p_expected_revision is null or p_expected_revision < 1 then
    raise exception 'invalid_revision' using errcode = '22023';
  end if;
  if v_project.current_revision <> p_expected_revision then
    raise exception 'revision_conflict' using errcode = 'PT409';
  end if;
  if p_title is not null and length(btrim(p_title)) not between 1 and 160 then
    raise exception 'invalid_title' using errcode = '22023';
  end if;
  insert into public.project_revisions(project_id, owner_id, revision, context, input_hash)
    values(v_project.id, v_owner, v_project.current_revision + 1, p_context, p_input_hash)
    returning * into v_revision;
  update public.projects p set current_revision = v_revision.revision,
    title = coalesce(btrim(p_title), v_project.title)
    where p.id = v_project.id and p.owner_id = v_owner;
  return v_revision;
end $$;


ALTER FUNCTION public.append_project_revision(p_project_id uuid, p_expected_revision integer, p_context jsonb, p_input_hash text, p_title text) OWNER TO postgres;

