-- Name: cancel_identity_directions(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_identity_directions(p_project_id uuid, p_batch_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o uuid := fluid_private.engine_identity_customer(p_project_id);
begin
  if not fluid_private.engine_identity_cancel(o, p_project_id, p_batch_id) then raise exception 'identity_batch_missing' using errcode = 'P0002'; end if;
  return fluid_private.shared_identity_batch_state(o, p_project_id, p_batch_id);
end $$;


ALTER FUNCTION public.cancel_identity_directions(p_project_id uuid, p_batch_id uuid) OWNER TO postgres;

--
-- Name: cancel_logo_input_request(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.cancel_logo_input_request(p_project_id uuid, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); prior public.logo_input_requests; validated jsonb:=p_request; request_state jsonb;
begin
 if owner is null then raise exception 'unauthenticated' using errcode='42501';end if;
 -- Preserve former client URL spellings only for cancellation, never admission.
 if p_request->>'kind'='font_upload' then
  if p_request#>'{input,licenseSourceUrl}' is distinct from 'null'::jsonb and (jsonb_typeof(p_request#>'{input,licenseSourceUrl}') is distinct from 'string' or length(p_request#>>'{input,licenseSourceUrl}')>2048) then raise exception 'invalid_logo_input' using errcode='22023';end if;
  validated:=jsonb_set(p_request,'{input,licenseSourceUrl}','null'::jsonb);
 end if;
 if octet_length(p_request::text)>327680 or fluid_private.logo_input_request_valid(validated) is distinct from true then raise exception 'invalid_logo_input' using errcode='22023';end if;
 perform 1 from public.projects where id=p_project_id and owner_id=owner for update;
 if not found then raise exception 'logo_project_not_found' using errcode='P0002';end if;
 select * into prior from public.logo_input_requests where owner_id=owner and project_id=p_project_id and request_key=(p_request#>>'{input,requestKey}')::uuid;
 if found then
  if prior.request is distinct from p_request then raise exception 'immutable_logo_input_request' using errcode='PT409';end if;
 else
  insert into public.logo_input_requests(owner_id,project_id,request_key,request) values(owner,p_project_id,(p_request#>>'{input,requestKey}')::uuid,p_request) returning * into prior;
 end if;
 request_state:=fluid_private.logo_input_state(owner,p_project_id,prior.request_key);
 if request_state->>'status' in('succeeded','rejected') then return request_state;end if;
 insert into public.logo_input_rejections(owner_id,project_id,request_key,reason) values(owner,p_project_id,prior.request_key,'cancelled_by_user');
 return fluid_private.logo_input_state(owner,p_project_id,prior.request_key);
end $$;


ALTER FUNCTION public.cancel_logo_input_request(p_project_id uuid, p_request jsonb) OWNER TO postgres;

--
-- Name: close_identity_directions_intent(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.close_identity_directions_intent(p_project_id uuid, p_intent jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o uuid := fluid_private.engine_identity_customer(p_project_id); admitted uuid; admitted_intent jsonb; closed_intent jsonb; jid uuid; closed boolean;
begin
  if fluid_private.shared_identity_intent_valid(p_intent) is not true then raise exception 'identity_generation_intent_invalid' using errcode = '22023'; end if;
  perform pg_advisory_xact_lock(hashtextextended(o::text || ':' || p_project_id::text, 724005));
  select r.batch_id, r.intent into admitted, admitted_intent from fluid_private.shared_identity_requests r
   where r.owner_id = o and r.project_id = p_project_id and r.request_key = p_intent->>'idempotencyKey';
  if admitted is not null then
    if admitted_intent is distinct from p_intent then raise exception 'identity_generation_intent_conflict' using errcode = 'PT409'; end if;
    if not fluid_private.engine_identity_cancel(o, p_project_id, admitted) then
      select job_id into strict jid from public.identity_batches where id = admitted and owner_id = o and project_id = p_project_id;
      perform public.request_job_cancel(jid);
    end if;
    return jsonb_build_object('status', 'admitted', 'batch', fluid_private.shared_identity_batch_state(o, p_project_id, admitted));
  end if;
  select c.intent, true into closed_intent, closed from fluid_private.shared_identity_rejected_intents c
   where c.owner_id = o and c.project_id = p_project_id and c.request_key = p_intent->>'idempotencyKey';
  if closed then
    if closed_intent is distinct from p_intent then raise exception 'identity_generation_intent_conflict' using errcode = 'PT409'; end if;
  else
    insert into fluid_private.shared_identity_rejected_intents (owner_id, project_id, request_key, intent, reason)
      values (o, p_project_id, p_intent->>'idempotencyKey', p_intent, 'explicit_cancel');
  end if;
  return jsonb_build_object('status', 'not_admitted', 'ownerId', o, 'projectId', p_project_id, 'intent', p_intent);
end $$;


ALTER FUNCTION public.close_identity_directions_intent(p_project_id uuid, p_intent jsonb) OWNER TO postgres;

--
-- Name: commit_shared_identity_request(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.commit_shared_identity_request(p_project uuid, p_request jsonb, p_proposal jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid; c fluid_private.shared_http_contexts; result jsonb;
begin
 owner:=fluid_private.shared_http_context_owner('identity');
 if owner is null then raise exception 'shared_http_context_required' using errcode='42501'; end if;
 select * into strict c from fluid_private.shared_http_contexts where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id();
 if c.action<>'identity' or c.arguments->0<>to_jsonb(p_project) or c.arguments->1 is distinct from p_request
 then raise exception 'shared_http_request_mismatch' using errcode='42501'; end if;
 result:=fluid_private.commit_identity_transaction(p_project,p_request,p_proposal);
 return result;
end $$;


ALTER FUNCTION public.commit_shared_identity_request(p_project uuid, p_request jsonb, p_proposal jsonb) OWNER TO postgres;

--
-- Name: create_brand_from_project_name(uuid, uuid, integer, text, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_brand_from_project_name(p_project_id uuid, p_candidate_id uuid, p_expected_source_revision integer, p_title text, p_accept_earlier_context boolean, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_owner uuid:=auth.uid();v_source public.name_candidates;v_source_project public.projects;v_candidate public.name_candidates;v_project public.projects;
 v_context jsonb;v_root jsonb;v_history jsonb;v_session public.naming_sessions;v_selection public.name_selections;
begin
 if p_accept_earlier_context is null or p_expected_source_revision is null or p_expected_source_revision<1 or p_title is null or length(btrim(p_title)) not between 1 and 160
  or p_idempotency_key is null or p_idempotency_key!~'^[A-Za-z0-9._:-]{16,128}$' then raise exception 'invalid_promotion' using errcode='22023'; end if;
 if v_owner is null then raise exception 'unauthenticated' using errcode='42501'; end if;
 perform pg_advisory_xact_lock(hashtextextended(v_owner::text,723903));
 select * into v_source_project from public.projects where id=p_project_id and owner_id=v_owner for update;
 if not found then raise exception 'not_found' using errcode='P0002'; end if;
 select * into v_source from public.name_candidates where id=p_candidate_id and owner_id=v_owner and project_id=p_project_id;
 if not found then raise exception 'not_found' using errcode='P0002'; end if;
 select * into v_candidate from public.name_candidates where owner_id=v_owner and idempotency_key=p_idempotency_key;
 if found then
  if v_candidate.origin->>'kind'<>'account_copy' or (v_candidate.source_project_id,v_candidate.source_candidate_id) is distinct from(p_project_id,p_candidate_id)
   or v_candidate.origin->>'sourceContextRevision'<>p_expected_source_revision::text then raise exception 'promotion_conflict' using errcode='PT409'; end if;
  select * into strict v_project from public.projects where id=v_candidate.project_id and owner_id=v_owner;
  select * into strict v_session from public.naming_sessions where project_id=v_project.id and owner_id=v_owner;
  select * into v_selection from public.name_selections where id=v_session.current_selection_id and owner_id=v_owner and project_id=v_project.id;
  if v_project.title<>btrim(p_title) or v_project.current_revision<>1 or v_selection.candidate_id is distinct from v_candidate.id or v_selection.accepted_earlier_context is distinct from p_accept_earlier_context then raise exception 'promotion_conflict' using errcode='PT409'; end if;
 else
  if v_source_project.current_revision<>p_expected_source_revision then raise exception 'revision_conflict' using errcode='PT409'; end if;
  select context into strict v_context from public.project_revisions where project_id=p_project_id and owner_id=v_owner and revision=p_expected_source_revision;
  if fluid_private.naming_strategy_basis(v_context)<>v_source.strategy_basis and not p_accept_earlier_context then raise exception 'earlier_context_requires_acknowledgment' using errcode='PT409'; end if;
  v_context:=v_context||jsonb_build_object('selectedName',v_source.value,'intake',coalesce(v_context->'intake','{}')||jsonb_build_object('suppliedName',v_source.value));
  v_project:=public.create_project('complete_brand',btrim(p_title),v_context,encode(sha256(convert_to(v_context::text,'UTF8')),'hex'));
  v_session:=fluid_private.ensure_naming_session(v_project.id,v_owner);
  v_root:=case when v_source.origin->>'kind' in('generated','local_import','brainstorm') then v_source.origin else v_source.origin->'root' end;v_history:=coalesce(v_source.origin->'history','[]');
  v_candidate.id:=gen_random_uuid();v_candidate.owner_id:=v_owner;v_candidate.project_id:=v_project.id;v_candidate.value:=v_source.value;v_candidate.identity_key:=v_source.identity_key;
  v_candidate.context_revision:=1;v_candidate.strategy_basis:=v_source.strategy_basis;v_candidate.rationale:=v_source.rationale;v_candidate.caution:=v_source.caution;v_candidate.created_at:=clock_timestamp();
  v_candidate.source_project_id:=p_project_id;v_candidate.source_candidate_id:=p_candidate_id;v_candidate.idempotency_key:=p_idempotency_key;
  v_candidate.origin:=jsonb_build_object('kind','account_copy','authorship',case when (v_root->>'kind'='generated' or (v_root->>'kind'='brainstorm' and v_root->>'profile'='brainstorm_v1' and v_root->'version'='1'::jsonb)) and jsonb_array_length(v_history)=0 then 'generated' else 'user_supplied' end,
   'sourceProjectId',p_project_id,'sourceCandidateId',p_candidate_id,'sourceContextRevision',p_expected_source_revision,'root',v_root,'history',v_history);
  insert into public.name_candidates select(v_candidate).*;
  insert into public.name_selections(owner_id,project_id,candidate_id,project_revision,accepted_earlier_context) values(v_owner,v_project.id,v_candidate.id,1,p_accept_earlier_context) returning * into v_selection;
  update public.naming_sessions set current_selection_id=v_selection.id,revision=revision+1,updated_at=clock_timestamp() where project_id=v_project.id and owner_id=v_owner returning * into v_session;
 end if;
 return jsonb_build_object('project',fluid_private.naming_project_dto(v_project),'session',fluid_private.naming_session_dto(v_session),
  'currentSelection',jsonb_build_object('selection',fluid_private.naming_selection_dto(v_selection),'candidate',fluid_private.naming_candidate_dto(v_candidate)));
end $_$;


ALTER FUNCTION public.create_brand_from_project_name(p_project_id uuid, p_candidate_id uuid, p_expected_source_revision integer, p_title text, p_accept_earlier_context boolean, p_idempotency_key text) OWNER TO postgres;

--
-- Name: create_project(text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_project(p_scope text, p_title text, p_context jsonb, p_input_hash text) RETURNS public.projects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid := auth.uid(); v_project public.projects;
begin
  if v_owner is null then raise exception 'unauthenticated' using errcode = '42501'; end if;
  insert into public.projects(owner_id, scope, title) values(v_owner, p_scope, p_title) returning * into v_project;
  insert into public.project_revisions(project_id, owner_id, revision, context, input_hash)
    values(v_project.id, v_owner, 1, p_context, p_input_hash);
  return v_project;
end $$;


ALTER FUNCTION public.create_project(p_scope text, p_title text, p_context jsonb, p_input_hash text) OWNER TO postgres;

