-- Name: create_project_with_request(uuid, text, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_project_with_request(p_request_key uuid, p_scope text, p_title text, p_context jsonb, p_input_hash text) RETURNS TABLE(id uuid, owner_id uuid, scope text, title text, current_revision integer, created_at timestamp with time zone, context jsonb)
    LANGUAGE sql
    SET search_path TO ''
    BEGIN ATOMIC
 SELECT create_project_with_request.id,
     create_project_with_request.owner_id,
     create_project_with_request.scope,
     create_project_with_request.title,
