     create_project_with_request.context
    FROM fluid_private.create_project_with_request(create_project_with_request.p_request_key, create_project_with_request.p_scope, create_project_with_request.p_title, create_project_with_request.p_context, create_project_with_request.p_input_hash) create_project_with_request(id, owner_id, scope, title, current_revision, created_at, context);
END;


ALTER FUNCTION public.create_project_with_request(p_request_key uuid, p_scope text, p_title text, p_context jsonb, p_input_hash text) OWNER TO postgres;

--
-- Name: execute_shared_home_request(text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.execute_shared_home_request(p_token text, p_action text, p_arguments jsonb, p_observation jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid; result jsonb;
begin
 owner:=fluid_private.shared_http_redeem(p_token,'home',p_action,p_arguments);
 -- Compatibility RPCs derive auth.uid from this transaction-local, independently verified context; caller GUCs never supply the owner.
 perform set_config('request.jwt.claim.sub',owner::text,true);
 case p_action
 when 'prepare' then result:=fluid_private.prepare_home_attachment(p_arguments->0,(p_arguments->>1)::bigint);
 when 'lookup' then result:=fluid_private.lookup_home_attachment((p_arguments->>0)::uuid);
 when 'resolve' then result:=fluid_private.resolve_home_attachments(array(select value::uuid from jsonb_array_elements_text(p_arguments->0)));
 when 'save' then result:=public.save_attached_home_project(p_arguments->0,p_arguments->>1);
 when 'lookup_project' then result:=public.read_attached_home_project_request((p_arguments->>0)::uuid);
 when 'readback' then
  if p_observation is null then raise exception 'shared_http_observation_required' using errcode='22023'; end if;
  result:=fluid_private.observe_home_attachment((p_arguments->>0)::uuid,p_observation);
 else raise exception 'shared_http_action_invalid' using errcode='22023';
 end case;
 if p_action<>'readback' and p_observation is not null then raise exception 'shared_http_scope_invalid' using errcode='22023'; end if;
 delete from fluid_private.shared_http_contexts where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id() and role_name=session_user;
 return result;
end $$;


ALTER FUNCTION public.execute_shared_home_request(p_token text, p_action text, p_arguments jsonb, p_observation jsonb) OWNER TO postgres;

--
-- Name: execute_shared_logo_request(text, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.execute_shared_logo_request(p_token text, p_action text, p_arguments jsonb, p_evidence jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare owner uuid; result jsonb; project uuid;
begin
 owner:=fluid_private.shared_logo_http_redeem(p_token,'logo',p_action,p_arguments);
 project:=(p_arguments->>0)::uuid;
 if p_evidence is not null and octet_length(p_evidence::text)>4194304 then raise exception 'shared_logo_http_evidence_unbounded' using errcode='22023';end if;
 if p_action in('asset_prepare','command_read','input_prepare') and p_evidence is not null
  or p_action in('asset_readback','command_apply','input_commit','proposal_quote') and p_evidence is null
 then raise exception 'shared_logo_http_evidence_scope_invalid' using errcode='22023';end if;
 case p_action
 when 'asset_prepare' then result:=fluid_private.prepare_logo_asset(project,p_arguments->1,null,null);
 when 'asset_readback' then result:=fluid_private.observe_logo_asset((p_arguments->>1)::uuid,p_evidence,null,null);
 when 'command_read' then
  if p_arguments#>>'{1,method}'='applyLogoVectorProposal' then
   if to_regprocedure('fluid_private.shared_logo_read_proposal_command(uuid,jsonb)') is null then raise exception 'shared_logo_proposal_unavailable' using errcode='55000';end if;
   execute 'select fluid_private.shared_logo_read_proposal_command($1,$2)' into result using project,p_arguments->1;
  else result:=fluid_private.read_logo_trusted_request(project,p_arguments->1);end if;
 when 'command_apply' then
  if p_arguments#>>'{1,method}'='applyLogoVectorProposal' then
   if to_regprocedure('fluid_private.shared_logo_apply_proposal_command(uuid,jsonb,jsonb)') is null then raise exception 'shared_logo_proposal_unavailable' using errcode='55000';end if;
   execute 'select fluid_private.shared_logo_apply_proposal_command($1,$2,$3)' into result using project,p_arguments->1,p_evidence;
  else result:=fluid_private.apply_logo_trusted_command(project,p_arguments->1,p_evidence);end if;
 when 'input_prepare' then result:=fluid_private.prepare_logo_input(project,p_arguments->1);
 when 'input_commit' then
  if jsonb_typeof(p_evidence)<>'object' or not(p_evidence ?& array['receipt','evidence']) or p_evidence-array['receipt','evidence']<>'{}'
  then raise exception 'shared_logo_http_evidence_scope_invalid' using errcode='22023';end if;
  result:=fluid_private.commit_logo_input(project,p_arguments->1,p_evidence->'receipt',p_evidence->'evidence');
 when 'proposal_quote' then
  if p_evidence->'request' is distinct from p_arguments->1 then raise exception 'shared_logo_http_quote_intent_mismatch' using errcode='42501';end if;
  if to_regprocedure('fluid_private.shared_logo_quote_vector_proposal(uuid,jsonb)') is null then raise exception 'shared_logo_proposal_unavailable' using errcode='55000';end if;
  execute 'select fluid_private.shared_logo_quote_vector_proposal($1,$2)' into result using project,p_evidence;
 else raise exception 'shared_logo_http_action_invalid' using errcode='22023';
 end case;
 delete from fluid_private.shared_logo_http_contexts where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id() and role_name=session_user;
 return result;
end $_$;


ALTER FUNCTION public.execute_shared_logo_request(p_token text, p_action text, p_arguments jsonb, p_evidence jsonb) OWNER TO postgres;

--
-- Name: finish_shared_identity_request(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.finish_shared_identity_request() RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if fluid_private.shared_http_context_owner('identity') is null then raise exception 'shared_http_context_required' using errcode='42501'; end if;
 delete from fluid_private.shared_http_contexts where backend_pid=pg_backend_pid() and transaction_id=pg_current_xact_id() and role_name=session_user;
 return true;
end $$;


