--
-- Name: get_identity_directions_availability(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_identity_directions_availability(p_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o uuid := fluid_private.engine_identity_customer(p_project_id); p public.projects; state jsonb; logo jsonb; reason text;
  members integer; bytes bigint; policy jsonb := fluid_private.engine_identity_policy();
begin
  select * into strict p from public.projects where id = p_project_id and owner_id = o;
  state := fluid_private.identity_current_state(p_project_id);
  if p.scope = 'naming_only' then reason := 'inputs_not_ready'; end if;
  logo := fluid_private.shared_identity_selected_logo(o, p_project_id);
  if reason is null and logo is null then
    reason := case when exists (select 1 from public.logo_stage_heads h join public.logo_stage_revisions r on r.id = h.revision_id
                where h.owner_id = o and h.project_id = p_project_id and h.stage = 'concepts' and r.record#>'{payload,selected}' <> 'null'::jsonb)
              then 'logo_needs_review' else 'logo_selection_required' end;
  end if;
  if reason is null and (state#>>'{referenceSnapshot,selectedReferenceCount}')::integer > 3 then reason := 'reference_limit_exceeded'; end if;
  if reason is null then
    select count(*), coalesce(sum(publication.byte_length), 0) into members, bytes
      from jsonb_array_elements(state#>'{referenceSnapshot,selected}') entry
      join public.logo_asset_publications publication on publication.owner_id = o and publication.project_id = p_project_id
       and publication.asset_id = (entry#>>'{reference,media,assetId}')::uuid and publication.version_id = (entry#>>'{reference,media,versionId}')::uuid
       and publication.content_hash = entry#>>'{reference,media,contentHash}' and publication.mime_type = entry#>>'{reference,media,mimeType}'
       and publication.state = 'committed' and publication.purpose = 'reference_media' and publication.verification->>'status' = 'verified'
      join fluid_private.shared_identity_reference_requests registered on registered.owner_id = o and registered.project_id = p_project_id
       and registered.request_key = publication.request_key and registered.reference_id = (entry#>>'{reference,id}')::uuid
      join public.asset_versions v on (v.id, v.asset_id, v.owner_id, v.project_id, v.content_hash, v.mime_type)
        = (publication.version_id, publication.asset_id, o, p_project_id, publication.content_hash, publication.mime_type)
       and v.provenance->>'publicationId' = publication.id::text;
    if members <> (state#>>'{referenceSnapshot,selectedReferenceCount}')::integer then reason := 'references_unavailable';
    elsif bytes + coalesce((logo#>>'{preview,verification,byteLength}')::bigint, 0) > 20971520 then reason := 'reference_bytes_exceeded';
    end if;
  end if;
  if reason is not null then
    return jsonb_build_object('ownerId', o, 'projectId', p_project_id, 'status', 'unavailable', 'operation', 'identity.image',
      'requestedModel', policy->'requestedModel', 'reason', reason);
  end if;
  return jsonb_build_object('version', 3, 'spendControl', 'uncapped', 'ownerId', o, 'projectId', p_project_id, 'status', 'available',
    'operation', 'identity.image', 'requestedModel', policy->'requestedModel', 'policyIdentity', policy->'policyIdentity',
    'handlerVersion', 'identity-image-v1', 'targetCount', 3, 'maxReferenceImages', 4, 'maxReferenceBytes', 20971520,
    'estimatedCostMicrousd', null, 'sourceLogo', logo,
    'expectedProjectRevision', p.current_revision, 'expectedReferenceRevision', state#>'{referenceSnapshot,referenceRevision}',
    'expectedPreferencesRevision', coalesce(state#>'{preferences,revision}', '0'::jsonb),
    'expectedIdentityRevision', coalesce(state#>'{session,identityRevision}', '0'::jsonb), 'expectedLogoRevision', logo->'selectionRevision');
end $$;


ALTER FUNCTION public.get_identity_directions_availability(p_project_id uuid) OWNER TO postgres;

--
-- Name: get_identity_logo_source(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_identity_logo_source(p_project_id uuid, p_system_version_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$declare o uuid:=auth.uid();j public.jobs;s public.identity_system_versions;begin
 if o is null then raise exception 'unauthenticated' using errcode='42501';end if;
 select * into s from public.identity_system_versions where id=p_system_version_id and owner_id=o and project_id=p_project_id;
 if not found then raise exception 'identity_system_not_found' using errcode='P0002';end if;
 select job.* into j from public.identity_generated_roots root join public.jobs job on job.id=root.job_id and job.owner_id=root.owner_id and job.project_id=root.project_id
 where root.system_id=s.root_system_id and root.owner_id=o and root.project_id=p_project_id;
 if j.id is null then raise exception 'identity_generated_source_missing' using errcode='55000';end if;
 if j.input->'version'<>'3' then return null;end if;
 if fluid_private.shared_identity_logo_source_valid(o,p_project_id,j.input->'sourceLogo') is not true then raise exception 'identity_logo_source_unavailable' using errcode='55000';end if;
 return jsonb_build_object('sourceLogo',j.input->'sourceLogo','sourceLogoCurrent',coalesce(((j.input->'sourceLogo')-'selectionRevision')=(fluid_private.shared_identity_selected_logo(o,p_project_id)-'selectionRevision'),false));
end $$;


ALTER FUNCTION public.get_identity_logo_source(p_project_id uuid, p_system_version_id uuid) OWNER TO postgres;

--
-- Name: get_identity_references(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_identity_references(p_project_id uuid, p_query jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid();v_query jsonb;v_excluded text[];v_limit integer;v_cursor jsonb;v_anchor public.identity_references;v_result jsonb;
begin
 if v_owner is null or not exists(select 1 from public.projects p where p.id=p_project_id and p.owner_id=v_owner) then raise exception 'reference_project_not_found' using errcode='P0002';end if;
 v_query:=fluid_private.identity_reference_query(p_query,p_project_id);v_excluded:=fluid_private.reference_tags(v_query->'excludedTags');v_limit:=(v_query->>'limit')::integer;v_cursor:=v_query->'cursor';
 if exists(select 1 from unnest(v_excluded) t where not exists(select 1 from public.identity_references r where r.project_id=p_project_id and r.owner_id=v_owner and t=any(r.tags))) then raise exception 'unknown_reference_tag' using errcode='22023';end if;
 if v_cursor is not null then
  select * into v_anchor from public.identity_references r where r.id=(v_cursor->>'referenceId')::uuid and r.project_id=p_project_id and r.owner_id=v_owner;
  if not found then raise exception 'reference_cursor_not_found' using errcode='P0002';end if;
  if v_anchor.created_at<>(v_cursor->>'createdAt')::timestamptz or v_anchor.tags && v_excluded then raise exception 'invalid_reference_cursor' using errcode='22023';end if;
 end if;
 with candidates as materialized (
  select r.* from public.identity_references r where r.project_id=p_project_id and r.owner_id=v_owner and not(r.tags && v_excluded)
   and(v_cursor is null or(r.created_at,r.id)<(v_anchor.created_at,v_anchor.id)) order by r.created_at desc,r.id desc limit v_limit+1
 ), page as materialized(select * from candidates order by created_at desc,id desc limit v_limit),
 suggestions as (select distinct t collate "C" as tag from public.identity_references r cross join lateral unnest(r.tags) t where r.project_id=p_project_id and r.owner_id=v_owner order by tag limit 50),
 metadata as materialized(select tag from suggestions union select unnest(tags) from page union select unnest(v_excluded)),
 last_row as(select * from page order by created_at,id limit 1)
 select jsonb_build_object('ownerId',v_owner,'projectId',p_project_id,'query',v_query,
  'referenceRevision',coalesce((select h.reference_revision from public.identity_reference_heads h where h.project_id=p_project_id and h.owner_id=v_owner),0),
  'selectedReferenceCount',coalesce((select h.selected_reference_count from public.identity_reference_heads h where h.project_id=p_project_id and h.owner_id=v_owner),0),
  'feed',jsonb_build_object('status','unavailable','reason','reference_source_unconfigured'),
  'availableTags',coalesce((select jsonb_agg(tag order by tag collate "C") from metadata),'[]'::jsonb),
  'tagsComplete',not exists(select 1 from public.identity_references r cross join lateral unnest(r.tags) t where r.project_id=p_project_id and r.owner_id=v_owner and not exists(select 1 from metadata m where m.tag=t)),
  'references',jsonb_build_object('items',coalesce((select jsonb_agg(fluid_private.identity_reference_entry(p.id,p_project_id,v_owner) order by p.created_at desc,p.id desc) from page p),'[]'::jsonb),
   'nextCursor',case when(select count(*) from candidates)>v_limit then(select jsonb_build_object('projectId',p_project_id,'referenceId',r.id,'createdAt',r.created_at,'excludedTags',v_excluded) from last_row r) else null end)) into v_result;
 return v_result;
end $$;


ALTER FUNCTION public.get_identity_references(p_project_id uuid, p_query jsonb) OWNER TO postgres;

