declare v_owner uuid:=auth.uid(); v_batch public.naming_batches; v_result jsonb;
begin
 select * into v_batch from public.naming_batches where id=p_batch_id and project_id=p_project_id and owner_id=v_owner;
 if not found then raise exception 'not_found' using errcode='P0002'; end if;
 select result into v_result from public.naming_batch_results where batch_id=v_batch.id and owner_id=v_owner and project_id=p_project_id;
 return jsonb_build_object('batch',fluid_private.naming_batch_dto(v_batch),'job',fluid_private.naming_job_dto(v_batch),'result',v_result);
end $$;


ALTER FUNCTION public.get_naming_batch(p_project_id uuid, p_batch_id uuid) OWNER TO postgres;

--
-- Name: get_naming_batches(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_naming_batches(p_project_id uuid, p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid();v_limit integer:=coalesce((p_query->>'limit')::integer,50);v_items jsonb;v_next jsonb;v_count integer;
begin
 if not exists(select 1 from public.projects where id=p_project_id and owner_id=v_owner) then raise exception 'not_found' using errcode='P0002'; end if;
 if v_limit not between 1 and 100 or p_query-array['limit','cursor']<>'{}' then raise exception 'invalid_query' using errcode='22023'; end if;
 with rows as(select b from public.naming_batches b where owner_id=v_owner and project_id=p_project_id and engine_version<3
   and(p_query->>'cursor' is null or (created_at,id)>((p_query#>>'{cursor,createdAt}')::timestamptz,(p_query#>>'{cursor,id}')::uuid)) order by created_at,id limit v_limit+1),
 numbered as(select b,row_number() over(order by(b).created_at,(b).id) n from rows)
 select coalesce(jsonb_agg(jsonb_build_object('batch',fluid_private.naming_batch_dto(b),'result',(select result from public.naming_batch_results where batch_id=(b).id)) order by(b).created_at,(b).id) filter(where n<=v_limit),'[]'),count(*) into v_items,v_count from numbered;
 if v_count>v_limit then v_next:=jsonb_build_object('createdAt',v_items#>>array[(v_limit-1)::text,'batch','createdAt'],'id',v_items#>>array[(v_limit-1)::text,'batch','id']); end if;
 return jsonb_build_object('ownerId',v_owner,'projectId',p_project_id,'items',v_items,'nextCursor',v_next);
end $$;


ALTER FUNCTION public.get_naming_batches(p_project_id uuid, p_query jsonb) OWNER TO postgres;

--
-- Name: get_naming_generation(uuid, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_naming_generation(p_project uuid, p_after_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o uuid:=auth.uid(); p public.projects; b public.naming_batches; j public.jobs; c public.name_candidates;
 run jsonb; entries jsonb:='[]'::jsonb; n integer:=0; more boolean:=false; last_created timestamptz; last_id uuid; pol record;
begin
 if o is null then raise exception 'unauthenticated' using errcode='42501'; end if;
 if p_limit is null or p_limit not between 1 and 100 or (p_after_created_at is null)<>(p_after_id is null) then
  raise exception 'invalid_naming_request' using errcode='22023'; end if;
 select * into p from public.projects where id=p_project and owner_id=o and deleted_at is null and deletion_requested_at is null;
 if not found then raise exception 'not_found' using errcode='P0002'; end if;
 select bb.* into b from public.naming_batches bb where bb.project_id=p.id and bb.owner_id=o and bb.engine_version=3 order by bb.sequence desc limit 1;
 if found then select * into strict j from public.jobs where id=b.job_id; run:=fluid_private.naming_run_json(b,j); end if;
 for c in select cc.* from public.name_candidates cc join public.naming_batches bb on (bb.id,bb.owner_id,bb.project_id)=(cc.batch_id,cc.owner_id,cc.project_id)
  where cc.project_id=p.id and cc.owner_id=o and bb.engine_version=3
   and (p_after_id is null or (cc.created_at,cc.id)>(p_after_created_at,p_after_id))
  order by cc.created_at,cc.id limit p_limit+1 loop
  n:=n+1; if n>p_limit then more:=true; exit; end if;
  entries:=entries||jsonb_build_array(jsonb_build_object('entry',fluid_private.naming_entry(c),'runId',c.batch_id,
   'primaryApproach',(select to_jsonb(a.primary_approach) from fluid_private.naming_candidate_approaches a where a.candidate_id=c.id)));
  last_created:=c.created_at; last_id:=c.id;
 end loop;
 select * into pol from fluid_private.naming_generation_policy();
 return jsonb_build_object('version',2,'projectId',p.id,
  'availability',case when pol.slot_id is null then jsonb_build_object('status','unavailable','code','worker_unavailable') else jsonb_build_object('status','available') end,
  'run',coalesce(run,'null'::jsonb),'entries',entries,
  'nextCursor',case when more then jsonb_build_object('createdAt',last_created,'id',last_id) else 'null'::jsonb end);
end $$;


ALTER FUNCTION public.get_naming_generation(p_project uuid, p_after_created_at timestamp with time zone, p_after_id uuid, p_limit integer) OWNER TO postgres;

--
-- Name: get_naming_usage(uuid[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_naming_usage(p_jobs uuid[]) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select coalesce(jsonb_agg(jsonb_build_object('jobId',x.job_id,'inputTokens',x.i,'outputTokens',x.o,'totalTokens',x.t) order by x.job_id),'[]'::jsonb)
 from (select r.job_id,sum((r.usage->>'inputTokens')::bigint) i,sum((r.usage->>'outputTokens')::bigint) o,sum((r.usage->>'totalTokens')::bigint) t
  from fluid_private.naming_rounds r where r.job_id=any(p_jobs) and r.owner_id=auth.uid() and r.usage is not null
  and cardinality(p_jobs)<=200 group by r.job_id) x;
$$;


