--
-- Name: get_project_name_transform(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_project_name_transform(p_project_id uuid, p_transform_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_transform public.name_transforms;
begin
 select * into v_transform from public.name_transforms where id=p_transform_id and project_id=p_project_id and owner_id=auth.uid();
 if not found then raise exception 'not_found' using errcode='P0002'; end if;
 return fluid_private.naming_transform_dto(v_transform);
end $$;


ALTER FUNCTION public.get_project_name_transform(p_project_id uuid, p_transform_id uuid) OWNER TO postgres;

--
-- Name: get_project_naming(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_project_naming(p_project_id uuid, p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid();v_project public.projects;v_session public.naming_sessions;v_preferences public.naming_preferences;v_current jsonb;v_context jsonb;
 v_items jsonb;v_jobs jsonb;v_next jsonb;v_count integer;v_limit integer:=coalesce((p_query->>'limit')::integer,100);v_filter text;v_search text;v_batch uuid;v_availability jsonb;v_readiness jsonb;
begin
 select * into v_project from public.projects where id=p_project_id and owner_id=v_owner;
 if not found then raise exception 'not_found' using errcode='P0002'; end if;
 if v_limit not between 1 and 100 or p_query-array['cursor','limit','filter','query','batchId']<>'{}' then raise exception 'invalid_query' using errcode='22023'; end if;
 select * into v_session from public.naming_sessions where project_id=p_project_id and owner_id=v_owner;
 select * into v_preferences from public.naming_preferences where project_id=p_project_id and owner_id=v_owner and version=v_session.preferences_version;
 select context into strict v_context from public.project_revisions where project_id=p_project_id and owner_id=v_owner and revision=v_project.current_revision;
 select jsonb_build_object('selection',fluid_private.naming_selection_dto(s),'candidate',fluid_private.naming_candidate_dto(c)) into v_current
  from public.name_selections s join public.name_candidates c on c.id=s.candidate_id and c.owner_id=s.owner_id and c.project_id=s.project_id where s.id=v_session.current_selection_id and s.owner_id=v_owner and s.project_id=p_project_id;
 v_filter:=coalesce(p_query->>'filter',v_session.view_state->>'filter','all');v_search:=coalesce(p_query->>'query',v_session.view_state->>'query','');
 v_batch:=case when p_query ? 'batchId' then (p_query->>'batchId')::uuid else(v_session.view_state->>'visibleBatchId')::uuid end;
 if v_filter not in('all','retained','favorite','saved') or length(v_search)>200 then raise exception 'invalid_query' using errcode='22023'; end if;
 if v_batch is not null and not exists(select 1 from public.naming_batches where id=v_batch and owner_id=v_owner and project_id=p_project_id) then raise exception 'not_found' using errcode='P0002'; end if;
 with rows as(select c from public.name_candidates c left join public.name_retention r on r.candidate_id=c.id and r.owner_id=c.owner_id and r.project_id=c.project_id
  where c.owner_id=v_owner and c.project_id=p_project_id and(v_batch is null or c.batch_id=v_batch) and strpos(lower(c.value),lower(v_search))>0
   and(v_filter='all' or(v_filter='retained' and(r.liked or r.saved or c.id=(select candidate_id from public.name_selections where id=v_session.current_selection_id and owner_id=v_owner and project_id=p_project_id))) or(v_filter='favorite' and r.liked) or(v_filter='saved' and r.saved))
   and(p_query->>'cursor' is null or(c.created_at,c.id)>((p_query#>>'{cursor,createdAt}')::timestamptz,(p_query#>>'{cursor,id}')::uuid)) order by c.created_at,c.id limit v_limit+1),
 numbered as(select c,row_number() over(order by(c).created_at,(c).id) n from rows)
 select coalesce(jsonb_agg(fluid_private.naming_entry(c) order by(c).created_at,(c).id) filter(where n<=v_limit),'[]'),count(*) into v_items,v_count from numbered;
 if v_count>v_limit then v_next:=jsonb_build_object('createdAt',v_items#>>array[(v_limit-1)::text,'candidate','createdAt'],'id',v_items#>>array[(v_limit-1)::text,'candidate','id']); end if;
 select coalesce(jsonb_agg(fluid_private.naming_job_dto(b) order by(b).created_at desc),'[]') into v_jobs from(select b from public.naming_batches b where owner_id=v_owner and project_id=p_project_id and engine_version=1 order by created_at desc,id desc limit 20) x;
 v_readiness:=fluid_private.naming_readiness(v_project.scope,v_context);v_availability:=public.get_naming_availability(p_project_id);
 if (v_readiness->>'ready')::boolean is not true then v_availability:=jsonb_build_object('status','unavailable','operation','naming.generate','reason',case when v_project.scope='visual_identity_only' then 'scope_unavailable' else 'strategy_incomplete' end); end if;
 return jsonb_build_object('project',fluid_private.naming_project_dto(v_project),'readiness',v_readiness,'session',fluid_private.naming_session_dto(v_session),'preferences',fluid_private.naming_preference_dto(v_preferences),
  'currentSelection',v_current,'batches',public.get_naming_batches(p_project_id,'{"limit":100}'),'candidates',jsonb_build_object('ownerId',v_owner,'projectId',p_project_id,'items',v_items,'nextCursor',v_next),
  'availability',v_availability,'jobs',v_jobs,'screening','{"domains":{"status":"not_checked","reason":"integration_unavailable"},"handles":{"status":"not_checked","reason":"integration_unavailable"},"trademarks":{"status":"not_checked","reason":"integration_unavailable"}}'::jsonb);
end $$;


ALTER FUNCTION public.get_project_naming(p_project_id uuid, p_query jsonb) OWNER TO postgres;

--
-- Name: get_project_screening(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_project_screening(p_project_id uuid, p_cursor jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid();v_project public.projects;v_records jsonb;v_more boolean;v_last jsonb;
begin
 if v_owner is null then raise exception 'unauthenticated' using errcode='42501';end if;
 select * into v_project from public.projects where id=p_project_id and owner_id=v_owner for share;
 if not found then raise exception 'not_found' using errcode='P0002';end if;
 if p_cursor is not null and (jsonb_typeof(p_cursor)<>'object' or not(p_cursor ?& array['recordedAt','id']) or p_cursor-array['recordedAt','id']<>'{}'::jsonb
  or jsonb_typeof(p_cursor->'recordedAt')<>'string' or jsonb_typeof(p_cursor->'id')<>'string') then raise exception 'invalid_cursor' using errcode='22023';end if;
 if p_cursor is not null and not exists(select 1 from public.project_screening_records where project_id=p_project_id and owner_id=v_owner and id=(p_cursor->>'id')::uuid and recorded_at=(p_cursor->>'recordedAt')::timestamptz) then raise exception 'invalid_cursor' using errcode='22023';end if;
 with page as (select r as item,row_number() over(order by recorded_at desc,id desc) ordinal from public.project_screening_records r
  where project_id=p_project_id and owner_id=v_owner and (p_cursor is null or (recorded_at,id)<((p_cursor->>'recordedAt')::timestamptz,(p_cursor->>'id')::uuid)) order by recorded_at desc,id desc limit 21)
 select coalesce(jsonb_agg(fluid_private.project_screening_record_dto(item) order by (item).recorded_at desc,(item).id desc) filter(where ordinal<=20),'[]'::jsonb),count(*)>20 into v_records,v_more from page;
 v_last:=v_records->-1;
 return jsonb_build_object('ownerId',v_owner,'projectId',p_project_id,'projectRevision',v_project.current_revision,
  'currentBasis',fluid_private.project_screening_basis(p_project_id,v_owner),'records',v_records,
  'nextCursor',case when v_more then jsonb_build_object('recordedAt',v_last->'recordedAt','id',v_last->'id') else null end);
end $$;


ALTER FUNCTION public.get_project_screening(p_project_id uuid, p_cursor jsonb) OWNER TO postgres;

--
-- Name: get_project_visual_direction(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_project_visual_direction(p_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); inspiration jsonb; current_direction jsonb; history jsonb;
begin
 -- This read also verifies an authenticated owner and existing project.
 inspiration:=public.get_project_inspiration(p_project_id);
 current_direction:=fluid_private.visual_direction_latest(owner,p_project_id);
 select coalesce(jsonb_agg(record order by revision desc),'[]') into history from
  (select record,revision from public.project_visual_directions where owner_id=owner and project_id=p_project_id and revision<(current_direction->>'revision')::bigint order by revision desc limit 20) h;
 return jsonb_build_object('inspiration',inspiration,'current',current_direction,'history',history,
  'hasEarlierHistory',coalesce((current_direction->>'revision')::bigint,0)>21,
  'stale',current_direction is not null and not fluid_private.visual_direction_source_current(owner,p_project_id,current_direction));
end $$;


ALTER FUNCTION public.get_project_visual_direction(p_project_id uuid) OWNER TO postgres;

--
-- Name: get_shared_identity_batch(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_shared_identity_batch(p_project_id uuid, p_batch_id uuid DEFAULT NULL::uuid, p_request_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare o uuid:=fluid_private.shared_identity_customer(p_project_id);bid uuid;begin
 if p_batch_id is not null and p_request_key is not null then raise exception 'shared_identity_selector_invalid' using errcode='22023';end if;
 select r.batch_id into bid from fluid_private.shared_identity_requests r join public.identity_batches b on b.id=r.batch_id
 where r.owner_id=o and r.project_id=p_project_id and (p_batch_id is null or r.batch_id=p_batch_id) and (p_request_key is null or r.request_key=p_request_key)
 order by b.created_at desc,b.id desc limit 1;
 return fluid_private.shared_identity_batch_state(o,p_project_id,bid);
end $$;


ALTER FUNCTION public.get_shared_identity_batch(p_project_id uuid, p_batch_id uuid, p_request_key text) OWNER TO postgres;

--
-- Name: get_strategy_job_summaries(uuid, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_strategy_job_summaries(p_project_id uuid, p_job_id uuid DEFAULT NULL::uuid) RETURNS SETOF jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid();
begin
 if v_owner is null then raise exception 'unauthenticated' using errcode='42501';end if;
 if not exists(select 1 from public.projects where id=p_project_id and owner_id=v_owner) then
  raise exception 'not_found' using errcode='P0002';end if;
 return query
 select jsonb_build_object(
  'id',j.id,'owner_id',j.owner_id,'project_id',j.project_id,'operation',j.operation,
  'input_revision',j.input_revision,'input_version',j.input->'version',
  'input_spend_control',j.input->>'spendControl','input_policy_identity',j.input->>'policyIdentity',
  'state',j.state,'progress',j.progress,'billing_mode',j.billing_mode,'policy_identity',j.policy_identity,
  'reserved_cost_microusd',j.reserved_cost_microusd,'actual_cost_microusd',j.actual_cost_microusd,
  'cancel_requested_at',j.cancel_requested_at,'error_code',j.error_code,
  'created_at',j.created_at,'finished_at',j.finished_at)
 from public.jobs j
 where j.owner_id=v_owner and j.project_id=p_project_id and (p_job_id is null or j.id=p_job_id)
  and j.operation in('strategy.reformulate','strategy.competitors','strategy.audience','strategy.personality','strategy.positioning','strategy.slogan')
 order by j.created_at desc,j.id desc limit 64;
end $$;


ALTER FUNCTION public.get_strategy_job_summaries(p_project_id uuid, p_job_id uuid) OWNER TO postgres;

--
-- Name: import_local_name(uuid, integer, jsonb, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.import_local_name(p_project_id uuid, p_expected_revision integer, p_source jsonb, p_context jsonb, p_identity_key text, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_owner uuid:=auth.uid();v_project public.projects;v_revision public.project_revisions;v_candidate public.name_candidates;
begin
 if p_expected_revision is null or p_expected_revision<1 or p_idempotency_key is null or p_idempotency_key!~'^[A-Za-z0-9._:-]{16,128}$'
  or jsonb_typeof(p_source) is distinct from 'object' or p_source-array['id','value','createdAt','origin','history']<>'{}' or p_source->>'origin' not in('manual','workshop')
  or not(p_source ?& array['id','value','createdAt','origin','history']) or jsonb_typeof(p_source->'history') is distinct from 'array' or jsonb_array_length(p_source->'history')>32
  or coalesce(length(p_source->>'value'),0) not between 1 and 160 or p_identity_key is null or length(p_identity_key)>320 or jsonb_typeof(p_context) is distinct from 'object'
  or octet_length(p_source::text)+octet_length(p_context::text)>32768 then raise exception 'invalid_import' using errcode='22023'; end if;
 if (p_source->>'origin'='manual' and jsonb_array_length(p_source->'history')<>0) or(p_source->>'origin'='workshop' and jsonb_array_length(p_source->'history')=0) then raise exception 'invalid_import_history' using errcode='22023'; end if;
 perform fluid_private.ensure_naming_session(p_project_id,v_owner);
 select * into v_candidate from public.name_candidates where owner_id=v_owner and idempotency_key=p_idempotency_key;
 if found then
  if v_candidate.project_id<>p_project_id or v_candidate.context_revision<>p_expected_revision or v_candidate.origin->>'kind'<>'local_import' or v_candidate.origin->'source'<>p_source
   or v_candidate.origin->'capturedContext'<>p_context or v_candidate.identity_key<>p_identity_key then raise exception 'import_conflict' using errcode='PT409'; end if;
  return jsonb_build_object('entry',fluid_private.naming_entry(v_candidate));
 end if;
 select * into strict v_project from public.projects where id=p_project_id and owner_id=v_owner;
 if v_project.current_revision<>p_expected_revision then raise exception 'revision_conflict' using errcode='PT409'; end if;
 select * into strict v_revision from public.project_revisions where project_id=p_project_id and owner_id=v_owner and revision=p_expected_revision;
 v_candidate.id:=gen_random_uuid();v_candidate.owner_id:=v_owner;v_candidate.project_id:=p_project_id;v_candidate.context_revision:=p_expected_revision;
 v_candidate.value:=p_source->>'value';v_candidate.identity_key:=p_identity_key;v_candidate.strategy_basis:=fluid_private.naming_strategy_basis(p_context);
 v_candidate.origin:=jsonb_build_object('kind','local_import','ownerId',v_owner,'projectId',p_project_id,'candidateId',v_candidate.id,'contextRevision',p_expected_revision,'source',p_source,'capturedContext',p_context);
 v_candidate.source_context:=p_context;v_candidate.idempotency_key:=p_idempotency_key;v_candidate.rationale:='Imported from a user-supplied local name.';v_candidate.created_at:=clock_timestamp();
 insert into public.name_candidates select(v_candidate).*;
 return jsonb_build_object('entry',fluid_private.naming_entry(v_candidate));
end $_$;


ALTER FUNCTION public.import_local_name(p_project_id uuid, p_expected_revision integer, p_source jsonb, p_context jsonb, p_identity_key text, p_idempotency_key text) OWNER TO postgres;

--
-- Name: initialize_existing_brand_logo(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.initialize_existing_brand_logo(p_project_id uuid, p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); project public.projects; command jsonb; existing public.logo_workspace_requests; rejected public.logo_operation_rejections; result jsonb;
begin
 if owner is null then raise exception 'unauthenticated' using errcode='42501'; end if;
 command:=jsonb_build_object('method','saveLogoBrief','body',p_input);
 if not fluid_private.logo_command_valid(command) then raise exception 'invalid_logo_initialization' using errcode='22023'; end if;
 -- Use the same project-first lock as context, Naming, references and stage
 -- writers. The downstream apply reads and compares every authoritative head.
 select * into project from public.projects where id=p_project_id and owner_id=owner for update;
 if not found then raise exception 'logo_project_not_found' using errcode='P0002'; end if;
 -- Exact original requests are recoverable even after later stage/context saves.
 -- Reuse the manual receipt contract; do not invent another request namespace.
 select * into existing from public.logo_workspace_requests
  where project_id=p_project_id and owner_id=owner and request_key=(p_input->>'requestKey')::uuid and method<>'startLogoProject';
 if found then
  if existing.input is distinct from command then raise exception 'logo_request_conflict' using errcode='PT409'; end if;
  if existing.input#>'{body,expected,stageRevisions,brief_references}' is distinct from '0'::jsonb then
   raise exception 'logo_initialization_conflict' using errcode='PT409';
  end if;
  return existing.receipt;
 end if;
 -- Durable tombstones share the already owner-scoped immutable cross-operation
 -- key fence. A lost rejection response can never later admit the same command.
 select * into rejected from public.logo_operation_rejections
  where owner_id=owner and project_id=p_project_id and request_key=(p_input->>'requestKey')::uuid;
 if found then
  if rejected.input is distinct from command then raise exception 'logo_request_conflict' using errcode='PT409'; end if;
  return rejected.receipt;
 end if;
 -- A preexisting different operation is not this initialization's rejection.
 if exists(select 1 from public.logo_operation_requests where owner_id=owner and project_id=p_project_id and request_key=(p_input->>'requestKey')::uuid) then
  raise exception 'logo_request_conflict' using errcode='PT409';
 end if;
 if project.scope in ('complete_brand','visual_identity_only')
  and p_input#>'{expected,stageRevisions,brief_references}'='0'::jsonb
  and not exists(select 1 from public.logo_stage_heads where project_id=p_project_id and owner_id=owner and stage='brief_references') then
  begin
   return fluid_private.logo_apply(owner,p_project_id,command);
  exception when sqlstate 'PT409' then
   -- Only the semantic CAS failure is recorded. Serialization failures, unique
   -- constraint errors and unavailable storage must remain uncertain/retryable.
   null;
  end;
 end if;
 result:=jsonb_build_object('kind','logo_initialization_rejected','rejection',jsonb_build_object('status','rejected','ownerId',owner,'projectId',p_project_id,'requestKey',p_input->'requestKey','input',p_input));
 insert into public.logo_operation_rejections(owner_id,project_id,request_key,input,receipt)
  values(owner,p_project_id,(p_input->>'requestKey')::uuid,command,result);
 return result;
end $$;


ALTER FUNCTION public.initialize_existing_brand_logo(p_project_id uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: issue_shared_account_request(text, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.issue_shared_account_request(p_lane text, p_action text, p_arguments jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare claims jsonb:=auth.jwt(); owner uuid:=auth.uid(); sid uuid; role_id oid; expires timestamptz; token text;
begin
 if session_user<>'authenticator' or current_setting('role')<>'authenticated' or owner is null
  or claims->>'sub' is distinct from owner::text or claims->>'role' is distinct from 'authenticated'
  or claims->>'aud' is distinct from 'authenticated' or claims->>'is_anonymous' is distinct from 'false'
  or not exists(select 1 from fluid_private.shared_http_target where claims->>'iss'=origin||'/auth/v1')
  or jsonb_typeof(claims->'exp') is distinct from 'number' or jsonb_typeof(p_arguments)<>'array'
  or octet_length(p_arguments::text)>(case when p_lane='home' then 131072 else 40000 end)
 then raise exception 'shared_http_verified_session_required' using errcode='42501'; end if;
 sid:=(claims->>'session_id')::uuid;
 expires:=least(to_timestamp((claims->>'exp')::double precision),clock_timestamp()+interval '30 seconds');
 perform 1 from auth.users where id=owner for share;
 perform 1 from auth.sessions where id=sid and user_id=owner for share;
 perform 1 from fluid_private.shared_accounts where owner_id=owner for share;
 if not fluid_private.shared_http_live(owner,sid,expires) then raise exception 'shared_http_account_unavailable' using errcode='42501'; end if;
 role_id:=fluid_private.shared_http_role(p_lane);
 if not ((p_lane='identity' and p_action='identity' and jsonb_array_length(p_arguments)=3
    and jsonb_typeof(p_arguments->0)='string' and jsonb_typeof(p_arguments->1)='object' and jsonb_typeof(p_arguments->2)='boolean')
   or (p_lane='home' and p_action='prepare' and jsonb_array_length(p_arguments)=2
    and jsonb_typeof(p_arguments->0)='object' and jsonb_typeof(p_arguments->1)='number')
   or (p_lane='home' and p_action in('lookup','readback') and jsonb_array_length(p_arguments)=1 and jsonb_typeof(p_arguments->0)='string')
   or (p_lane='home' and p_action='lookup_project' and jsonb_array_length(p_arguments)=1 and jsonb_typeof(p_arguments->0)='string')
   or (p_lane='home' and p_action='save' and jsonb_array_length(p_arguments)=2 and jsonb_typeof(p_arguments->0)='object' and jsonb_typeof(p_arguments->1)='string')
   or (p_lane='home' and p_action='resolve' and jsonb_array_length(p_arguments)=1 and jsonb_typeof(p_arguments->0)='array' and jsonb_array_length(p_arguments->0)<=5))
 then raise exception 'shared_http_scope_invalid' using errcode='22023'; end if;
 if p_lane='identity' and not exists(select 1 from public.projects where id=(p_arguments->>0)::uuid and owner_id=owner)
  or p_lane='home' and p_action='readback' and not exists(select 1 from public.home_attachments where id=(p_arguments->>0)::uuid and owner_id=owner)
 then raise exception 'shared_http_scope_missing' using errcode='P0002'; end if;
 -- Bound abandoned delegations. These rows contain hashes and authority metadata, never passwords or JWTs.
 perform pg_advisory_xact_lock(hashtextextended(owner::text||':shared-http-issuer',0));
 delete from fluid_private.shared_http_requests r where r.owner_id=owner and r.expires_at<clock_timestamp()
  and not exists(select 1 from fluid_private.shared_http_contexts c where c.token_hash=r.token_hash);
 if (select count(*) from fluid_private.shared_http_requests where owner_id=owner and expires_at>clock_timestamp())>=64
 then raise exception 'shared_http_request_busy' using errcode='55000'; end if;
 token:=encode(uuid_send(gen_random_uuid())||uuid_send(gen_random_uuid()),'hex');
 insert into fluid_private.shared_http_requests values(sha256(convert_to(token,'UTF8')),owner,sid,p_lane,role_id,p_action,sha256(convert_to(p_arguments::text,'UTF8')),
  (select eligibility_epoch from fluid_private.shared_accounts where owner_id=owner),expires,false);
 return jsonb_build_object('version',1,'token',token,'ownerId',owner,'expiresAt',expires);
end $$;


ALTER FUNCTION public.issue_shared_account_request(p_lane text, p_action text, p_arguments jsonb) OWNER TO postgres;

--
-- Name: issue_shared_logo_request(text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.issue_shared_logo_request(p_action text, p_arguments jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p_lane text:='logo'; claims jsonb:=auth.jwt(); owner uuid:=auth.uid(); sid uuid; role_id oid; expires timestamptz; token text;
begin
 if session_user<>'authenticator' or current_setting('role')<>'authenticated' or owner is null
  or claims->>'sub' is distinct from owner::text or claims->>'role' is distinct from 'authenticated'
  or claims->>'aud' is distinct from 'authenticated' or claims->>'is_anonymous' is distinct from 'false'
  or not exists(select 1 from fluid_private.shared_http_target where claims->>'iss'=origin||'/auth/v1')
  or jsonb_typeof(claims->'exp') is distinct from 'number' or jsonb_typeof(p_arguments)<>'array'
  or octet_length(p_arguments::text)>1048576
 then raise exception 'shared_logo_http_verified_session_required' using errcode='42501'; end if;
 sid:=(claims->>'session_id')::uuid;
 expires:=least(to_timestamp((claims->>'exp')::double precision),clock_timestamp()+interval '30 seconds');
 perform 1 from auth.users where id=owner for share;
 perform 1 from auth.sessions where id=sid and user_id=owner for share;
 perform 1 from fluid_private.shared_accounts where owner_id=owner for share;
 if not fluid_private.shared_logo_http_live(owner,sid,expires) then raise exception 'shared_logo_http_account_unavailable' using errcode='42501'; end if;
 role_id:=fluid_private.shared_logo_http_role(p_lane);
 if p_action not in('asset_prepare','asset_readback','command_read','command_apply','input_prepare','input_commit','proposal_quote')
  or jsonb_array_length(p_arguments)<>2 or jsonb_typeof(p_arguments->0)<>'string'
  or (p_action='asset_readback' and jsonb_typeof(p_arguments->1)<>'string')
  or (p_action<>'asset_readback' and jsonb_typeof(p_arguments->1)<>'object')
 then raise exception 'shared_logo_http_scope_invalid' using errcode='22023';end if;
 if not exists(select 1 from public.projects where id=(p_arguments->>0)::uuid and owner_id=owner)
  or p_action='asset_readback' and not exists(select 1 from public.logo_asset_publications
   where id=(p_arguments->>1)::uuid and project_id=(p_arguments->>0)::uuid and owner_id=owner)
 then raise exception 'shared_logo_http_scope_missing' using errcode='P0002';end if;
 -- Bound abandoned delegations. These rows contain hashes and authority metadata, never passwords or JWTs.
 perform pg_advisory_xact_lock(hashtextextended(owner::text||':shared-http-issuer',0));
 delete from fluid_private.shared_logo_http_requests r where r.owner_id=owner and r.expires_at<clock_timestamp()
  and not exists(select 1 from fluid_private.shared_logo_http_contexts c where c.token_hash=r.token_hash);
 if (select count(*) from fluid_private.shared_logo_http_requests where owner_id=owner and expires_at>clock_timestamp())>=64
 then raise exception 'shared_logo_http_request_busy' using errcode='55000'; end if;
 token:=encode(uuid_send(gen_random_uuid())||uuid_send(gen_random_uuid()),'hex');
 insert into fluid_private.shared_logo_http_requests values(sha256(convert_to(token,'UTF8')),owner,sid,p_lane,role_id,p_action,sha256(convert_to(p_arguments::text,'UTF8')),
  (select eligibility_epoch from fluid_private.shared_accounts where owner_id=owner),expires,false);
 return jsonb_build_object('version',1,'token',token,'ownerId',owner,'expiresAt',expires);
end $$;


ALTER FUNCTION public.issue_shared_logo_request(p_action text, p_arguments jsonb) OWNER TO postgres;

--
-- Name: list_account_assets(jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_account_assets(p_query jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid();v_query jsonb;v_asset public.assets;v_project public.projects;v_items jsonb:='[]';v_count integer:=0;v_last public.assets;v_next jsonb;v_cursor jsonb;
begin
 if v_owner is null then raise exception 'unauthenticated' using errcode='42501';end if;v_query:=fluid_private.asset_library_query(p_query,false);v_cursor:=v_query->'cursor';
 if v_query ? 'projectId' and not exists(select 1 from public.projects where id=(v_query->>'projectId')::uuid and owner_id=v_owner) then raise exception 'not_found' using errcode='P0002';end if;
 if v_cursor is not null and not exists(select 1 from public.assets where id=(v_cursor->>'assetId')::uuid and owner_id=v_owner and purpose<>'reference_media' and created_at=(v_cursor->>'createdAt')::timestamptz and(not(v_query ? 'projectId') or project_id=(v_query->>'projectId')::uuid)) then raise exception 'not_found' using errcode='P0002';end if;
 for v_asset in select a.* from public.assets a where a.owner_id=v_owner and a.purpose<>'reference_media'
  and(v_query->>'tab'='all_generations' or a.liked or a.saved or a.legacy_used or exists(select 1 from public.asset_usages u join public.identity_sessions ih on ih.current_selection_id=u.selection_id and ih.project_id=u.project_id and ih.owner_id=u.owner_id where u.asset_id=a.id and u.project_id=a.project_id and u.owner_id=a.owner_id))
  and(not(v_query ? 'projectId') or a.project_id=(v_query->>'projectId')::uuid)
  and(not(v_query ? 'format') or exists(select 1 from public.asset_versions v where v.asset_id=a.id and v.project_id=a.project_id and v.owner_id=v_owner and fluid_private.asset_library_format(v.mime_type)=v_query->>'format'))
  and(v_cursor is null or(a.created_at,a.id)<((v_cursor->>'createdAt')::timestamptz,(v_cursor->>'assetId')::uuid))
  order by a.created_at desc,a.id desc limit (v_query->>'limit')::integer+1 loop
  v_count:=v_count+1;if v_count>(v_query->>'limit')::integer then
   v_next:=jsonb_build_object('createdAt',v_last.created_at,'assetId',v_last.id,'tab',v_query->>'tab','projectId',v_query->'projectId','format',v_query->'format');exit;
  end if;
  select * into strict v_project from public.projects where id=v_asset.project_id and owner_id=v_owner;
  v_items:=v_items||jsonb_build_array(fluid_private.asset_library_item(v_asset,v_project,v_query->>'format'));v_last:=v_asset;
 end loop;
 return jsonb_build_object('ownerId',v_owner,'query',v_query,'items',v_items,'nextCursor',v_next);
end $$;


ALTER FUNCTION public.list_account_assets(p_query jsonb) OWNER TO postgres;

