--
-- Name: list_logo_input_fonts(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_logo_input_fonts(p_project_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); result jsonb;
begin
 if owner is null then raise exception 'unauthenticated' using errcode='42501';end if;
 if not exists(select 1 from public.projects where id=p_project_id and owner_id=owner) then raise exception 'logo_project_not_found' using errcode='P0002';end if;
 select coalesce(jsonb_agg(record order by record_id),'[]') into result from public.logo_font_records where owner_id=owner and project_id=p_project_id;
 if jsonb_array_length(result)>100 then raise exception 'logo_font_limit' using errcode='55000';end if;
 return result;
end $$;


ALTER FUNCTION public.list_logo_input_fonts(p_project_id uuid) OWNER TO postgres;

--
-- Name: list_logo_input_references(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_logo_input_references(p_project_id uuid, p_query jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); lim integer; cursor_row public.logo_input_receipts; row public.logo_input_receipts; items jsonb:='[]'; last_id uuid; more boolean:=false;
begin
 if owner is null then raise exception 'unauthenticated' using errcode='42501';end if;
 if not exists(select 1 from public.projects where id=p_project_id and owner_id=owner) then raise exception 'logo_project_not_found' using errcode='P0002';end if;
 if jsonb_typeof(p_query) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_query) k where k not in('cursor','limit')) or not p_query?'limit' or jsonb_typeof(p_query->'limit') is distinct from 'number' then raise exception 'invalid_logo_input_query' using errcode='22023';end if;
 lim:=(p_query->>'limit')::integer;if lim not between 1 and 50 or to_jsonb(lim) is distinct from p_query->'limit' then raise exception 'invalid_logo_input_query' using errcode='22023';end if;
 if p_query?'cursor' then
  if not fluid_private.logo_uuid(p_query->'cursor') then raise exception 'invalid_logo_input_cursor' using errcode='22023';end if;
  select * into cursor_row from public.logo_input_receipts where owner_id=owner and project_id=p_project_id and reference_id=(p_query->>'cursor')::uuid;
  if not found then raise exception 'invalid_logo_input_cursor' using errcode='22023';end if;
 end if;
 for row in select * from public.logo_input_receipts where owner_id=owner and project_id=p_project_id and reference_id is not null and(cursor_row.reference_id is null or(created_at,reference_id)>(cursor_row.created_at,cursor_row.reference_id)) order by created_at,reference_id limit lim+1 loop
  if jsonb_array_length(items)=lim then more:=true;exit;end if;
  items:=items||jsonb_build_array(row.result);last_id:=row.reference_id;
 end loop;
 return jsonb_build_object('ownerId',owner,'projectId',p_project_id,'items',items,'nextCursor',case when more then last_id else null end);
end $$;


ALTER FUNCTION public.list_logo_input_references(p_project_id uuid, p_query jsonb) OWNER TO postgres;

--
-- Name: list_logo_input_requests(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_logo_input_requests(p_project_id uuid, p_query jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); lim integer; cursor_row public.logo_input_requests; row public.logo_input_requests; items jsonb:='[]'; last_key uuid; more boolean:=false;
begin
 if owner is null then raise exception 'unauthenticated' using errcode='42501';end if;
 if not exists(select 1 from public.projects where id=p_project_id and owner_id=owner) then raise exception 'logo_project_not_found' using errcode='P0002';end if;
 if jsonb_typeof(p_query) is distinct from 'object' or exists(select 1 from jsonb_object_keys(p_query) k where k not in('cursor','limit')) or not p_query?'limit' or jsonb_typeof(p_query->'limit') is distinct from 'number' then raise exception 'invalid_logo_input_query' using errcode='22023';end if;
 lim:=(p_query->>'limit')::integer;if lim not between 1 and 10 or to_jsonb(lim) is distinct from p_query->'limit' then raise exception 'invalid_logo_input_query' using errcode='22023';end if;
 if p_query?'cursor' then
  if not fluid_private.logo_uuid(p_query->'cursor') then raise exception 'invalid_logo_input_cursor' using errcode='22023';end if;
  select * into cursor_row from public.logo_input_requests where owner_id=owner and project_id=p_project_id and request_key=(p_query->>'cursor')::uuid;
  if not found then raise exception 'invalid_logo_input_cursor' using errcode='22023';end if;
 end if;
 for row in select r.* from public.logo_input_requests r where r.owner_id=owner and r.project_id=p_project_id
  and not exists(select 1 from public.logo_input_receipts c where c.owner_id=r.owner_id and c.project_id=r.project_id and c.request_key=r.request_key)
  and not exists(select 1 from public.logo_input_rejections c where c.owner_id=r.owner_id and c.project_id=r.project_id and c.request_key=r.request_key)
  and(cursor_row.request_key is null or(r.created_at,r.request_key)>(cursor_row.created_at,cursor_row.request_key)) order by r.created_at,r.request_key limit lim+1 loop
  if jsonb_array_length(items)=lim then more:=true;exit;end if;
  items:=items||jsonb_build_array(fluid_private.logo_input_state(owner,p_project_id,row.request_key));last_key:=row.request_key;
 end loop;
 return jsonb_build_object('ownerId',owner,'projectId',p_project_id,'items',items,'nextCursor',case when more then last_key else null end);
end $$;


ALTER FUNCTION public.list_logo_input_requests(p_project_id uuid, p_query jsonb) OWNER TO postgres;

--
-- Name: list_logo_workspace_base_records(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_logo_workspace_base_records(p_project_id uuid, p_kind text, p_query jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); n integer; cursor_id uuid; cursor_revision bigint; row public.logo_stage_revisions; items jsonb:='[]'; next_cursor jsonb; seen integer:=0;
begin
 if owner is null then raise exception 'unauthenticated' using errcode='42501'; end if;
 if not exists(select 1 from public.projects where id=p_project_id and owner_id=owner) then raise exception 'logo_project_not_found' using errcode='P0002'; end if;
 if p_kind not in ('brief_references','concepts','vector','refinements','directions','deliverables') or jsonb_typeof(p_query) is distinct from 'object' or p_query-array['cursor','limit']<>'{}' or octet_length(p_query::text)>32768 then raise exception 'invalid_logo_query' using errcode='22023'; end if;
 if p_query ? 'limit' and (jsonb_typeof(p_query->'limit') is distinct from 'number' or (p_query->>'limit')::numeric<>trunc((p_query->>'limit')::numeric) or (p_query->>'limit')::numeric not between 1 and 50) then raise exception 'invalid_logo_limit' using errcode='22023'; end if;
 n:=coalesce((p_query->>'limit')::integer,20);
 if p_query ? 'cursor' then
  if not fluid_private.standalone_keys(p_query->'cursor',array['stage','createdAt','id']) or p_query#>>'{cursor,stage}'<>p_kind or not fluid_private.logo_uuid(p_query#>'{cursor,id}') or not fluid_private.standalone_timestamp(p_query#>'{cursor,createdAt}') or length(p_query#>>'{cursor,createdAt}')>64 then raise exception 'invalid_logo_cursor' using errcode='22023'; end if;
  cursor_id:=(p_query#>>'{cursor,id}')::uuid;
  select revision into cursor_revision from public.logo_stage_revisions where id=cursor_id and owner_id=owner and project_id=p_project_id and stage=p_kind and record->'createdAt'=p_query#>'{cursor,createdAt}';
  if not found then raise exception 'invalid_logo_cursor' using errcode='22023'; end if;
 end if;
 for row in select * from public.logo_stage_revisions where owner_id=owner and project_id=p_project_id and stage=p_kind and (cursor_revision is null or revision<cursor_revision) order by revision desc limit n+1 loop
  seen:=seen+1;
  if seen>n then return jsonb_build_object('ownerId',owner,'projectId',p_project_id,'items',items,'nextCursor',next_cursor); end if;
  items:=items||jsonb_build_array(row.record);
  next_cursor:=jsonb_build_object('stage',p_kind,'createdAt',row.record->'createdAt','id',row.id);
 end loop;
 return jsonb_build_object('ownerId',owner,'projectId',p_project_id,'items',items,'nextCursor',null);
end $$;


ALTER FUNCTION public.list_logo_workspace_base_records(p_project_id uuid, p_kind text, p_query jsonb) OWNER TO postgres;

--
-- Name: list_logo_workspace_records(uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.list_logo_workspace_records(p_project_id uuid, p_kind text, p_query jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid();
begin
 if owner is null then raise exception 'unauthenticated' using errcode='42501';end if;
 if not exists(select 1 from public.projects where id=p_project_id and owner_id=owner) then raise exception 'logo_project_not_found' using errcode='P0002';end if;
 if p_kind in('brief_references','concepts','vector','refinements','directions','deliverables') then return public.list_logo_workspace_base_records(p_project_id,p_kind,p_query);end if;
 if p_kind in('raster_refinement','concept_batch') then return fluid_private.logo_job_records(owner,p_project_id,p_kind,p_query);end if;
 if p_kind='directions_overview' then return fluid_private.logo_direction_overview(owner,p_project_id,p_query);end if;
 raise exception 'invalid_logo_read_kind' using errcode='22023';
end $$;


ALTER FUNCTION public.list_logo_workspace_records(p_project_id uuid, p_kind text, p_query jsonb) OWNER TO postgres;

--
-- Name: persist_name_transform(uuid, uuid, uuid, jsonb, jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.persist_name_transform(p_project_id uuid, p_parent_candidate_id uuid, p_secondary_candidate_id uuid, p_input jsonb, p_result jsonb, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_owner uuid:=auth.uid();v_parent public.name_candidates;v_secondary public.name_candidates;v_candidate public.name_candidates;v_transform public.name_transforms;
 v_root jsonb;v_history jsonb;v_item jsonb;v_entries jsonb:='[]';v_outputs jsonb:='[]';v_candidates public.name_candidates[]:='{}';v_depth integer;
begin
 if p_idempotency_key is null or p_idempotency_key!~'^[A-Za-z0-9._:-]{16,128}$' or jsonb_typeof(p_input) is distinct from 'object' or p_input->>'kind' not in('affixes','tweaks','blend','swap')
  or jsonb_typeof(p_result) is distinct from 'object' or p_result-array['candidates','truncated','notes']<>'{}' or jsonb_typeof(p_result->'candidates') is distinct from 'array'
  or jsonb_array_length(p_result->'candidates')>64 or jsonb_typeof(p_result->'truncated') is distinct from 'boolean' or jsonb_typeof(p_result->'notes') is distinct from 'array'
  or jsonb_array_length(p_result->'notes')>20 or octet_length(p_input::text)+octet_length(p_result::text)>32768 then raise exception 'invalid_transform' using errcode='22023'; end if;
 perform fluid_private.ensure_naming_session(p_project_id,v_owner);
 select * into v_parent from public.name_candidates where id=p_parent_candidate_id and owner_id=v_owner and project_id=p_project_id;
 if not found then raise exception 'not_found' using errcode='P0002'; end if;
 if (p_input->>'kind'='blend')<>(p_secondary_candidate_id is not null) then raise exception 'invalid_transform_parents' using errcode='22023'; end if;
 if p_secondary_candidate_id is not null then
  select * into v_secondary from public.name_candidates where id=p_secondary_candidate_id and owner_id=v_owner and project_id=p_project_id;
  if not found then raise exception 'not_found' using errcode='P0002'; end if;
  if p_input->>'left' is distinct from v_parent.value or p_input->>'right' is distinct from v_secondary.value then raise exception 'invalid_transform_seed' using errcode='22023'; end if;
 elsif p_input->>'seed' is distinct from v_parent.value then raise exception 'invalid_transform_seed' using errcode='22023'; end if;
 select * into v_transform from public.name_transforms where owner_id=v_owner and idempotency_key=p_idempotency_key;
 if found then
  if (v_transform.project_id,v_transform.parent_candidate_id,v_transform.secondary_candidate_id,v_transform.input,v_transform.request)
   is distinct from(p_project_id,p_parent_candidate_id,p_secondary_candidate_id,p_input,p_result) then raise exception 'transform_conflict' using errcode='PT409'; end if;
  select coalesce(jsonb_agg(fluid_private.naming_entry(c) order by n),'[]') into v_entries from jsonb_array_elements(v_transform.outputs) with ordinality o(x,n)
   join public.name_candidates c on c.id=(x->>'candidateId')::uuid and c.owner_id=v_owner and c.project_id=p_project_id;
  return jsonb_build_object('transform',fluid_private.naming_transform_dto(v_transform),'entries',v_entries);
 end if;
 v_root:=case when v_parent.origin->>'kind' in('generated','local_import','brainstorm') then v_parent.origin else v_parent.origin->'root' end;
 v_history:=coalesce(v_parent.origin->'history','[]');v_depth:=jsonb_array_length(v_history)+case when v_root->>'kind'='local_import' then jsonb_array_length(v_root#>'{source,history}') else 0 end;
 if v_depth>=32 then raise exception 'transform_history_full' using errcode='22023'; end if;
 v_transform.id:=gen_random_uuid();v_transform.owner_id:=v_owner;v_transform.project_id:=p_project_id;v_transform.parent_candidate_id:=p_parent_candidate_id;v_transform.secondary_candidate_id:=p_secondary_candidate_id;
 v_transform.input:=p_input;v_transform.request:=p_result;v_transform.truncated:=(p_result->>'truncated')::boolean;v_transform.notes:=p_result->'notes';v_transform.idempotency_key:=p_idempotency_key;v_transform.created_at:=clock_timestamp();
 -- Output text remains a user-supplied claim. Exact V1 replay occurs at every
 -- application read/use; no caller can manufacture generated authorship here.
 for v_item in select value from jsonb_array_elements(p_result->'candidates') loop
  if v_item-array['value','explanation','identityKey']<>'{}' or coalesce(length(v_item->>'value'),0) not between 1 and 160 or jsonb_typeof(v_item->'identityKey') is distinct from 'string'
   or length(v_item->>'identityKey')>320 or coalesce(length(v_item->>'explanation'),0) not between 1 and 2000 then raise exception 'invalid_transform_output' using errcode='22023'; end if;
  v_candidate:=null;v_candidate.id:=gen_random_uuid();v_candidate.owner_id:=v_owner;v_candidate.project_id:=p_project_id;v_candidate.value:=v_item->>'value';v_candidate.identity_key:=v_item->>'identityKey';
  v_candidate.context_revision:=v_parent.context_revision;v_candidate.strategy_basis:=v_parent.strategy_basis;v_candidate.transform_id:=v_transform.id;v_candidate.rationale:=v_item->>'explanation';v_candidate.created_at:=v_transform.created_at;
  v_candidate.origin:=jsonb_build_object('kind','transform','authorship','user_supplied','algorithmVersion',1,'transformId',v_transform.id,'parentCandidateId',p_parent_candidate_id,'secondaryCandidateId',p_secondary_candidate_id,
   'root',v_root,'history',v_history||jsonb_build_array(jsonb_build_object('transformId',v_transform.id,'projectId',p_project_id,'parentCandidateId',p_parent_candidate_id,'secondaryCandidateId',p_secondary_candidate_id,'input',p_input,'output',v_candidate.value,'createdAt',v_transform.created_at)));
  v_candidates:=array_append(v_candidates,v_candidate);v_outputs:=v_outputs||jsonb_build_array(jsonb_build_object('candidateId',v_candidate.id,'value',v_candidate.value,'explanation',v_item->>'explanation'));
 end loop;
 v_transform.outputs:=v_outputs;insert into public.name_transforms select(v_transform).*;
 foreach v_candidate in array v_candidates loop insert into public.name_candidates select(v_candidate).*;v_entries:=v_entries||jsonb_build_array(fluid_private.naming_entry(v_candidate)); end loop;
 return jsonb_build_object('transform',fluid_private.naming_transform_dto(v_transform),'entries',v_entries);
end $_$;


ALTER FUNCTION public.persist_name_transform(p_project_id uuid, p_parent_candidate_id uuid, p_secondary_candidate_id uuid, p_input jsonb, p_result jsonb, p_idempotency_key text) OWNER TO postgres;

--
-- Name: prepare_shared_identity_reference_upload(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.prepare_shared_identity_reference_upload(p_project_id uuid, p_request jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o uuid:=fluid_private.shared_identity_customer(p_project_id);prior public.logo_input_requests;workspace jsonb;begin
 if p_request->>'kind' is distinct from 'reference_upload' or fluid_private.logo_input_request_valid(p_request) is distinct from true
 then raise exception 'identity_reference_upload_intent_invalid' using errcode='22023';end if;
 perform 1 from public.projects where id=p_project_id and owner_id=o for update;
 select * into prior from public.logo_input_requests where owner_id=o and project_id=p_project_id and request_key=(p_request#>>'{input,requestKey}')::uuid;
 if found then
  if prior.request is distinct from p_request then raise exception 'identity_reference_upload_intent_conflict' using errcode='PT409';end if;
  return fluid_private.logo_input_state(o,p_project_id,prior.request_key);
 end if;
 perform 1 from public.identity_reference_heads where owner_id=o and project_id=p_project_id for update;
 perform 1 from public.identity_sessions where owner_id=o and project_id=p_project_id for update;
 workspace:=fluid_private.logo_workspace_json(o,p_project_id);
 if workspace->'heads' is distinct from p_request#>'{input,expected}' then raise exception 'identity_reference_upload_heads_changed' using errcode='PT409';end if;
 if exists(select 1 from public.logo_workspace_requests where owner_id=o and project_id=p_project_id and request_key=(p_request#>>'{input,requestKey}')::uuid) then raise exception 'identity_reference_upload_key_conflict' using errcode='PT409';end if;
 insert into public.logo_input_requests(owner_id,project_id,request_key,request) values(o,p_project_id,(p_request#>>'{input,requestKey}')::uuid,p_request);
 return fluid_private.logo_input_state(o,p_project_id,(p_request#>>'{input,requestKey}')::uuid);
end $$;


ALTER FUNCTION public.prepare_shared_identity_reference_upload(p_project_id uuid, p_request jsonb) OWNER TO postgres;

