--
-- Name: read_logo_workspace_base_record(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_logo_workspace_base_record(p_project_id uuid, p_kind text, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); result jsonb;
begin
 if owner is null then raise exception 'unauthenticated' using errcode='42501'; end if;
 if not exists(select 1 from public.projects where id=p_project_id and owner_id=owner) then raise exception 'logo_project_not_found' using errcode='P0002'; end if;
 case p_kind
 when 'stage' then select record into result from public.logo_stage_revisions where id=p_id and project_id=p_project_id and owner_id=owner;
 when 'reference_snapshot' then return fluid_private.logo_snapshot_json(owner,p_project_id,p_id);
 when 'manual_request' then
  select receipt into result from public.logo_workspace_requests where request_key=p_id and project_id=p_project_id and owner_id=owner and method<>'startLogoProject';
  if not found then return jsonb_build_object('status','not_found'); end if;
  return jsonb_build_object('status','succeeded','requestKey',p_id,'receipt',result,'outputs','[]'::jsonb,'billing',jsonb_build_object('status','recorded','confirmedMicrousd',0),'reason',null);
 else raise exception 'invalid_logo_read_kind' using errcode='22023';
 end case;
 if result is null then raise exception 'logo_record_not_found' using errcode='P0002'; end if;
 return result;
end $$;


ALTER FUNCTION public.read_logo_workspace_base_record(p_project_id uuid, p_kind text, p_id uuid) OWNER TO postgres;

--
-- Name: read_logo_workspace_record(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.read_logo_workspace_record(p_project_id uuid, p_kind text, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid();result jsonb;vector jsonb;
begin
 if owner is null then raise exception 'unauthenticated' using errcode='42501';end if;
 if not exists(select 1 from public.projects where id=p_project_id and owner_id=owner) then raise exception 'logo_project_not_found' using errcode='P0002';end if;
 if p_kind in('stage','reference_snapshot','manual_request') then return public.read_logo_workspace_base_record(p_project_id,p_kind,p_id);end if;
 if p_kind='vector' then select record into result from public.logo_vector_revisions where id=p_id and owner_id=owner and project_id=p_project_id;
 elsif p_kind='vector_source_preview' then
  select record into vector from public.logo_vector_revisions where id=p_id and owner_id=owner and project_id=p_project_id;
  if vector is not null then
   select fluid_private.logo_asset_receipt(r) into result from public.logo_asset_publications r where r.owner_id=owner and r.project_id=p_project_id and r.version_id::text=vector#>>'{sourcePreview,versionId}' and r.state='committed' and fluid_private.logo_asset_reservation(r)->'reference'=vector->'sourcePreview';
  end if;
 elsif p_kind in('concept_batch','raster_refinement') then return fluid_private.logo_job_record(owner,p_project_id,p_kind,p_id);
 else raise exception 'invalid_logo_read_kind' using errcode='22023';end if;
 if result is null then raise exception 'logo_record_not_found' using errcode='P0002';end if;return result;
end $$;


ALTER FUNCTION public.read_logo_workspace_record(p_project_id uuid, p_kind text, p_id uuid) OWNER TO postgres;

