--
-- Name: record_project_screening(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.record_project_screening(p_project_id uuid, p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_owner uuid:=auth.uid();v_basis jsonb;v_record public.project_screening_records;v_criteria jsonb;v_value jsonb;v_item text;v_observed timestamptz;
begin
 if v_owner is null then raise exception 'unauthenticated' using errcode='42501';end if;
 if p_input is null or jsonb_typeof(p_input)<>'object' or octet_length(p_input::text)>32768
  or not(p_input ?& array['requestId','selectionId','expectedProjectRevision','criteria','notes','sourceUrls','observedAt','acknowledged'])
  or p_input-array['requestId','selectionId','expectedProjectRevision','criteria','notes','sourceUrls','observedAt','acknowledged']<>'{}'::jsonb
  or p_input->'acknowledged' is distinct from 'true'::jsonb or jsonb_typeof(p_input->'requestId')<>'string' or jsonb_typeof(p_input->'selectionId')<>'string'
  or jsonb_typeof(p_input->'expectedProjectRevision')<>'number' or (p_input->>'expectedProjectRevision')!~'^[1-9][0-9]*$'
  or jsonb_typeof(p_input->'notes')<>'string' or length(btrim(p_input->>'notes')) not between 1 and 3000
  or jsonb_typeof(p_input->'observedAt')<>'string' or jsonb_typeof(p_input->'sourceUrls')<>'array' then raise exception 'invalid_record' using errcode='22023';end if;
 if jsonb_array_length(p_input->'sourceUrls')>5 then raise exception 'invalid_sources' using errcode='22023';end if;
 for v_value in select value from jsonb_array_elements(p_input->'sourceUrls') loop
  v_item:=v_value#>>'{}';
  if jsonb_typeof(v_value)<>'string' or length(v_item)>2048 or v_item!~'^https://[A-Za-z0-9]([A-Za-z0-9.-]*[A-Za-z0-9])?(:[0-9]{1,5})?([/?#].*)?$' or v_item~'[[:cntrl:][:space:]]'
   or coalesce(substring(v_item from '^https://[^/:?#]+:([0-9]+)')::integer,0)>65535 then raise exception 'invalid_source' using errcode='22023';end if;
 end loop;
 if (select count(*)<>count(distinct value) from jsonb_array_elements(p_input->'sourceUrls')) then raise exception 'duplicate_sources' using errcode='22023';end if;
 v_observed:=(p_input->>'observedAt')::timestamptz;
 if not isfinite(v_observed) or v_observed>clock_timestamp() then raise exception 'invalid_observation_time' using errcode='22023';end if;
 v_criteria:=p_input->'criteria';
 if jsonb_typeof(v_criteria)<>'object' then raise exception 'invalid_criteria' using errcode='22023';end if;
 if v_criteria->>'tool'='domains' then
  if not(v_criteria ?& array['tool','domain']) or v_criteria-array['tool','domain']<>'{}'::jsonb or jsonb_typeof(v_criteria->'domain')<>'string'
   or length(v_criteria->>'domain')>253 or v_criteria->>'domain'!~'^([a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$' or v_criteria->>'domain'~'(^|\.)xn--' then raise exception 'invalid_domain' using errcode='22023';end if;
 elsif v_criteria->>'tool'='handles' then
  if not(v_criteria ?& array['tool','platform','handle']) or v_criteria-array['tool','platform','handle']<>'{}'::jsonb
   or v_criteria->>'platform' not in ('instagram','tiktok','youtube','x','linkedin') or jsonb_typeof(v_criteria->'platform')<>'string'
   or jsonb_typeof(v_criteria->'handle')<>'string' or v_criteria->>'handle'!~'^[a-zA-Z0-9_.-]{1,64}$' then raise exception 'invalid_handle' using errcode='22023';end if;
 elsif v_criteria->>'tool'='trademarks' then
  if not(v_criteria ?& array['tool','mark','jurisdictions','niceClasses','mode']) or v_criteria-array['tool','mark','jurisdictions','niceClasses','mode']<>'{}'::jsonb
   or v_criteria->'mode' is distinct from '"exact_word"'::jsonb or jsonb_typeof(v_criteria->'mark')<>'string' or length(v_criteria->>'mark') not between 1 and 160
   or jsonb_typeof(v_criteria->'jurisdictions')<>'array' or jsonb_typeof(v_criteria->'niceClasses')<>'array' then raise exception 'invalid_trademark' using errcode='22023';end if;
  if jsonb_array_length(v_criteria->'jurisdictions') not between 1 and 20 or jsonb_array_length(v_criteria->'niceClasses')>45 then raise exception 'invalid_trademark_scope' using errcode='22023';end if;
  for v_value in select value from jsonb_array_elements(v_criteria->'jurisdictions') loop
   if jsonb_typeof(v_value)<>'string' or v_value#>>'{}'!~'^[A-Z0-9-]{2,32}$' then raise exception 'invalid_jurisdiction' using errcode='22023';end if;
  end loop;
  for v_value in select value from jsonb_array_elements(v_criteria->'niceClasses') loop
   if jsonb_typeof(v_value)<>'number' or v_value::text!~'^[0-9]+$' or (v_value::text)::integer not between 1 and 45 then raise exception 'invalid_class' using errcode='22023';end if;
  end loop;
  if (select count(*)<>count(distinct value) from jsonb_array_elements(v_criteria->'jurisdictions')) or (select count(*)<>count(distinct value) from jsonb_array_elements(v_criteria->'niceClasses')) then raise exception 'duplicate_criteria' using errcode='22023';end if;
 else raise exception 'unsupported_tool' using errcode='22023';end if;
 -- Lock order matches Naming: project before session. Context/selection changes
 -- cannot interleave with binding this explicit review to its saved basis.
 perform 1 from public.projects where id=p_project_id and owner_id=v_owner for update;
 if not found then raise exception 'not_found' using errcode='P0002';end if;
 select * into v_record from public.project_screening_records where owner_id=v_owner and request_id=(p_input->>'requestId')::uuid;
 if found then
  if v_record.project_id<>p_project_id or v_record.request_payload<>p_input then raise exception 'intent_conflict' using errcode='PT409';end if;
  return fluid_private.project_screening_record_dto(v_record);
 end if;
 v_basis:=fluid_private.project_screening_basis(p_project_id,v_owner);
 if v_basis is null or (v_basis->>'selectionId')::uuid<>(p_input->>'selectionId')::uuid or (v_basis->>'projectRevision')::integer<>(p_input->>'expectedProjectRevision')::integer then raise exception 'context_conflict' using errcode='PT409';end if;
 if v_criteria->>'tool'='trademarks' and v_criteria->>'mark'<>v_basis->>'name' then raise exception 'name_mismatch' using errcode='22023';end if;
 if (select count(*) from public.project_screening_records where project_id=p_project_id and owner_id=v_owner)>=1000 then raise exception 'history_capacity' using errcode='PT409';end if;
 insert into public.project_screening_records(request_id,owner_id,project_id,selection_id,candidate_id,project_revision,context_hash,selected_name,criteria,notes,source_urls,observed_at,request_payload)
 values((p_input->>'requestId')::uuid,v_owner,p_project_id,(v_basis->>'selectionId')::uuid,(v_basis->>'candidateId')::uuid,(v_basis->>'projectRevision')::integer,v_basis->>'contextHash',v_basis->>'name',v_criteria,btrim(p_input->>'notes'),p_input->'sourceUrls',v_observed,p_input) returning * into v_record;
 return fluid_private.project_screening_record_dto(v_record);
end $_$;


ALTER FUNCTION public.record_project_screening(p_project_id uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: register_shared_identity_reference(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.register_shared_identity_reference(p_project_id uuid, p_upload_request_key uuid, p_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare o uuid:=fluid_private.shared_identity_customer(p_project_id);prior fluid_private.shared_identity_reference_requests;
 request public.logo_input_requests;receipt public.logo_input_receipts;publication public.logo_asset_publications;rights public.logo_input_rights;reference public.identity_references;
 intent jsonb:=jsonb_build_object('uploadRequestKey',p_upload_request_key,'metadata',p_metadata);rid uuid;
begin
 if p_upload_request_key is null or not fluid_private.standalone_keys(p_metadata,array['attribution','relevantElements','tags'])
 or not fluid_private.reference_attribution(p_metadata->'attribution') or octet_length(p_metadata::text)>8192 then raise exception 'identity_reference_registration_invalid' using errcode='22023';end if;
 perform fluid_private.reference_elements(p_metadata->'relevantElements');perform fluid_private.reference_tags(p_metadata->'tags');
 perform 1 from public.projects where id=p_project_id and owner_id=o for update;
 select * into prior from fluid_private.shared_identity_reference_requests where owner_id=o and project_id=p_project_id and request_key=p_upload_request_key;
 if found then if prior.intent is distinct from intent then raise exception 'identity_reference_registration_conflict' using errcode='PT409';end if;return fluid_private.identity_reference_entry(prior.reference_id,p_project_id,o);end if;
 select * into request from public.logo_input_requests where owner_id=o and project_id=p_project_id and request_key=p_upload_request_key;
 select * into receipt from public.logo_input_receipts where owner_id=o and project_id=p_project_id and request_key=p_upload_request_key;
 select * into publication from public.logo_asset_publications where owner_id=o and project_id=p_project_id and request_key=p_upload_request_key and job_id is null;
 select * into rights from public.logo_input_rights where id=publication.rights_evidence_id and owner_id=o and project_id=p_project_id and publication_id=publication.id;
 if request.request_key is null or receipt.request_key is null or publication.id is null or rights.id is null
 or request.request->>'kind'<>'reference_upload' or receipt.reference_id is distinct from publication.source_receipt_id or receipt.font_record_id is not null
 or publication.state<>'committed' or publication.source_kind<>'logo_reference' or publication.purpose<>'reference_media' or publication.mime_type not in('image/png','image/jpeg','image/webp')
 or publication.verification->>'status'<>'verified' or publication.verification->>'contentHash'<>publication.content_hash or publication.verification->>'mimeType'<>publication.mime_type
 or publication.verification->'byteLength'<>to_jsonb(publication.byte_length) or publication.request#>>'{intent,usage}'<>'logo_reference'
 or rights.source_kind<>'user_declaration' or rights.catalog_id is not null or rights.content_hash<>publication.content_hash
 or request.request->'file' is distinct from jsonb_build_object('contentHash',publication.content_hash,'mimeType',publication.mime_type,'byteLength',publication.byte_length)
 or rights.rights_declaration is distinct from publication.request#>>'{intent,rightsDeclaration}'
 or p_metadata#>>'{attribution,rightsNote}' is distinct from rights.rights_declaration
 or receipt.result->'asset' is distinct from fluid_private.logo_asset_reservation(publication)->'reference'
 or exists(select 1 from public.logo_input_rejections where owner_id=o and project_id=p_project_id and request_key=p_upload_request_key)
 or not exists(select 1 from public.asset_versions v join public.assets a on (a.id,a.owner_id,a.project_id)=(v.asset_id,v.owner_id,v.project_id)
  where v.id=publication.version_id and v.asset_id=publication.asset_id and v.owner_id=o and v.project_id=p_project_id and v.mime_type=publication.mime_type
  and v.content_hash=publication.content_hash and a.purpose='reference_media' and v.provenance->>'publicationId'=publication.id::text)
 then raise exception 'identity_reference_upload_unconfirmed' using errcode='42501';end if;
 insert into public.identity_references(project_id,owner_id,asset_id,media_version_id,source,attribution,relevant_elements,tags)
 values(p_project_id,o,publication.asset_id,publication.version_id,'user_supplied',p_metadata->'attribution',fluid_private.reference_elements(p_metadata->'relevantElements'),fluid_private.reference_tags(p_metadata->'tags')) returning * into reference;
 insert into fluid_private.shared_identity_reference_requests values(o,p_project_id,p_upload_request_key,intent,reference.id);
 return fluid_private.identity_reference_entry(reference.id,p_project_id,o);
end $$;


ALTER FUNCTION public.register_shared_identity_reference(p_project_id uuid, p_upload_request_key uuid, p_metadata jsonb) OWNER TO postgres;

--
-- Name: request_job_cancel(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.request_job_cancel(p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_job public.jobs;
begin
  if auth.uid() is not null then perform fluid_private.lock_strategy_owner(auth.uid()); end if;
  select * into v_job from public.jobs where id = p_job_id and owner_id = auth.uid() for update;
  if not found then raise exception 'not_found' using errcode = 'P0002'; end if;
  if v_job.state = 'queued' then
    if not fluid_private.shared_identity_job(v_job) and v_job.operation<>'naming.generate' then perform fluid_private.settle_reservation(p_job_id);end if;
    update public.jobs set state = 'cancelled', cancel_requested_at = clock_timestamp(), finished_at = clock_timestamp()
      where id = p_job_id returning * into v_job;
  elsif v_job.state = 'running' and v_job.operation = 'naming.generate' then
    update public.jobs set cancel_requested_at = coalesce(cancel_requested_at, clock_timestamp()) where id = p_job_id returning * into v_job;
  elsif v_job.state = 'running' then
    update public.jobs set state = 'cancel_requested', cancel_requested_at = clock_timestamp() where id = p_job_id returning * into v_job;
  elsif v_job.state = 'needs_reconciliation' then
    update public.jobs set cancel_requested_at = coalesce(cancel_requested_at, clock_timestamp()) where id = p_job_id returning * into v_job;
  end if;
  return jsonb_build_object(
    'id', v_job.id, 'project_id', v_job.project_id, 'operation', v_job.operation,
    'input_revision', v_job.input_revision, 'state', v_job.state, 'progress', v_job.progress,
    'reserved_cost_microusd', v_job.reserved_cost_microusd, 'actual_cost_microusd', v_job.actual_cost_microusd,
    'cancel_requested_at', v_job.cancel_requested_at, 'error_code', v_job.error_code,
    'created_at', v_job.created_at, 'finished_at', v_job.finished_at);
end $$;


ALTER FUNCTION public.request_job_cancel(p_job_id uuid) OWNER TO postgres;

--
-- Name: request_project_deletion(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.request_project_deletion(p_project_id uuid, p_expected_revision integer, p_expected_lifecycle_version integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid(); p public.projects; j public.jobs;
begin
  if v_owner is null then raise exception 'authentication_required' using errcode='42501'; end if;
  if p_expected_revision is null or p_expected_revision<1 or p_expected_lifecycle_version is null
    or p_expected_lifecycle_version not between 0 and 2147483646 then raise exception 'invalid_lifecycle_request' using errcode='22023'; end if;
  -- Identity/existence before any owner lock. This never discloses a foreign ID.
  if not exists(select 1 from public.projects where id=p_project_id and owner_id=v_owner) then raise exception 'project_not_found' using errcode='P0002'; end if;
  -- Same advisory identity used by lock_strategy_owner. All additional locks
  -- are NOWAIT in this owner-request transaction only: a contended child/account
  -- can never form a project->job/ledger cycle with a paid worker. Retry means
  -- the entire request rolled back, including intent and reservation changes.
  if not pg_try_advisory_xact_lock(hashtextextended(v_owner::text,723902)) then
    raise exception 'deletion_lock_busy' using errcode='55P03';
  end if;
  perform 1 from fluid_private.strategy_billing_routes where owner_id=v_owner for update nowait;
  perform 1 from public.usage_accounts where owner_id=v_owner for update nowait;
  select * into p from public.projects where id=p_project_id and owner_id=v_owner for update nowait;
  if not found then raise exception 'project_not_found' using errcode='P0002'; end if;
  -- Lost HTTP acknowledgements replay only their exact still-current epoch.
  -- Withdrawal/Restore increments the epoch, so a late retry cannot re-delete.
  if p.deletion_requested_at is not null and p.current_revision=p_expected_revision
    and p.lifecycle_version=p_expected_lifecycle_version+1 then return fluid_private.project_deletion_summary(p.id,v_owner); end if;
  if p.current_revision<>p_expected_revision or p.lifecycle_version<>p_expected_lifecycle_version
    or p.deleted_at is not null or p.deletion_requested_at is not null then raise exception 'lifecycle_conflict' using errcode='PT409'; end if;
  perform j0.id from public.jobs j0 where j0.project_id=p.id and j0.owner_id=v_owner order by j0.id for update nowait;
  perform r.job_id from public.usage_reservations r where r.project_id=p.id and r.owner_id=v_owner order by r.job_id for update nowait;
  update public.projects set deletion_requested_at=clock_timestamp(),lifecycle_version=lifecycle_version+1 where id=p.id and owner_id=v_owner;
  for j in select * from public.jobs where project_id=p.id and owner_id=v_owner order by id loop
    if j.state='queued' then
      -- begin_job_step is durable before any potentially billed request. A prior
      -- predispatch claim alone (attempts>0) is not evidence of provider spending.
      if j.actual_cost_microusd=0 and j.lease_token is null
        and not exists(select 1 from public.job_steps where job_id=j.id)
        and not exists(select 1 from public.subscription_job_partials where job_id=j.id)
        and not exists(select 1 from public.logo_provider_responses where job_id=j.id)
        and not exists(select 1 from public.logo_asset_publications where job_id=j.id)
        and not exists(select 1 from public.logo_direction_publications where job_id=j.id)
        and not exists(select 1 from public.logo_export_publications where job_id=j.id) then
        perform public.request_job_cancel(j.id);
      else
        update public.jobs set state='needs_reconciliation',cancel_requested_at=coalesce(cancel_requested_at,clock_timestamp()),
          error_code=coalesce(error_code,'deletion_stop_requires_review') where id=j.id and owner_id=v_owner;
      end if;
    elsif j.state in ('running','cancel_requested') then
      update public.jobs set project_deletion_requested_at=coalesce(project_deletion_requested_at,clock_timestamp()) where id=j.id and owner_id=v_owner;
      if j.state='running' then perform public.request_job_cancel(j.id); end if;
    elsif j.state='needs_reconciliation' then
      perform public.request_job_cancel(j.id);
    end if;
  end loop;
  return fluid_private.project_deletion_summary(p.id,v_owner);
exception when lock_not_available then
  raise exception 'project_deletion_retry' using errcode='PT409';
end $$;


ALTER FUNCTION public.request_project_deletion(p_project_id uuid, p_expected_revision integer, p_expected_lifecycle_version integer) OWNER TO postgres;

--
-- Name: restore_project_deletion(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.restore_project_deletion(p_project_id uuid, p_expected_revision integer, p_expected_lifecycle_version integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid(); p public.projects;
begin
  if v_owner is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select * into p from public.projects where id=p_project_id and owner_id=v_owner for update;
  if not found then raise exception 'project_not_found' using errcode='P0002'; end if;
  if p_expected_revision is null or p_expected_revision<1 or p_expected_lifecycle_version is null
    or p_expected_lifecycle_version not between 0 and 2147483646 then raise exception 'invalid_lifecycle_request' using errcode='22023'; end if;
  if p.current_revision<>p_expected_revision or p.lifecycle_version<>p_expected_lifecycle_version
    or (p.deleted_at is null and p.deletion_requested_at is null) then raise exception 'lifecycle_conflict' using errcode='PT409'; end if;
  update public.projects set deleted_at=null,deletion_requested_at=null,lifecycle_version=lifecycle_version+1 where id=p.id and owner_id=v_owner;
  -- Cancellation already requested remains intact. Restore never queues work.
  return fluid_private.project_deletion_summary(p.id,v_owner);
end $$;


ALTER FUNCTION public.restore_project_deletion(p_project_id uuid, p_expected_revision integer, p_expected_lifecycle_version integer) OWNER TO postgres;

--
-- Name: review_project_visual_direction(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.review_project_visual_direction(p_project_id uuid, p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); project public.projects; latest jsonb; guidance jsonb; refs jsonb; next_id uuid:=gen_random_uuid();
 expected numeric; expected_project numeric; expected_selection numeric; selection_revision bigint; field text; value text; revision bigint;
begin
 -- All inspiration/project/review writers acquire this same project lock first.
 select * into project from public.projects where id=p_project_id and owner_id=owner for update;
 if not found then raise exception 'project_not_found' using errcode='P0002';end if;
 if project.scope='naming_only' then raise exception 'visual_direction_scope' using errcode='22023';end if;
 if not fluid_private.standalone_keys(p_input,array['expectedRevision','expectedProjectRevision','expectedSelectionRevision','catalogVersion','guidance']) or octet_length(p_input::text)>32768
  or jsonb_typeof(p_input->'expectedRevision') is distinct from 'number' or jsonb_typeof(p_input->'expectedProjectRevision') is distinct from 'number'
  or jsonb_typeof(p_input->'expectedSelectionRevision') is distinct from 'number' then raise exception 'invalid_visual_direction' using errcode='22023';end if;
 expected:=(p_input->>'expectedRevision')::numeric;expected_project:=(p_input->>'expectedProjectRevision')::numeric;expected_selection:=(p_input->>'expectedSelectionRevision')::numeric;
 if expected not between 0 and 9007199254740990 or expected<>trunc(expected) or expected_project not between 1 and 9007199254740991 or expected_project<>trunc(expected_project)
  or expected_selection not between 0 and 9007199254740991 or expected_selection<>trunc(expected_selection) then raise exception 'invalid_visual_direction_revision' using errcode='22023';end if;
 guidance:=p_input->'guidance';
 if not fluid_private.standalone_keys(guidance,array['character','colors','typography','graphics']) then raise exception 'invalid_visual_guidance' using errcode='22023';end if;
 foreach field in array array['character','colors','typography','graphics'] loop
  value:=guidance->>field;
  -- Match the JS schema's UTF-16 length and ECMAScript trim, including astral
  -- characters. Direct RPC calls cannot persist a value the reader rejects.
  if jsonb_typeof(guidance->field) is distinct from 'string' or char_length(value)+(select count(*) from regexp_split_to_table(value,'') c where ascii(nullif(c,''))>65535)>1200
   or value ~ '[\x01-\x08\x0B\x0C\x0E-\x1F\x7F]' or value<>btrim(value,E' \t\r\n'||chr(11)||chr(12)||chr(160)||chr(5760)||chr(8192)||chr(8193)||chr(8194)||chr(8195)||chr(8196)||chr(8197)||chr(8198)||chr(8199)||chr(8200)||chr(8201)||chr(8202)||chr(8232)||chr(8233)||chr(8239)||chr(8287)||chr(12288)||chr(65279)) then raise exception 'invalid_visual_guidance' using errcode='22023';end if;
 end loop;
 latest:=fluid_private.visual_direction_latest(owner,p_project_id);
 select coalesce((select h.revision from public.project_inspiration_heads h where h.owner_id=owner and h.project_id=p_project_id),0) into selection_revision;
 if expected<>coalesce((latest->>'revision')::bigint,0) or expected_project<>project.current_revision or expected_selection<>selection_revision or p_input->>'catalogVersion' is distinct from '2026-10-13.1'
  then raise exception 'visual_direction_changed' using errcode='PT409';end if;
 select coalesce(jsonb_agg(jsonb_build_object('referenceId',c.reference_id,'brand',a.descriptor->'brand','creator',a.descriptor->'creator',
  'description',a.descriptor->'description','sourceUrl',a.descriptor->'sourceUrl','contentHash',a.descriptor->'contentHash','ensemble',c.ensemble,'elements',c.elements) order by c.reference_id),'[]') into refs
  from public.project_inspiration_choices c join fluid_private.inspiration_catalog a on a.id=c.reference_id
  where c.owner_id=owner and c.project_id=p_project_id and (c.ensemble or cardinality(c.elements)>0);
 if refs='[]' and not exists(select 1 from jsonb_each_text(guidance) t where t.value<>'') then raise exception 'visual_direction_empty' using errcode='22023';end if;
 revision:=expected::bigint+1;
 insert into public.project_visual_directions(id,owner_id,project_id,revision,record) values(next_id,owner,p_project_id,revision,
  jsonb_build_object('id',next_id,'ownerId',owner,'projectId',p_project_id,'revision',revision,'projectRevision',project.current_revision,'selectionRevision',selection_revision,
   'catalogVersion','2026-10-13.1','guidance',guidance,'references',refs,'reviewedAt',to_char(clock_timestamp() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.MS"Z"')));
 return public.get_project_visual_direction(p_project_id);
end $$;


ALTER FUNCTION public.review_project_visual_direction(p_project_id uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: save_attached_home_project(jsonb, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_attached_home_project(p_input jsonb, p_context_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare owner uuid:=auth.uid(); nonce uuid; body jsonb; ids uuid[]; v_attachment_id uuid; row public.home_attachments; previous public.home_attachment_project_requests; total bigint:=0; p public.projects; refs jsonb:='[]'; result jsonb;
begin
 if owner is null then raise exception 'unauthenticated' using errcode='42501'; end if;
 if not fluid_private.standalone_keys(p_input,array['requestKey','project','attachmentIds']) or not fluid_private.logo_uuid(p_input->'requestKey') or octet_length(p_input::text)>32768 or jsonb_typeof(p_input->'attachmentIds') is distinct from 'array' then raise exception 'invalid_home_project' using errcode='22023'; end if;
 if jsonb_array_length(p_input->'attachmentIds')>5 or exists(select 1 from jsonb_array_elements(p_input->'attachmentIds') v where not fluid_private.logo_uuid(v)) then raise exception 'invalid_home_ids' using errcode='22023'; end if;
 select coalesce(array_agg(value::uuid order by n),'{}'::uuid[]) into ids from jsonb_array_elements_text(p_input->'attachmentIds') with ordinality v(value,n);
 if cardinality(ids)<>(select count(distinct v) from unnest(ids) v) then raise exception 'duplicate_home_ids' using errcode='22023'; end if;
 body:=p_input->'project';
 if not fluid_private.standalone_keys(body,array['title','scope','context']) or jsonb_typeof(body->'title') is distinct from 'string' or length(body->>'title') not between 1 and 160 or body->>'title'<>fluid_private.idea_trim(body->>'title') or jsonb_typeof(body->'scope') is distinct from 'string' or body->>'scope' not in('complete_brand','naming_only','visual_identity_only') or jsonb_typeof(body->'context') is distinct from 'object' or p_context_text is null or octet_length(p_context_text)>32768 or p_context_text::jsonb is distinct from body->'context' then raise exception 'invalid_home_context' using errcode='22023'; end if;
 if fluid_private.identity_material_context(body->'context') is distinct from body->'context' then raise exception 'invalid_home_context' using errcode='22023'; end if;
 nonce:=(p_input->>'requestKey')::uuid; perform pg_advisory_xact_lock(hashtextextended(owner::text||':home-project:'||nonce::text,0));
 select * into previous from public.home_attachment_project_requests where owner_id=owner and request_key=nonce;
 if found then if previous.input<>p_input then raise exception 'home_request_conflict' using errcode='PT409'; end if; return previous.receipt; end if;
 -- Deterministic row lock order avoids cross-request deadlocks. Every file must
 -- still be verified, owned and unlinked before creating any project rows.
 perform 1 from public.home_attachments where owner_id=owner and home_attachments.id=any(ids) order by home_attachments.id for update;
 foreach v_attachment_id in array ids loop
  select * into row from public.home_attachments where home_attachments.id=v_attachment_id and owner_id=owner;
  if not found then raise exception 'home_attachment_not_found' using errcode='P0002'; end if;
  if not row.verified or row.project_id is not null then raise exception 'home_attachment_conflict' using errcode='PT409'; end if;
  total:=total+row.byte_length;
 end loop;
 if total>26214400 then raise exception 'home_aggregate_limit' using errcode='22023'; end if;
 p:=public.create_project(body->>'scope',body->>'title',body->'context',encode(sha256(convert_to(p_context_text,'UTF8')),'hex'));
 foreach v_attachment_id in array ids loop
  update public.home_attachments set project_id=p.id,project_revision=1 where home_attachments.id=v_attachment_id and owner_id=owner and verified and project_id is null returning * into row;
  if not found then raise exception 'home_attachment_conflict' using errcode='PT409'; end if;
  refs:=refs||jsonb_build_array(fluid_private.home_attachment_ref(row));
 end loop;
 result:=jsonb_build_object('ownerId',owner,'requestKey',nonce,'project',jsonb_build_object('id',p.id,'owner_id',owner,'title',p.title,'scope',p.scope,'current_revision',1,'created_at',fluid_private.idea_timestamp(p.created_at),'context',body->'context'),'attachments',refs);
 insert into public.home_attachment_project_requests(owner_id,request_key,project_id,input,receipt) values(owner,nonce,p.id,p_input,result);
 return result;
end $$;


ALTER FUNCTION public.save_attached_home_project(p_input jsonb, p_context_text text) OWNER TO postgres;

--
-- Name: save_naming_preferences(uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_naming_preferences(p_project_id uuid, p_expected_version integer, p_preferences jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid(); v_session public.naming_sessions; v_preferences public.naming_preferences;
begin
 if p_expected_version is null or p_expected_version<0 or not fluid_private.valid_naming_preferences(p_preferences) then raise exception 'invalid_preferences' using errcode='22023'; end if;
 v_session:=fluid_private.ensure_naming_session(p_project_id,v_owner);
 if v_session.preferences_version=p_expected_version+1 then
 select * into v_preferences from public.naming_preferences where project_id=p_project_id and owner_id=v_owner and version=v_session.preferences_version and preferences=p_preferences;
 if found then return jsonb_build_object('session',fluid_private.naming_session_dto(v_session),'preferences',fluid_private.naming_preference_dto(v_preferences)); end if;
 end if;
 if coalesce(v_session.preferences_version,0)<>p_expected_version then raise exception 'preferences_conflict' using errcode='PT409'; end if;
 insert into public.naming_preferences(project_id,owner_id,version,preferences) values(p_project_id,v_owner,p_expected_version+1,p_preferences) returning * into v_preferences;
 update public.naming_sessions set preferences_version=v_preferences.version,revision=revision+1,updated_at=clock_timestamp() where project_id=p_project_id and owner_id=v_owner returning * into v_session;
 return jsonb_build_object('session',fluid_private.naming_session_dto(v_session),'preferences',fluid_private.naming_preference_dto(v_preferences));
end $$;


ALTER FUNCTION public.save_naming_preferences(p_project_id uuid, p_expected_version integer, p_preferences jsonb) OWNER TO postgres;

--
-- Name: save_naming_view(uuid, integer, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.save_naming_view(p_project_id uuid, p_expected_revision integer, p_view jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare v_owner uuid:=auth.uid(); v_session public.naming_sessions; v_key text; v_chat jsonb; v_answer jsonb;
begin
 if p_expected_revision is null or p_expected_revision<1 or jsonb_typeof(p_view) is distinct from 'object'
  or p_view-array['pane','conversationOpen','filter','query','visibleBatchId','scrollCandidateId','workshopCandidateId','namingChat']<>'{}'
  or not(p_view ?& array['pane','conversationOpen','filter','query','visibleBatchId','scrollCandidateId','workshopCandidateId'])
  or jsonb_typeof(p_view->'pane')<>'string' or jsonb_typeof(p_view->'filter')<>'string' or p_view->>'pane' not in('results','screening','workshop') or jsonb_typeof(p_view->'conversationOpen')<>'boolean'
  or p_view->>'filter' not in('all','retained','favorite','saved') or jsonb_typeof(p_view->'query')<>'string' or length(p_view->>'query')>200 then raise exception 'invalid_view' using errcode='22023'; end if;
 if p_view ? 'namingChat' then
  v_chat:=p_view->'namingChat';
  if jsonb_typeof(v_chat) is distinct from 'object' or v_chat-array['version','preferencesVersion','confirmed']<>'{}'
   or not(v_chat ?& array['version','preferencesVersion','confirmed']) or v_chat->'version' is distinct from '1'::jsonb
   or jsonb_typeof(v_chat->'preferencesVersion') is distinct from 'number' or v_chat->>'preferencesVersion' !~ '^[1-9][0-9]{0,9}$'
   or jsonb_typeof(v_chat->'confirmed') is distinct from 'object'
   or (v_chat->'confirmed')-array['approaches','directness','language','length','fragments']<>'{}' then raise exception 'invalid_view' using errcode='22023'; end if;
  if (v_chat->>'preferencesVersion')::bigint>2147483647 then raise exception 'invalid_view' using errcode='22023'; end if;
  for v_key,v_answer in select key,value from jsonb_each(v_chat->'confirmed') loop
   if jsonb_typeof(v_answer) is distinct from 'string' or length(v_answer#>>'{}')>(case v_key when 'approaches' then 400 when 'directness' then 32 when 'language' then 200 when 'length' then 32 else 13200 end) then raise exception 'invalid_view' using errcode='22023'; end if;
  end loop;
 end if;
 v_session:=fluid_private.ensure_naming_session(p_project_id,v_owner);
 if v_session.view_revision<>p_expected_revision then raise exception 'view_conflict' using errcode='PT409'; end if;
 -- Older view bodies remain accepted and cannot erase a newer acknowledgement.
 if not(p_view ? 'namingChat') and v_session.view_state ? 'namingChat' then p_view:=p_view||jsonb_build_object('namingChat',v_session.view_state->'namingChat'); end if;
 -- An unchanged checkpoint can accompany ordinary navigation after a preference
 -- edit. New confirmations must bind the exact current immutable V2 preference.
 if p_view ? 'namingChat' and p_view->'namingChat' is distinct from v_session.view_state->'namingChat' then
  if (p_view->'namingChat'->>'preferencesVersion')::integer is distinct from v_session.preferences_version
   or not exists(select 1 from public.naming_preferences where project_id=p_project_id and owner_id=v_owner and version=v_session.preferences_version and preferences->'version'='2'::jsonb)
   then raise exception 'preferences_conflict' using errcode='PT409'; end if;
 end if;
 if p_view->>'visibleBatchId' is not null and not exists(select 1 from public.naming_batches where id=(p_view->>'visibleBatchId')::uuid and project_id=p_project_id and owner_id=v_owner) then raise exception 'not_found' using errcode='P0002'; end if;
 foreach v_key in array array['scrollCandidateId','workshopCandidateId'] loop
  if p_view->>v_key is not null and not exists(select 1 from public.name_candidates where id=(p_view->>v_key)::uuid and project_id=p_project_id and owner_id=v_owner) then raise exception 'not_found' using errcode='P0002'; end if;
 end loop;
 update public.naming_sessions set view_state=p_view,view_revision=view_revision+1,revision=revision+1,updated_at=clock_timestamp() where project_id=p_project_id and owner_id=v_owner returning * into v_session;
 return jsonb_build_object('session',fluid_private.naming_session_dto(v_session));
end $_$;


ALTER FUNCTION public.save_naming_view(p_project_id uuid, p_expected_revision integer, p_view jsonb) OWNER TO postgres;

--
-- Name: select_asset_version(uuid, uuid, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.select_asset_version(p_asset_id uuid, p_version_id uuid, p_expected_project_revision integer, p_expected_selection_revision integer, p_accept_stale_basis boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid();v_asset public.assets;v_project public.projects;v_head public.asset_heads;v_version public.asset_versions;v_selection public.asset_selections;v_reason text;
begin
 if v_owner is null then raise exception 'unauthenticated' using errcode='42501';end if;
 if p_expected_project_revision is null or p_expected_project_revision<1 or p_expected_selection_revision is null or p_expected_selection_revision<0 or p_accept_stale_basis is null then raise exception 'invalid_asset_selection' using errcode='22023';end if;
 select * into v_asset from public.assets where id=p_asset_id and owner_id=v_owner and purpose<>'reference_media';if not found then raise exception 'not_found' using errcode='P0002';end if;
 select * into strict v_project from public.projects where id=v_asset.project_id and owner_id=v_owner for update;
 perform 1 from public.assets where id=p_asset_id and owner_id=v_owner for update;
 select * into strict v_head from public.asset_heads where asset_id=p_asset_id and project_id=v_project.id and owner_id=v_owner for update;
 select * into v_version from public.asset_versions where id=p_version_id and asset_id=p_asset_id and project_id=v_project.id and owner_id=v_owner;if not found then raise exception 'not_found' using errcode='P0002';end if;
 if v_project.current_revision<>p_expected_project_revision or v_head.selection_revision<>p_expected_selection_revision then raise exception 'asset_selection_conflict' using errcode='PT409';end if;
 if v_version.input_revision<>v_project.current_revision and not p_accept_stale_basis then raise exception 'stale_asset_requires_acknowledgment' using errcode='PT409';end if;
 v_reason:=case when exists(select 1 from public.asset_selections where version_id=p_version_id and asset_id=p_asset_id and project_id=v_project.id and owner_id=v_owner) then 'restored' else 'selected' end;
 insert into public.asset_selections(owner_id,project_id,asset_id,version_id,reason) values(v_owner,v_project.id,p_asset_id,p_version_id,v_reason) returning * into v_selection;
 insert into public.asset_selection_receipts(selection_id,version_id,asset_id,project_id,owner_id,project_revision,accepted_stale_basis,previous_selection_id)
 values(v_selection.id,p_version_id,p_asset_id,v_project.id,v_owner,v_project.current_revision,p_accept_stale_basis,v_head.current_selection_id);
 update public.asset_heads set current_selection_id=v_selection.id,current_version_id=p_version_id,selection_revision=selection_revision+1,updated_at=clock_timestamp() where asset_id=p_asset_id and project_id=v_project.id and owner_id=v_owner;
 return public.get_asset_detail(p_asset_id,'{}');
end $$;


ALTER FUNCTION public.select_asset_version(p_asset_id uuid, p_version_id uuid, p_expected_project_revision integer, p_expected_selection_revision integer, p_accept_stale_basis boolean) OWNER TO postgres;

--
-- Name: select_project_name(uuid, uuid, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.select_project_name(p_project_id uuid, p_candidate_id uuid, p_expected_revision integer, p_accept_earlier_context boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid();v_session public.naming_sessions;v_candidate public.name_candidates;v_project public.projects;v_revision public.project_revisions;v_context jsonb;v_selection public.name_selections;v_prior uuid;
begin
 if p_expected_revision is null or p_expected_revision<1 or p_accept_earlier_context is null then raise exception 'invalid_selection' using errcode='22023'; end if;
 v_session:=fluid_private.ensure_naming_session(p_project_id,v_owner);v_prior:=v_session.current_selection_id;
 select * into strict v_project from public.projects where id=p_project_id and owner_id=v_owner;
 if v_project.current_revision<>p_expected_revision then raise exception 'revision_conflict' using errcode='PT409'; end if;
 select * into v_candidate from public.name_candidates where id=p_candidate_id and project_id=p_project_id and owner_id=v_owner;
 if not found then raise exception 'not_found' using errcode='P0002'; end if;
 select context into strict v_context from public.project_revisions where project_id=p_project_id and owner_id=v_owner and revision=p_expected_revision;
 if fluid_private.naming_strategy_basis(v_context)<>v_candidate.strategy_basis and not p_accept_earlier_context then raise exception 'earlier_context_requires_acknowledgment' using errcode='PT409'; end if;
 v_context:=v_context||jsonb_build_object('selectedName',v_candidate.value,'intake',coalesce(v_context->'intake','{}')||jsonb_build_object('suppliedName',v_candidate.value));
 v_revision:=public.append_project_revision(p_project_id,p_expected_revision,v_context,encode(sha256(convert_to(v_context::text,'UTF8')),'hex'));
 insert into public.name_selections(owner_id,project_id,candidate_id,project_revision,prior_selection_id,accepted_earlier_context)
  values(v_owner,p_project_id,p_candidate_id,v_revision.revision,v_prior,p_accept_earlier_context) returning * into v_selection;
 update public.naming_sessions set current_selection_id=v_selection.id,revision=revision+1,updated_at=clock_timestamp() where project_id=p_project_id and owner_id=v_owner returning * into v_session;
 select * into strict v_project from public.projects where id=p_project_id and owner_id=v_owner;
 return jsonb_build_object('project',fluid_private.naming_project_dto(v_project),'session',fluid_private.naming_session_dto(v_session),
 'currentSelection',jsonb_build_object('selection',fluid_private.naming_selection_dto(v_selection),'candidate',fluid_private.naming_candidate_dto(v_candidate)));
end $$;


ALTER FUNCTION public.select_project_name(p_project_id uuid, p_candidate_id uuid, p_expected_revision integer, p_accept_earlier_context boolean) OWNER TO postgres;

--
-- Name: set_asset_retention(uuid, integer, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_asset_retention(p_asset_id uuid, p_expected_retention_revision integer, p_liked boolean, p_saved boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid();v_asset public.assets;v_project public.projects;
begin
 if v_owner is null then raise exception 'unauthenticated' using errcode='42501';end if;
 if p_expected_retention_revision is null or p_expected_retention_revision<0 or p_liked is null or p_saved is null then raise exception 'invalid_asset_retention' using errcode='22023';end if;
 select * into v_asset from public.assets where id=p_asset_id and owner_id=v_owner and purpose<>'reference_media' for update;if not found then raise exception 'not_found' using errcode='P0002';end if;
 if v_asset.retention_revision<>p_expected_retention_revision then raise exception 'asset_retention_conflict' using errcode='PT409';end if;
 update public.assets set liked=p_liked,saved=p_saved,retention_revision=retention_revision+1 where id=p_asset_id and owner_id=v_owner returning * into v_asset;
 select * into strict v_project from public.projects where id=v_asset.project_id and owner_id=v_owner;
 return jsonb_build_object('asset',fluid_private.asset_library_record(v_asset),'project',fluid_private.asset_library_project(v_project));
end $$;


ALTER FUNCTION public.set_asset_retention(p_asset_id uuid, p_expected_retention_revision integer, p_liked boolean, p_saved boolean) OWNER TO postgres;

--
-- Name: set_identity_preferences(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_identity_preferences(p_project_id uuid, p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid();v_expected bigint;v_value jsonb;v_session public.identity_sessions;v_preferences public.identity_preferences;
begin
 if v_owner is null then raise exception 'unauthenticated' using errcode='42501';end if;
 if p_input is null or jsonb_typeof(p_input)<>'object' or p_input-array['expectedPreferencesRevision','preferences']<>'{}' or not(p_input ?& array['expectedPreferencesRevision','preferences']) then raise exception 'invalid_identity_preferences' using errcode='22023';end if;
 v_expected:=fluid_private.identity_counter(p_input->'expectedPreferencesRevision');v_value:=fluid_private.identity_preferences_value(p_input->'preferences');
 perform 1 from public.projects p where p.id=p_project_id and p.owner_id=v_owner for update;if not found then raise exception 'not_found' using errcode='P0002';end if;
 insert into public.identity_sessions(project_id,owner_id) values(p_project_id,v_owner) on conflict do nothing;
 select * into strict v_session from public.identity_sessions where project_id=p_project_id and owner_id=v_owner for update;
 if coalesce(v_session.current_preferences_revision,0)<>v_expected or v_expected>=9007199254740991 then raise exception 'identity_preferences_conflict' using errcode='PT409';end if;
 insert into public.identity_preferences(project_id,owner_id,revision,preferences) values(p_project_id,v_owner,v_expected+1,v_value) returning * into v_preferences;
 update public.identity_sessions set current_preferences_revision=v_preferences.revision,updated_at=clock_timestamp() where project_id=p_project_id and owner_id=v_owner returning * into v_session;
 return jsonb_build_object('session',fluid_private.identity_session_json(v_session),'preferences',fluid_private.identity_preferences_json(v_preferences));
end $$;


ALTER FUNCTION public.set_identity_preferences(p_project_id uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: set_identity_reference_reaction(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_identity_reference_reaction(p_project_id uuid, p_reference_id uuid, p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid();v_expected numeric;v_elements text[];v_ensemble boolean;v_reference public.identity_references;
 v_head public.identity_reference_heads;v_current public.identity_reference_reactions;v_revision bigint;v_delta integer;v_count integer;
begin
 perform 1 from public.projects p where p.id=p_project_id and p.owner_id=v_owner for update;
 if not found then raise exception 'reference_project_not_found' using errcode='P0002';end if;
 select * into v_reference from public.identity_references r where r.id=p_reference_id and r.project_id=p_project_id and r.owner_id=v_owner;
 if not found then raise exception 'reference_not_found' using errcode='P0002';end if;
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'invalid_reference_reaction' using errcode='22023';end if;
 if p_input-array['expectedRevision','ensemble','elements']<>'{}' or not(p_input ?& array['expectedRevision','ensemble','elements'])
  or jsonb_typeof(p_input->'expectedRevision')<>'number' or jsonb_typeof(p_input->'ensemble')<>'boolean' then raise exception 'invalid_reference_reaction' using errcode='22023';end if;
 v_expected:=(p_input->>'expectedRevision')::numeric;
 if v_expected not between 0 and 9007199254740991 or v_expected<>trunc(v_expected) then raise exception 'invalid_reference_revision' using errcode='22023';end if;
 v_elements:=fluid_private.reference_elements(p_input->'elements');v_ensemble:=(p_input->>'ensemble')::boolean;
 if not(v_elements<@v_reference.relevant_elements) then raise exception 'irrelevant_reference_element' using errcode='22023';end if;
 insert into public.identity_reference_heads(project_id,owner_id) values(p_project_id,v_owner) on conflict do nothing;
 select * into v_head from public.identity_reference_heads h where h.project_id=p_project_id and h.owner_id=v_owner for update;
 select * into v_current from public.identity_reference_reactions r where r.reference_id=p_reference_id and r.project_id=p_project_id and r.owner_id=v_owner for update;
 v_revision:=coalesce(v_current.revision,0);
 if v_revision<>v_expected then raise exception 'reference_reaction_conflict' using errcode='PT409';end if;
 if v_revision=9007199254740991 or v_head.reference_revision=9007199254740991 then raise exception 'reference_revision_exhausted' using errcode='PT409';end if;
 v_delta:=(case when v_ensemble or cardinality(v_elements)>0 then 1 else 0 end)-(case when coalesce(v_current.ensemble,false) or coalesce(cardinality(v_current.elements),0)>0 then 1 else 0 end);
 v_count:=v_head.selected_reference_count+v_delta;
 if v_count>100 then raise exception 'reference_selection_capacity' using errcode='PT409';end if;
 if v_count<0 then raise exception 'invalid_reference_count' using errcode='55000';end if;
 insert into public.identity_reference_reactions(reference_id,project_id,owner_id,revision,ensemble,elements,updated_at)
  values(p_reference_id,p_project_id,v_owner,v_revision+1,v_ensemble,v_elements,clock_timestamp())
  on conflict(reference_id) do update set revision=excluded.revision,ensemble=excluded.ensemble,elements=excluded.elements,updated_at=excluded.updated_at;
 update public.identity_reference_heads set reference_revision=reference_revision+1,selected_reference_count=v_count where project_id=p_project_id and owner_id=v_owner returning * into v_head;
 return jsonb_build_object('ownerId',v_owner,'projectId',p_project_id,'referenceRevision',v_head.reference_revision,'selectedReferenceCount',v_head.selected_reference_count,
  'entry',fluid_private.identity_reference_entry(p_reference_id,p_project_id,v_owner));
end $$;


ALTER FUNCTION public.set_identity_reference_reaction(p_project_id uuid, p_reference_id uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: set_name_retention(uuid, uuid, integer, boolean, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_name_retention(p_project_id uuid, p_candidate_id uuid, p_expected_revision integer, p_favorite boolean, p_saved boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid(); v_candidate public.name_candidates; v_retention public.name_retention;
begin
 if p_expected_revision is null or p_expected_revision<0 or p_favorite is null or p_saved is null then raise exception 'invalid_retention' using errcode='22023'; end if;
 perform fluid_private.ensure_naming_session(p_project_id,v_owner);
 select * into v_candidate from public.name_candidates where id=p_candidate_id and project_id=p_project_id and owner_id=v_owner;
 if not found then raise exception 'not_found' using errcode='P0002'; end if;
 select * into v_retention from public.name_retention where candidate_id=p_candidate_id and project_id=p_project_id and owner_id=v_owner;
 if coalesce(v_retention.revision,0)<>p_expected_revision then raise exception 'retention_conflict' using errcode='PT409'; end if;
 insert into public.name_retention(candidate_id,owner_id,project_id,liked,saved,revision) values(p_candidate_id,v_owner,p_project_id,p_favorite,p_saved,p_expected_revision+1)
  on conflict(candidate_id) do update set liked=excluded.liked,saved=excluded.saved,revision=excluded.revision,updated_at=clock_timestamp();
 return jsonb_build_object('entry',fluid_private.naming_entry(v_candidate));
end $$;


ALTER FUNCTION public.set_name_retention(p_project_id uuid, p_candidate_id uuid, p_expected_revision integer, p_favorite boolean, p_saved boolean) OWNER TO postgres;

--
-- Name: set_project_deleted(uuid, integer, integer, boolean); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_project_deleted(p_project_id uuid, p_expected_revision integer, p_expected_lifecycle_version integer, p_deleted boolean) RETURNS public.projects
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid(); v_project public.projects;
begin
  if v_owner is null then raise exception 'authentication_required' using errcode='42501'; end if;
  select p.* into v_project from public.projects p where p.id=p_project_id and p.owner_id=v_owner for update;
  if not found then raise exception 'project_not_found' using errcode='P0002'; end if;
  if p_expected_revision is null or p_expected_revision<1 or p_expected_lifecycle_version is null
    or p_expected_lifecycle_version not between 0 and 2147483646 or p_deleted is null then
    raise exception 'invalid_lifecycle_request' using errcode='22023';
  end if;
  if v_project.current_revision<>p_expected_revision or v_project.lifecycle_version<>p_expected_lifecycle_version
    or (v_project.deleted_at is not null)=p_deleted then
    raise exception 'lifecycle_conflict' using errcode='PT409';
  end if;
  update public.projects p set deleted_at=case when p_deleted then clock_timestamp() else null end,
    lifecycle_version=p.lifecycle_version+1 where p.id=v_project.id and p.owner_id=v_owner returning p.* into v_project;
  return v_project;
end $$;


ALTER FUNCTION public.set_project_deleted(p_project_id uuid, p_expected_revision integer, p_expected_lifecycle_version integer, p_deleted boolean) OWNER TO postgres;

--
-- Name: set_project_inspiration_reaction(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.set_project_inspiration_reaction(p_project_id uuid, p_reference_id uuid, p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_owner uuid:=auth.uid(); v_project public.projects; v_catalog fluid_private.inspiration_catalog;
 v_expected numeric; v_project_revision numeric; v_elements text[]; v_previous bigint;
begin
 -- Same lock used by project/context writers: scope and revision cannot change
 -- between admission and the preference write. auth.uid(), never a body owner.
 select * into v_project from public.projects where id=p_project_id and owner_id=v_owner for update;
 if not found then raise exception 'project_not_found' using errcode='P0002'; end if;
 if v_project.scope='naming_only' then raise exception 'inspiration_scope' using errcode='22023'; end if;
 if jsonb_typeof(p_input) is distinct from 'object' or
  not(p_input ?& array['catalogVersion','expectedProjectRevision','expectedRevision','ensemble','elements']) or
  p_input-array['catalogVersion','expectedProjectRevision','expectedRevision','ensemble','elements']<>'{}' or
  jsonb_typeof(p_input->'expectedRevision') is distinct from 'number' or
  jsonb_typeof(p_input->'expectedProjectRevision') is distinct from 'number' or
  jsonb_typeof(p_input->'ensemble') is distinct from 'boolean' then
  raise exception 'invalid_inspiration_choices' using errcode='22023';
 end if;
 v_expected:=(p_input->>'expectedRevision')::numeric; v_project_revision:=(p_input->>'expectedProjectRevision')::numeric;
 if v_expected not between 0 and 9007199254740990 or v_expected<>trunc(v_expected) or
  v_project_revision not between 1 and 9007199254740991 or v_project_revision<>trunc(v_project_revision) then
  raise exception 'invalid_inspiration_revision' using errcode='22023';
 end if;
 if v_project_revision<>v_project.current_revision then raise exception 'project_changed' using errcode='PT409'; end if;
 select * into v_catalog from fluid_private.inspiration_catalog where id=p_reference_id;
 if not found then raise exception 'design_not_found' using errcode='P0002'; end if;
 if p_input->>'catalogVersion' is distinct from v_catalog.catalog_version then raise exception 'catalog_changed' using errcode='PT409'; end if;
 v_elements:=fluid_private.reference_elements(p_input->'elements');
 if not(v_elements<@v_catalog.relevant_elements) then raise exception 'irrelevant_element' using errcode='22023'; end if;
 select revision into v_previous from public.project_inspiration_choices
  where project_id=p_project_id and owner_id=v_owner and reference_id=p_reference_id;
 if coalesce(v_previous,0)<>v_expected then raise exception 'choices_changed' using errcode='PT409'; end if;
 insert into public.project_inspiration_heads(project_id,owner_id,revision) values(p_project_id,v_owner,1)
  on conflict(project_id,owner_id) do update set revision=public.project_inspiration_heads.revision+1;
 insert into public.project_inspiration_choices(project_id,owner_id,reference_id,revision,ensemble,elements)
  values(p_project_id,v_owner,p_reference_id,v_expected::bigint+1,(p_input->>'ensemble')::boolean,v_elements)
  on conflict(project_id,owner_id,reference_id) do update set revision=excluded.revision,ensemble=excluded.ensemble,elements=excluded.elements,updated_at=clock_timestamp();
 return public.get_project_inspiration(p_project_id);
end $$;


ALTER FUNCTION public.set_project_inspiration_reaction(p_project_id uuid, p_reference_id uuid, p_input jsonb) OWNER TO postgres;

--
-- Name: shared_account_http_principal(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.shared_account_http_principal() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p fluid_private.shared_http_principals;
begin
 select * into p from fluid_private.shared_http_principals where role_name=session_user and role_oid=to_regrole(session_user)::oid;
 if p.role_oid is null or current_setting('role')<>'none' or fluid_private.shared_http_role(p.lane)<>p.role_oid
 then raise exception 'shared_http_principal_unqualified' using errcode='42501'; end if;
 return jsonb_build_object('version',1,'lane',p.lane,'roleName',p.role_name,'roleOid',p.role_oid::bigint,'origin',(select origin from fluid_private.shared_http_target));
end $$;


ALTER FUNCTION public.shared_account_http_principal() OWNER TO postgres;

