    model text,
    engine jsonb,
    max_cost_microusd bigint NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    subscription_policy jsonb,
    CONSTRAINT logo_directions_subscription_policy CHECK (((subscription_policy IS NULL) OR ((fluid_private.valid_logo_directions_subscription_policy(subscription_policy) AND (operation = 'identity.logo_directions'::text) AND (provider = 'openai'::text) AND (model = (subscription_policy ->> 'model'::text)) AND (handler_version = 'logo-directions-v1'::text) AND (engine IS NULL) AND (max_cost_microusd = 0) AND (policy_identity = encode(sha256(convert_to((subscription_policy)::text, 'UTF8'::name)), 'hex'::text))) IS TRUE))),
    CONSTRAINT logo_runtime_policies_check CHECK (((provider IS NULL) = (model IS NULL))),
    CONSTRAINT logo_runtime_policies_check1 CHECK (((operation <> 'identity.logo_concept'::text) OR ((provider = 'openai'::text) AND (model = 'gpt-image-2.5-sunburst-2026-09-08'::text) AND (handler_version = 'logo-image-v1'::text) AND (max_cost_microusd > 0)))),
    CONSTRAINT logo_runtime_policies_check2 CHECK (((operation <> 'identity.logo_vectorize'::text) OR ((provider IS NULL) AND (model IS NULL) AND (engine IS NOT NULL) AND (max_cost_microusd = 0)))),
    CONSTRAINT logo_runtime_policies_handler_version_check CHECK ((handler_version ~ '^[A-Za-z0-9._:-]{1,200}$'::text)),
    CONSTRAINT logo_runtime_policies_max_cost_microusd_check CHECK (((max_cost_microusd >= 0) AND (max_cost_microusd <= '9007199254740991'::bigint))),
    CONSTRAINT logo_runtime_policies_operation_check CHECK ((operation = ANY (ARRAY['identity.logo_concept'::text, 'identity.logo_refine'::text, 'identity.logo_vectorize'::text, 'identity.logo_directions'::text, 'identity.logo_export'::text]))),
    CONSTRAINT logo_runtime_policies_policy_identity_check CHECK ((policy_identity ~ '^[0-9a-f]{64}$'::text))
);

