INSERT INTO fluid_private.inspiration_catalog (id, catalog_version, descriptor, relevant_elements) VALUES ('82a30592-62c1-5258-b616-119d4757270c', '2026-10-13.1', '{"id": "82a30592-62c1-5258-b616-119d4757270c", "kind": "identity", "slug": "archi-tex", "tags": ["construction", "industrial", "orange", "extended-sans"], "brand": "Archi-Tex", "image": "/inspiration/brands/archi-tex/01-logo.webp", "parts": [{"part": "logo", "image": "/inspiration/brands/archi-tex/01-logo.webp", "width": 1600, "height": 900, "thumbnail": "/inspiration/brands/archi-tex/01-logo-small.webp", "contentHash": "cded98446fc0d4e561acd0e0326e372ec1f9675ee93445fb39e7ef194e08a533", "description": "White symbol of three nested rising arcs beside the extended, squared geometric sans wordmark ARCHI-TEX, shown over a muted steel-frame construction photo."}, {"part": "colors", "image": "/inspiration/brands/archi-tex/02-color-palette.webp", "width": 1600, "height": 900, "thumbnail": "/inspiration/brands/archi-tex/02-color-palette-small.webp", "contentHash": "f5fedf0e5d9255eae133c38fc653fcfc84c632817fb1b7bf9765731599eef6c1", "description": "Caution Orange #ef4723, Solid White #ffffff and Coal Black #231f20."}, {"fill": "#fefefe", "part": "typefaces", "image": "/inspiration/brands/archi-tex/03-typography.webp", "width": 1600, "height": 802, "thumbnail": "/inspiration/brands/archi-tex/03-typography-small.webp", "contentHash": "9b7f138fb43b0a2a3f4f292bfdf8c4e9e6b2bf258599dc4ca57dd35af503057f", "description": "Manifold Extd CF, a wide, squared-off geometric sans shown in Thin, Regular, Medium and Bold with italics."}, {"fill": "#ffffff", "part": "socials", "image": "/inspiration/brands/archi-tex/04-social-profile.webp", "width": 1236, "height": 1147, "thumbnail": "/inspiration/brands/archi-tex/04-social-profile-small.webp", "contentHash": "c5b8f43474458017cedcfd3d6f9e78d4dab984b5970d1217c1aca03471992ee4", "description": "Dark social profile card framed in orange: a steel-frame construction header photo, an orange square avatar with black nested arcs and the name Archi-Tex."}, {"part": "visuals", "image": "/inspiration/brands/archi-tex/05-brand-poster.webp", "width": 1600, "height": 1065, "thumbnail": "/inspiration/brands/archi-tex/05-brand-poster-small.webp", "contentHash": "73879b591dfc47dc2ab6ddc6e9003753d731ebd19e967bafdf32db698380d636", "description": "Roadside billboard: orange panel with stacked ARCHI TEX, a black arc symbol and a service list, beside a photo of two hard-hat workers on steel stairs."}], "width": 1600, "height": 900, "elements": ["logo", "typography", "colors", "images", "composition"], "contentHash": "cded98446fc0d4e561acd0e0326e372ec1f9675ee93445fb39e7ef194e08a533", "description": "Bold industrial identity in safety orange, white and near-black, pairing an extended geometric typeface with construction-site photography for a construction company.", "availableSince": "2026-11-08.1"}', '{logo,typography,colors,images,composition}');
INSERT INTO fluid_private.inspiration_catalog (id, catalog_version, descriptor, relevant_elements) VALUES ('80f2a36a-4c86-5be5-9470-730d98df4b3c', '2026-10-13.1', '{"id": "80f2a36a-4c86-5be5-9470-730d98df4b3c", "kind": "identity", "slug": "asteor", "tags": ["playful", "rounded", "art-studio", "colorful"], "brand": "Asteor", "image": "/inspiration/brands/asteor/01-logo.webp", "parts": [{"fill": "#1e1e1e", "part": "logo", "image": "/inspiration/brands/asteor/01-logo.webp", "width": 971, "height": 403, "thumbnail": "/inspiration/brands/asteor/01-logo-small.webp", "contentHash": "8ff60897e0e5b933b9a9764c4a72fcf6a7324f44ce50c22b7c4b02e63b014936", "description": "Heavy rounded lowercase wordmark asteor with a TM in white on near-black, the a drawn as a dot plus a curved stroke."}, {"part": "colors", "image": "/inspiration/brands/asteor/02-color-palette.webp", "width": 1600, "height": 807, "thumbnail": "/inspiration/brands/asteor/02-color-palette-small.webp", "contentHash": "b8b09850c34d943e9eac3d56d192836b9cd66b55f25fb82fd1dc55a1b1f8bb69", "description": "Obsidian Ink #1E1E1E (primary), Ultramarine Pigment #004AAD, Zinc Chartreuse #E7F67F, Cadmium Crimson #C91414 and Acrylic Blossom pink #FFA1F9."}, {"part": "typefaces", "image": "/inspiration/brands/asteor/03-typography.webp", "width": 1600, "height": 870, "thumbnail": "/inspiration/brands/asteor/03-typography-small.webp", "contentHash": "153d5c3f41fae16ca080d95b2df449564518eb26973c9fafc7e6d20449d0a590", "description": "Cinqcent, a heavy, rounded display sans with quirky letterforms, shown in Light, Regular, Medium and Bold."}, {"fill": "#fefefe", "part": "socials", "image": "/inspiration/brands/asteor/04-social-profile.webp", "width": 1001, "height": 813, "thumbnail": "/inspiration/brands/asteor/04-social-profile-small.webp", "contentHash": "7c6955226b606dd8d65e9c76682ef37e5b1920a4fe8acb9d0be85eb7771149d8", "description": "One profile card labeled Art Studio on black: a chartreuse as monogram on a black avatar under a blurred blue abstract banner, with a blue Follow button."}, {"part": "visuals", "image": "/inspiration/brands/asteor/05-brand-poster.webp", "width": 1600, "height": 1261, "thumbnail": "/inspiration/brands/asteor/05-brand-poster-small.webp", "contentHash": "c602fb23b0ddd7050a5b74d85f02b709ff4e1f134fe91fbd1a465b42c56983cb", "description": "Two framed posters on a dark slatted wall, each a vivid surreal portrait illustration in purple, pink, orange and teal with the asteor logo below."}], "width": 971, "height": 403, "elements": ["logo", "typography", "colors", "images", "composition"], "contentHash": "8ff60897e0e5b933b9a9764c4a72fcf6a7324f44ce50c22b7c4b02e63b014936", "description": "Bold, playful identity for an art studio: a chunky rounded wordmark on near-black, with ultramarine blue, chartreuse, crimson and pink accents and vivid illustrated posters.", "availableSince": "2026-11-08.1"}', '{logo,typography,colors,images,composition}');
INSERT INTO fluid_private.inspiration_catalog (id, catalog_version, descriptor, relevant_elements) VALUES ('7e5e2ef8-cd9e-5880-8330-ae7610d26d3d', '2026-10-13.1', '{"id": "7e5e2ef8-cd9e-5880-8330-ae7610d26d3d", "kind": "identity", "slug": "astrix-builders", "tags": ["construction", "modern", "orange", "navy"], "brand": "Astrix Builders", "image": "/inspiration/brands/astrix-builders/01-logo.webp", "parts": [{"part": "logo", "image": "/inspiration/brands/astrix-builders/01-logo.webp", "width": 1600, "height": 967, "thumbnail": "/inspiration/brands/astrix-builders/01-logo-small.webp", "contentHash": "3a15e1bccbfe24c16a11805990fba23cfee94e511b815e41c7694fb59b62a7b2", "description": "Half-asterisk symbol of one vertical and two diagonal strokes on a base bar, beside the two-line sans wordmark Astrix Builders; white over a site photo."}, {"part": "colors", "image": "/inspiration/brands/astrix-builders/02-color-palette.webp", "width": 1600, "height": 1454, "thumbnail": "/inspiration/brands/astrix-builders/02-color-palette-small.webp", "contentHash": "a90c0c8767307049f6c0cb73ae2dbededa76426c76758ba9cd9994348a7ce106", "description": "Light sky blue AACFDF, bright orange F24E24 and deep navy 0B2639, with white, shown beside a crane photo and short taglines."}, {"fill": "#ffffff", "part": "typefaces", "image": "/inspiration/brands/astrix-builders/03-typography.webp", "width": 1600, "height": 902, "thumbnail": "/inspiration/brands/astrix-builders/03-typography-small.webp", "contentHash": "fc4fba036ddd32497d29eb9712127f86480df5a57cda582ced3f4dbfc96e69ef", "description": "Geist, a clean, neutral sans, shown in Regular, Medium and Semi Bold."}, {"fill": "#ffffff", "part": "socials", "image": "/inspiration/brands/astrix-builders/04-social-profile.webp", "width": 721, "height": 591, "thumbnail": "/inspiration/brands/astrix-builders/04-social-profile-small.webp", "contentHash": "86001a872ee22217c19ee37204dcf507c8f0145d383d5073f5c4575235e1f7ac", "description": "Profile card on light sky blue: a banner of stacked concrete blocks, an orange circular avatar with the white symbol and the tagline A Legacy Of Excellence."}, {"part": "visuals", "image": "/inspiration/brands/astrix-builders/05-brand-poster.webp", "width": 1600, "height": 1022, "thumbnail": "/inspiration/brands/astrix-builders/05-brand-poster-small.webp", "contentHash": "8debb192cfbeaade83331391df1fde7bb9f284e67de9566823099e299bd8ed3a", "description": "Wall billboard with three panels: a navy panel with a timber-structure photo, a hard-hat worker on a forklift, and an orange panel with a tagline and logo."}], "width": 1600, "height": 967, "elements": ["logo", "typography", "colors", "images", "composition"], "contentHash": "3a15e1bccbfe24c16a11805990fba23cfee94e511b815e41c7694fb59b62a7b2", "description": "Clean, modern construction identity in light sky blue, bright orange and deep navy, with a half-asterisk symbol, a neutral sans and site photography.", "availableSince": "2026-11-08.1"}', '{logo,typography,colors,images,composition}');
