INSERT INTO fluid_private.inspiration_catalog (id, catalog_version, descriptor, relevant_elements) VALUES ('98ef66d8-8b4b-5040-9b9a-85024ae88c16', '2026-10-13.1', '{"id": "98ef66d8-8b4b-5040-9b9a-85024ae88c16", "kind": "identity", "slug": "forma", "tags": ["fashion", "serif", "burgundy", "editorial"], "brand": "Forma", "image": "/inspiration/brands/forma/01-logo.webp", "parts": [{"part": "logo", "image": "/inspiration/brands/forma/01-logo.webp", "width": 1344, "height": 1082, "thumbnail": "/inspiration/brands/forma/01-logo-small.webp", "contentHash": "613566e57dfb900b4b8f708536b98da85996f3593d2b071ecfe8f4f9d63ed03f", "description": "Serif F monogram in an offset square frame above the high-contrast serif wordmark FORMA and the tagline WHERE STYLE TAKES SHAPE, in white over a model photo."}, {"part": "colors", "image": "/inspiration/brands/forma/02-color-palette.webp", "width": 1600, "height": 2390, "thumbnail": "/inspiration/brands/forma/02-color-palette-small.webp", "contentHash": "221b71d033a44aa749ed641f6f3f76e391c52a076013fbd26011ef4d60b2c3b1", "description": "Midnight Tuxedo #121D30 (primary), Burgundy Atelier #6E2731, Olive Sartorial #49533A, Camel Suede #A8763E, Raw Alabaster #F5F2EA and Slate Editorial #6B7280."}, {"part": "typefaces", "image": "/inspiration/brands/forma/03-typography.webp", "width": 1600, "height": 2201, "thumbnail": "/inspiration/brands/forma/03-typography-small.webp", "contentHash": "fb1f16cad46cb8ffe32a6116ba80809441a2e830d99a2d07f15e7a1b03c2cec4", "description": "Casko Luxury, a high-contrast display serif, in cream and gold on navy, and Clash Grotesk, a sans from Light to Bold with a heading scale, on burgundy."}, {"fill": "#ffffff", "part": "socials", "image": "/inspiration/brands/forma/04-social-profile.webp", "width": 989, "height": 885, "thumbnail": "/inspiration/brands/forma/04-social-profile-small.webp", "contentHash": "9af2cecbc9258a2957bbfb4ee22c25898dbbbf178f61045ae96a3b3c637d3f82", "description": "One profile card labeled Fas