INSERT INTO fluid_private.inspiration_catalog (id, catalog_version, descriptor, relevant_elements) VALUES ('05a3faee-ba0b-5d23-bf17-ad8e27265849', '2026-10-13.1', '{"id": "05a3faee-ba0b-5d23-bf17-ad8e27265849", "kind": "identity", "slug": "vetter", "tags": ["pet-food", "purple", "playful", "rounded"], "brand": "Vetter", "image": "/inspiration/brands/vetter/01-logo.webp", "parts": [{"fill": "#2f0558", "part": "logo", "image": "/inspiration/brands/vetter/01-logo.webp", "width": 1065, "height": 383, "thumbnail": "/inspiration/brands/vetter/01-logo-small.webp", "contentHash": "1a9dd3781cfcc54f914f552d4c23ab313b33016883710c67dbce8ce1e3f66524", "description": "White lowercase wordmark vetter whose tt loops into a dog face with ears and a heart-shaped nose, on deep purple."}, {"part": "colors", "image": "/inspiration/brands/vetter/02-color-palette.webp", "width": 1600, "height": 776, "thumbnail": "/inspiration/brands/vetter/02-color-palette-small.webp", "contentHash": "c809afe140af70ec4166cd870b0b411f10694952548d69cb9bb3700ee5eed610", "description": "Alpha Purple #4D2178 (primary), Wilderness Bark maroon #5C0C15, Trailblazer Blue #3835AA, Kibble Lime #9BDD28 and Fetch Yellow #FEF23A."}, {"part": "typefaces", "image": "/inspiration/brands/vetter/03-typography.webp", "width": 1600, "height": 842, "thumbnail": "/inspiration/brands/vetter/03-typography-small.webp", "contentHash": "92ea04c866fe541b900620fc332621e909526d38c97251672d76f68bc18a7be9", "description": "Delius Swash, a rounded, informal handwritten-style face with swash capitals, shown in Light, Regular, Medium and Bold."}, {"fill": "#fefeff", "part": "socials", "image": "/inspiration/brands/vetter/04-social-profile.webp", "width": 989, "height": 859, "thumbnail": "/inspiration/brands/vetter/04-social-profile-small.webp", "contentHash": "ec7a5318becab7ddad0d3c99e2c9c5e50a4d7ed5de84f012df2fde43eaf4882c", "description": "One profile card labeled Pet Food on purple: an orange tabby cat licking its lips as the banner, and a purple avatar with the white dog-face mark."}, {"part": "visuals", "image": "/inspiration/brands/vetter/05-brand-poster.webp", "width": 1600, "height": 1062, "thumbnail": "/inspiration/brands/vetter/05-brand-poster-small.webp", "contentHash": "eaa37bd6914ef5a1a4149ea270c021b3348b785335ccad8633e6eca1b6cc3d0a", "description": "Wall billboard with a passerby: orange Trusted Nutrition For Everyday Pet Wellness beside a curly-haired dog holding a bone biscuit amid falling treats."}], "width": 1065, "height": 383, "elements": ["logo", "typography", "colors", "images", "composition"], "contentHash": "1a9dd3781cfcc54f914f552d4c23ab313b33016883710c67dbce8ce1e3f66524", "description": "Warm, playful pet-food identity in deep purple with maroon, lime, blue and yellow accents, a dog-face ligature, swashy rounded type and pet photography.", "availableSince": "2026-11-08.1"}', '{logo,typography,colors,images,composition}');
INSERT INTO fluid_private.inspiration_catalog (id, catalog_version, descriptor, relevant_elements) VALUES ('e889f824-cfaa-5055-bb1a-72951c5469f6', '2026-10-13.1', '{"id": "e889f824-cfaa-5055-bb1a-72951c5469f6", "kind": "identity", "slug": "wellis", "tags": ["wellness", "teal", "olive", "rounded"], "brand": "Wellis", "image": "/inspiration/brands/wellis/01-logo.webp", "parts": [{"fill": "#003d41", "part": "logo", "image": "/inspiration/brands/wellis/01-logo.webp", "width": 1018, "height": 330, "thumbnail": "/inspiration/brands/wellis/01-logo-small.webp", "contentHash": "f5a14660c7d5f5b41d751ea2999a8680aadbd7bdaba80cf7e90b036a619f90e7", "description": "White rounded wordmark Wellis with a registered mark on deep forest teal, the W drawn as one looping stroke and the l''s looped."}, {"part": "colors", "image": "/inspiration/brands/wellis/02-color-palette.webp", "width": 1600, "height": 887, "thumbnail": "/inspiration/brands/wellis/02-color-palette-small.webp", "contentHash": "9abcce1bbfd6ce9bbde298d2f68b6feed8d5aaa4355e444f2bf9378233c79177", "description": "Forest Canopy #003D41 (primary), Botanical Leaf #647F3A, Pure Oatmeal #E7DCC8, Healing Clay #AE5F3D and Solar Vitality pale yellow #EEFF85."}, {"fill": "#fefefe", "part": "typefaces", "image": "/inspiration/brands/wellis/03-typography.webp", "width": 1600, "height": 908, "thumbnail": "/inspiration/brands/wellis/03-typography-small.webp", "contentHash": "51d3057f8ceb82c77ed475caa88716bdf573f6e0a7db8be1ba75c9e5e43d3798", "description": "Neulis, a geometric sans with looped l and curled s details, shown from Extra Light to Black."}, {"fill": "#ffffff", "part": "socials", "image": "/inspiration/brands/wellis/04-social-profile.webp", "width": 989, "height": 959, "thumbnail": "/inspiration/brands/wellis/04-social-profile-small.webp", "contentHash": "1db461c12e0b6a7ff970564320497bf99c35ba2ca3350cce34b0a2bb5074d28c", "description": "One profile card labeled Health & Wellness on dark green: a woman stretching against blue sky as the banner, and a dark green avatar with a yellow W."}, {"part": "visuals", "image": "/inspiration/brands/wellis/05-brand-poster.webp", "width": 1600, "height": 1227, "thumbnail": "/inspiration/brands/wellis/05-brand-poster-small.webp", "contentHash": "b5e02807de1113d47570ea5fb0182d613850b8cc8f6585f21a49ec75460d954a", "description": "Two backlit posters on a dark teal slatted wall: athletes in olive and yellow sportswear beside a large 3D yellow W loop and wellness slogans."}], "width": 1018, "height": 330, "elements": ["logo", "typography", "colors", "images", "composition"], "contentHash": "f5a14660c7d5f5b41d751ea2999a8680aadbd7bdaba80cf7e90b036a619f90e7", "description": "Calm, active wellness identity in deep forest teal and olive green with oatmeal, clay and soft yellow, a looping W and athletic lifestyle photography.", "availableSince": "2026-11-08.1"}', '{logo,typography,colors,images,composition}');
INSERT INTO fluid_private.inspiration_catalog (id, catalog_version, descriptor, relevant_elements) VALUES ('9e4b08f0-2a9e-5841-9df6-7ec3f2ba6726', '2026-10-13.1', '{"id": "9e4b08f0-2a9e-5841-9df6-7ec3f2ba6726", "kind": "identity", "slug": "zapp", "tags": ["app", "lime", "navy", "friendly"], "brand": "Zapp", "image": "/inspiration/brands/zapp/01-logo.webp", "parts": [{"fill": "#1f2a44", "part": "logo", "image": "/inspiration/brands/zapp/01-logo.webp", "width": 449, "height": 236, "thumbnail": "/inspiration/brands/zapp/01-logo-small.webp", "contentHash": "6037be8a494b4bffe908b919f9e30185222e0be72dc36686feb27ba018244f44", "description": "Lime Z bolt of two slanted parallel strokes beside the rounded lowercase wordmark zapp in gray, on deep navy."}, {"part": "colors", "image": "/inspiration/brands/zapp/02-color-palette.webp", "width": 1524, "height": 785, "thumbnail": "/inspiration/brands/zapp/02-color-palette-small.webp", "contentHash": "a98a0c71dfc0f10a8bd92b4e5d083765b5c966d4ccac1ef1c499722227cded6e", "description": "Lime Green a6c936, Deep Navy 1f2a44, Cool Gray 808080, Cream FFF9E5, Warm Orange FD521B, Muted Blue 344870, Pastel Pink and Olive Green 808931."}, {"fill": "#fbfaf1", "part": "typefaces", "image": "/inspiration/brands/zapp/03-typography.webp", "width": 708, "height": 667, "thumbnail": "/inspiration/brands/zapp/03-typography-small.webp", "contentHash": "02baa41a4bb40d331ff2ddc66d4fe5453987124d70e59c1bcec275eb169f9e34", "description": "Bw Gradual, a sans serif for text and display, shown in Extra Bold, Bold and Medium over a grid."}, {"fill": "#fffdf5", "part": "socials", "image": "/inspiration/brands/zapp/04-social-profile.webp", "width": 938, "height": 1038, "thumbnail": "/inspiration/brands/zapp/04-social-profile-small.webp", "contentHash": "37e17a691d3fbfae24166ee3cf25afbc9f20117d023a4e6b0f259d9585ea5fda", "description": "Profile card with lime and gray diagonal shapes and a cartoon robot with a visor and lightning bolts, above a dark panel with a navy zapp avatar."}, {"part": "visuals", "image": "/inspiration/brands/zapp/05-brand-poster.webp", "width": 1500, "height": 892, "thumbnail": "/inspiration/brands/zapp/05-brand-poster-small.webp", "contentHash": "a64fe66506505a7f986bab7aefa444a3ee76b39d997436ad7323f53a2263d221", "description": "Billboard on a dark tiled wall: lime Download the Z-app with map pins and a smiling man holding a phone, plus the zapp logo."}], "width": 449, "height": 236, "elements": ["logo", "typography", "colors", "images", "composition"], "contentHash": "6037be8a494b4bffe908b919f9e30185222e0be72dc36686feb27ba018244f44", "description": "Friendly, modern app identity in lime green and deep navy with gray, cream, orange and pastel accents, a slanted Z bolt symbol and a robot mascot.", "availableSince": "2026-11-08.1"}', '{logo,typography,colors,images,composition}');
